AUTO_ROLL_BAG_PRICES = [15_000, 30_000, 55_000, 90_000, 140_000, 210_000, 300_000]

# Редкости, доступные для автоутиля в эссенцию (по умолчанию выкл.)
AUTO_ROLL_ESSENCE_RARITIES = ("epic", "legendary", "mythic", "nightmare")


def get_auto_roll_bag_level(user: Optional[dict]) -> int:
    return max(0, min(len(AUTO_ROLL_BAG_PRICES), int((user or {}).get("auto_roll_bag_level", 0) or 0)))


def get_auto_roll_bag_capacity(user: Optional[dict]) -> int:
    return AUTO_ROLL_BAG_BASE + AUTO_ROLL_BAG_STEP * get_auto_roll_bag_level(user)


def get_auto_roll_duration(user: dict) -> int:
    level = user.get("level", 1) if user else 1
    return AUTO_ROLL_DURATION_SECONDS + level * 3 * 60
