def premium_cross(text: str) -> str:
    """Для сообщений: обычный ❌ → премиум (во всплывашках оставляем обычный)."""
    return (text or "").replace("❌", PE_CROSS)


def premium_emoji_id(emoji_html: str) -> Optional[str]:
    match = re.search(r'emoji-id=["\']?(\d+)', emoji_html or "")
    return match.group(1) if match else None

