def skill_premium_emoji(skill_id: str, fallback: str = "") -> str:
    emoji_id = SKILL_BUTTON_EMOJI_IDS.get(skill_id)
    if not emoji_id:
        return fallback
    return f'<tg-emoji emoji-id="{emoji_id}">{fallback or "▫️"}</tg-emoji>'

