# Суффиксы больших чисел: каждый следующий — ×1000. После последнего — научная запись (1.2e66).
NUM_SUFFIXES = [
    "к", "м", "б", "т", "кд", "кв", "с", "сп", "ок", "нн", "дц",
    "ундц", "дуодц", "тредц", "квтдц", "квндц", "сдц", "спдц", "октдц", "новдц", "вгт",
]


def format_num(n) -> str:
    """Коротко и аккуратно: 999 · 1.5к · 12.3к · 123к · 1.2м · … · 4.5вгт · дальше 1.2e66.
    Раньше после «сп» числа превращались в «7000000.0сп»."""
    try:
        if isinstance(n, float) and (n != n or n in (float("inf"), float("-inf"))):
            return "∞"
        sign = "-" if n < 0 else ""
        n = abs(n)
        if n < 1000:
            return sign + (str(int(n)) if float(n).is_integer() else f"{n:.1f}".rstrip("0").rstrip("."))
        digits = len(str(int(n)))
        exp = (digits - 1) // 3
        if exp > len(NUM_SUFFIXES):  # больше последнего суффикса
            mant, power = f"{float(n):.2e}".split("e")
            return sign + f"{float(mant):g}e{int(power)}"
        scaled = n / (10 ** (3 * exp))  # одно точное деление вместо цепочки (без «499» вместо «500»)
        if scaled >= 100:
            text = str(int(scaled))
        else:
            text = f"{scaled:.1f}".rstrip("0").rstrip(".")
            if text == "1000":
                text = "999"
        return sign + text + NUM_SUFFIXES[exp - 1]
    except Exception:
        return str(n)

