def calculate_weapon_power(weapon: dict) -> int:
    min_damage, max_damage = weapon.get("dmg", (0, 0))
    return ((int(min_damage) + int(max_damage)) * 13 + 1) // 2

def get_fusion_multiplier(item: Optional[dict]) -> int:
    try:
        level = int((item or {}).get("fusion_level", 0))
    except (TypeError, ValueError):
        level = 0
    level = max(0, min(MAX_FUSION_LEVEL, level))
    return level * 2 if level > 0 else 1

def get_fusion_stars(item: Optional[dict]) -> str:
    try:
        level = int((item or {}).get("fusion_level", 0))
    except (TypeError, ValueError):
        level = 0
    level = max(0, min(MAX_FUSION_LEVEL, level))
    return "⭐" * level

def ensure_item_base_stats(item: Optional[dict]) -> bool:
    if not item:
        return False
    changed = False
    try:
        fusion_level = int(item.get("fusion_level", 0))
    except (TypeError, ValueError):
        fusion_level = 0
    fusion_level = max(0, min(MAX_FUSION_LEVEL, fusion_level))
    if item.get("fusion_level") != fusion_level:
        item["fusion_level"] = fusion_level
        changed = True

    multiplier = get_fusion_multiplier(item)
    if item.get("item_type") == "armor":
        if "base_hp" not in item:
            item["base_hp"] = max(1, math.ceil(int(item.get("hp", 0) or 0) / multiplier))
            changed = True
        for resource in ("mana", "stamina"):
            if int(item.get(resource, 0) or 0) > 0 and f"base_{resource}" not in item:
                item[f"base_{resource}"] = max(1, math.ceil(int(item.get(resource, 0) or 0) / multiplier))
                changed = True
    elif item.get("item_type") == "weapon" or "dmg" in item:
        if "base_dmg" not in item:
            lo, hi = item.get("dmg", (1, 1))
            item["base_dmg"] = (
                max(1, math.ceil(int(lo) / multiplier)),
                max(1, math.ceil(int(hi) / multiplier)),
            )
            changed = True
    return changed

def apply_item_fusion_stats(item: Optional[dict]) -> bool:
    if not item:
        return False
    changed = ensure_item_base_stats(item)
    multiplier = get_fusion_multiplier(item)
    if item.get("item_type") == "armor":
        hp = max(1, math.ceil(int(item.get("base_hp", item.get("hp", 1))) * multiplier))
        if item.get("hp") != hp:
            item["hp"] = hp
            changed = True
        for resource in ("mana", "stamina"):
            base_key = f"base_{resource}"
            if base_key in item:
                value = max(1, math.ceil(int(item.get(base_key, 0) or 0) * multiplier))
                if item.get(resource) != value:
                    item[resource] = value
                    changed = True
    elif item.get("item_type") == "weapon" or "dmg" in item:
        base_lo, base_hi = item.get("base_dmg", item.get("dmg", (1, 1)))
        dmg = (
            max(1, math.ceil(int(base_lo) * multiplier)),
            max(1, math.ceil(int(base_hi) * multiplier)),
        )
        if tuple(item.get("dmg", (0, 0))) != dmg:
            item["dmg"] = dmg
            changed = True
        power = calculate_weapon_power(item)
        if item.get("power") != power:
            item["power"] = power
            changed = True
    return changed

def scale_weapon_damage(damage: tuple, player_level: int) -> tuple:
    multiplier = 1 + max(0, player_level - 1) * 0.02
    return (
        max(damage[0], math.ceil(damage[0] * multiplier)),
        max(damage[1], math.ceil(damage[1] * multiplier)),
    )

def roll_weapon_level(player_level: int) -> int:
    return random.randint(max(1, player_level - 5), player_level + 5)

def scale_base_damage_by_weapon_level(damage: tuple, weapon_level: int) -> tuple:
    multiplier = 1 + max(0, weapon_level - 1) * 0.02
    return (
        max(damage[0], math.ceil(damage[0] * multiplier)),
        max(damage[1], math.ceil(damage[1] * multiplier)),
    )

def calculate_player_power(weapon: Optional[dict], player_level: int) -> int:
    if not weapon:
        return 0
    scaled_min, scaled_max = scale_weapon_damage(weapon.get("dmg", (0, 0)), player_level)
    return ((int(scaled_min) + int(scaled_max)) * 13 + 1) // 2

def calculate_user_power(user: Optional[dict]) -> int:
    if not user or not user.get("equipped"):
        return 0
    base_power = calculate_player_power(user.get("equipped"), user.get("level", 1))
    return max(0, math.ceil(base_power * get_damage_multiplier(user)))

def get_skill_level(user: Optional[dict], skill_id: str) -> int:
    if not user:
        return 0
    try:
        return max(0, min(SKILL_MAX_LEVEL, int(user.get("skills", {}).get(skill_id, 0))))
    except (TypeError, ValueError):
        return 0

def get_skill_points(user: Optional[dict]) -> int:
    if not user:
        return 0
    try:
        return max(0, int(user.get("skill_points", 0)))
    except (TypeError, ValueError):
        return 0

def get_user_path(user: Optional[dict]) -> Optional[str]:
    path = (user or {}).get("path")
    return path if path in PATHS else None

def get_path_level(user: Optional[dict]) -> int:
    if not get_user_path(user):
        return 0
    try:
        return max(1, min(PATH_MAX_LEVEL, int((user or {}).get("path_level", 1))))
    except (TypeError, ValueError):
        return 1

def get_path_xp_required(level: int) -> int:
    """Опыт мастерства до следующего уровня. Раньше рос экспоненциально — до 200 уровня
    нужно было ~782 трлн опыта (недостижимо). Теперь квадратичная кривая: всего ~8,7 млн."""
    level = max(1, int(level))
    return math.ceil(150 + 40 * level + 3 * level * level)

