def infer_weapon_type(weapon: Optional[dict]) -> str:
    if not weapon:
        return "melee"
    if weapon.get("weapon_type") in ("melee", "bow", "magic"):
        return weapon["weapon_type"]
    wid = str(weapon.get("id", "")).lower()
    name = str(weapon.get("name", "")).lower()
    if any(key in wid or key in name for key in ("bow", "crossbow", "лук", "арбалет")):
        return "bow"
    if any(key in wid or key in name for key in ("staff", "wand", "orb", "tome", "посох", "палоч", "сфера", "том", "маг")):
        return "magic"
    return "melee"

for rarity_weapons in WEAPONS.values():
    for weapon in rarity_weapons:
        weapon.setdefault("weapon_type", infer_weapon_type(weapon))

