class Database:
    def __init__(self):
        self.data: Dict = {}
        self._loaded = False
        self._save_lock = asyncio.Lock()

    async def load(self):
        if self._loaded:
            return
        self.data = await load_all_users()
        self._loaded = True
        init_user_log_snapshots()

    async def save(self):
        async with self._save_lock:
            await upsert_many(self.data)
        lines = [build_user_change_log(uid, u, fast=True) for uid, u in list(self.data.items())]
        await write_activity_lines(lines)

    async def save_users(self, user_ids) -> None:
        """Сохраняет только указанных игроков (вместо всей базы)."""
        subset = {str(uid): self.data[str(uid)] for uid in user_ids if str(uid) in self.data}
        if not subset:
            return
        async with self._save_lock:
            await upsert_many(subset)
        lines = [build_user_change_log(uid, u, fast=True) for uid, u in subset.items()]
        await write_activity_lines(lines)

    async def has_user(self, user_id: int) -> bool:
        await self.load()
        return str(user_id) in self.data

    async def is_name_taken(self, name: str, exclude_user_id: Optional[int] = None) -> bool:
        await self.load()
        normalized = name.casefold()
        excluded_uid = str(exclude_user_id) if exclude_user_id is not None else None
        for uid, user in self.data.items():
            if uid == excluded_uid:
                continue
            if str(user.get("name", "")).casefold() == normalized:
                return True
        return False

    async def get_user(self, user_id: int, create: bool = False, name: str = "") -> Optional[dict]:
        await self.load()
        uid = str(user_id)
        if uid not in self.data:
            if not create:
                return None
            self.data[uid] = create_default_user(name)
            await self.save()
        migrated = False
        if "trash" not in self.data[uid]:
            self.data[uid]["trash"] = []
            migrated = True
        if "rarity_stats" not in self.data[uid]:
            self.data[uid]["rarity_stats"] = {rarity: 0 for rarity in RARITIES}
            migrated = True
        else:
            for rarity in RARITIES:
                if rarity not in self.data[uid]["rarity_stats"]:
                    self.data[uid]["rarity_stats"][rarity] = 0
                    migrated = True
        if "equipped_armor" not in self.data[uid]:
            self.data[uid]["equipped_armor"] = {slot: None for slot in ARMOR_SLOTS}
            migrated = True
        else:
            # Миграция: добавляем недостающие слоты (bracers_left, bracers_right)
            for slot in ARMOR_SLOTS:
                if slot not in self.data[uid]["equipped_armor"]:
                    self.data[uid]["equipped_armor"][slot] = None
                    migrated = True
        quests = self.data[uid].setdefault("quests", {})
        for quest_id in QUESTS:
            if quest_id not in quests:
                quests[quest_id] = {"claimed": False, "notified": False}
                migrated = True
                continue
            quest_state = quests[quest_id]
            if "claimed" not in quest_state:
                quest_state["claimed"] = False
                migrated = True
            if "notified" not in quest_state:
                quest_state["notified"] = False
                migrated = True
        if "auto_roll_unlocked" not in self.data[uid]:
            self.data[uid]["auto_roll_unlocked"] = bool(quests[AUTO_ROLL_QUEST_ID].get("claimed"))
            migrated = True
        if "auto_roll_filters" not in self.data[uid]:
            self.data[uid]["auto_roll_filters"] = []
            migrated = True
        else:
            valid_filters = [rarity for rarity in self.data[uid]["auto_roll_filters"] if rarity in RARITIES]
            if valid_filters != self.data[uid]["auto_roll_filters"]:
                self.data[uid]["auto_roll_filters"] = valid_filters
                migrated = True
        if "auto_roll_essence" not in self.data[uid]:
            self.data[uid]["auto_roll_essence"] = []
            migrated = True
        else:
            valid_essence = [rarity for rarity in self.data[uid]["auto_roll_essence"] if rarity in AUTO_ROLL_ESSENCE_RARITIES]
            if valid_essence != self.data[uid]["auto_roll_essence"]:
                self.data[uid]["auto_roll_essence"] = valid_essence
                migrated = True
        if "auto_roll_session" not in self.data[uid]:
            self.data[uid]["auto_roll_session"] = {"items": [], "running": False, "until": 0}
            migrated = True
        if "auto_roll_end_notified" not in self.data[uid]:
            self.data[uid]["auto_roll_end_notified"] = False
            migrated = True
        if "nickname_custom_emoji_ids" not in self.data[uid] or not isinstance(self.data[uid].get("nickname_custom_emoji_ids"), list):
            self.data[uid]["nickname_custom_emoji_ids"] = []
            migrated = True
        if "nickname_custom_emoji_texts" not in self.data[uid] or not isinstance(self.data[uid].get("nickname_custom_emoji_texts"), list):
            self.data[uid]["nickname_custom_emoji_texts"] = []
            migrated = True
        if "tg_xp_bonus" not in self.data[uid]:
            self.data[uid]["tg_xp_bonus"] = False
            migrated = True
        if "tg_display_name" not in self.data[uid]:
            self.data[uid]["tg_display_name"] = ""
            migrated = True
        if "active_battle" not in self.data[uid]:
            self.data[uid]["active_battle"] = None
            migrated = True
        if "locked_iids" not in self.data[uid]:
            self.data[uid]["locked_iids"] = []
            migrated = True
        if "rebirths" not in self.data[uid]:
            self.data[uid]["rebirths"] = 0
            migrated = True
        if "boss_loot" not in self.data[uid]:
            self.data[uid]["boss_loot"] = {}
            migrated = True
        if "active_buffs" not in self.data[uid]:
            self.data[uid]["active_buffs"] = {}
            migrated = True
        else:
            now = time.time()
            active_buffs = {
                key: exp
                for key, exp in self.data[uid].get("active_buffs", {}).items()
                if exp > now
            }
            if active_buffs != self.data[uid].get("active_buffs", {}):
                self.data[uid]["active_buffs"] = active_buffs
                migrated = True
        if "witch_potions" not in self.data[uid]:
            self.data[uid]["witch_potions"] = []
            migrated = True
        if "active_brew" not in self.data[uid]:
            self.data[uid]["active_brew"] = None
            migrated = True
        if "pets" not in self.data[uid] or not isinstance(self.data[uid].get("pets"), list):
            self.data[uid]["pets"] = []
            migrated = True
        equipped_pets = self.data[uid].get("equipped_pets")
        if not isinstance(equipped_pets, list):
            equipped_pets = []
        while len(equipped_pets) < 2:
            equipped_pets.append(None)
            migrated = True
        if len(equipped_pets) > 2:
            equipped_pets = equipped_pets[:2]
            migrated = True
        if equipped_pets != self.data[uid].get("equipped_pets"):
            self.data[uid]["equipped_pets"] = equipped_pets
            migrated = True
        if "pet_eggs" not in self.data[uid]:
            self.data[uid]["pet_eggs"] = {}
            migrated = True
        pet_incubator = self.data[uid].get("pet_incubator")
        if not isinstance(pet_incubator, list):
            pet_incubator = []
        while len(pet_incubator) < 1:
            pet_incubator.append({"egg_id": None, "started_at": 0, "ready_at": 0})
            migrated = True
        if len(pet_incubator) > 1:
            pet_incubator = pet_incubator[:1]
            migrated = True
        for idx, slot in enumerate(pet_incubator):
            if not isinstance(slot, dict):
                pet_incubator[idx] = {"egg_id": None, "started_at": 0, "ready_at": 0}
                migrated = True
                continue
            for key, default in (("egg_id", None), ("started_at", 0), ("ready_at", 0)):
                if key not in slot:
                    slot[key] = default
                    migrated = True
        if pet_incubator != self.data[uid].get("pet_incubator"):
            self.data[uid]["pet_incubator"] = pet_incubator
            migrated = True
        if "marshmallows" not in self.data[uid]:
            self.data[uid]["marshmallows"] = 0
            migrated = True
        if "boss_kills" not in self.data[uid]:
            self.data[uid]["boss_kills"] = 0
            migrated = True
        if "boss_location_kills" not in self.data[uid]:
            self.data[uid]["boss_location_kills"] = {}
            migrated = True
        if "boss_defeats" not in self.data[uid]:
            self.data[uid]["boss_defeats"] = {}
            migrated = True
        if "clan_id" not in self.data[uid]:
            self.data[uid]["clan_id"] = None
            migrated = True
        if "boss_cd_notified" not in self.data[uid] or not isinstance(self.data[uid].get("boss_cd_notified"), dict):
            self.data[uid]["boss_cd_notified"] = {}
            migrated = True
        if "daily_stats" not in self.data[uid]:
            self.data[uid]["daily_stats"] = {}
            migrated = True
        skills = self.data[uid].get("skills")
        if not isinstance(skills, dict):
            skills = {}
            self.data[uid]["skills"] = skills
            migrated = True
        normalized_skills = {}
        for skill_id in SKILL_DEFS:
            try:
                level = int(skills.get(skill_id, 0))
            except (TypeError, ValueError):
                level = 0
            normalized_skills[skill_id] = max(0, min(SKILL_MAX_LEVEL, level))
        if normalized_skills != skills:
            self.data[uid]["skills"] = normalized_skills
            skills = normalized_skills
            migrated = True
        if "skill_points" not in self.data[uid]:
            spent_points = sum(skills.values())
            self.data[uid]["skill_points"] = max(0, int(self.data[uid].get("level", 1)) - 1 - spent_points)
            migrated = True
        if self.data[uid].get("path") not in PATHS:
            if self.data[uid].get("path") is not None:
                migrated = True
            self.data[uid]["path"] = None
        if "path_level" not in self.data[uid]:
            self.data[uid]["path_level"] = 1
            migrated = True
        else:
            try:
                self.data[uid]["path_level"] = max(1, min(PATH_MAX_LEVEL, int(self.data[uid].get("path_level") or 1)))
            except (TypeError, ValueError):
                self.data[uid]["path_level"] = 1
                migrated = True
        if "path_xp" not in self.data[uid]:
            self.data[uid]["path_xp"] = 0
            migrated = True
        if "path_skill_cooldowns" not in self.data[uid] or not isinstance(self.data[uid].get("path_skill_cooldowns"), dict):
            self.data[uid]["path_skill_cooldowns"] = {}
            migrated = True
        if "mannequins" not in self.data[uid] or not isinstance(self.data[uid].get("mannequins"), dict):
            self.data[uid]["mannequins"] = {}
            migrated = True
        else:
            before_mannequins = json.dumps(self.data[uid]["mannequins"], sort_keys=True, ensure_ascii=False)
            normalize_mannequins(self.data[uid])
            after_mannequins = json.dumps(self.data[uid]["mannequins"], sort_keys=True, ensure_ascii=False)
            if before_mannequins != after_mannequins:
                migrated = True
        if "last_seen_at" not in self.data[uid]:
            self.data[uid]["last_seen_at"] = 0
            migrated = True
        if "last_seen_date" not in self.data[uid]:
            self.data[uid]["last_seen_date"] = ""
            migrated = True

        inventory = self.data[uid].setdefault("inventory", [])
        # Тяжёлая миграция предметов (сотни вещей) — только если состав предметов изменился
        eq_now = self.data[uid].get("equipped")
        items_sig = (
            len(inventory), len(self.data[uid].get("trash") or []),
            eq_now.get("iid") if isinstance(eq_now, dict) else None,
            tuple((p or {}).get("iid") for p in (self.data[uid].get("equipped_armor") or {}).values()),
            inventory[-1].get("iid") if inventory and isinstance(inventory[-1], dict) else None,
        )
        if _items_migrated_sig.get(uid) == items_sig:
            if migrated:
                await upsert_user(user_id, self.data[uid])
            return self.data[uid]
        for weapon in inventory:
            if ensure_weapon_power(weapon):
                migrated = True

        equipped = self.data[uid].get("equipped")
        if equipped and ensure_weapon_power(equipped):
            migrated = True

        for trash_item in self.data[uid].get("trash", []):
            weapon = trash_item.get("item", {})
            if ensure_weapon_power(weapon):
                migrated = True

        # Миграция: добавляем уникальный iid старым предметам
        all_items = list(inventory)
        if equipped:
            all_items.append(equipped)
        for slot in ARMOR_SLOTS:
            piece = self.data[uid].get("equipped_armor", {}).get(slot)
            if piece:
                all_items.append(piece)
        for trash_item in self.data[uid].get("trash", []):
            all_items.append(trash_item.get("item", {}))
        for item in all_items:
            if item and "iid" not in item:
                item["iid"] = random.randint(100000000, 999999999)
                migrated = True
            if item and "engraving_level" not in item:
                item["engraving_level"] = 0
                migrated = True
            if item and apply_item_fusion_stats(item):
                migrated = True

        _items_migrated_sig[uid] = items_sig
        if migrated:
            await upsert_user(user_id, self.data[uid])
        return self.data[uid]

    async def save_user(self, user_id: int, data: dict):
        self.data[str(user_id)] = data
        await upsert_user(user_id, data)
        line = build_user_change_log(user_id, data)
        if line:
            await write_activity_lines([line])

    async def reset_user(self, user_id: int) -> bool:
        await self.load()
        uid = str(user_id)
        existed = uid in self.data
        self.data.pop(uid, None)
        await delete_user(user_id)
        return existed

