NOTIFY_MAX_PER_SECOND = 20          # Telegram режет бота целиком при ~30 сообщениях/сек
_notify_lock = asyncio.Lock()
_notify_last_sent = 0.0


async def send_user_notification(user_id: int, text: str, reply_markup=None) -> bool:
    """Уведомления в ЛС идут с ограничением скорости.
    Массовые рассылки (Лутиафан в 00:00, боссы, питомцы) больше не упираются во флуд-лимит Telegram,
    который на время блокирует ВСЕ ответы бота — поэтому бот и «лежал» по ночам."""
    global _notify_last_sent
    if not NOTIFY_BOT:
        return False
    for attempt in range(2):
        async with _notify_lock:
            wait = _notify_last_sent + 1.0 / NOTIFY_MAX_PER_SECOND - time.time()
            if wait > 0:
                await asyncio.sleep(wait)
            _notify_last_sent = time.time()
        try:
            await NOTIFY_BOT.send_message(
                user_id,
                text,
                reply_markup=reply_markup,
                parse_mode="HTML",
                disable_web_page_preview=True,
            )
            return True
        except Exception as e:
            retry = getattr(e, "retry_after", None)
            if retry and attempt == 0:
                print(f"[send_user_notification] flood, ждём {retry} c")
                async with _notify_lock:
                    await asyncio.sleep(float(retry) + 0.5)  # притормаживаем все уведомления разом
                continue
            print(f"[send_user_notification] failed uid={user_id}: {e}")
            return False
    return False

def get_empty_auto_roll_session() -> dict:
    return {"items": [], "running": False, "until": 0}

async def save_runtime_state(user_id: int, user: Optional[dict] = None):
    user = user or await db.get_user(user_id)
    if not user:
        return
    _lazy_dirty.pop(user_id, None)
    user["auto_roll_session"] = auto_roll_sessions.get(user_id, get_empty_auto_roll_session())
    battle = active_battles.get(user_id)
    if battle:
        battle_to_save = copy.deepcopy(battle)
        battle_to_save["busy"] = False
        user["active_battle"] = battle_to_save
    else:
        user["active_battle"] = None
    await db.save_user(user_id, user)

AUTO_ROLL_SAVE_INTERVAL = 20.0
_lazy_dirty: Dict[int, float] = {}       # user_id → время первой несохранённой правки
_lazy_last_saved: Dict[int, float] = {}


async def save_runtime_state_lazy(user_id: int, user: dict):
    """Отложенное сохранение для частых мелких изменений (авторолл)."""
    now = time.time()
    if now - _lazy_last_saved.get(user_id, 0) >= AUTO_ROLL_SAVE_INTERVAL:
        _lazy_dirty.pop(user_id, None)
        _lazy_last_saved[user_id] = now
        await save_runtime_state(user_id, user)
    else:
        _lazy_dirty.setdefault(user_id, now)


async def flush_lazy_saves(force: bool = False):
    now = time.time()
    for user_id in list(_lazy_dirty):
        if force or now - _lazy_dirty[user_id] >= AUTO_ROLL_SAVE_INTERVAL:
            _lazy_dirty.pop(user_id, None)
            _lazy_last_saved[user_id] = now
            try:
                await save_runtime_state(user_id)
            except Exception as e:
                print(f"[lazy save] {user_id}: {e}")


async def lazy_save_loop():
    while True:
        await asyncio.sleep(5)
        try:
            await flush_lazy_saves()
        except Exception as e:
            print(f"[lazy_save_loop] {e}")


async def save_battle_state_throttled(user_id: int, user: dict, force: bool = False):
    """Сохранение боя не задерживает ход: запись в базу уходит в фон."""
    battle = active_battles.get(user_id)
    if not battle:
        await save_runtime_state(user_id, user)
        return
    now = time.time()
    if not force and now - battle.get("last_saved_at", 0) < BATTLE_SAVE_INTERVAL_SECONDS:
        _lazy_dirty.setdefault(user_id, now)  # всё равно сохранится фоновым циклом
        return
    battle["last_saved_at"] = now
    _spawn_background_save(user_id, user)


_bg_save_tasks: Dict[int, asyncio.Task] = {}


def _spawn_background_save(user_id: int, user: dict) -> None:
    prev = _bg_save_tasks.get(user_id)

    async def _run():
        if prev and not prev.done():
            try:
                await prev  # сохраняем строго по порядку
            except Exception:
                pass
        try:
            await save_runtime_state(user_id, user)
        except Exception as e:
            print(f"[bg save] {user_id}: {e}")

    try:
        _bg_save_tasks[user_id] = asyncio.get_running_loop().create_task(_run())
    except RuntimeError:
        pass

def is_boss_battle_expired(battle: Optional[dict]) -> bool:
    if not battle or battle.get("mode") != "bosses":
        return False
    last_action = float(battle.get("last_action_at") or battle.get("created_at") or time.time())
    return time.time() - last_action >= BOSS_BATTLE_IDLE_TIMEOUT_SECONDS

async def clear_expired_boss_battle(user_id: int, user: Optional[dict] = None) -> bool:
    battle = active_battles.get(user_id)
    if not is_boss_battle_expired(battle):
        return False
    active_battles.pop(user_id, None)
    if user is None:
        user = await db.get_user(user_id)
    await save_runtime_state(user_id, user)
    return True

def build_lock_keys_from_iids(user: dict) -> set:
    locked_iids = set(user.get("locked_iids", []))
    if not locked_iids:
        return set()
    keys = set()
    copy_counts = {}
    for item in user.get("inventory", []):
        item_id = item.get("id")
        copy_idx = copy_counts.get(item_id, 0)
        copy_counts[item_id] = copy_idx + 1
        if item.get("iid") in locked_iids:
            keys.add(f"{item_id}|{copy_idx}")
    return keys

def save_lock_session_to_user(user_id: int, user: dict):
    locked_keys = lock_sessions.get(user_id, set())
    locked_iids = []
    copy_counts = {}
    for item in user.get("inventory", []):
        item_id = item.get("id")
        copy_idx = copy_counts.get(item_id, 0)
        copy_counts[item_id] = copy_idx + 1
        if f"{item_id}|{copy_idx}" in locked_keys and item.get("iid"):
            locked_iids.append(item["iid"])
    user["locked_iids"] = locked_iids[:50]

def restore_lock_session_from_user(user_id: int, user: dict):
    lock_sessions[user_id] = build_lock_keys_from_iids(user)

