def message_command(message: Message) -> str:
    text = (message.text or "").strip().casefold()
    if not text:
        return ""
    first = text.split()[0]
    if first.startswith("/"):
        first = first[1:]
    if "@" in first:
        first = first.split("@", 1)[0]
    return first

def is_text_command(message: Message, *commands: str) -> bool:
    return message_command(message) in {cmd.casefold() for cmd in commands}

def get_message_custom_emoji_data(message: Message) -> tuple[List[str], List[str]]:
    ids = []
    texts = []
    text = message.text or message.caption or ""
    entities = message.entities or message.caption_entities or []
    for entity in entities:
        if getattr(entity, "type", None) != "custom_emoji":
            continue
        custom_emoji_id = getattr(entity, "custom_emoji_id", None)
        if custom_emoji_id:
            ids.append(str(custom_emoji_id))
        try:
            entity_text = entity.extract_from(text)
        except Exception:
            entity_text = ""
        if entity_text:
            texts.append(entity_text)
    return ids, texts

def render_nickname_html(name: str, ids: Optional[List[str]] = None, texts: Optional[List[str]] = None) -> str:
    """Ник в HTML: эмодзи, которые игрок вводил премиумом, снова показываются премиум-эмодзи."""
    result = html.escape(str(name or ""))
    ids = list(ids or [])
    texts = list(texts or [])
    pos = 0
    for emoji_id, emoji_text in zip(ids, texts):
        if not emoji_text:
            continue
        idx = result.find(emoji_text, pos)
        if idx < 0:
            continue
        tag = f'<tg-emoji emoji-id="{emoji_id}">{emoji_text}</tg-emoji>'
        result = result[:idx] + tag + result[idx + len(emoji_text):]
        pos = idx + len(tag)
    return result


def render_user_nickname(user: Optional[dict], fallback: str = "Игрок") -> str:
    user = user or {}
    return render_nickname_html(
        user.get("name") or fallback,
        user.get("nickname_custom_emoji_ids"),
        user.get("nickname_custom_emoji_texts"),
    )


