class CallbackOwnerMiddleware(BaseMiddleware):
    async def __call__(
        self,
        handler: Callable[[Any, Dict[str, Any]], Awaitable[Any]],
        event: Any,
        data: Dict[str, Any],
    ) -> Any:
        if not isinstance(event, CallbackQuery) or not event.message:
            return await handler(event, data)
        owner_id = interactive_message_owners.get((event.message.chat.id, event.message.message_id))
        if owner_id is not None and event.from_user and event.from_user.id != owner_id:
            await event.answer("Это не твои кнопки.", show_alert=True)
            return None
        return await handler(event, data)

dp.callback_query.middleware(CallbackOwnerMiddleware())

