BOSS_HARD_MIN_LEVEL = 35
BOSS_HARD_XP_MULTIPLIER = 2
BOSS_HARD_COOLDOWN_MULTIPLIER = 1.5
BOSS_HARD_HP_MULTIPLIER = 2.5
BOSS_HARD_DAMAGE_MULTIPLIER = 1.8
BOSS_HARD_POWER_MULTIPLIER = 3
NIGHT_EVENT_MSK_START_HOUR = 0
NIGHT_EVENT_MSK_END_HOUR = 6
# ====== ЛОКАЦИИ И БОССЫ ======

def get_msk_now() -> datetime:
    return datetime.utcnow() + timedelta(hours=3)

def is_night_event_active(now: Optional[datetime] = None) -> bool:
    now = now or get_msk_now()
    return NIGHT_EVENT_MSK_START_HOUR <= now.hour < NIGHT_EVENT_MSK_END_HOUR

def get_night_event_time_left(now: Optional[datetime] = None) -> int:
    now = now or get_msk_now()
    if is_night_event_active(now):
        end = now.replace(hour=NIGHT_EVENT_MSK_END_HOUR, minute=0, second=0, microsecond=0)
        return max(0, int((end - now).total_seconds()))
    start = now.replace(hour=NIGHT_EVENT_MSK_START_HOUR, minute=0, second=0, microsecond=0)
    if now.hour >= NIGHT_EVENT_MSK_END_HOUR:
        start += timedelta(days=1)
    return max(0, int((start - now).total_seconds()))

def is_boss_hard_mode_enabled(user: Optional[dict]) -> bool:
    if not user:
        return False
    return bool(user.get("boss_hard_mode")) and int(user.get("level", 1)) >= BOSS_HARD_MIN_LEVEL

def get_boss_hp_multiplier(hard_mode: bool = False) -> float:
    multiplier = 2 if is_night_event_active() else 1
    if hard_mode:
        multiplier *= BOSS_HARD_HP_MULTIPLIER
    return multiplier

def get_boss_damage_multiplier(hard_mode: bool = False) -> float:
    multiplier = BOSS_DAMAGE_MULTIPLIER
    if is_night_event_active():
        multiplier *= 2
    if hard_mode:
        multiplier *= BOSS_HARD_DAMAGE_MULTIPLIER
    return multiplier

def get_effective_boss_power(boss: dict, hard_mode: bool = False) -> int:
    power = int(boss.get("power", 0))
    return power * BOSS_HARD_POWER_MULTIPLIER if hard_mode else power

def apply_night_event_boss_xp(xp: int) -> int:
    if is_night_event_active():
        return math.ceil(xp * 1.5)
    return xp

def apply_boss_hard_xp(xp: int, hard_mode: bool = False) -> int:
    if hard_mode:
        return math.ceil(xp * BOSS_HARD_XP_MULTIPLIER)
    return xp

def apply_night_event_rare_resource_chance(chance: int) -> int:
    if is_night_event_active():
        return max(1, math.floor(chance * 0.5))
    return chance

def apply_night_event_fragment_chance(chance: int) -> int:
    if is_night_event_active():
        return min(100, math.ceil(chance * 1.5))
    return chance

