# Активная варка хранится в самом user'е (user["active_brew"] = {"started_at": float})
# чтобы переживать рестарт бота.
def get_active_brew(user: dict) -> Optional[dict]:
    return user.get("active_brew")

def set_active_brew(user: dict, brew: Optional[dict]):
    if brew is None:
        user.pop("active_brew", None)
    else:
        user["active_brew"] = brew

def get_active_buffs(user: dict) -> dict:
    """Возвращает словарь активных баффов {buff_key: expires_at}"""
    now = time.time()
    buffs = user.get("active_buffs", {})
    return {k: v for k, v in buffs.items() if v > now}

def has_buff(user: dict, buff_key: str) -> bool:
    return get_active_buffs(user).get(buff_key, 0) > time.time()

def buff_remaining(user: dict, buff_key: str) -> int:
    exp = get_active_buffs(user).get(buff_key, 0)
    return max(0, int(exp - time.time()))

def format_buff_time(seconds: int) -> str:
    m = seconds // 60
    s = seconds % 60
    return f"{m}м {s:02d}с"

def apply_damage_buff(user: dict, damage: int) -> int:
    damage = math.ceil(damage * get_damage_multiplier(user))
    if has_buff(user, "damage_strong"):
        damage = math.ceil(damage * 1.35)
    elif has_buff(user, "nightmare"):
        damage = math.ceil(damage * 1.25)
    elif has_buff(user, "damage"):
        damage = math.ceil(damage * 1.20)
    return damage

def apply_xp_buff(user: dict, xp: int) -> int:
    xp = math.ceil(xp * get_xp_skill_multiplier(user))
    if has_star_pass(user):
        xp = math.ceil(xp * (1 + STAR_PASS_XP_BONUS))
    if has_buff(user, "xp"):
        xp = math.ceil(xp * 1.10)
    if has_nickname_xp_bonus(user):
        xp = math.ceil(xp * 1.10)
    if has_bio_xp_bonus(user):
        xp = math.ceil(round(xp * (1 + BIO_XP_BONUS), 6))  # round: 100×1.1 = 110.00000000000001 → не 111
    clan = get_user_clan(user)
    clan_xp = get_clan_buff_bonus(clan, "xp")
    if clan_xp:
        xp = math.ceil(xp * (1 + clan_xp / 100))
    return xp

def apply_coin_buff(user: dict, coins: int) -> int:
    coins = math.ceil(coins * (1 + get_path_bonus(user, "coins") / 100))
    if has_star_pass(user):
        coins = math.ceil(coins * (1 + STAR_PASS_COIN_BONUS))
    if has_buff(user, "coins"):
        return math.ceil(coins * 1.30)
    return coins

def get_luck_rarity_chances(user: dict, rebirths: int) -> dict:
    """Базовые шансы + бонус зелья удачи (+15% к редким шансам)"""
    chances = get_rebirth_rarity_chances(rebirths)
    luck_multiplier = get_luck_skill_multiplier(user)
    if has_buff(user, "luck"):
        luck_multiplier *= 1.15
    if luck_multiplier <= 1:
        return chances
    # Увеличиваем шансы редкостей на 15%
    boosted = {}
    for rarity in ("uncommon", "rare", "epic", "legendary", "mythic", "nightmare"):
        boosted[rarity] = chances[rarity] * luck_multiplier
    boosted_total = sum(boosted.values())
    remaining = max(0, 100 - boosted_total)
    base_common = chances.get("common", 0)
    boosted["common"] = remaining if base_common > 0 else 0
    return boosted

def get_boss_loot_chance_with_luck(boss: dict, user: dict) -> int:
    base = get_boss_loot_chance(boss)
    base = math.ceil(base * get_luck_skill_multiplier(user))
    if has_buff(user, "luck"):
        base = min(100, math.ceil(base * 1.15))
    base = apply_night_event_rare_resource_chance(base)
    return min(100, base)

def get_boss_fragment_chance_with_luck(boss: dict, user: dict) -> int:
    base = get_boss_fragment_chance(boss)
    base = math.ceil(base * get_luck_skill_multiplier(user))
    if has_buff(user, "luck"):
        base = min(100, math.ceil(base * 1.15))
    base = apply_night_event_fragment_chance(base)
    return min(100, base)

def get_boss_engraving_shard_chance_with_luck(boss: dict, user: dict) -> int:
    base = get_boss_engraving_shard_chance(boss)
    base = math.ceil(base * get_luck_skill_multiplier(user))
    if has_buff(user, "luck"):
        base = min(100, math.ceil(base * 1.15))
    return min(100, base)

def get_potions_in_inventory(user: dict) -> List[dict]:
    return [item for item in user.get("witch_potions", []) if isinstance(item, dict)]

def add_potion_to_user(user: dict, potion_id: str):
    user.setdefault("witch_potions", []).append({"potion_id": potion_id})

def remove_potion_from_user(user: dict, potion_id: str) -> bool:
    potions = user.get("witch_potions", [])
    for i, p in enumerate(potions):
        if p.get("potion_id") == potion_id:
            potions.pop(i)
            return True
    return False

def use_potion(user: dict, potion_id: str) -> bool:
    """Применить зелье из инвентаря. Возвращает True если успешно."""
    if not remove_potion_from_user(user, potion_id):
        return False
    potion = POTION_DEFS.get(potion_id)
    if not potion:
        return False
    buffs = user.setdefault("active_buffs", {})
    current = buffs.get(potion["buff_key"], 0)
    base = max(current, time.time())  # если бафф ещё идёт — добавляем к остатку
    buffs[potion["buff_key"]] = base + WITCH_POTION_BUFF_SECONDS
    return True

def get_buff_line(user: dict) -> str:
    """Краткая строка для отображения активных баффов."""
    active = get_active_buffs(user)
    if not active:
        return ""
    parts = []
    buff_emojis = {
        "damage": '<tg-emoji emoji-id="5373173798633752502">🛡</tg-emoji>',
        "xp": '<tg-emoji emoji-id="5431816358675366190">🆙</tg-emoji>',
        "luck": '<tg-emoji emoji-id="5395325195542078574">🍀</tg-emoji>',
        "speed": '<tg-emoji emoji-id="5287473790735890430">⏳</tg-emoji>',
        "coins": '<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji>',
    }
    for key in ("damage", "xp", "luck", "speed", "coins"):
        if key in active:
            mins = buff_remaining(user, key) // 60
            parts.append(f"{buff_emojis[key]}{mins}м")
    return " | ".join(parts)


def get_weapon_enchant(user: dict) -> Optional[dict]:
    enc = user.get("weapon_enchant")
    if not enc:
        return None
    if enc.get("expires_at", 0) <= time.time():
        user.pop("weapon_enchant", None)
        return None
    return enc


def get_enchant_display_emoji(enc: Optional[dict]) -> str:
    """Премиум-эмодзи зачарования из BOSS_RESOURCE_DEFS, иначе сохранённый/дефолт."""
    if not enc:
        return "✨"
    loot_id = enc.get("id")
    info = BOSS_RESOURCE_DEFS.get(loot_id, {}) if loot_id else {}
    return info.get("emoji") or enc.get("emoji") or "✨"


def get_enchant_damage_bonus(user: Optional[dict]) -> float:
    if not user:
        return 0.0
    enc = get_weapon_enchant(user)
    if not enc:
        return 0.0
    return float(enc.get("damage_bonus", 0) or 0)

def get_enchant_crit_bonus(user: Optional[dict]) -> float:
    if not user:
        return 0.0
    enc = get_weapon_enchant(user)
    if not enc:
        return 0.0
    return float(enc.get("crit_bonus", 0) or 0)

async def show_enchanter(user_id: int, answer_func):
    user = await db.get_user(user_id)
    resources = user.get("boss_loot", {})
    enc = get_weapon_enchant(user)
    equipped = user.get("equipped")

    status = ""
    if enc:
        left = max(0, int(enc["expires_at"] - time.time()))
        hours = left // 3600
        mins = (left % 3600) // 60
        status = (
            f"\n\n<tg-emoji emoji-id=\"5370831521039017384\">✨</tg-emoji> <b>Активное зачарование:</b> {get_enchant_display_emoji(enc)} {html.escape(enc.get('name', ''))}\n"
            f"{html.escape(enc.get('description', ''))}\n"
            f"<tg-emoji emoji-id=\"5287473790735890430\">⏳</tg-emoji> Осталось: <b>{hours}ч {mins}м</b>"
        )
    else:
        status = "\n\n<tg-emoji emoji-id=\"5370831521039017384\">✨</tg-emoji> Сейчас оружие <b>не зачаровано</b>."

    if not equipped:
        status += "\n\n⚠️ Сначала экипируй оружие — зачарование вешается на текущее экипированное."

    loot_lines = []
    for loot_id, edef in WEAPON_ENCHANT_DEFS.items():
        cnt = resources.get(loot_id, 0)
        info = BOSS_RESOURCE_DEFS.get(loot_id, {})
        emoji = info.get("emoji", edef["emoji"])
        loot_lines.append(
            f"{emoji} {edef['name']}: <b>{cnt}</b> (нужно {edef['cost']}) — {edef['description']}"
        )

    text = (
        "<tg-emoji emoji-id=\"5287734091523829559\">🔮</tg-emoji> <b>Зачарователь</b>\n\n"
        "<blockquote>Накладывает чары на <b>экипированное оружие</b> на 12 часов.\n"
        "Расходует лут боссов: осколки ночи с Тёмного леса или редкий лут с финальных боссов.</blockquote>\n\n"
        "<blockquote>" + "\n".join(loot_lines) + "</blockquote>"
        + status
    )

    buttons = []
    if enc:
        # пока чары активны — новые наложить нельзя, только снять текущие
        buttons.append([InlineKeyboardButton(text="Снять зачарование", callback_data="enchant_remove|ask", icon_custom_emoji_id="5352669272575321097")])
    elif equipped:
        for loot_id, edef in WEAPON_ENCHANT_DEFS.items():
            cnt = resources.get(loot_id, 0)
            if cnt >= edef["cost"]:
                res_icon = premium_emoji_id(BOSS_RESOURCE_DEFS.get(loot_id, {}).get("emoji", ""))
                buttons.append([InlineKeyboardButton(
                    text=f"{edef['name']} (−{edef['cost']})" if res_icon else f"{edef['emoji']} {edef['name']} (−{edef['cost']})",
                    callback_data=f"enchant|{loot_id}",
                    icon_custom_emoji_id=res_icon,
                )])
    if enc:
        text += "\n\n<i>Новое зачарование можно наложить, когда действующее закончится или будет снято.</i>"
    if not buttons:
        if not equipped:
            buttons.append([InlineKeyboardButton(text="Нет экипированного оружия", callback_data="noop", icon_custom_emoji_id="5296369303661067030")])
        else:
            buttons.append([InlineKeyboardButton(text="Нет редкого лута", callback_data="noop", icon_custom_emoji_id="5296369303661067030")])
    buttons.append([InlineKeyboardButton(text="Закрыть", callback_data="noop", icon_custom_emoji_id="5215361191051798408")])

    await answer_func(text, InlineKeyboardMarkup(inline_keyboard=buttons))

@dp.callback_query(F.data.startswith("enchant_remove|"))
async def cb_enchant_remove(call: CallbackQuery):
    uid = call.from_user.id
    action = call.data.split("|", 1)[1]
    user = await db.get_user(uid)
    enc = get_weapon_enchant(user)
    if not enc:
        await call.answer("Активного зачарования нет.", show_alert=True)
        await show_enchanter(uid, lambda t, kb: edit_for_user(call, t, kb))
        return
    if action == "ask":
        await call.answer()
        left = max(0, int(enc["expires_at"] - time.time()))
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="Да, снять", callback_data="enchant_remove|do", icon_custom_emoji_id="5352669272575321097")],
            [InlineKeyboardButton(text="Отмена", callback_data="enchanter_open", icon_custom_emoji_id="5215361191051798408")],
        ])
        await edit_for_user(
            call,
            f'<tg-emoji emoji-id="5440660757194744323">‼️</tg-emoji> <b>Снять зачарование?</b>\n\n'
            f"<blockquote>{get_enchant_display_emoji(enc)} <b>{html.escape(enc.get('name', ''))}</b>\n"
            f"{html.escape(enc.get('description', ''))}\n"
            f"{PE_HOURGLASS} Осталось: <b>{left // 3600}ч {(left % 3600) // 60}м</b></blockquote>\n\n"
            f"<blockquote>{PE_CROSS} Чары пропадут, потраченный лут <b>не вернётся</b>.</blockquote>",
            kb,
        )
        return
    user.pop("weapon_enchant", None)
    await db.save_user(uid, user)
    await write_activity_log(f"ENCHANT {_log_user_name(uid, user)} | снял зачарование {enc.get('name')}")
    await call.answer("Зачарование снято.")
    await show_enchanter(uid, lambda t, kb: edit_for_user(call, t, kb))


@dp.callback_query(F.data == "enchanter_open")
async def cb_enchanter_open(call: CallbackQuery):
    await call.answer()
    await show_enchanter(call.from_user.id, lambda t, kb: edit_for_user(call, t, kb))


async def apply_weapon_enchant(user_id: int, loot_id: str, answer_func, popup_func=None):
    user = await db.get_user(user_id)
    edef = WEAPON_ENCHANT_DEFS.get(loot_id)
    if not edef:
        msg = "❌ Неизвестный тип зачарования."
        if popup_func:
            await popup_func(msg)
        else:
            await answer_func(premium_cross(msg), None)
        return
    equipped = user.get("equipped")
    if not equipped:
        msg = "❌ Экипируй оружие перед зачарованием."
        if popup_func:
            await popup_func(msg)
        else:
            await answer_func(premium_cross(msg), None)
        return
    active = get_weapon_enchant(user)
    if active:
        left = max(0, int(active["expires_at"] - time.time()))
        msg = (f"❌ Уже действует «{active.get('name', '')}» (ещё {left // 3600}ч {(left % 3600) // 60}м). "
               "Сначала сними его у чародея или дождись окончания.")
        if popup_func:
            await popup_func(msg)
        else:
            await answer_func(premium_cross(msg), None)
        return
    resources = user.setdefault("boss_loot", {})
    cost = edef["cost"]
    if resources.get(loot_id, 0) < cost:
        msg = f"❌ Нужно {cost}× {edef['name']}."
        if popup_func:
            await popup_func(msg)
        else:
            await answer_func(premium_cross(msg), None)
        return
    resources[loot_id] -= cost
    if resources[loot_id] <= 0:
        resources.pop(loot_id, None)
    res_emoji = BOSS_RESOURCE_DEFS.get(loot_id, {}).get("emoji") or edef["emoji"]
    user["weapon_enchant"] = {
        "id": loot_id,
        "name": edef["name"],
        "emoji": res_emoji,
        "description": edef["description"],
        "damage_bonus": edef["damage_bonus"],
        "crit_bonus": edef["crit_bonus"],
        "expires_at": time.time() + WEAPON_ENCHANT_DURATION,
        "weapon_uid": equipped.get("uid") or equipped.get("id"),
    }
    await db.save_user(user_id, user)
    # Обновляем экран зачарователя (с активным чаром)
    await show_enchanter(user_id, answer_func)

async def show_witch(user_id: int, answer_func):
    user = await db.get_user(user_id)
    resources = user.get("boss_loot", {})

    # Статус варки (хранится в user, переживает рестарт)
    brew = get_active_brew(user)
    brew_text = ""
    brew_ready = False
    if brew:
        elapsed = time.time() - brew["started_at"]
        if elapsed >= WITCH_BREW_DURATION_SECONDS:
            brew_ready = True
            brew_text = '\n<tg-emoji emoji-id="5416081784641168838">🟢</tg-emoji> <b>Зелье готово!</b> Нажми «Забрать зелье».'
            if not brew.get("notified"):
                brew["notified"] = True
                await db.save_user(user_id, user)
        else:
            remaining = int(WITCH_BREW_DURATION_SECONDS - elapsed)
            brew_text = f'\n<tg-emoji emoji-id="5787432469598835099">⏳</tg-emoji> Варка: осталось <b>{format_buff_time(remaining)}</b>'

    frag_lines = []
    for frag_id, fdef in FRAGMENT_BREW_DEFS.items():
        cnt = resources.get(frag_id, 0)
        frag_lines.append(f"{fdef['emoji']} {fdef['name']}: <b>{cnt}</b> (варка за {fdef['cost']})")

    text = (
        '<tg-emoji emoji-id="5895509368778001770">😡</tg-emoji> <b>Ведьма</b>\n\n'
        + "<blockquote>"
        + "\n".join(frag_lines)
        + "</blockquote>\n\n"
        + "<blockquote>Каждый тип фрагментов варится отдельно. Фрагменты новых локаций дают более сильные зелья."
        + brew_text
        + "</blockquote>\n\n"
        + '<blockquote>Готовые зелья юзай в <b>инвентаре</b> → <tg-emoji emoji-id="5445217335243732887">🧪</tg-emoji> Зелья.</blockquote>'
    )
    buttons = []
    if brew_ready:
        buttons.append([InlineKeyboardButton(text="Забрать зелье", callback_data="witch_claim", icon_custom_emoji_id="5293998404404272267")])
    elif not brew:
        for resource_id, fdef in FRAGMENT_BREW_DEFS.items():
            cnt = resources.get(resource_id, 0)
            if cnt >= fdef["cost"]:
                buttons.append([InlineKeyboardButton(
                    text=f"Сварить из {fdef['name']} ({fdef['cost']})",
                    callback_data=f"witch_brew|{resource_id}",
                    icon_custom_emoji_id="5355271322677047411",
                )])
        if not buttons:
            buttons.append([InlineKeyboardButton(text="Нет фрагментов", callback_data="noop", icon_custom_emoji_id="5296369303661067030")])
    else:
        buttons.append([InlineKeyboardButton(text="Варится...", callback_data="noop", icon_custom_emoji_id="5287473790735890430")])

    await answer_func(text, InlineKeyboardMarkup(inline_keyboard=buttons))

async def witch_brew_start(user_id: int, fragment_id: str, answer_func):
    user = await db.get_user(user_id)
    fdef = FRAGMENT_BREW_DEFS.get(fragment_id)
    if not fdef:
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Неизвестный тип фрагментов.", None)
        return
    resources = user.get("boss_loot", {})
    cost = fdef["cost"]
    if resources.get(fragment_id, 0) < cost:
        await answer_func(f"<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Нужно {cost} фрагментов ({fdef['name']}) для варки.", None)
        return
    if get_active_brew(user):
        await answer_func("⚗️ Зелье уже варится!", None)
        return
    resources[fragment_id] -= cost
    set_active_brew(user, {"started_at": time.time(), "fragment_id": fragment_id, "notified": False})
    await db.save_user(user_id, user)
    await show_witch(user_id, answer_func)

async def witch_brew_claim(user_id: int, answer_func):
    user = await db.get_user(user_id)
    brew = get_active_brew(user)
    if not brew:
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Нет активной варки.", None)
        return
    elapsed = time.time() - brew["started_at"]
    if elapsed < WITCH_BREW_DURATION_SECONDS:
        remaining = int(WITCH_BREW_DURATION_SECONDS - elapsed)
        await answer_func(f"<tg-emoji emoji-id=\"5287473790735890430\">⏳</tg-emoji> Ещё не готово. Осталось: {format_buff_time(remaining)}", None)
        return
    frag = brew.get("fragment_id")
    pool = FRAGMENT_POTION_POOLS.get(frag) or POTION_IDS
    pool = [p for p in pool if p in POTION_DEFS]
    if not pool:
        pool = list(POTION_DEFS.keys())
    potion_id = random.choice(pool)
    add_potion_to_user(user, potion_id)
    set_active_brew(user, None)
    await db.save_user(user_id, user)
    pdef = POTION_DEFS[potion_id]
    await answer_func(
        f"<tg-emoji emoji-id=\"5325762861539016690\">✅</tg-emoji> Зелье готово!\n{pdef['emoji']} <b>{pdef['name']}</b>\n{pdef['description']}\n\n"
        "Используй его в <b>инвентаре</b> → 🧪 Зелья.",
        None,
    )
    await show_witch(user_id, answer_func)

async def witch_use_potion(user_id: int, potion_id: str, answer_func):
    user = await db.get_user(user_id)
    if not use_potion(user, potion_id):
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> У тебя нет такого зелья.", None)
