        await answer_func(f"{title}\n\n<blockquote>" + "\u0410\u043a\u0442\u0438\u0432\u043d\u044b\u0445 \u0431\u0430\u0444\u0444\u043e\u0432 \u043d\u0435\u0442." + "</blockquote>", None)
