    title_emoji = '<tg-emoji emoji-id="5217822164362739968">👑</tg-emoji>'
    for loc_id, loc in LOCATIONS.items():
        if player_level < loc["min_level"]:
            continue
        loc_bosses = [b for b in BOSSES.values() if b["location"] == loc_id]
        loc_lines = []
        for boss in loc_bosses:
            cd = get_boss_cd_remaining(user, boss["id"])
            if cd > 0:
                status = f"{cooldown_emoji} <b>{format_cd_time(cd)}</b>"
            else:
                status = f"{ready_emoji} Готов"
            loc_lines.append(f"  {boss.get('premium_emoji', boss['emoji'])} {html.escape(boss['name'])}: {status}")
        if loc_lines:
            block = f"{loc.get('premium_emoji', loc['emoji'])} <b>{loc['name']}</b>\n" + "\n".join(loc_lines)
            lines.append(f"<blockquote>{block}</blockquote>")
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="Обновить", callback_data="bosscd_refresh", icon_custom_emoji_id="5346321684574003384")],
        [InlineKeyboardButton(
            text=f"Воскресить босса ({get_boss_revives_left(user)}/{get_boss_revive_limit(user)})",
            callback_data="rv_list|0", icon_custom_emoji_id="5325762861539016690",
        )],
    ])
    # время обновления — чтобы было видно, что нажатие сработало (и Telegram не ругался на «не изменилось»)
    updated = get_msk_now().strftime("%H:%M:%S")
    footer = f"\n\n<i>Обновлено в {updated} МСК</i>"
    if not lines:
        await answer_func(f"{title_emoji} <b>Кулдауны боссов</b>\n\nВсе боссы готовы к бою.{footer}", kb)
        return
    await answer_func(f"{title_emoji} <b>Кулдауны боссов</b>\n\n" + "\n".join(lines) + footer, kb)


