# ====== КД БОССОВ ======
BOSS_COOLDOWNS = {
    "swamp":   {"normal": 3 * 60,          "final": 10 * 60},
    "desert":  {"normal": 15 * 60,         "final": 45 * 60},
    "forest":  {"normal": 90 * 60,         "final": 4 * 60 * 60},
    "rift":    {"normal": 3 * 60 * 60,     "final": 12 * 60 * 60},
    "volcano": {"normal": 6 * 60 * 60,     "final": 18 * 60 * 60},
    "glacier": {"normal": 10 * 60 * 60,    "final": 24 * 60 * 60},
    "citadel": {"normal": 16 * 60 * 60,    "final": 36 * 60 * 60},
}

def get_boss_cooldown(boss: dict, user: Optional[dict] = None, hard_mode: Optional[bool] = None) -> int:
    loc_id = boss.get("location", "swamp")
    loc_bosses = [b for b in BOSSES.values() if b["location"] == loc_id]
    is_final = len(loc_bosses) > 0 and loc_bosses[-1]["id"] == boss["id"]
    cd = BOSS_COOLDOWNS.get(loc_id, {"normal": 0, "final": 0})
    cooldown = cd["final"] if is_final else cd["normal"]
    if is_night_event_active():
        cooldown = math.ceil(cooldown / 2)
    if hard_mode if hard_mode is not None else is_boss_hard_mode_enabled(user):
        cooldown = math.ceil(cooldown * BOSS_HARD_COOLDOWN_MULTIPLIER)
    return max(0, cooldown)

def get_boss_cd_remaining(user: dict, boss_id: str) -> int:
    cooldowns = user.get("boss_cooldowns", {})
    cd_end = cooldowns.get(boss_id, 0)
    return max(0, int(cd_end - time.time()))

def get_final_location_bosses() -> List[dict]:
    """Последний (самый сильный по level) босс каждой локации."""
    final_bosses = []
    for loc_id in LOCATIONS:
        loc_bosses = [boss for boss in BOSSES.values() if boss.get("location") == loc_id]
        if loc_bosses:
            loc_bosses.sort(key=lambda b: int(b.get("level", 0)))
            final_bosses.append(loc_bosses[-1])
    return final_bosses

