def format_cd_time(seconds: int) -> str:
    if seconds >= 3600:
        h = seconds // 3600
        m = (seconds % 3600) // 60
        return f"{h}ч {m}м" if m else f"{h}ч"
    m = seconds // 60
    s = seconds % 60
    return f"{m}м {s:02d}с" if s else f"{m}м"

def format_training_time(seconds: int) -> str:
    seconds = max(0, int(seconds))
    h = seconds // 3600
    m = (seconds % 3600) // 60
    s = seconds % 60
    if h:
        return f"{h}ч {m:02d}м {s:02d}с"
    return f"{m}м {s:02d}с"

def get_display_training_seconds(mannequin: dict) -> int:
    seconds = int(mannequin.get("training_seconds", 0))
    if mannequin.get("training_active"):
        elapsed = max(0, int(time.time() - float(mannequin.get("last_train_tick") or time.time())))
        seconds = max(0, seconds - elapsed)
    return seconds

