# не обесценивалась на высоких уровнях. Итог: max(xp, xp_share × опыт уровня).
# ============================================================

def _add_quest_chain(chain: str, start_requires: Optional[str], steps: List[dict]) -> None:
    prev = start_requires
    for step in steps:
        qid = step.pop("id")
        step.setdefault("chain", chain)
        step.setdefault("xp", 0)
        step["requires"] = prev
        QUESTS[qid] = step
        prev = qid


def _fmt_big(n: int) -> str:
    for value, suffix in ((10**12, " трлн"), (10**9, " млрд"), (10**6, " млн")):
        if n >= value:
            whole, rest = divmod(n, value)
            if rest == 0:
                return f"{whole}{suffix}"
            if (rest * 10) % value == 0:
                return f"{whole},{rest * 10 // value}{suffix}"
    return f"{n:,}".replace(",", " ")


