def _chain_last(chain: str) -> Optional[str]:
    ids = [qid for qid, q in QUESTS.items() if q.get("chain", qid) == chain]
    required = {QUESTS[q].get("requires") for q in ids}
    tail = [q for q in ids if q not in required]
    return tail[-1] if tail else (ids[-1] if ids else None)


