def get_quest_reward_xp(user: dict, quest: dict) -> int:
    """Фиксированный опыт или доля текущего уровня — что больше."""
    xp = int(quest.get("xp", 0) or 0)
    share = float(quest.get("xp_share", 0) or 0)
    if share > 0:
        xp = max(xp, math.ceil(get_level_xp_required(int(user.get("level", 1) or 1)) * share))
    return xp



