def get_rebirth_count(user: Optional[dict]) -> int:
    if not user:
        return 0
    raw = user.get("rebirths", 0)
    try:
        value = int(raw)
    except (TypeError, ValueError):
        value = 0
    return max(0, min(len(REBIRTH_REQUIREMENTS), value))

def get_prestige_xp_multiplier(rebirths: int) -> float:
    # До 5 престижа множитель тот же, что и раньше (x2 за каждый, максимум x32),
    # чтобы у игроков с текущим прогрессом ничего не просело.
    # Дальше (6-20 престиж) рост продолжается, но по нарастающей (квадратично),
    # а не удваиванием — иначе на 20 престиже множитель был бы x524288.
    base_tier = min(rebirths, 5)
    extra_tier = max(0, rebirths - 5)
    multiplier = (2 ** base_tier) * (1 + 0.2 * extra_tier + 0.02 * extra_tier ** 2)
    return multiplier

def get_chest_xp_reward(user: Optional[dict]) -> int:
    return round(10 * get_prestige_xp_multiplier(get_rebirth_count(user)))

# Целевое распределение редкостей на максимальном престиже (20/20).
# Подобрано так, чтобы сумма была 100% и рост был плавным на всех 20 уровнях,
# без переполнения (в отличие от старой формулы chance * multiplier ** rebirths,
# которая на 10+ престиже уже выходила за 100% и ломала все редкости выше него).
REBIRTH_MAX_RARITY_CHANCES = {
    "common": 14.0,
    "uncommon": 24.0,
    "rare": 24.0,
    "epic": 22.0,
    "legendary": 13.5,
    "mythic": 2.0,
    "nightmare": 0.02,   # было 0.5 — урезано в 25 раз
}
NIGHTMARE_START_CHANCE = 0.0005  # % на престиже открытия (5-м)

# Кошмарная редкость открывается только с этого престижа и ниже никогда не выпадает
NIGHTMARE_UNLOCK_REBIRTHS = 5

def get_rebirth_rarity_chances(rebirths: int) -> dict:
    max_rebirths = len(REBIRTH_REQUIREMENTS)
    rebirths = max(0, min(max_rebirths, int(rebirths)))
    base = {rarity: info["chance"] for rarity, info in RARITIES.items()}
    if rebirths <= 0 or max_rebirths <= 0:
        return base

    # Доля пути от стартового распределения к целевому (0 в начале, 1 на макс. престиже)
    t = rebirths / max_rebirths

    # Геометрическая интерполяция для обычных редкостей: на каждом престиже шанс
    # сдвигается в сторону цели пропорционально текущему значению, поэтому итог
    # всегда положителен и сумма нормализуется до ровно 100% — переполнение
    # невозможно даже на 20 престиже.
    weights = {}
    for rarity, base_chance in base.items():
        if rarity == "nightmare":
            continue
        target_chance = REBIRTH_MAX_RARITY_CHANCES.get(rarity, base_chance)
        base_chance = max(base_chance, 1e-9)
        target_chance = max(target_chance, 1e-9)
        weights[rarity] = (base_chance ** (1 - t)) * (target_chance ** t)

    # Кошмарная редкость: стартует с 0% на NIGHTMARE_UNLOCK_REBIRTHS престиже и
    # линейно растёт до целевого значения на максимальном престиже. Геометрическая
    # интерполяция здесь не подходит, потому что стартовый шанс равен нулю.
    if rebirths >= NIGHTMARE_UNLOCK_REBIRTHS:
        span = max_rebirths - NIGHTMARE_UNLOCK_REBIRTHS + 1
        # Геометрический рост: NIGHTMARE_START_CHANCE на престиже открытия → максимум на последнем
        steps = max(1, max_rebirths - NIGHTMARE_UNLOCK_REBIRTHS)
        t_nightmare = min(1.0, (rebirths - NIGHTMARE_UNLOCK_REBIRTHS) / steps)
        top = REBIRTH_MAX_RARITY_CHANCES.get("nightmare", 0.0)
        weights["nightmare"] = NIGHTMARE_START_CHANCE * (top / NIGHTMARE_START_CHANCE) ** t_nightmare
    else:
        weights["nightmare"] = 0.0

    # Кошмарная — точный процент, остальные нормализуются в оставшиеся (100 − кошмар)%
    nightmare = float(weights.pop("nightmare", 0.0))
    total = sum(weights.values())
    if total <= 0:
        return base
    result = {rarity: value / total * (100 - nightmare) for rarity, value in weights.items()}
    result["nightmare"] = nightmare
    return result

def get_rarity_by_chance(rebirths: int = 0) -> str:
    roll = random.uniform(0, 100)
    cum = 0.0
    chances = get_rebirth_rarity_chances(rebirths)
    for key in RARITIES:
        cum += chances.get(key, 0)
        if roll <= cum:
            return key
    return "common"

def get_rarity_by_chance_custom(chances: dict) -> str:
    roll = random.uniform(0, 100)
    cum = 0.0
    for key in RARITIES:
        cum += chances.get(key, 0)
        if roll <= cum:
            return key
    return "common"

def create_weapon_item(weapon: dict, rarity_key: str, player_level: int = 1) -> dict:
    rarity_info = RARITIES[rarity_key]
    weapon_level = roll_weapon_level(player_level)
    rarity_damage = (int(weapon["dmg"][0] * rarity_info["mult"]), int(weapon["dmg"][1] * rarity_info["mult"]))
    dmg = scale_base_damage_by_weapon_level(rarity_damage, weapon_level)
    rolled_weapon = {
        "iid": random.randint(100000000, 999999999),
        "id": weapon["id"], "name": weapon["name"], "emoji": weapon["emoji"],
        "rarity": rarity_key, "rarity_name": rarity_info["name"],
        "rarity_emoji": rarity_info["emoji"], "rarity_color": rarity_info["color"],
        "dmg": dmg, "base_dmg": dmg, "dmg_mult": rarity_info["mult"],
        "weapon_level": weapon_level, "upgrade_level": 0,
        "weapon_type": infer_weapon_type(weapon),
        "item_type": "weapon",
        "fusion_level": 0,
    }
    rolled_weapon["power"] = calculate_weapon_power(rolled_weapon)
    return rolled_weapon

def create_weapon_by_id(weapon_id: str, rarity_key: str, player_level: int = 1) -> Optional[dict]:
    for weapon in WEAPONS.get(rarity_key, []):
        if weapon["id"] == weapon_id:
            return create_weapon_item(weapon, rarity_key, player_level)
    return None

def find_weapon_def(query: str):
    """Ищет оружие по id или по (части) названия среди ВСЕХ редкостей.
    Возвращает (weapon_dict, rarity_key) либо None."""
    q = (query or "").strip().lower()
    if not q:
        return None
    for rarity_key, weapons in WEAPONS.items():
        for weapon in weapons:
            if q == weapon["id"].lower() or q == weapon["name"].lower():
                return weapon, rarity_key
    matches = []
    for rarity_key, weapons in WEAPONS.items():
        for weapon in weapons:
            if q in weapon["id"].lower() or q in weapon["name"].lower():
                matches.append((weapon, rarity_key))
    if len(matches) == 1:
        return matches[0]
    return None

ARMOR_GROUP_NAMES = {
    "helmet": "Шлем",
    "chestplate": "Нагрудник",
    "bracers": "Наручи",
    "leggings": "Поножи",
    "boots": "Ботинки",
}

def find_armor_def(query: str):
    """Ищет броню по id или по (части) названия среди ВСЕХ редкостей и слотов.
    Возвращает (armor_piece, slot_group, rarity_key) либо None."""
    q = (query or "").strip().lower()
    if not q:
        return None
    for rarity_key, slots in ARMOR.items():
        for slot_group, pieces in slots.items():
            for piece in pieces:
                if q == piece["id"].lower() or q == piece["name"].lower():
                    return piece, slot_group, rarity_key
    matches = []
    for rarity_key, slots in ARMOR.items():
        for slot_group, pieces in slots.items():
            for piece in pieces:
                if q in piece["id"].lower() or q in piece["name"].lower():
                    matches.append((piece, slot_group, rarity_key))
    if len(matches) == 1:
        return matches[0]
    return None

def list_weapons_text() -> str:
    lines = ["<b><tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> Список всего оружия (id — название):</b>"]
    for rarity_key in RARITY_ORDER:
        weapons = WEAPONS.get(rarity_key, [])
        if not weapons:
            continue
        info = RARITIES[rarity_key]
        lines.append(f"\n{info['emoji']} <b>{info['name']}</b>:")
        for weapon in weapons:
            lines.append(f"  <code>{weapon['id']}</code> — {html.escape(weapon['name'])}")
    return "\n".join(lines)

def list_armor_text() -> str:
    lines = ["<b><tg-emoji emoji-id=\"5287786962571241490\">🛡️</tg-emoji> Список всей брони (id — название):</b>"]
    for rarity_key in RARITY_ORDER:
        slots = ARMOR.get(rarity_key, {})
        if not slots:
            continue
        info = RARITIES[rarity_key]
        lines.append(f"\n{info['emoji']} <b>{info['name']}</b>:")
        for slot_group, pieces in slots.items():
            group_name = ARMOR_GROUP_NAMES.get(slot_group, slot_group)
            lines.append(f"  <u>{group_name}</u>:")
            for piece in pieces:
                lines.append(f"    <code>{piece['id']}</code> — {html.escape(piece['name'])}")
    return "\n".join(lines)

def roll_weapon(player_level: int = 1, rebirths: int = 0, user: Optional[dict] = None) -> dict:
    if user is not None:
        chances = get_luck_rarity_chances(user, rebirths)
        rarity_key = get_rarity_by_chance_custom(chances)
    else:
        rarity_key = get_rarity_by_chance(rebirths)
    weapons = WEAPONS.get(rarity_key, [])
    if not weapons:
        rarity_key = "common"
        weapons = WEAPONS["common"]
    path = get_user_path(user)
    if path and random.random() < 0.65:
        preferred_type = PATHS[path]["weapon_type"]
        preferred = [weapon for weapon in weapons if infer_weapon_type(weapon) == preferred_type]
        weapon = random.choice(preferred or weapons)
    else:
        weapon = random.choice(weapons)
    return create_weapon_item(weapon, rarity_key, player_level)

def roll_armor(player_level: int = 1, rebirths: int = 0, user: Optional[dict] = None) -> dict:
    if user is not None:
        chances = get_luck_rarity_chances(user, rebirths)
        rarity_key = get_rarity_by_chance_custom(chances)
    else:
        rarity_key = get_rarity_by_chance(rebirths)
    slot = random.choice(ARMOR_SLOTS)
    # bracers_left и bracers_right берут данные из ключа "bracers" в ARMOR
    armor_lookup = "bracers" if slot in ("bracers_left", "bracers_right") else slot
    pieces = ARMOR.get(rarity_key, {}).get(armor_lookup, [])
    if not pieces:
        rarity_key = "common"
        pieces = ARMOR.get("common", {}).get(armor_lookup, [])
        if not pieces:
            pieces = [{"id": "cloth_hood", "name": "Тканевый капюшон", "emoji": "🧢", "hp": 5}]
    piece = random.choice(pieces)
    return create_armor_item(piece, slot, rarity_key, player_level)

