def build_belt_keyboard(user: Optional[dict] = None) -> InlineKeyboardMarkup:
    equipped_weapon = user.get("equipped") if user else None
    equipped_armor = user.get("equipped_armor", {}) if user else {}
    weapon_text = ("💢" + equipped_weapon.get("emoji", "⚔️")) if equipped_weapon else "⚔️"
    buttons = [
        [InlineKeyboardButton(text=weapon_text, callback_data="belt_slot|weapon")],
    ]
    for slot_group in (("helmet",), ("chestplate",), ("bracers_left", "bracers_right"), ("leggings",), ("boots",)):
        row = []
        for slot in slot_group:
            piece = equipped_armor.get(slot)
            icon_id = ITEM_PREMIUM_ICON_IDS.get((piece or {}).get("id"))
            if piece and icon_id:
                slot_text = "💢"  # премиум-иконка предмета + отметка «надето»
            elif piece:
                slot_text = "💢" + piece.get("emoji", ARMOR_SLOT_EMOJI[slot])
            else:
                slot_text = ARMOR_SLOT_EMOJI[slot]
            row.append(InlineKeyboardButton(text=slot_text, callback_data=f"belt_armor|{slot}", icon_custom_emoji_id=icon_id))
        buttons.append(row)
    buttons.append([
        InlineKeyboardButton(text="Лучшее", callback_data="belt_best", icon_custom_emoji_id="5332336747072208845"),
        InlineKeyboardButton(text="Снять", callback_data="belt_clear", icon_custom_emoji_id="5352669272575321097"),
    ])
    return InlineKeyboardMarkup(inline_keyboard=buttons)

