def armor_slot_matches(item_slot: str, target_slot: str) -> bool:
    if target_slot in ("bracers_left", "bracers_right"):
        return item_slot in (target_slot, "bracers")
    return item_slot == target_slot

def find_inventory_item_by_iid(user: dict, iid: Any, *, item_type: Optional[str] = None, slot: Optional[str] = None) -> Optional[dict]:
    try:
        iid_int = int(iid)
    except (TypeError, ValueError):
        return None
    for item in user.get("inventory", []):
        if item.get("iid") != iid_int:
            continue
        if item_type == "armor" and item.get("item_type") != "armor":
            continue
        if item_type == "weapon" and item.get("item_type") == "armor":
            continue
        if slot and item.get("item_type") == "armor" and not armor_slot_matches(item.get("slot"), slot):
            continue
        return item
    return None

def get_item_card_keyboard(item: dict, user: dict, copy_idx: int, page: int = 0):
    item_id = item["id"]
    item_type = item.get("item_type", "weapon")

    if item_type == "armor":
        item_slot = item.get("slot", "")
        slots = ("bracers_left", "bracers_right") if item_slot == "bracers" else (item_slot,)
        equipped_armor = user.get("equipped_armor", {})
        rows = []
        iid = item.get("iid")
        item_ref = f"iid:{iid}" if iid else f"{item_id}|{copy_idx}"
        for slot in slots:
            if slot not in ARMOR_SLOTS:
                continue
            current_in_slot = equipped_armor.get(slot)
            is_equipped = current_in_slot and current_in_slot.get("iid") == item.get("iid")
            slot_emoji = ARMOR_SLOT_EMOJI.get(slot, "")
            equip_text = f"{slot_emoji} Снять" if is_equipped else f"{slot_emoji} Надеть"
            equip_icon = "5352669272575321097" if is_equipped else "5325762861539016690"
            rows.append([InlineKeyboardButton(text=equip_text, callback_data=f"equip_armor|{slot}|{item_ref}|{page}", icon_custom_emoji_id=equip_icon)])
        if not rows:
            rows.append([InlineKeyboardButton(text="Слот брони не найден", callback_data="noop", icon_custom_emoji_id="5352669272575321097")])
        if item.get("iid"):
            rows.append([InlineKeyboardButton(text="В эссенцию", callback_data=f"item_essence_ask|{item['iid']}|{page}", icon_custom_emoji_id="5370831521039017384")])
        rows.append([InlineKeyboardButton(text="Назад", callback_data=f"inv_page_{page}", icon_custom_emoji_id="5215361191051798408")])
        return InlineKeyboardMarkup(inline_keyboard=rows)

    equipped = user.get("equipped")
    is_equipped = equipped and equipped.get("iid") == item.get("iid")
    equip_text = "Снять" if is_equipped else "Надеть"
    equip_icon = "5352669272575321097" if is_equipped else "5325762861539016690"
    return InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text=equip_text, callback_data=f"equip_{item_id}_{copy_idx}_{page}", icon_custom_emoji_id=equip_icon)],
        [InlineKeyboardButton(text="В эссенцию", callback_data=f"item_essence_ask|{item.get('iid')}|{page}", icon_custom_emoji_id="5370831521039017384")],
        [InlineKeyboardButton(text="Назад", callback_data=f"inv_page_{page}", icon_custom_emoji_id="5215361191051798408")],
    ])

async def convert_item_to_essence(user_id: int, iid: Any) -> tuple[bool, str]:
    user = await db.get_user(user_id)
    item = get_user_item_by_iid(user, iid)
    if not item:
        return False, "Предмет не найден."
    rarity = item.get("rarity")
    essence_id = get_essence_id_for_rarity(rarity)
    if essence_id not in BOSS_RESOURCE_DEFS:
        return False, "Редкость не найдена."
    user["inventory"] = [
        inv_item for inv_item in user.get("inventory", [])
        if str(inv_item.get("iid")) != str(iid)
    ]
    add_boss_resource(user, essence_id, 1)
    refresh_equipped_from_inventory(user)
    await save_runtime_state(user_id, user)
    essence = BOSS_RESOURCE_DEFS[essence_id]
    return True, f"{item.get('name', 'Предмет')} превращён в {essence.get('name', 'эссенцию')}."

