def get_user_donated_stars(user: dict) -> int:
    return sum(int(p.get("stars", 0) or 0) for p in (user.get("star_purchases") or []) if not p.get("refunded"))

def get_top_value(user: dict, category: str, period: str) -> int:
    if category == "power":
        return calculate_user_power(user)
    if category == "prestige":
        return get_rebirth_count(user)
    if category == "donate":
        return get_user_donated_stars(user)
    if category == "tower":
        t = user.get("tower") or {}
        return int(t.get("best_week", 0) or 0) if t.get("week") == get_msk_week_key() else 0
    if period == "day":
        daily = ensure_daily_stats(user)
        if category == "level":
            return daily.get("levels", 0)
        if category == "rolls":
            return daily.get("rolls", 0)
        return daily.get("boss_kills", 0)
    if category == "level":
        return user.get("level", 1)
    if category == "rolls":
        return user.get("chests_opened", 0)
    if category == "power":
        return calculate_user_power(user)
    return user.get("boss_kills", 0)

def is_real_top_user(uid: str, user: dict) -> bool:
    try:
        numeric_uid = int(uid)
        if numeric_uid <= 0 :
            return False
    except (TypeError, ValueError):
        return False
    if (user or {}).get("hide_from_tops"):
        return False  # админ скрыл себя из топов («топ скрыть»)
    return str(user.get("name", "")).casefold() not in {"prestige-test", "prestige test"}

def cleanup_test_profiles() -> bool:
    removed_any = False
    for uid, user in list(db.data.items()):
        name = str((user or {}).get("name", "")).casefold()
        if name in {"prestige-test", "prestige test"}:
            db.data.pop(uid, None)
            removed_any = True
    return removed_any

