TOP_BUTTON_ORDER = [("level", "Уровень"), ("power", "Сила"), ("rolls", "Роллы"),
                    ("bosses", "Боссы"), ("prestige", "Престиж"), ("tower", "Башня"), ("donate", "Донат")]


def build_top_keyboard(category: str, period: str) -> Optional[InlineKeyboardMarkup]:
    """Топы кнопками, как раньше: переключение категорий + период."""
    buttons = []
    for key, label in TOP_BUTTON_ORDER:
        p_ = "day" if key in ("rolls", "bosses") and key != category else (period if key == category else "all")
        buttons.append(InlineKeyboardButton(
            text=("· " + label + " ·") if key == category else label,
            callback_data=f"top|{key}|{p_}",
            icon_custom_emoji_id=TOP_BUTTON_ICONS.get(key),
        ))
    rows = [buttons[i:i + 3] for i in range(0, len(buttons), 3)]
    if category not in TOP_ALL_TIME_ONLY:
        rows.append([InlineKeyboardButton(
            text="За всё время" if period == "day" else "За день",
            callback_data=f"top|{category}|{'all' if period == 'day' else 'day'}",
            icon_custom_emoji_id="5028418466000930064",
        )])
    rows.append([InlineKeyboardButton(text="Награды за топы", callback_data="top_rewards", icon_custom_emoji_id="5226431245918942763")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


