async def show_top(user_id: int, answer_func, category: str = "level", period: str = "all"):
    await db.load()
    category = category if category in TOP_CATEGORIES else "level"
    period = period if period in ("day", "all") else "all"
    if category in TOP_ALL_TIME_ONLY:
        period = "all"
    info = TOP_CATEGORIES[category]
    period_text = "за день (идёт в награды)" if period == "day" and category in ("rolls", "bosses") else ("за день" if period == "day" else "за всё время")
    label = info["day_label"] if period == "day" else info["all_label"]

    entries = []
    for uid, user in db.data.items():
        if not is_real_top_user(uid, user):
            continue
        value = get_top_value(user, category, period)
        if value <= 0:
            continue
        entries.append((value, int(uid), user))
    entries.sort(key=lambda entry: (-entry[0], entry[1]))

    style = TOP_STYLES.get(category, TOP_STYLES["level"])
    medals = TOP_PLACE_EMOJIS
    lines = []
    emoji_budget = 90  # Telegram не любит сообщения с очень большим числом премиум-эмодзи
    emoji_budget -= 2
    for idx, (value, uid, user) in enumerate(entries[:TOP_SIZE], start=1):
        name = render_user_nickname(user, f"ID {uid}")
        cost = name.count("<tg-emoji") + 1
        if cost > emoji_budget:
            name = html.escape(str(user.get("name") or f"ID {uid}"))  # запас премиум-эмодзи кончился
            cost = 1
        emoji_budget -= cost
        if has_star_pass(user) and emoji_budget > 0:
            name += f" {PE_PASS}"  # значок пропуска
            emoji_budget -= 1
        marker = " ← ты" if uid == user_id else ""
        icon = medals.get(idx, style["icon"])
        shown = str(value) if category == "prestige" else format_num(value)
        line = f"{idx}{icon}. <b>{name}</b> — <b>{shown}</b> {style['unit']}{marker}"
        lines.append(f"<b>{line}</b>" if idx <= 3 else line)
    if not lines:
        lines.append("Пока пусто." if category != "donate" else "Пока никто не поддержал бота звёздами — стань первым: <code>донат</code>")

    my_place = next((i for i, (_, uid, _u) in enumerate(entries, start=1) if uid == user_id), None)
    my_line = ""
    if my_place and my_place > TOP_SIZE:
        my_value = entries[my_place - 1][0]
        shown = str(my_value) if category == "prestige" else format_num(my_value)
        my_line = f"\n\n<blockquote>{style['icon']} Твоё место: <b>{my_place}</b> — <b>{shown}</b> {style['unit']}</blockquote>"

    period_line = "" if category in TOP_ALL_TIME_ONLY else f"\n<i>Период: {period_text}</i>"
    # Обычная цитата (не сворачиваемая): тройка лидеров отдельно, остальные — второй цитатой
    body = "<blockquote>" + "\n".join(lines[:3]) + "</blockquote>"
    if len(lines) > 3:
        body += "\n\n<blockquote>" + "\n".join(lines[3:]) + "</blockquote>"
    await answer_func(
        f'<tg-emoji emoji-id="5947236241199074198">🏆</tg-emoji> <b>Топ: {info["name"]}</b> {style["icon"]}{period_line}\n\n'
        + body + my_line,
        build_top_keyboard(category, period),
    )


