def get_quest_state(user: dict, quest_id: str) -> dict:
    quests = user.setdefault("quests", {})
    return quests.setdefault(quest_id, {"claimed": False, "notified": False})

def is_quest_unlocked(user: dict, quest_id: str) -> bool:
    required = QUESTS[quest_id].get("requires")
    return not required or get_quest_state(user, required).get("claimed", False)

def get_quest_progress(user: dict, quest_id: str) -> int:
    quest = QUESTS.get(quest_id)
    if not quest:
        return 0

    quest_type = quest.get("type", "rolls")
    if quest_type == "boss_kills":
        progress = user.get("boss_kills", 0)
    elif quest_type == "location_boss_kills":
        progress = user.get("boss_location_kills", {}).get(quest.get("location"), 0)
    elif quest_type == "specific_boss_kills":
        progress = user.get("boss_defeats", {}).get(quest.get("boss_id"), 0)
    elif quest_type == "power":
        progress = calculate_user_power(user)
    elif quest_type == "prestige":
        progress = get_rebirth_count(user)
    elif quest_type == "total_damage":
        progress = int(user.get("total_damage", 0) or 0)
    elif quest_type == "clan_boss_kills":
        progress = int(user.get("clan_boss_kills", 0) or 0)
    else:
        progress = user.get("chests_opened", 0)
    return min(progress, quest["target"])

def is_quest_completed(user: dict, quest_id: str) -> bool:
    return get_quest_progress(user, quest_id) >= QUESTS[quest_id]["target"]

def get_current_quest_ids(user: dict) -> List[str]:
    current = []
    seen_chains = set()
    for quest_id in QUESTS:
        chain = QUESTS[quest_id].get("chain", quest_id)
        if chain in seen_chains:
            continue
        if is_quest_unlocked(user, quest_id) and not get_quest_state(user, quest_id).get("claimed"):
            current.append(quest_id)
            seen_chains.add(chain)
    return current

def get_today_key() -> str:
    """Игровые сутки — по Москве. Раньше бралось время сервера, и если сервер в UTC,
    дневные лимиты (воскрешения, переводы, роллы дня) сбрасывались в 03:00 МСК, а не в 00:00."""
    return get_msk_now().strftime("%Y-%m-%d")

def ensure_daily_stats(user: dict) -> dict:
    today = get_today_key()
    stats = user.setdefault("daily_stats", {})
    if stats.get("date") != today:
        stats.clear()
        stats.update({"date": today, "rolls": 0, "boss_kills": 0, "levels": 0})
    for key in ("rolls", "boss_kills", "levels"):
        stats.setdefault(key, 0)
    return stats

def add_item_to_inventory_or_trash(user: dict, item: dict) -> bool:
    if len(user.get("inventory", [])) >= MAX_INVENTORY:
        user.setdefault("trash", []).append({
            "item": item,
            "expires_at": time.time() + TRASH_TTL_SECONDS,
        })
        return False
    user.setdefault("inventory", []).append(item)
    return True

def get_boss_loot_chance(boss: dict) -> int:
    return max(6, min(35, 6 + boss.get("power", 0) // 22000))

def get_boss_fragment_chance(boss: dict) -> int:
    return max(18, min(45, 18 + boss.get("power", 0) // 25000))

def get_boss_engraving_shard_id(boss: dict) -> str:
    location = boss.get("location")
    if location == "desert":
        return "engraving_shard_2"
    if location == "forest":
        return "engraving_shard_3"
    if location in ("rift", "volcano", "glacier", "citadel"):
        return "engraving_shard_4"
    return "engraving_shard_1"

def get_boss_engraving_shard_chance(boss: dict) -> int:
    power = boss.get("power", 0)
    location = boss.get("location")
    if location == "forest":
        # осколки III уровня нужны и для гравировки 11–20 — раньше шанс был всего 9–23%
        return max(30, min(50, 30 + power // 30000))
    if location == "desert":
        # осколки II уровня были самыми редкими (12–14%), хотя нужны для гравировки 4–10
        return max(25, min(35, 25 + power // 2500))
    return max(16, min(40, 16 + power // 25000))

def is_final_location_boss(boss: dict) -> bool:
    loc_id = boss.get("location", "swamp")
    loc_bosses = [b for b in BOSSES.values() if b.get("location") == loc_id]
    if not loc_bosses:
        return False
    loc_bosses.sort(key=lambda b: int(b.get("level", 0)))
    return loc_bosses[-1].get("id") == boss.get("id")

def get_boss_engraving_shard_amount(boss: dict) -> int:
    if boss.get("location") in ("forest", "desert"):
        return random.randint(2, 3) if is_final_location_boss(boss) else random.randint(1, 2)
    return random.randint(1, 2) if is_final_location_boss(boss) else 1

def get_reward_range_text(value) -> str:
    if isinstance(value, int):
        return format_num(value)
    return f"{format_num(value[0])}-{format_num(value[1])}"

def add_boss_resource(user: dict, resource_id: str, amount: int = 1):
    resources = user.setdefault("boss_loot", {})
    resources[resource_id] = resources.get(resource_id, 0) + amount

def get_essence_id_for_rarity(rarity: str) -> str:
    return f"essence_{rarity}"

def get_user_essence_count(user: dict, rarity: str) -> int:
    return int(user.get("boss_loot", {}).get(get_essence_id_for_rarity(rarity), 0) or 0)

def roll_boss_loot(user: dict, boss: dict) -> List[str]:
    drops = []
    loot_id = boss.get("loot_item")
    fragment_id = boss.get("fragment_item")

    if loot_id and random.randint(1, 100) <= get_boss_loot_chance_with_luck(boss, user):
        add_boss_resource(user, loot_id)
        item = BOSS_RESOURCE_DEFS.get(loot_id, {})
        drops.append(f"{item.get('emoji', '🎁')} {html.escape(item.get('name', loot_id))}")

    if fragment_id and random.randint(1, 100) <= get_boss_fragment_chance_with_luck(boss, user):
        add_boss_resource(user, fragment_id)
        item = BOSS_RESOURCE_DEFS.get(fragment_id, {})
        drops.append(f"{item.get('emoji', '🧩')} {html.escape(item.get('name', fragment_id))}")

    shard_id = get_boss_engraving_shard_id(boss)
    if shard_id and random.randint(1, 100) <= get_boss_engraving_shard_chance_with_luck(boss, user):
        amount = get_boss_engraving_shard_amount(boss)
        add_boss_resource(user, shard_id, amount)
        item = BOSS_RESOURCE_DEFS.get(shard_id, {})
        drops.append(f"{item.get('emoji', '🔹')} {html.escape(item.get('name', shard_id))} x{amount}")

    return drops

def get_boss_details_text(boss: dict, player_power: int, user: Optional[dict] = None) -> str:
    coins_text = get_reward_range_text(boss["coins"])
    hard_mode = is_boss_hard_mode_enabled(user)
    xp_value = boss["xp"]
    if hard_mode:
        xp_value = (
            math.ceil(xp_value * BOSS_HARD_XP_MULTIPLIER)
            if isinstance(xp_value, int)
            else tuple(math.ceil(value * BOSS_HARD_XP_MULTIPLIER) for value in xp_value)
        )
    xp_text = get_reward_range_text(xp_value)
    loot = BOSS_RESOURCE_DEFS.get(boss.get("loot_item"), {})
    fragment = BOSS_RESOURCE_DEFS.get(boss.get("fragment_item"), {})
    boss_power = get_effective_boss_power(boss, hard_mode)
    can_beat = player_power >= boss_power
    power_mark = "💪" if can_beat else "<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji>"
    coin_emoji = '<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji>'
    xp_emoji = '<tg-emoji emoji-id="5431816358675366190">🆙</tg-emoji>'

    loot_chance = get_boss_loot_chance_with_luck(boss, user) if user else get_boss_loot_chance(boss)
    frag_chance = get_boss_fragment_chance_with_luck(boss, user) if user else get_boss_fragment_chance(boss)
    shard_id = get_boss_engraving_shard_id(boss)
    shard = BOSS_RESOURCE_DEFS.get(shard_id, {})
    shard_chance = get_boss_engraving_shard_chance_with_luck(boss, user) if user else get_boss_engraving_shard_chance(boss)
    if boss.get("location") in ("forest", "desert"):
        shard_amount_text = "2-3 шт." if is_final_location_boss(boss) else "1-2 шт."
    else:
        shard_amount_text = "1-2 шт." if is_final_location_boss(boss) else "1 шт."

    lines = [
        f"{boss['emoji']} <b>{html.escape(boss['name'])}</b>",
        f"{power_mark} Сила: <b>{format_num(boss_power)}</b>",
        "",
        "<b>Награды:</b>",
        f"{coin_emoji} Монеты: <b>{coins_text}</b>",
        f"{xp_emoji}Опыт: <b>{xp_text}</b>",
    ]
    if loot:
        lines.append(
            f"{loot['emoji']} Лут: <b>{html.escape(loot['name'])}</b> ({loot_chance}%)"
        )
    if fragment:
        lines.append(
            f"{fragment['emoji']} Фрагменты: <b>{html.escape(fragment['name'])}</b> ({frag_chance}%)"
        )
    if shard:
        lines.append(
            f"{shard['emoji']} Осколки: <b>{html.escape(shard['name'])}</b> ({shard_chance}%, {shard_amount_text})"
        )
    return "\n".join(lines)

async def show_boss_details(message: Message, user_id: Optional[int], boss_id: str, answer_func=None):
    uid = user_id or message.from_user.id
    as_reply = user_id is None

    async def _send(text, kb):
        if answer_func:
            await answer_func(text, kb)
        else:
            await send_owned_message(message, uid, text, reply_markup=kb, as_reply=as_reply)

    boss = BOSSES.get(boss_id)
    if not boss:
        await _send("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Босс не найден.", None)
        return

    user = await db.get_user(uid)
    player_level = user.get("level", 1)
    equipped_power = calculate_user_power(user)
    hard_mode = is_boss_hard_mode_enabled(user)
    loc_id = boss.get("location", "swamp")
    cd_remaining = get_boss_cd_remaining(user, boss_id)
    if cd_remaining > 0:
        fight_btn = InlineKeyboardButton(text=f"КД {format_cd_time(cd_remaining)}", callback_data="noop", icon_custom_emoji_id="5287473790735890430")
    else:
        fight_btn = InlineKeyboardButton(text="Сразиться", callback_data=f"boss_start|{boss_id}", icon_custom_emoji_id="5373173798633752502")
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [fight_btn],
        [InlineKeyboardButton(text="Назад", callback_data=f"location|{loc_id}", icon_custom_emoji_id="5215361191051798408")],
    ])
    await _send(get_boss_details_text(boss, equipped_power, user), kb)

