async def show_loot_inventory(user_id, answer_func):
    user = await db.get_user(user_id)
    resources = user.setdefault("boss_loot", {})
    present_items = [
        (item_id, count)
        for item_id, count in resources.items()
        if count > 0 and item_id in BOSS_RESOURCE_DEFS
    ]
    potions_count = len(get_potions_in_inventory(user))

    if not present_items:
        if potions_count:
            await answer_func(
                "🎒 <b>Склад пуст</b>\n\nЛут и фрагменты падают с боссов.",
                InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(
                    text=f"🧪 Зелья ({potions_count})", callback_data="inv_potions"
                )]]),
            )
        else:
            await answer_func("🎒 <b>Склад пуст</b>\n\nЛут и фрагменты падают с боссов.", None)
        return

    def sort_key(entry):
        item = BOSS_RESOURCE_DEFS[entry[0]]
        kind_order = {"loot": 0, "fragment": 1, "engraving_shard": 2, "essence": 3}.get(item.get("kind"), 4)
        return (kind_order, item["name"])

    loot_lines = []
    fragment_lines = []
    shard_lines = []
    essence_lines = []
    for item_id, count in sorted(present_items, key=sort_key):
        item = BOSS_RESOURCE_DEFS[item_id]
        line = f"{item['emoji']} {html.escape(item['name'])}: <b>{count}</b>"
        if item.get("kind") == "fragment":
            fragment_lines.append(line)
        elif item.get("kind") == "engraving_shard":
            shard_lines.append(line)
        elif item.get("kind") == "essence":
            essence_lines.append(line)
        else:
            loot_lines.append(line)

    text_parts = ["🎒 <b>Склад</b>"]
    if loot_lines:
        text_parts.append("<b>Лут:</b>\n" + "\n".join(loot_lines))
    if fragment_lines:
        text_parts.append("<b>Фрагменты:</b>\n" + "\n".join(fragment_lines))
    if shard_lines:
        text_parts.append("<b>Осколки:</b>\n" + "\n".join(shard_lines))
    if essence_lines:
        text_parts.append("<b>Эссенции:</b>\n" + "\n".join(essence_lines))

    keyboard = None
    if potions_count:
        keyboard = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(
            text=f"🧪 Зелья ({potions_count})", callback_data="inv_potions"
        )]])

    await answer_func("\n\n".join(text_parts), keyboard)


