async def show_smith_items(user_id: int, mode: str, item_type: str, rarity: str, answer_func):
    user = await db.get_user(user_id)
    rows = []
    lines = ["<tg-emoji emoji-id=\"6269538837723090339\">⭐</tg-emoji> <b>Скрещивание</b>" if mode == "fusion" else "\U0001f6e0 <b>\u041a\u0443\u0437\u043d\u0435\u0446</b>", "", "\u0412\u044b\u0431\u0435\u0440\u0438 \u043f\u0440\u0435\u0434\u043c\u0435\u0442:"]
    items = get_fusion_smith_items(user, item_type, rarity) if mode == "fusion" else get_smith_items(user, item_type, rarity)
    for item in items:
        iid = item.get("iid")
        engr = item.get("engraving_level", 0)
        stars = get_fusion_stars(item)
        stat = f"+{item.get('hp', 0)} HP" if item.get("item_type") == "armor" else f"{item.get('dmg', (0,0))[0]}-{item.get('dmg', (0,0))[1]}"
        lines.append(f"{item['emoji']} {html.escape(item['name'])}{(' ' + stars) if stars else ''} - \u0443\u0440. {get_item_level(item)} - \u0433\u0440. {engr}/10 - {stat}")
        rows.append([InlineKeyboardButton(text=f"{item['emoji']} {item['name']}{(' ' + stars) if stars else ''} - \u0443\u0440. {get_item_level(item)}", callback_data=f"smith_item|{mode}|{iid}")])
    if not items:
        lines.append("Подходящих одинаковых предметов нет.")
    rows.append([InlineKeyboardButton(text="\u2b05\ufe0f \u041d\u0430\u0437\u0430\u0434", callback_data=f"smith_type|{mode}|{item_type}")])
    await answer_func("\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows))

def get_engraving_cost_text(cost: dict) -> str:
    coin_emoji = '<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji>'
    parts = [f"{coin_emoji} {cost['coins']} монет"]
    for shard_id, amount in cost["shards"].items():
        info = BOSS_RESOURCE_DEFS[shard_id]
        parts.append(f"{info['emoji']} {amount} {info['name']}")
    return "\n".join(parts)

async def show_smith_item(user_id: int, mode: str, iid: str, answer_func):
    user = await db.get_user(user_id)
    item = get_user_item_by_iid(user, iid)
    if not item:
        await answer_func("\u274c \u041f\u0440\u0435\u0434\u043c\u0435\u0442 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d.", None)
