def path_progress_text(user: dict) -> str:
    path = get_user_path(user)
    if not path:
        return "Путь не выбран."
    level = get_path_level(user)
    xp = int(user.get("path_xp", 0))
    needed = get_path_xp_required(level) if level < PATH_MAX_LEVEL else get_path_xp_required(PATH_MAX_LEVEL)
    path_emoji = PATHS[path].get("premium_emoji", PATHS[path]["emoji"])
    return (
        f"{path_emoji} <b>{PATHS[path]['name']}:</b>\n\n"
        f"<blockquote>Мастерство: <b>{level}/{PATH_MAX_LEVEL}</b>\n"
        f"Опыт: <b>{format_num(xp)}/{format_num(needed)}</b></blockquote>"
    )

