def get_mannequin(user: dict) -> Optional[dict]:
    path = get_user_path(user)
    if not path:
        return None
    mannequins = user.setdefault("mannequins", {})
    return mannequins.get(path)

def ensure_mannequin(user: dict) -> dict:
    path = get_user_path(user)
    mannequins = user.setdefault("mannequins", {})
    if path not in mannequins:
        mannequins[path] = {"owned": False, "training_seconds": 0, "durability": 100, "last_hit": 0}
    mannequin = mannequins[path]
    mannequin.setdefault("training_active", False)
    mannequin.setdefault("last_train_tick", 0)
    mannequin.setdefault("durability_minutes_used", 0)
    return mannequin

def normalize_mannequins(user: dict):
    mannequins = user.setdefault("mannequins", {})
    for mannequin in mannequins.values():
        if not isinstance(mannequin, dict):
            continue
        mannequin.setdefault("owned", False)
        mannequin.setdefault("training_seconds", 0)
        mannequin.setdefault("durability", 100)
        mannequin.setdefault("last_hit", 0)
        mannequin.setdefault("training_active", False)
        mannequin.setdefault("last_train_tick", 0)
        mannequin.setdefault("durability_minutes_used", 0)

MANNEQUIN_EMOJI = '<tg-emoji emoji-id="5235516570628796933">🤣</tg-emoji>'
MANNEQUIN_REPAIR_EMOJI = '<tg-emoji emoji-id="5863945989127148135">🛠</tg-emoji>'
