async def show_mannequin(user_id: int, answer_func):
    user = await db.get_user(user_id)
    if process_mannequin_training(user):
        await save_runtime_state(user_id, user)
    path = get_user_path(user)
    if not path:
        await answer_func("🪵 <b>Манекен</b>\n\nСначала выбери путь: <b>пути</b>.", None)
        return
    info = PATHS[path]
    mannequin = ensure_mannequin(user)
    if not mannequin.get("owned"):
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text=f"Купить · {format_num(info['cost'])} монет", callback_data="mannequin_buy")],
        ])
        await answer_func(
            f"{MANNEQUIN_EMOJI} <b>{info['mannequin']}</b>\n\n"
            f"<blockquote>Стоимость: <b>{format_num(info['cost'])}</b> {COIN_EMOJI}.</blockquote>",
            kb,
        )
        return
    status = "тренируется" if mannequin.get("training_active") else "остановлен"
    text = (
        f"{MANNEQUIN_EMOJI} <b>{info['mannequin']}</b>\n\n"
        f"<blockquote>Статус: <b>{status}</b>\n"
        f"Время тренировок: <b>{format_training_time(get_display_training_seconds(mannequin))}</b>\n"
        f"Прочность: <b>{int(mannequin.get('durability', 100))}%</b>\n"
        f"1 минута тренировки = <b>{get_mannequin_xp_per_minute(user)} опыта мастерства</b> (растёт с уровнем пути).\n"
        f"Удар по манекену = <b>+{MANNEQUIN_HIT_MINUTES} мин</b> тренировки.</blockquote>"
    )
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="⏸ Стоп" if mannequin.get("training_active") else "▶️ Тренироваться", callback_data="mannequin_train")],
        [
            InlineKeyboardButton(text="🗡", callback_data="mannequin_time"),
            InlineKeyboardButton(text="❤️", callback_data="mannequin_repair_menu"),
        ],
    ])
    await answer_func(text, kb)

async def buy_mannequin(user_id: int, answer_func, popup_func=None):
    user = await db.get_user(user_id)
    path = get_user_path(user)
    if not path:
        await show_paths(user_id, answer_func)
        return
    info = PATHS[path]
    mannequin = ensure_mannequin(user)
    if mannequin.get("owned"):
        await show_mannequin(user_id, answer_func)
        return
    if user.get("coins", 0) < info["cost"]:
        if popup_func:
            await popup_func("Не хватает монет.", show_alert=True)
        return
    user["coins"] -= info["cost"]
    mannequin.update({"owned": True, "training_seconds": 2 * 60 * 60, "durability": 100, "last_hit": 0, "training_active": False, "last_train_tick": 0, "durability_minutes_used": 0})
    await save_runtime_state(user_id, user)
    if popup_func:
        await popup_func("Манекен куплен!")
    await show_mannequin(user_id, answer_func)

async def train_mannequin(user_id: int, answer_func, popup_func=None):
    user = await db.get_user(user_id)
    mannequin = get_mannequin(user)
    if not mannequin or not mannequin.get("owned"):
        await show_mannequin(user_id, answer_func)
        return
    if int(mannequin.get("durability", 100)) <= 0:
        if mannequin.get("training_active"):
            mannequin["training_active"] = False
            mannequin["last_train_tick"] = 0
            await save_runtime_state(user_id, user)
        if popup_func:
            await popup_func("Манекен сломан.", show_alert=True)
        await show_mannequin(user_id, answer_func)
        return
    if mannequin.get("training_active"):
        mannequin["training_active"] = False
        mannequin["last_train_tick"] = 0
        await save_runtime_state(user_id, user)
        if popup_func:
            await popup_func("Тренировка остановлена.")
        await show_mannequin(user_id, answer_func)
        return
    if int(mannequin.get("training_seconds", 0)) < MANNEQUIN_TRAIN_TICK_SECONDS:
        if popup_func:
            await popup_func("Нет времени тренировки.", show_alert=True)
        return
    mannequin["training_active"] = True
    mannequin["last_train_tick"] = time.time()
    await save_runtime_state(user_id, user)
    if popup_func:
        await popup_func("Тренировка началась.")
    await show_mannequin(user_id, answer_func)

async def show_mannequin_time(user_id: int, answer_func):
    user = await db.get_user(user_id)
    mannequin = get_mannequin(user)
    if not mannequin or not mannequin.get("owned"):
        await show_mannequin(user_id, answer_func)
        return
    now = time.time()
    left = max(0, math.ceil(MANNEQUIN_HIT_COOLDOWN_SECONDS - (now - float(mannequin.get("last_hit", 0)))))
    durability = int(mannequin.get("durability", 100))
    hit_text = "Сломан" if durability <= 0 else f"Бить 🗡 ({left}с)" if left > 0 else "Бить 🗡"
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text=hit_text, callback_data="mannequin_hit")],
        [InlineKeyboardButton(text="Назад", callback_data="mannequin", icon_custom_emoji_id="5215361191051798408")],
    ])
    await answer_func(
        f"{MANNEQUIN_TIME_EMOJI} <b>Фарм времени</b>\n\n"
        f"<blockquote>Время тренировок: <b>{format_training_time(get_display_training_seconds(mannequin))}</b>\n"
        f"Прочность: <b>{durability}%</b>\n"
        f"Каждый удар даёт <b>+{MANNEQUIN_HIT_MINUTES} минут</b> тренировки.</blockquote>",
        kb,
    )

async def hit_mannequin(user_id: int, answer_func, popup_func=None):
    user = await db.get_user(user_id)
    mannequin = get_mannequin(user)
    if not mannequin or not mannequin.get("owned"):
        await show_mannequin(user_id, answer_func)
        return
    if int(mannequin.get("durability", 100)) <= 0:
        if mannequin.get("training_active"):
            mannequin["training_active"] = False
            mannequin["last_train_tick"] = 0
            await save_runtime_state(user_id, user)
        if popup_func:
            await popup_func("Манекен сломан.", show_alert=True)
        await show_mannequin_time(user_id, answer_func)
        return
    now = time.time()
    left = MANNEQUIN_HIT_COOLDOWN_SECONDS - (now - float(mannequin.get("last_hit", 0)))
    if left > 0:
        if popup_func:
            await popup_func(f"КД {math.ceil(left)} сек.")
        await show_mannequin_time(user_id, answer_func)
        return
    if int(mannequin.get("training_seconds", 0)) >= MANNEQUIN_MAX_TRAINING_SECONDS:
        if popup_func:
            await popup_func("Запас тренировок полный.")
        return
    mannequin["training_seconds"] = min(MANNEQUIN_MAX_TRAINING_SECONDS, int(mannequin.get("training_seconds", 0)) + 60 * MANNEQUIN_HIT_MINUTES)
    mannequin["last_hit"] = now
    await save_runtime_state(user_id, user)
    if popup_func:
        await popup_func(f"+{MANNEQUIN_HIT_MINUTES} минут тренировки.")
    await show_mannequin_time(user_id, answer_func)

