async def repair_mannequin(user_id: int, answer_func, popup_func=None):
    user = await db.get_user(user_id)
    mannequin = get_mannequin(user)
    if not mannequin or not mannequin.get("owned"):
        await show_mannequin(user_id, answer_func)
        return
    missing = max(0, 100 - int(mannequin.get("durability", 100)))
    cost = missing * 200
    if missing <= 0:
        if popup_func:
            await popup_func("Прочность полная.")
        return
