async def show_pet_detail(user_id: int, iid: int, answer_func, rarity_filter: str = "", pet_filter: str = ""):
    user = await db.get_user(user_id)
    messages = process_pet_feeds(user)
    if messages:
        recalculate_user_combat_stats(user, active_battles.get(user_id))
    pet = get_pet_by_iid(user, iid)
    if not pet:
        await show_pets(user_id, answer_func, rarity_filter, pet_filter)
        return
    slots = get_pet_slots(user)
    equipped = user.setdefault("equipped_pets", [None, None])
    equipped_slot = next((idx for idx, current_iid in enumerate(equipped) if current_iid == iid), None)
    rows = []
    if equipped_slot is not None:
        if float(pet.get("feeding_until") or 0) > time.time():
            rows.append([InlineKeyboardButton(text=f"🍽 Кушает · слот {equipped_slot + 1}", callback_data="noop")])
        else:
            rows.append([InlineKeyboardButton(text=f"🍬 Покормить · слот {equipped_slot + 1}", callback_data=f"pet_feed_iid|{iid}|{rarity_filter}|{pet_filter}")])
        rows.append([InlineKeyboardButton(text=f"Снять · слот {equipped_slot + 1}", callback_data=f"pet_unequip_iid|{iid}|{rarity_filter}|{pet_filter}", icon_custom_emoji_id="5352669272575321097")])
    else:
        for idx in range(slots):
            rows.append([InlineKeyboardButton(text=f"Надеть в слот {idx + 1}", callback_data=f"pet_equip|{iid}|{idx}")])
        rows.append([InlineKeyboardButton(text="Утиль питомца", callback_data=f"pet_scrap_ask|{iid}", icon_custom_emoji_id="5445267414562389170")])
        if get_pet_rarity_key(pet) in PET_EVOLVE_CHANCES:
            n_copies = len(evolvable_copies(user, pet))
            if n_copies >= 3:
                rows.append([InlineKeyboardButton(text=f"Эволюция · {n_copies} шт. · шанс {PET_EVOLVE_CHANCES[get_pet_rarity_key(pet)]}%",
                                                  callback_data=f"pet_evo|ask|{iid}", icon_custom_emoji_id="5370831521039017384")])
    if rarity_filter.startswith("all"):
        back_callback = f"pets_all|{rarity_filter[3:] or 0}"
    elif rarity_filter and pet_filter:
        back_callback = f"pets_group|{rarity_filter}|{pet_filter}"
    else:
        back_callback = f"pets_filter|{rarity_filter}" if rarity_filter else "pets"
    rows.append([InlineKeyboardButton(text="Назад", callback_data=back_callback, icon_custom_emoji_id="5215361191051798408")])
    await save_runtime_state(user_id, user)
    await answer_func(get_pet_card_text(pet), InlineKeyboardMarkup(inline_keyboard=rows))

def return_incubating_eggs(user: dict) -> int:
    """Инкубатора больше нет: яйца, которые лежали в нём, возвращаются в запас (их можно сразу открыть)."""
    returned = 0
    for slot in user.get("pet_incubator") or []:
        if isinstance(slot, dict) and slot.get("egg_id") in PET_EGGS:
            eggs = user.setdefault("pet_eggs", {})
            eggs[slot["egg_id"]] = int(eggs.get(slot["egg_id"], 0)) + 1
            slot["egg_id"] = None
            slot["started_at"] = 0
            slot["ready_at"] = 0
            returned += 1
    return returned


async def show_pet_incubator(user_id: int, answer_func):
    """Экран «Яйца»: яйца открываются сразу, без инкубатора."""
    user = await db.get_user(user_id)
    if return_incubating_eggs(user):
        await db.save_user(user_id, user)
    eggs = get_available_pet_eggs(user)
    title = '<tg-emoji emoji-id="5332550902731535734">🥚</tg-emoji> <b>Яйца</b>'
    rows = []
    if not eggs:
        text = f"{title}\n\n<blockquote>Яиц пока нет. Купи яйцо в магазине питомцев — оно откроется сразу.</blockquote>"
    else:
        lines = [f"{PET_EGGS[e].get('shop_emoji', PET_EGGS[e]['emoji'])} {html.escape(PET_EGGS[e]['name'])}: <b>{n}</b>" for e, n in eggs.items()]
        text = f"{title}\n\n<blockquote>" + "\n".join(lines) + "</blockquote>\n\n<blockquote>Нажми, чтобы открыть яйцо — питомец появится сразу.</blockquote>"
        for egg_id, amount in eggs.items():
            egg = PET_EGGS[egg_id]
            rows.append([InlineKeyboardButton(
                text=f"Открыть {egg['name']} ×{amount}",
                callback_data=f"pet_egg_open|{egg_id}",
                icon_custom_emoji_id=egg.get("icon_id") or "5332550902731535734",
            )])
    rows.append([InlineKeyboardButton(text="Магазин питомцев", callback_data="pet_shop", icon_custom_emoji_id="5440841102871517055")])
    rows.append([InlineKeyboardButton(text="Назад", callback_data="pet", icon_custom_emoji_id="5215361191051798408")])
    await answer_func(text, InlineKeyboardMarkup(inline_keyboard=rows))


async def open_pet_egg(user_id: int, egg_id: str) -> Optional[dict]:
    """Списывает одно яйцо и сразу выдаёт питомца. None — если яйца нет."""
    user = await db.get_user(user_id)
    return_incubating_eggs(user)
    eggs = user.setdefault("pet_eggs", {})
    if egg_id not in PET_EGGS or int(eggs.get(egg_id, 0)) <= 0:
        return None
    eggs[egg_id] = int(eggs[egg_id]) - 1
    if eggs[egg_id] <= 0:
        eggs.pop(egg_id, None)
    pet = roll_pet_from_egg(egg_id, user)
    pet["egg_id"] = egg_id  # для утиля: вернём 50% цены этого яйца
    user.setdefault("pets", []).append(pet)
    await db.save_user(user_id, user)
    announce_pet_drop(user_id, user, pet, egg_id)
    await write_activity_log(f"PET {_log_user_name(user_id, user)} | открыл {PET_EGGS[egg_id]['name']} → {pet['name']} ({pet.get('rarity')})")
    return pet


PET_SCRAP_REFUND = 0.5  # утиль питомца возвращает 50% цены яйца (монеты и ресурсы)
PET_SCRAP_DEFAULT_EGG = "swamp_egg"  # на случай питомца без яйца в PET_DEFS (например, выданного админом неизвестного)


def get_pet_source_egg(pet: dict) -> str:
    egg_id = pet.get("egg_id")
    if egg_id in PET_EGGS:
        return egg_id
    own_egg = PET_DEFS.get(pet.get("pet_id"), {}).get("egg")  # питомцы яиц локаций выпадают только из своего яйца
    if own_egg in PET_EGGS:
        return own_egg
    return PET_SCRAP_DEFAULT_EGG


def get_pet_scrap_refund(pet: dict) -> tuple:
    egg_id = get_pet_source_egg(pet)
    egg = PET_EGGS[egg_id]
    coins = int(int(egg.get("coins", 0) or 0) * PET_SCRAP_REFUND)
    resources = {rid: int(amount * PET_SCRAP_REFUND) for rid, amount in egg.get("resources", {}).items()}
    resources = {rid: n for rid, n in resources.items() if n > 0}
    return egg_id, coins, resources


def format_scrap_refund(coins: int, resources: dict) -> str:
    lines = []
    if coins:
        lines.append(f'<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji> Монеты: <b>+{format_num(coins)}</b>')
    for rid, n in resources.items():
        info = BOSS_RESOURCE_DEFS.get(rid, {})
        lines.append(f"{info.get('emoji', '▫️')} {html.escape(str(info.get('name', rid)))}: <b>+{n}</b>")
    return "\n".join(lines) or "ничего"


PETS_ALL_PAGE_SIZE = 8


async def show_all_pets(user_id: int, page: int, answer_func):
    """Все питомцы игрока — и надетые, и нет. Листаются по 8."""
    user = await db.get_user(user_id)
    if process_pet_feeds(user):
        recalculate_user_combat_stats(user, active_battles.get(user_id))
        await save_runtime_state(user_id, user)
    pets = list(user.get("pets") or [])
    paw = '<tg-emoji emoji-id="5258111319831227095">🐾</tg-emoji>'
    back_row = [InlineKeyboardButton(text="Назад", callback_data="pets", icon_custom_emoji_id="5215361191051798408")]
    if not pets:
        await answer_func(
            f"{paw} <b>Все питомцы</b>\n\n<blockquote>Питомцев пока нет. Купи яйцо в магазине питомцев.</blockquote>",
            InlineKeyboardMarkup(inline_keyboard=[back_row]),
        )
        return
    order = {r: i for i, r in enumerate(reversed(list(PET_RARITIES.keys())))}
    equipped = [x for x in (user.get("equipped_pets") or []) if x]
    pets.sort(key=lambda p: (p.get("iid") not in equipped, order.get(get_pet_rarity_key(p), 99), -get_pet_level(p), p.get("name", "")))
    pages = max(1, math.ceil(len(pets) / PETS_ALL_PAGE_SIZE))
    page = max(0, min(page, pages - 1))
    counts = collections.Counter(get_pet_rarity_key(p) for p in pets)
    summary = " · ".join(
        f"{PET_RARITY_PREMIUM_EMOJIS.get(r, PET_RARITIES[r]['emoji'])} {counts[r]}"
        for r in reversed(list(PET_RARITIES.keys())) if counts.get(r)
    )
    rows = []
    for pet in pets[page * PETS_ALL_PAGE_SIZE:(page + 1) * PETS_ALL_PAGE_SIZE]:
        mark = " · надет" if pet.get("iid") in equipped else ""
        rows.append([InlineKeyboardButton(
            text=f"{pet.get('name', 'Питомец')} · ур. {get_pet_level(pet)}{mark}",
            callback_data=f"pet_view|{pet['iid']}|all{page}|",
            icon_custom_emoji_id=get_pet_icon_custom_emoji_id(pet),
        )])
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="◀️", callback_data=f"pets_all|{page - 1}"))
    if pages > 1:
        nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page < pages - 1:
        nav.append(InlineKeyboardButton(text="▶️", callback_data=f"pets_all|{page + 1}"))
    if nav:
        rows.append(nav)
    rows.append(back_row)
    await answer_func(
        f"{paw} <b>Все питомцы</b> · {len(pets)}\n\n"
        f"<blockquote>{summary}</blockquote>\n\n"
        "<blockquote>Сначала надетые, дальше по редкости и уровню. Нажми на питомца, чтобы открыть его карточку.</blockquote>",
        InlineKeyboardMarkup(inline_keyboard=rows),
    )


