async def show_pet_incubator_slot(user_id: int, slot_idx: int, answer_func):
    user = await db.get_user(user_id)
    normalize_pet_storage(user)
    if slot_idx >= get_pet_incubator_slots(user):
        await show_pet_incubator(user_id, answer_func)
        return
    slot = get_pet_incubator_slot(user, slot_idx)
    egg_id = slot.get("egg_id")
    title = '<tg-emoji emoji-id="5332550902731535734">🥚</tg-emoji> <b>Инкубатор</b>'
    if egg_id and egg_id in PET_EGGS:
        egg = PET_EGGS[egg_id]
        remaining = max(0, int(float(slot.get("ready_at") or 0) - time.time()))
        if remaining <= 0:
            status = '<tg-emoji emoji-id="5325593644122524396">✅</tg-emoji> <b>Готово</b>'
        else:
            status = f'<tg-emoji emoji-id="5787432469598835099">⏳</tg-emoji> Осталось: <b>{format_hatch_time(remaining)}</b>'
        text = (
            f"{title}\n\n"
            f"<blockquote>{egg.get('shop_emoji', egg['emoji'])} <b>{html.escape(egg['name'])}</b>\n"
            f"{status}</blockquote>"
        )
        rows = []
        if remaining <= 0:
            rows.append([InlineKeyboardButton(text="Забрать", callback_data=f"pet_incubator_claim|{slot_idx}", icon_custom_emoji_id="5293998404404272267")])
        rows.append([InlineKeyboardButton(text="Назад", callback_data="pet_incubator", icon_custom_emoji_id="5215361191051798408")])
        await answer_func(text, InlineKeyboardMarkup(inline_keyboard=rows))
        return

    eggs = get_available_pet_eggs(user)
    if not eggs:
        await answer_func(
            f"{title}\n\n<blockquote>У тебя нет яиц для вылупления.</blockquote>",
            InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="Магазин питомцев", callback_data="pet_shop", icon_custom_emoji_id="5440841102871517055")],
                [InlineKeyboardButton(text="Назад", callback_data="pet_incubator", icon_custom_emoji_id="5215361191051798408")],
            ]),
        )
        return
    rows = []
    for available_egg_id, amount in eggs.items():
        egg = PET_EGGS[available_egg_id]
        rows.append([InlineKeyboardButton(
            text=f"{egg['emoji']} {egg['name']} x{amount}",
            callback_data=f"pet_incubator_set|{slot_idx}|{available_egg_id}",
        )])
    rows.append([InlineKeyboardButton(text="Назад", callback_data="pet_incubator", icon_custom_emoji_id="5215361191051798408")])
    await answer_func(
        f"{title}\n\n<blockquote>Выбери яйцо для слота {slot_idx + 1}.</blockquote>",
        InlineKeyboardMarkup(inline_keyboard=rows),
    )

async def start_pet_incubation(user_id: int, slot_idx: int, egg_id: str, answer_func):
    user = await db.get_user(user_id)
    normalize_pet_storage(user)
    if slot_idx >= get_pet_incubator_slots(user):
        await show_pet_incubator(user_id, answer_func)
        return
    slot = get_pet_incubator_slot(user, slot_idx)
    if slot.get("egg_id"):
        await show_pet_incubator_slot(user_id, slot_idx, answer_func)
        return
    eggs = user.setdefault("pet_eggs", {})
    if eggs.get(egg_id, 0) <= 0 or egg_id not in PET_EGGS:
        await show_pet_incubator_slot(user_id, slot_idx, answer_func)
        return
    egg = PET_EGGS[egg_id]
    eggs[egg_id] -= 1
    if eggs[egg_id] <= 0:
        eggs.pop(egg_id, None)
    now = time.time()
    slot["egg_id"] = egg_id
    slot["started_at"] = now
    slot["ready_at"] = now + int(egg.get("hatch_seconds", 1800))
    await db.save_user(user_id, user)
    await answer_func(
        '<tg-emoji emoji-id="5332550902731535734">🥚</tg-emoji> <b>Инкубатор</b>\n\n'
        f'<blockquote>{egg.get("shop_emoji", egg["emoji"])} <b>{html.escape(egg["name"])}</b>\n'
        f'Вылупление началось. Осталось: <b>{format_hatch_time(int(egg.get("hatch_seconds", 1800)))}</b></blockquote>',
        InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="Назад", callback_data="pet_incubator", icon_custom_emoji_id="5215361191051798408")]]),
    )

async def claim_pet_incubator(user_id: int, slot_idx: int, answer_func, popup_func=None):
    user = await db.get_user(user_id)
    normalize_pet_storage(user)
    if slot_idx >= get_pet_incubator_slots(user):
        await show_pet_incubator(user_id, answer_func)
        return
    slot = get_pet_incubator_slot(user, slot_idx)
    egg_id = slot.get("egg_id")
    if not egg_id or egg_id not in PET_EGGS:
        await show_pet_incubator_slot(user_id, slot_idx, answer_func)
        return
    remaining = float(slot.get("ready_at") or 0) - time.time()
    if remaining > 0:
        if popup_func:
            await popup_func(f"Ещё не готово: {format_hatch_time(int(remaining))}", show_alert=True)
        await show_pet_incubator_slot(user_id, slot_idx, answer_func)
        return
    pet = roll_pet_from_egg(egg_id, user)
    slot["egg_id"] = None
    slot["started_at"] = 0
    slot["ready_at"] = 0
    user.setdefault("pets", []).append(pet)
    await db.save_user(user_id, user)
    if popup_func:
        await popup_func(f"Вылупился {pet['name']}!", show_alert=True)
    await show_pet_detail(user_id, pet["iid"], answer_func)

