def format_egg_cost_lines(egg: dict, resources: dict) -> List[str]:
    cost = []
    if egg.get("coins"):
        cost.append(f"Монеты: {format_num(egg['coins'])}")
    for res_id, amount in egg["resources"].items():
        res = BOSS_RESOURCE_DEFS.get(res_id, {})
        have = int(resources.get(res_id, 0) or 0)
        mark = PE_OK if have >= amount else PE_CROSS
        cost.append(f"{mark} {res.get('emoji', '▫️')} {html.escape(res.get('name', res_id))}: <b>{min(have, amount)}/{amount}</b>")
    return cost


