def can_buy_pet_egg(user: dict, egg_id: str) -> tuple[bool, str]:
    egg = PET_EGGS.get(egg_id)
    if not egg:
        return False, "Яйцо не найдено."
    if user.get("coins", 0) < egg["coins"]:
        return False, "Не хватает монет."
    resources = user.get("boss_loot", {})
    missing = [
        f"{BOSS_RESOURCE_DEFS.get(res_id, {}).get('name', res_id)} ×{amount - int(resources.get(res_id, 0) or 0)}"
        for res_id, amount in egg["resources"].items() if resources.get(res_id, 0) < amount
    ]
    if missing:
        return False, "Не хватает: " + ", ".join(missing)
    return True, ""


async def notify_completed_quests(user_id: int, user: dict, notify_func, sticker_func=None):
    for quest_id, quest in QUESTS.items():
        if not is_quest_unlocked(user, quest_id):
            continue
        state = get_quest_state(user, quest_id)
        if state.get("claimed") or state.get("notified") or not is_quest_completed(user, quest_id):
            continue
        state["notified"] = True
        await db.save_user(user_id, user)
        if sticker_func:
            await sticker_func()
        await notify_func(
            f'<tg-emoji emoji-id="5354920801806066333">👍</tg-emoji> Задание выполнено: <b>"{html.escape(quest["name"])}"</b>\n'
            "Напиши <b>задания</b> и забери награду.",
            None,
        )
QUEST_NOTIFY_LOOP_SECONDS = 30
QUEST_NOTIFY_ACTIVE_WINDOW = 3 * 3600  # проверяем тех, кто был активен (или роллит авторолл) последние 3 часа


async def quest_notification_loop():
    """Уведомления о выполненных заданиях для ВСЕХ способов прогресса.
    Раньше они отправлялись только после ручного ролла и победы над боссом — авторолл, сила,
    престиж, Лутиафан и урон задания выполняли молча."""
    while True:
        await asyncio.sleep(QUEST_NOTIFY_LOOP_SECONDS)
        try:
            await db.load()
            now = time.time()
            for uid_str, user in list(db.data.items()):
                if not isinstance(user, dict):
                    continue
                try:
                    uid = int(uid_str)
                except ValueError:
                    continue
                active = now - float(user.get("last_seen_at", 0) or 0) < QUEST_NOTIFY_ACTIVE_WINDOW
                if not active and not get_auto_roll_session(uid).get("running"):
                    continue
                await notify_new_achievements(uid, user)
                await notify_completed_quests(
                    uid, user,
                    lambda text, kb, _uid=uid: send_user_notification(
                        _uid, f"<blockquote>{text}</blockquote>",
                        reply_markup=nav_kb(("К заданиям", "quests", "5197269100878907942")),
                    ),
                )
        except Exception as e:
            print(f"[quest_notification_loop] {e}")


# ====== АЛХИМИК ПЕТРОСЯН ======
ALCHEMIST_DAILY_LIMIT = 5

def get_alchemist_stats(user: dict) -> dict:
    """Возвращает статистику обменов Алхимика за сегодня."""
    today = get_today_key()
    stats = user.setdefault("alchemist_stats", {})
    if stats.get("date") != today:
        stats.clear()
        stats.update({"date": today, "trades": 0})
    stats.setdefault("trades", 0)
    return stats

def get_potion_count(user: dict, potion_id: str) -> int:
    return sum(1 for p in user.get("witch_potions", []) if p.get("potion_id") == potion_id)

def get_total_potion_count(user: dict) -> int:
    return len(user.get("witch_potions", []))

def remove_potions(user: dict, potion_id: str, amount: int = 1) -> int:
    """Удаляет до `amount` зелий указанного id. Возвращает сколько удалено."""
    potions = user.get("witch_potions", [])
    removed = 0
    new_potions = []
    for p in potions:
        if p.get("potion_id") == potion_id and removed < amount:
            removed += 1
            continue
        new_potions.append(p)
    user["witch_potions"] = new_potions
    return removed

def format_alchemist_item_line(potion_id: str, count: int) -> str:
    pdef = POTION_DEFS.get(potion_id, {})
    emoji = get_potion_emoji(potion_id)
    name = pdef.get("name", potion_id)
    return f"{emoji} {html.escape(name)} — <b>{count}</b>"

async def show_alchemist(user_id: int, answer_func):
    user = await db.get_user(user_id)
    stats = get_alchemist_stats(user)
    used = stats["trades"]
    left = max(0, ALCHEMIST_DAILY_LIMIT - used)

    total_potions = get_total_potion_count(user)
    potion_lines = []
    for pid in POTION_IDS:
        cnt = get_potion_count(user, pid)
        if cnt > 0:
            potion_lines.append(format_alchemist_item_line(pid, cnt))

    potion_text = "\n".join(potion_lines) if potion_lines else "<i>У тебя нет зелий</i>"

    petrosyan_emoji = '<tg-emoji emoji-id="5276124975311370560">👀</tg-emoji>'

