@dp.callback_query(F.data == "alch_start")
async def cb_alch_start(call: CallbackQuery):
    await call.answer()
    alchemist_sessions.pop(call.from_user.id, None)
    await show_alchemist_pick_first(call.from_user.id, lambda t, kb: edit_for_user(call, t, kb))


@dp.callback_query(F.data.startswith("alch_pick1|"))
async def cb_alch_pick1(call: CallbackQuery):
    first_pid = call.data.split("|", 1)[1]
    user = await db.get_user(call.from_user.id)
    if get_potion_count(user, first_pid) < 1:
        await call.answer("❌ У тебя нет такого зелья.", show_alert=True)
        return
    alchemist_sessions[call.from_user.id] = {"first_pid": first_pid}
    await call.answer()
    await show_alchemist_pick_second(call.from_user.id, first_pid, lambda t, kb: edit_for_user(call, t, kb))


@dp.callback_query(F.data.startswith("alch_pick2|"))
async def cb_alch_pick2(call: CallbackQuery):
    second_pid = call.data.split("|", 1)[1]
    session = alchemist_sessions.get(call.from_user.id)
    if not session or "first_pid" not in session:
        await call.answer("Сессия устарела. Начни заново.", show_alert=True)
        return
    first_pid = session["first_pid"]

    user = await db.get_user(call.from_user.id)
    required_first = 1
    required_second = 2 if second_pid == first_pid else 1
    if get_potion_count(user, first_pid) < required_first or get_potion_count(user, second_pid) < required_second:
        await call.answer("❌ Не хватает зелий. Начни заново.", show_alert=True)
        alchemist_sessions.pop(call.from_user.id, None)
        await show_alchemist(call.from_user.id, lambda t, kb: edit_for_user(call, t, kb))
        return

    session["second_pid"] = second_pid
    await call.answer()
    await show_alchemist_choose_result(call.from_user.id, first_pid, second_pid, lambda t, kb: edit_for_user(call, t, kb))


@dp.callback_query(F.data.startswith("alch_result|"))
async def cb_alch_result(call: CallbackQuery):
    result_pid = call.data.split("|", 1)[1]
    session = alchemist_sessions.pop(call.from_user.id, None)
    if not session or "first_pid" not in session or "second_pid" not in session:
        await call.answer("Сессия устарела. Начни заново.", show_alert=True)
        return
    first_pid = session["first_pid"]
    second_pid = session["second_pid"]

    user = await db.get_user(call.from_user.id)
    stats = get_alchemist_stats(user)
    if stats["trades"] >= ALCHEMIST_DAILY_LIMIT:
        await call.answer("⏳ Лимит на сегодня исчерпан.", show_alert=True)
        await show_alchemist(call.from_user.id, lambda t, kb: edit_for_user(call, t, kb))
        return

    if first_pid == second_pid:
        if get_potion_count(user, first_pid) < 2:
            await call.answer("❌ Не хватает зелий.", show_alert=True)
            await show_alchemist(call.from_user.id, lambda t, kb: edit_for_user(call, t, kb))
            return
        remove_potions(user, first_pid, 2)
    else:
        if get_potion_count(user, first_pid) < 1 or get_potion_count(user, second_pid) < 1:
            await call.answer("❌ Не хватает зелий.", show_alert=True)
            await show_alchemist(call.from_user.id, lambda t, kb: edit_for_user(call, t, kb))
            return
        remove_potions(user, first_pid, 1)
        remove_potions(user, second_pid, 1)

    add_potion_to_user(user, result_pid)
    stats["trades"] += 1
    await save_runtime_state(call.from_user.id, user)

    result_pdef = POTION_DEFS.get(result_pid, {})
    await call.answer(f"✅ Обмен успешен! +1 {result_pdef.get('name', result_pid)}", show_alert=True)
