@dp.callback_query(F.data.startswith("pet_equip|"))
async def cb_pet_equip(call: CallbackQuery):
    uid = call.from_user.id
    user = await db.get_user(uid)
    normalize_pet_storage(user)
    try:
        parts = call.data.split("|")
        iid_text = parts[1]
        slot_text = parts[2]
        return_to_pets = len(parts) > 3 and parts[3] == "pets"
        iid = int(iid_text)
        slot = int(slot_text)
    except (ValueError, IndexError):
        await call.answer("Некорректный питомец.", show_alert=True)
        return
    if slot < 0 or slot >= get_pet_slots(user):
        await call.answer("Этот слот ещё закрыт.", show_alert=True)
        return
    pet = get_pet_by_iid(user, iid)
    if not pet:
        await call.answer("Пет не найден.", show_alert=True)
        return
    equipped = user.setdefault("equipped_pets", [None, None])
    for idx, current_iid in enumerate(equipped):
        if current_iid == iid:
            equipped[idx] = None
    equipped[slot] = iid
    recalculate_user_combat_stats(user, active_battles.get(uid))
    await save_runtime_state(uid, user)
    await call.answer("Пет надет.", show_alert=True)
    if return_to_pets:
        await show_pets(uid, lambda t, kb: edit_for_user(call, t, kb))
    else:
        await show_pet_detail(uid, iid, lambda t, kb: edit_for_user(call, t, kb))

