def get_hungry_equipped_pets(user: dict) -> List[dict]:
    now = time.time()
    pets = []
    for slot in range(get_pet_slots(user)):
        pet = get_equipped_pet(user, slot)
        if pet and float(pet.get("feeding_until") or 0) <= now:
            pets.append(pet)
    return pets


@dp.callback_query(F.data == "pets_feed_all")
async def cb_pets_feed_all(call: CallbackQuery):
    uid = call.from_user.id
    user = await db.get_user(uid)
    normalize_pet_storage(user)
    finished = process_pet_feeds(user)  # сначала забираем награды тех, кто доел
    hungry = get_hungry_equipped_pets(user)
    if not hungry:
        if finished:
            await save_runtime_state(uid, user)
        await call.answer("Все надетые питомцы уже кушают." if get_active_pets(user) else "Нет надетых питомцев.", show_alert=True)
        await show_pets(uid, lambda t, kb: edit_for_user(call, t, kb))
        return
    fed, skipped = [], []
    for pet in hungry:
        cost = get_pet_food_cost(pet)
        if int(user.get("marshmallows", 0)) >= cost:
            user["marshmallows"] = int(user.get("marshmallows", 0)) - cost
            pet["feeding_until"] = time.time() + get_pet_feed_seconds(pet)
            add_weekly_stat(user, "pet_feeds")
            fed.append(pet["name"])
        else:
            skipped.append(f"{pet['name']} (нужно {cost})")
    recalculate_user_combat_stats(user, active_battles.get(uid))
    await save_runtime_state(uid, user)
    if fed and not skipped:
        await call.answer(f"Покормлены: {', '.join(fed)}", show_alert=True)
    elif fed:
        await call.answer(f"Покормлены: {', '.join(fed)}. Не хватило зефирок: {', '.join(skipped)}", show_alert=True)
    else:
        await call.answer(f"Не хватает зефирок: {', '.join(skipped)}. Купи их в магазине питомцев.", show_alert=True)
    await show_pets(uid, lambda t, kb: edit_for_user(call, t, kb))


