@dp.message(lambda msg: (
    msg.from_user
    and msg.from_user.id in pending_nicknames
    and msg.reply_to_message is not None
    and msg.reply_to_message.message_id == pending_nicknames.get(msg.from_user.id)
))
async def text_set_nickname(message: Message):
    uid = message.from_user.id
    nickname = (message.text or "").strip()

    if not nickname or nickname.startswith("/"):
        await reply_to_user(message, "Напиши ник обычным текстом.")
        return
    if len(nickname) < 2 or len(nickname) > 20:
        await reply_to_user(message, "Ник должен быть от 2 до 20 символов.")
        return
    if any(char in nickname for char in "<>\n\r\t"):
        await reply_to_user(message, "В нике нельзя использовать переносы и символы < >.")
        return
    if await db.is_name_taken(nickname):
        await reply_to_user(message, "Такой ник уже занят. Выбери другой.")
        return

    custom_emoji_ids, custom_emoji_texts = get_message_custom_emoji_data(message)
    user = await db.get_user(uid, create=True, name=nickname)
    user["nickname_custom_emoji_ids"] = custom_emoji_ids
    user["nickname_custom_emoji_texts"] = custom_emoji_texts
    user["tg_xp_bonus"] = telegram_name_has_xp_bonus(message.from_user)
    user["tg_display_name"] = " ".join(
        part for part in (message.from_user.first_name or "", message.from_user.last_name or "") if part
    ).strip()
    if message.from_user.username:
        user["tg_display_name"] = (user["tg_display_name"] + f" @{message.from_user.username}").strip()
    await db.save_user(uid, user)
    pending_nicknames.pop(uid, None)
    await reply_to_user(message,
        f'<tg-emoji emoji-id="5325593644122524396">✅</tg-emoji> Ник <b>{render_user_nickname(user)}</b> сохранён.\n'
        "Теперь команды доступны.",
        parse_mode="HTML",
    )

