@dp.callback_query(F.data == "roll")
async def cb_roll(call: CallbackQuery):
    now = time.time()
    if call.from_user.id in last_roll and now - last_roll[call.from_user.id] < 5:
        seconds = math.ceil(5 - (now - last_roll[call.from_user.id]))
        await call.answer(f"⏳ Осталось {seconds} сек.")
        return
    await call.answer()
    await do_roll(
        call.from_user.id,
        lambda t, kb: edit_for_user(call, t, kb),
        lambda t, kb: answer_from_callback(call, t, kb),
        sticker_func=lambda: send_quest_done_sticker(call.message),
    )

