@dp.callback_query(F.data.startswith("auto_filter|"))
async def cb_auto_filter(call: CallbackQuery):
    rarity = call.data.split("|", 1)[1]
    user = await db.get_user(call.from_user.id)
    filters = set(user.get("auto_roll_filters", []))
    if rarity in filters:
        filters.remove(rarity)
        await call.answer("Фильтр снят.")
    else:
        filters.add(rarity)
        await call.answer("Редкость будет удаляться.")
    user["auto_roll_filters"] = [rarity_key for rarity_key in RARITIES if rarity_key in filters]
    await save_runtime_state(call.from_user.id, user)
    await show_auto_filter_menu(call.from_user.id, lambda t, kb: edit_for_user(call, t, kb))


