@dp.callback_query(F.data.startswith("auto_essence|"))
async def cb_auto_essence(call: CallbackQuery):
    rarity = call.data.split("|", 1)[1]
    if rarity not in AUTO_ROLL_ESSENCE_RARITIES:
        await call.answer("Эта редкость недоступна для автоутиля в эссенцию.", show_alert=True)
        return
    user = await db.get_user(call.from_user.id)
    enabled = set(user.get("auto_roll_essence", []))
    if rarity in enabled:
        enabled.remove(rarity)
        await call.answer("Автоутиль в эссенцию выключен.")
    else:
        enabled.add(rarity)
        filters = set(user.get("auto_roll_filters", []))
        if rarity in filters:
            filters.discard(rarity)
            user["auto_roll_filters"] = [rarity_key for rarity_key in RARITIES if rarity_key in filters]
        await call.answer("Будет превращаться в эссенцию.")
    user["auto_roll_essence"] = [r for r in AUTO_ROLL_ESSENCE_RARITIES if r in enabled]
    await save_runtime_state(call.from_user.id, user)
    await show_auto_essence_menu(call.from_user.id, lambda t, kb: edit_for_user(call, t, kb))


@dp.callback_query(F.data.startswith("auto_essence_all|"))
async def cb_auto_essence_all(call: CallbackQuery):
    mode = call.data.split("|", 1)[1]
    user = await db.get_user(call.from_user.id)
    if mode == "on":
        user["auto_roll_essence"] = list(AUTO_ROLL_ESSENCE_RARITIES)
        filters = set(user.get("auto_roll_filters", []))
        for r in AUTO_ROLL_ESSENCE_RARITIES:
            filters.discard(r)
        user["auto_roll_filters"] = [rarity_key for rarity_key in RARITIES if rarity_key in filters]
        await call.answer("Автоутиль в эссенцию включён для эпик+.")
    else:
        user["auto_roll_essence"] = []
        await call.answer("Автоутиль в эссенцию выключен.")
    await save_runtime_state(call.from_user.id, user)
    await show_auto_essence_menu(call.from_user.id, lambda t, kb: edit_for_user(call, t, kb))

