@dp.callback_query(F.data.startswith("quick_boss|"))
async def cb_quick_boss_start(call: CallbackQuery):
    if not await ensure_bosses_private_callback(call):
        return
    boss_id = call.data.split("|", 1)[1]
    boss = BOSSES.get(boss_id)
    if not boss:
        await call.answer("❌ Босс не найден.", show_alert=True)
        return

    user = await db.get_user(call.from_user.id)
    player_level = user.get("level", 1)
    loc = LOCATIONS.get(boss.get("location"))
    if loc and player_level < loc["min_level"]:
        await call.answer(f"🔒 Нужен {loc['min_level']} уровень.", show_alert=True)
        return

    cd_remaining = get_boss_cd_remaining(user, boss_id)
    if cd_remaining > 0:
        await call.answer(f"⏳ Осталось {format_cd_time(cd_remaining)}.", show_alert=True)
        return

    await call.answer()
    await start_boss_raid(call.message, call.from_user.id, boss_id, answer_func=lambda t, kb: edit_for_user(call, t, kb))

