@dp.callback_query(F.data.startswith("smith_fusion_boost|"))
async def cb_smith_fusion_boost(call: CallbackQuery):
    try:
        _, iid, shard_id = call.data.split("|", 2)
    except (ValueError, IndexError):
        await call.answer("Кузнец не понял осколок.", show_alert=True)
        return
    if shard_id not in FUSION_SHARD_BOOSTS:
        await call.answer("Осколок не подходит.", show_alert=True)
        return
    user = await db.get_user(call.from_user.id)
    item = get_user_item_by_iid(user, iid)
    if not item:
        await call.answer("Предмет не найден.", show_alert=True)
        return
    boost = get_fusion_boost_session(call.from_user.id, iid)
    current_percent = int(boost.get("percent", 0) or 0)
    add_percent = FUSION_SHARD_BOOSTS[shard_id]
    limit = get_fusion_boost_limit(item)
    if current_percent + add_percent > limit:
        await call.answer(f"Лимит буста для этой звезды: {limit}%.", show_alert=True)
        return
    selected = int(boost.setdefault("shards", {}).get(shard_id, 0) or 0)
    if user.get("boss_loot", {}).get(shard_id, 0) <= selected:
        await call.answer("Нет такого осколка.", show_alert=True)
        return
    boost["shards"][shard_id] = selected + 1
    boost["percent"] = current_percent + add_percent
    await call.answer(f"+{add_percent}% к шансу.")
    await show_smith_item(call.from_user.id, "fusion", iid, lambda t, kb: edit_for_user(call, t, kb))

