@dp.callback_query(F.data == "recycle_toggle")
async def cb_recycle_toggle(call: CallbackQuery):
    uid = call.from_user.id
    selected = recycle_sessions.get(uid)
    if recycle_modes.get(uid) == "essence":
        selected = None  # переключились из режима эссенции в утиль — начинаем выбор заново
    if not selected:
        recycle_sessions[uid] = set()
        recycle_modes[uid] = "coins"
        await call.answer("Выбери предметы для переработки.")
        await show_inv(uid, lambda t, kb: edit_for_user(call, t, kb))
        return

    coins, removed_count = await recycle_selected_weapons(uid)
    await call.answer(f"Переработано: {removed_count}. +{coins} монет.", show_alert=True)
    await show_inv(uid, lambda t, kb: edit_for_user(call, t, kb))

def is_item_equipped(user: dict, item: dict) -> bool:
    iid = item.get("iid")
    if not iid:
        return False
    eq = user.get("equipped")
    if isinstance(eq, dict) and eq.get("iid") == iid:
        return True
    return any(isinstance(p, dict) and p.get("iid") == iid for p in (user.get("equipped_armor") or {}).values())


def collect_essence_selection(user_id: int, user: dict) -> tuple:
    """[(индекс в инвентаре, предмет)] для превращения + сколько пропущено (надето/замок)."""
    selected = recycle_sessions.get(user_id) or set()
    locked = lock_sessions.get(user_id, set())
    picked, skipped = [], 0
    copy_counts: Dict[str, int] = {}
    for idx, item in enumerate(user.get("inventory", [])):
        item_id = item["id"]
        copy_idx = copy_counts.get(item_id, 0)
        copy_counts[item_id] = copy_idx + 1
        key = f"{item_id}|{copy_idx}"
        if key not in selected:
            continue
        if key in locked or is_item_equipped(user, item) or get_essence_id_for_rarity(item.get("rarity")) not in BOSS_RESOURCE_DEFS:
            skipped += 1
            continue
        picked.append((idx, item))
    return picked, skipped


