@dp.callback_query(F.data == "essence_ask")
async def cb_essence_ask(call: CallbackQuery):
    uid = call.from_user.id
    user = await db.get_user(uid)
    restore_lock_session_from_user(uid, user)
    picked, skipped = collect_essence_selection(uid, user)
    if not picked:
        await call.answer("Ничего не выбрано (надетые и предметы под замком не считаются).", show_alert=True)
        return
    await call.answer()
    by_rarity = collections.Counter(item.get("rarity") for _, item in picked)
    order = {r: i for i, r in enumerate(RARITY_ORDER)}
    lines = []
    for rarity, n in sorted(by_rarity.items(), key=lambda kv: order.get(kv[0], 99)):
        info = BOSS_RESOURCE_DEFS.get(get_essence_id_for_rarity(rarity), {})
        lines.append(f"{info.get('emoji', '✨')} {html.escape(str(info.get('name', rarity)))}: <b>+{n}</b>")
    names = ", ".join(html.escape(str(item.get("name", "?"))) for _, item in picked[:12]) + (" …" if len(picked) > 12 else "")
    skip_text = f"\n<i>Пропущено {skipped}: надетые или под замком.</i>" if skipped else ""
    text = (
        '<tg-emoji emoji-id="5440660757194744323">‼️</tg-emoji> <b>Превратить в эссенцию?</b>\n\n'
        f"<blockquote>Предметов: <b>{len(picked)}</b>\n{names}</blockquote>\n\n"
        "<blockquote><b>Получишь</b>\n" + "\n".join(lines) + "</blockquote>"
        f"{skip_text}\n\nПредметы пропадут навсегда."
    )
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text=f"Да, превратить {len(picked)} шт.", callback_data="essence_do", icon_custom_emoji_id="5325762861539016690")],
        [InlineKeyboardButton(text="Назад к выбору", callback_data="essence_back", icon_custom_emoji_id="5215361191051798408")],
    ])
    await edit_for_user(call, text, kb)


