@dp.callback_query(F.data == "essence_do")
async def cb_essence_do(call: CallbackQuery):
    uid = call.from_user.id
    if recycle_modes.get(uid) != "essence" or not recycle_sessions.get(uid):
        await call.answer("Выбор устарел — открой экипировку заново.", show_alert=True)
        return
    user = await db.get_user(uid)
    restore_lock_session_from_user(uid, user)
    picked, _ = collect_essence_selection(uid, user)
    if not picked:
        await call.answer("Нечего превращать.", show_alert=True)
        return
    remove_idx = {idx for idx, _ in picked}
    gained = collections.Counter()
    for _, item in picked:
        essence_id = get_essence_id_for_rarity(item.get("rarity"))
        add_boss_resource(user, essence_id, 1)
        gained[essence_id] += 1
    user["inventory"] = [it for i, it in enumerate(user.get("inventory", [])) if i not in remove_idx]
    recycle_sessions.pop(uid, None)
    recycle_modes.pop(uid, None)
    sync_equipment_with_inventory(user)
    # замки хранятся по iid и не удаляются — пересобираем ключи под новый порядок инвентаря
    restore_lock_session_from_user(uid, user)
    await save_runtime_state(uid, user)
    summary = ", ".join(f"{BOSS_RESOURCE_DEFS.get(eid, {}).get('name', eid)} +{n}" for eid, n in gained.items())
    await call.answer(f"Готово! {summary}", show_alert=True)
    await show_inv(uid, lambda t, kb: edit_for_user(call, t, kb))


