@dp.callback_query(F.data == "recycle_all")
async def cb_recycle_all(call: CallbackQuery):
    uid = call.from_user.id
    user = await db.get_user(uid)
    restore_lock_session_from_user(uid, user)
    locked = lock_sessions.get(uid, set())
    all_keys = []
    copy_counts = {}
    for item in user.get("inventory", []):
        item_id = item["id"]
        copy_idx = copy_counts.get(item_id, 0)
        copy_counts[item_id] = copy_idx + 1
        key = f"{item_id}|{copy_idx}"
        if key not in locked:
            all_keys.append(key)

    selected = recycle_sessions.setdefault(uid, set())
    if all_keys and len(selected.intersection(all_keys)) == len(all_keys):
        selected.clear()
        await call.answer("Выбор очищен.")
    else:
        selected.clear()
        selected.update(all_keys)
        await call.answer("Выбрано всё.")
    await show_inv(uid, lambda t, kb: edit_for_user(call, t, kb))

