@dp.callback_query(F.data == "claim_trash")
async def cb_claim_trash(call: CallbackQuery):
    uid = call.from_user.id
    u = await db.get_user(uid)
    trash = u.get("trash") or []
    inv = u.get("inventory", [])

    if not trash:
        await call.answer()
        await call.message.edit_text("🗑️ <b>Корзина пуста</b>", reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="Назад", callback_data="equipment", icon_custom_emoji_id="5215361191051798408")]
        ]), parse_mode="HTML")
        return

    free_slots = MAX_INVENTORY - len(inv)
    if free_slots <= 0:
        await call.answer("❌ В инвентаре нет места! Освободи место и попробуй снова.", show_alert=True)
        return

    taken = 0
    new_trash = []
    for t in trash:
        if taken >= free_slots:
            new_trash.append(t)
        else:
            inv.append(t["item"])
            taken += 1

    u["inventory"] = inv
    u["trash"] = new_trash
    trash_recycle_sessions.pop(uid, None)
    await db.save_user(uid, u)

    if taken > 0:
        await call.answer(f"✅ Забрано {taken} предмет(ов)!", show_alert=True)
    else:
        await call.answer("❌ Нет места в инвентаре!", show_alert=True)

    await show_trash(uid, lambda t, kb: edit_for_user(call, t, kb))

