@dp.callback_query(F.data.startswith("equip_") & ~F.data.startswith("equip_armor|"))
async def cb_equip(call: CallbackQuery):
    uid = call.from_user.id
    try:
        payload = call.data.removeprefix("equip_")
        parts = payload.rsplit("_", 2)
        if len(parts) == 3 and parts[2].isdigit():
            weapon_id, copy_idx_text, page_text = parts
        else:
            weapon_id, copy_idx_text = payload.rsplit("_", 1)
            page_text = "0"
        copy_idx = int(copy_idx_text)
        page = int(page_text)
    except (AttributeError, ValueError):
        await call.answer("❌ Некорректные данные оружия!", show_alert=True)
        return

    u = await db.get_user(uid)
    copies = [i for i, w in enumerate(u["inventory"]) if w["id"] == weapon_id and w.get("item_type") != "armor"]
    if not copies or copy_idx < 0 or copy_idx >= len(copies):
        await call.answer("❌ Оружие не найдено!", show_alert=True)
        return

    idx = copies[copy_idx]
    weapon = u["inventory"][idx]
    equipped = u.get("equipped")

    if equipped and equipped.get("iid") and equipped.get("iid") == weapon.get("iid"):
        u["equipped"] = None
        await db.save_user(uid, u)
        await call.answer("❌ Оружие снято!", show_alert=True)
    else:
        u["equipped"] = weapon
        await db.save_user(uid, u)
        await call.answer(f"✨ {weapon['name']} надето!", show_alert=True)

    is_equipped = u["equipped"] and u["equipped"].get("iid") == weapon.get("iid")
    text = get_item_card_text(weapon)
    kb = get_item_card_keyboard(weapon, u, copy_idx, page)
    await call.message.edit_text(text, reply_markup=kb, parse_mode="HTML")

@dp.callback_query(F.data.startswith("equip_armor|"))
async def cb_equip_armor(call: CallbackQuery):
    uid = call.from_user.id
    try:
        parts = call.data.split("|")
        if len(parts) == 4 and parts[2].startswith("iid:"):
            _, slot, item_ref, page_text = parts
            armor_id = None
            copy_idx = 0
        elif len(parts) >= 5:
            _, slot, armor_id, copy_idx_text, page_text = parts[:5]
            item_ref = None
            copy_idx = int(copy_idx_text)
        else:
            raise ValueError
        page = int(page_text)
    except (AttributeError, ValueError):
        await call.answer("❌ Некорректная броня!", show_alert=True)
        return

    if slot not in ARMOR_SLOTS:
        await call.answer("❌ Неверный слот брони!", show_alert=True)
        return

    u = await db.get_user(uid)
    if item_ref and item_ref.startswith("iid:"):
        armor_item = find_inventory_item_by_iid(u, item_ref.removeprefix("iid:"), item_type="armor", slot=slot)
    else:
        copies = [
            a for a in u.get("inventory", [])
            if a.get("id") == armor_id and a.get("item_type") == "armor" and armor_slot_matches(a.get("slot"), slot)
        ]
        armor_item = copies[copy_idx] if copies and 0 <= copy_idx < len(copies) else None

    if not armor_item:
        await call.answer("❌ Броня не найдена!", show_alert=True)
        return

    equipped_armor = u.setdefault("equipped_armor", {slot_name: None for slot_name in ARMOR_SLOTS})
    current_in_slot = equipped_armor.get(slot)

    if current_in_slot and current_in_slot.get("iid") == armor_item.get("iid"):
        equipped_armor[slot] = None
        await call.answer(f"❌ {armor_item['name']} снята!", show_alert=True)
    else:
        equipped_armor[slot] = armor_item
        await call.answer(f"✅ {armor_item['name']} надета!", show_alert=True)

    u["max_hp"] = calculate_max_hp_with_armor(u.get("level", 1), equipped_armor, u)
    u["hp"] = min(u.get("hp", u["max_hp"]), u["max_hp"])
    await db.save_user(uid, u)

    text = get_item_card_text(armor_item)
    kb = get_item_card_keyboard(armor_item, u, copy_idx, page)
    await call.message.edit_text(text, reply_markup=kb, parse_mode="HTML")

@dp.callback_query(F.data.startswith("upgrade|"))
async def cb_upgrade_weapon(call: CallbackQuery):
    try:
        _, weapon_id, copy_idx_text = call.data.split("|", 2)
        copy_idx = int(copy_idx_text)
    except (AttributeError, ValueError):
        await call.answer("❌ Некорректные данные.", show_alert=True)
        return

    uid = call.from_user.id
    u = await db.get_user(uid)
    copies = [i for i, w in enumerate(u["inventory"]) if w["id"] == weapon_id and w.get("item_type") != "armor"]
    if not copies or copy_idx < 0 or copy_idx >= len(copies):
        await call.answer("❌ Оружие не найдено.", show_alert=True)
        return

    weapon = u["inventory"][copies[copy_idx]]
    upgrade_level = weapon.get("upgrade_level", 0)
    if upgrade_level >= MAX_UPGRADE_LEVEL:
        await call.answer("У оружия уже максимальный уровень.", show_alert=True)
        return

    cost = get_upgrade_cost(weapon)
    if u.get("coins", 0) < cost:
        await call.answer(f"Нужно {cost} монет. У тебя {u.get('coins', 0)}.", show_alert=True)
        return

    ensure_item_base_stats(weapon)
    old_min, old_max = weapon.get("base_dmg", weapon["dmg"])
    weapon["base_dmg"] = (
        old_min + max(1, math.ceil(old_min * 0.10)),
        old_max + max(1, math.ceil(old_max * 0.10)),
    )
    weapon["upgrade_level"] = upgrade_level + 1
    apply_item_fusion_stats(weapon)
    u["coins"] -= cost

    equipped = u.get("equipped")
    is_equipped = bool(equipped and equipped.get("iid") == weapon.get("iid"))
    if is_equipped:
        u["equipped"] = weapon

    await db.save_user(uid, u)
    await call.answer(f"Улучшено до +{weapon['upgrade_level']}! −{cost} монет.", show_alert=True)
    await call.message.edit_text(
        get_item_card_text(weapon),
        reply_markup=get_item_card_keyboard(weapon, u, copy_idx),
        parse_mode="HTML",
    )

@dp.callback_query(F.data.startswith("battle_attack"))
async def cb_battle_attack(call: CallbackQuery):
    uid = call.from_user.id
    lock = battle_locks.setdefault(uid, asyncio.Lock())
    if lock.locked():
        await call.answer("Ход уже выполняется.")
        return

    async with lock:
        target_idx = None
        if "|" in call.data:
            try:
                target_idx = int(call.data.split("|", 1)[1])
            except (TypeError, ValueError):
                target_idx = None
        await process_battle_attack(call, target_idx)
    if uid not in active_battles:
        battle_locks.pop(uid, None)

