async def process_battle_attack(call: CallbackQuery, target_idx: Optional[int] = None):
    uid = call.from_user.id
    battle = active_battles.get(uid)
    if not battle:
        await call.answer("Эта битва уже завершена.", show_alert=True)
        return
    if is_boss_battle_expired(battle):
        user = await db.get_user(uid)
        await clear_expired_boss_battle(uid, user)
        await call.answer("⏳ Рейд завершён: ты не атаковал 5 минут.", show_alert=True)
        await edit_battle_message(
            call,
            get_battle_text(battle, "<tg-emoji emoji-id=\"5287473790735890430\">⏳</tg-emoji> <b>Рейд завершён.</b> Ты не атаковал 5 минут."),
        )
        return
    if battle.get("busy"):
        await call.answer("Ход уже выполняется.")
        return

    battle["busy"] = True
    if battle.get("mode") == "bosses":
        battle["last_action_at"] = time.time()
    await call.answer()
    await set_battle_waiting(call)
    try:
        battle = active_battles.get(uid)
        if not battle:
            return
        user = await db.get_user(uid)
        if battle.get("mode") == "bosses":
            active_skill = battle.get(ACTIVE_BATTLE_SKILL_KEY)
            if active_skill in TOGGLE_BATTLE_SKILLS:
                block_reason = get_battle_skill_block_reason(user, battle, active_skill)
                if block_reason:
                    battle.pop(ACTIVE_BATTLE_SKILL_KEY, None)
                    await save_battle_state_throttled(uid, user, force=True)
                else:
                    await apply_battle_skill(call, active_skill, target_idx=target_idx, auto_from_attack=True)
                    return
        equipped = user.get("equipped")
        if equipped:
            level = user.get("level", 1)
            player_damage = random.randint(*scale_weapon_damage(equipped["dmg"], level))
            weapon_name = html.escape(equipped["name"])
        else:
            level = user.get("level", 1)
            player_damage = random.randint(1 + level // 3, 3 + level // 2)
            weapon_name = "кулаки"
        attack_context = battle_user_context(user, battle) if battle.get("mode") == "bosses" else user
        player_damage = apply_damage_buff(attack_context, player_damage)
        player_damage, attack_notes = roll_player_attack_effects(attack_context, player_damage)

        if battle.get("mode") == "bosses":
            ensure_boss_battle_damage_scaled(battle)
            await handle_boss_attack(call, battle, user, player_damage, weapon_name, attack_notes, target_idx=target_idx)
            return

        add_path_attack_xp(user)
        enemy = battle["enemy"]
        enemy["hp"] -= player_damage
        user["total_damage"] = user.get("total_damage", 0) + player_damage
        if "промах" in attack_notes:
            player_log = f"<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> {weapon_name}: промах"
        else:
            note_text = " · " + ", ".join(attack_notes) if attack_notes else ""
            player_log = f"<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> {weapon_name}: −{player_damage} HP{note_text}"
            heal = apply_vampirism_heal(user, battle, player_damage)
            if heal:
                player_log += f'\n<tg-emoji emoji-id="5188280649156420607">🩸</tg-emoji> Вампиризм: +{heal} HP'

        if enemy["hp"] <= 0:
            coins = apply_coin_buff(user, random.randint(*enemy["coins"]) + enemy["level"] * 2)
            xp = random.randint(*enemy["xp"]) + enemy["level"] * 3
            xp = apply_xp_buff(user, xp)
            user["coins"] = user.get("coins", 0) + coins
            user["monsters_killed"] = user.get("monsters_killed", 0) + 1
            levels_gained = add_xp(user, xp)
            active_battles.pop(uid, None)
            await save_battle_state_throttled(uid, user, force=True)
            level_text = f"\n<tg-emoji emoji-id=\"6084922627736996647\">🆙</tg-emoji> Новый уровень: <b>{user['level']}</b>" if levels_gained else ""
            await edit_battle_message(
                call,
                get_battle_text(battle, player_log)
                + "\n\n<tg-emoji emoji-id=\"5226431245918942763\">🏆</tg-emoji> <b>Победа!</b>"
                + f"\n<tg-emoji emoji-id=\"5463046637842608206\">🪙</tg-emoji> +{coins} монет · <tg-emoji emoji-id=\"5370831521039017384\">✨</tg-emoji> +{format_num(xp)} опыта"
                + level_text,
            )
            return

        enemy_damage = random.randint(*enemy["damage"])
        enemy_damage = apply_incoming_damage_reduction(user, enemy_damage)
        battle["player_hp"] -= enemy_damage
        if battle["player_hp"] <= 0:
            active_battles.pop(uid, None)
            await save_battle_state_throttled(uid, user, force=True)
            await edit_battle_message(
                call,
                get_battle_text(
                    battle,
                    f"{player_log}\n"
                    f"{enemy['emoji']} Ответный удар: −{enemy_damage} HP",
                ) + "\n\n<tg-emoji emoji-id=\"6327816922544997828\">💀</tg-emoji> <b>Поражение.</b> Награды не получены.",
            )
            return

        await save_battle_state_throttled(uid, user)
        await edit_battle_message(
            call,
            get_battle_text(
                battle,
                f"{player_log}\n"
                f"{enemy['emoji']} Ответный удар: −{enemy_damage} HP",
            ),
            reply_markup=battle_keyboard(battle),
        )
    finally:
        battle["busy"] = False
@dp.callback_query(F.data == "belt_best")
async def cb_belt_best(call: CallbackQuery):
    uid = call.from_user.id
    u = await db.get_user(uid)
    inv = u.get("inventory", [])
    changed = False

    weapons = [item for item in inv if item.get("item_type") != "armor"]
    if weapons:
        best_weapon = max(weapons, key=lambda w: (calculate_player_power(w, u.get("level", 1)), sum(scale_weapon_damage(w.get("dmg", (0, 0)), u.get("level", 1)))))
        current = u.get("equipped")
        if not current or best_weapon.get("iid") != current.get("iid"):
            u["equipped"] = best_weapon
            changed = True

    equipped_armor = u.setdefault("equipped_armor", {slot: None for slot in ARMOR_SLOTS})
    for slot in ARMOR_SLOTS:
        slot_pieces = [item for item in inv if item.get("item_type") == "armor" and item.get("slot") == slot]
        if slot_pieces:
            best_piece = max(slot_pieces, key=lambda a: (a.get("hp", 0), a.get("level", 1)))
            current = equipped_armor.get(slot)
            if not current or best_piece.get("iid") != current.get("iid"):
                equipped_armor[slot] = best_piece
                changed = True

    refresh_equipped_from_inventory(u)
    await db.save_user(uid, u)
    await call.answer("🔥 Лучшее экипировано!" if changed else "Уже надето лучшее.", show_alert=True)
    await call.message.edit_text(
        get_belt_text(u),
        reply_markup=build_belt_keyboard(u),
        parse_mode="HTML",
    )

