@dp.callback_query(F.data.startswith("admin_pet_take|"))
async def cb_admin_pet_take(call: CallbackQuery):
    if call.from_user.id not in ADMIN_IDS:
        await call.answer("Только для админов.", show_alert=True)
        return
    parts = call.data.split("|")
    if len(parts) != 4:
        await call.answer("Ошибка данных.", show_alert=True)
        return
    try:
        target_id = int(parts[1])
        iid = int(parts[2])
        page = int(parts[3])
    except ValueError:
        await call.answer("Ошибка данных.", show_alert=True)
        return

    user = await db.get_user(target_id)
    if not user:
        await call.answer("Профиль не найден.", show_alert=True)
        return
    normalize_pet_storage(user)
    pet = get_pet_by_iid(user, iid)
    if not pet:
        await call.answer("Пет уже не найден.", show_alert=True)
        await edit_for_user(
            call,
            admin_pet_take_text(target_id, user),
            build_admin_pet_take_keyboard(target_id, user, page),
            parse_mode="HTML",
        )
        return

    pet_name = PET_DEFS.get(pet.get("pet_id"), {}).get("name", pet.get("name", "Пет"))
    user["pets"] = [
        item for item in user.get("pets", [])
        if str(item.get("iid")) != str(iid)
    ]
    user["equipped_pets"] = [
        None if str(slot) == str(iid) else slot
        for slot in user.get("equipped_pets", [None, None])
    ]
    while len(user["equipped_pets"]) < 2:
        user["equipped_pets"].append(None)
    if len(user["equipped_pets"]) > 2:
        del user["equipped_pets"][2:]

    recalculate_user_combat_stats(user, active_battles.get(target_id))
    await save_runtime_state(target_id, user)
    await call.answer(f"Забран: {pet_name}", show_alert=True)
    await edit_for_user(
        call,
        admin_pet_take_text(target_id, user),
        build_admin_pet_take_keyboard(target_id, user, page),
        parse_mode="HTML",
    )

