def get_level_xp_required(level: int) -> int:
    return max(1, math.ceil(50 * (1.25 ** max(0, level - 1))))

def get_high_level_boss_xp_bonus(user: dict, boss: Optional[dict] = None, hard_mode: bool = False) -> int:
    level = int(user.get("level", 1))
    if level < 50:
        return 0
    if boss and boss.get("location") == "swamp":
        bonus_percent = 0.001
    elif hard_mode:
        bonus_percent = 0.005
    else:
        bonus_percent = 0.0025
    return max(1, math.ceil(get_level_xp_required(level) * bonus_percent))

def get_boss_xp_reward(user: dict, boss: dict, hard_mode: bool = False) -> int:
    xp = random.randint(*boss["xp"])
    xp = apply_night_event_boss_xp(xp)
    xp = apply_boss_hard_xp(xp, hard_mode)
    xp = apply_xp_buff(user, xp)
    return xp + get_high_level_boss_xp_bonus(user, boss, hard_mode)

def add_xp(user: dict, amount: int) -> int:
    user["xp"] = user.get("xp", 0) + amount
    levels_gained = 0
    while user["xp"] >= get_level_xp_required(user.get("level", 1)):
        required = get_level_xp_required(user.get("level", 1))
        user["xp"] -= required
        user["level"] += 1
        user["skill_points"] = get_skill_points(user) + 1
        equipped_armor = user.get("equipped_armor", {slot: None for slot in ARMOR_SLOTS})
        user["max_hp"] = calculate_max_hp_with_armor(user["level"], equipped_armor, user)
        user["hp"] = user["max_hp"]
        levels_gained += 1
    if levels_gained:
        ensure_daily_stats(user)["levels"] += levels_gained
    return levels_gained

