def get_equipped_attack(user: dict) -> tuple[int, str]:
    level = user.get("level", 1)
    equipped = user.get("equipped")
    if equipped:
        damage = random.randint(*scale_weapon_damage(equipped.get("dmg", (1, 2)), level))
        return apply_damage_buff(user, damage), html.escape(equipped.get("name", "оружие"))
    return apply_damage_buff(user, random.randint(1 + level // 3, 3 + level // 2)), "кулаки"

def get_skill_resource_cost(user: dict, skill_id: str) -> tuple[str, int]:
    discount = 1 - get_path_bonus(user, "resource_discount") / 100
    if skill_id == "juggernaut":
        raw = _get_path_raw_bonus(user, "juggernaut_cost")
        percent = int(raw) if raw else 8
        return "hp_percent", max(1, percent)
    if skill_id in ("war_cry", "blood_rage", "berserk", "great_power", "fortify"):
        percent = {
            "war_cry": 10,
            "blood_rage": 5,
            "berserk": 10,
            "great_power": 40,
            "fortify": 0,
        }[skill_id]
        if percent <= 0:
            return "none", 0
        return "hp_percent", percent
    if skill_id == "arrow_rain":
        cost = int(get_path_bonus(user, "arrow_rain_cost") or 50)
        return "stamina", max(1, math.ceil(cost * discount))
    if skill_id == "sniper_shot":
        return "stamina", max(1, math.ceil(60 * discount))
    if skill_id == "aim":
        return "stamina", max(1, math.ceil(250 * discount))
    if skill_id == "multi_shot":
        return "stamina", max(1, math.ceil(80 * discount))
    if skill_id == "eagle_eye":
        return "stamina", max(1, math.ceil(120 * discount))
    if skill_id == "pierce_shot":
        return "stamina", max(1, math.ceil(100 * discount))
    if skill_id == "splash":
        cost = int(get_path_bonus(user, "splash_cost") or 50)
        return "mana", max(1, math.ceil(cost * discount))
    if skill_id == "magic_shield":
        return "mana", max(1, math.ceil(90 * discount))
    if skill_id == "blast_wave":
        return "mana", max(1, math.ceil(250 * discount))
    if skill_id == "arcane_shield":
        return "mana", max(1, math.ceil(110 * discount))
    if skill_id == "rune_barrage":
        return "mana", max(1, math.ceil(100 * discount))
    if skill_id == "nova":
        return "mana", max(1, math.ceil(200 * discount))
    return "none", 0

BASE_RESOURCE_REGEN_PCT = 3.0  # базовое восстановление маны/выносливости за ход, %


def tick_battle_effects(battle: dict) -> str:
    """Тикает эффекты. Возвращает строку с DoT-уроном для лога."""
    dot_log = ""
    # Тик ранения на врагах
    for enemy in battle.get("enemies", []):
        if enemy.get("hp", 0) <= 0:
            continue
        if int(enemy.get("slow_turns", 0) or 0) > 0:
            enemy["slow_turns"] = int(enemy["slow_turns"]) - 1
        dot = enemy.get("dot", {})
        wound = dot.get("wound")
        if wound and wound.get("turns", 0) > 0:
            dmg = wound["damage"]
            enemy["hp"] -= dmg
            wound["turns"] -= 1
            dot_log += f"\n<tg-emoji emoji-id=\"5188280649156420607\">🩸</tg-emoji> Ранение: −{dmg} HP по {enemy['emoji']} {html.escape(enemy['name'])}."
            if wound["turns"] <= 0:
                del dot["wound"]
        poison = dot.get("poison")
        if poison and poison.get("turns", 0) > 0 and enemy.get("hp", 0) > 0:
            dmg = int(poison["damage"])
            enemy["hp"] -= dmg
            poison["turns"] -= 1
            dot_log += f"\n<tg-emoji emoji-id=\"5474265685125271190\">🩸</tg-emoji> Яд: −{dmg} HP по {enemy['emoji']} {html.escape(enemy['name'])}."
            if poison["turns"] <= 0:
                del dot["poison"]
    effects = battle.setdefault("effects", {})
    # arcane_shield_hp — запас щита, не тикает как ходы
    for key in list(effects):
        if key == "arcane_shield_hp":
            continue
        if effects[key] > 0:
            effects[key] -= 1
        if effects.get(key, 0) <= 0:
            effects.pop(key, None)
            if key == "arcane_shield_turns":
                effects.pop("arcane_shield_hp", None)
    cooldowns = battle.setdefault("skill_cooldowns", {})
    for key in list(cooldowns):
        if cooldowns[key] > 0:
            cooldowns[key] -= 1
        if cooldowns.get(key, 0) <= 0:
            cooldowns.pop(key, None)
    if battle.get("max_mana", 0) > 0:
        # базовые 3% за ход + бонус пути (раньше до первых уровней «Потока» маны не восстанавливалось вовсе)
        regen = BASE_RESOURCE_REGEN_PCT + get_path_bonus({"path": "magic", "path_level": battle.get("path_level", 1)}, "mana_regen")
        if regen:
            battle["mana"] = min(battle["max_mana"], battle.get("mana", 0) + max(1, math.ceil(battle["max_mana"] * regen / 100)))
    if battle.get("max_stamina", 0) > 0:
        regen = BASE_RESOURCE_REGEN_PCT + get_path_bonus({"path": "bow", "path_level": battle.get("path_level", 1)}, "stamina_regen")
        if regen:
            battle["stamina"] = min(battle["max_stamina"], battle.get("stamina", 0) + max(1, math.ceil(battle["max_stamina"] * regen / 100)))
    return dot_log

_BATTLE_CTX_SHARED_KEYS = {
    # большие поля, которые бой только читает — не копируем (раньше deepcopy всего профиля
    # с сотнями вещей стоил ~1.5 мс на каждый вызов, а вызовов несколько за ход)
    "inventory", "trash", "pets", "star_purchases", "quests", "witch_potions", "boss_loot",
    "auto_roll_session", "rarity_stats", "daily_top", "daily_top_prev", "bp", "tower", "mannequins",
}


def battle_user_context(user: dict, battle: dict) -> dict:
    temp_user = {k: (v if k in _BATTLE_CTX_SHARED_KEYS else copy.deepcopy(v)) for k, v in user.items()}
    temp_user["battle_effects"] = battle.get("effects", {})
    return temp_user

async def finish_boss_reward(call: CallbackQuery, battle: dict, user: dict, enemy_log: str, player_log: str) -> bool:
    if not all(enemy["hp"] <= 0 for enemy in battle.get("enemies", [])):
        return False
    uid = call.from_user.id
    if battle.get("wave", 1) < 4:
        battle["wave"] += 1
        battle["enemies"] = create_boss_wave(
            battle["wave"],
            get_current_boss_template(battle),
            bool(battle.get("hard_mode")),
        )
        tick_battle_effects(battle)
        await save_battle_state_throttled(uid, user, force=True)
        await edit_battle_message(
            call,
            get_battle_text(battle, f"{enemy_log}\n{player_log}\n\n🌊 Волна {battle['wave']}/4. Противники ходят первыми."),
            reply_markup=battle_keyboard(battle),
        )
        return True

    boss = battle.get("boss", next(iter(BOSSES.values())))
    coins_reward = boss["coins"]
    coins = coins_reward if isinstance(coins_reward, int) else random.randint(*coins_reward)
    coins = apply_coin_buff(user, coins)
    hard_mode = bool(battle.get("hard_mode"))
    xp = get_boss_xp_reward(user, boss, hard_mode)
    user["coins"] = user.get("coins", 0) + coins
    user["monsters_killed"] = user.get("monsters_killed", 0) + 10
    user["boss_kills"] = user.get("boss_kills", 0) + 1
    ensure_daily_stats(user)["boss_kills"] += 1
    add_weekly_stat(user, "bosses")
    location_id = boss.get("location")
    if location_id:
        location_kills = user.setdefault("boss_location_kills", {})
        location_kills[location_id] = location_kills.get(location_id, 0) + 1
    boss_id = boss.get("id")
    if boss_id:
        defeats = user.setdefault("boss_defeats", {})
        defeats[boss_id] = defeats.get(boss_id, 0) + 1
    drops = roll_boss_loot(user, boss)
    levels_gained = add_xp(user, xp)
    await log_boss_victory(call.from_user.id, user, boss, hard_mode, coins, xp, drops)
    user.setdefault("boss_cooldowns", {})[boss.get("id", "")] = time.time() + get_boss_cooldown(boss, user, hard_mode)
    if is_final_location_boss(boss):
        user.setdefault("boss_cd_notified", {})[boss.get("id", "")] = False
    active_battles.pop(uid, None)
    await save_battle_state_throttled(uid, user, force=True)
    await db.save_user(uid, user)
    loot_emoji = '<tg-emoji emoji-id="5463046637842608206">🪙</tg-emoji>'
    drop_text = "\n" + "\n".join(f"{loot_emoji} {drop}" for drop in drops) if drops else f"\n{loot_emoji} Лут не выпал."
    level_text = f"\n<tg-emoji emoji-id=\"6084922627736996647\">🆙</tg-emoji> Новый уровень: <b>{user['level']}</b>" if levels_gained else ""
    await edit_battle_message(
        call,
        get_battle_text(battle, f"{enemy_log}\n{player_log}")
        + f"\n\n<tg-emoji emoji-id=\"5226431245918942763\">🏆</tg-emoji> <b>Босс побеждён!</b>"
        + f"\n<tg-emoji emoji-id=\"5433594926107481306\">⚪️</tg-emoji> +{coins} монет · <tg-emoji emoji-id=\"5431816358675366190\">🆙</tg-emoji> +{format_num(xp)} опыта"
        + drop_text + level_text,
        reply_markup=boss_victory_keyboard(),
    )
    await notify_completed_quests(
        uid,
        user,
        lambda t, kb: answer_from_callback(call, t, kb),
        lambda: send_quest_done_sticker(call.message),
    )
    return True

async def show_battle_skills(call: CallbackQuery, answer_text: Optional[str] = None):
    user = await db.get_user(call.from_user.id)
    battle = active_battles.get(call.from_user.id)
    if not battle:
        await call.answer("Боя нет.", show_alert=True)
        return
    skills = get_unlocked_path_skills(user)
    if not skills:
        await call.answer("Скиллов нет.", show_alert=True)
        return
    rows = []
    cooldowns = battle.setdefault("skill_cooldowns", {})
    wrong_weapon = path_weapon_mismatch(user)
    active_skill = battle.get(ACTIVE_BATTLE_SKILL_KEY)
    for skill_id in skills:
        info = PATH_SKILL_INFO.get(skill_id)
        if not info:
            continue
        resource, cost = get_skill_resource_cost(user, skill_id)
        available = not wrong_weapon
        cd = int(cooldowns.get(skill_id, 0))
        suffix = f" · КД {cd}" if cd > 0 else ""
        if resource == "hp_percent":
            suffix += f" · {cost}% HP"
            hp_cost = max(1, math.ceil(battle.get("player_hp", 1) * cost / 100))
            available = available and battle.get("player_hp", 0) > hp_cost
        elif resource in ("mana", "stamina"):
            suffix += f" · {cost}"
            available = available and battle.get(resource, 0) >= cost
        if active_skill == skill_id:
            skill_icon = "5325762861539016690"
        elif cd <= 0 and not available:
            skill_icon = "5352669272575321097"
        else:
            skill_icon = "5373268949339227455"  # 🔫
        rows.append([InlineKeyboardButton(text=f"{info['name']}{suffix}", callback_data=f"battle_skill|{skill_id}", icon_custom_emoji_id=skill_icon)])
    rows.append([InlineKeyboardButton(text="Назад", callback_data="battle_skill_back", icon_custom_emoji_id="5215361191051798408")])
    await edit_battle_markup(call, InlineKeyboardMarkup(inline_keyboard=rows))
    if answer_text:
        await call.answer(answer_text)
    else:
        await call.answer()

def path_weapon_mismatch(user: dict) -> bool:
    path = get_user_path(user)
    if not path:
        return False
    equipped = user.get("equipped")
    if not equipped:
        return True
    return infer_weapon_type(equipped) != PATHS[path]["weapon_type"]

def get_battle_skill_block_reason(user: dict, battle: dict, skill_id: str) -> Optional[str]:
    if skill_id not in get_unlocked_path_skills(user):
        return "Скилл не открыт."
    if path_weapon_mismatch(user):
        return "Оружие не того типа."
    cooldowns = battle.setdefault("skill_cooldowns", {})
    if cooldowns.get(skill_id, 0) > 0:
        return f"КД {cooldowns[skill_id]} ход."
    resource, cost = get_skill_resource_cost(user, skill_id)
    if resource == "hp_percent":
        hp_cost = max(1, math.ceil(battle.get("player_hp", 1) * cost / 100))
        if battle.get("player_hp", 0) <= hp_cost:
            return "Не хватает HP."
    elif resource in ("mana", "stamina") and battle.get(resource, 0) < cost:
        resource_name = "маны" if resource == "mana" else "выносливости"
        return f"Не хватает {resource_name}."
    return None

def is_single_target_path_skill(skill_id: str) -> bool:
    return skill_id in ("great_power", "sniper_shot", "multi_shot", "pierce_shot", "rune_barrage")

async def show_battle_skill_targets(call: CallbackQuery, skill_id: str, battle: dict):
    alive = [(idx, enemy) for idx, enemy in enumerate(battle.get("enemies", [])) if enemy.get("hp", 0) > 0]
    if not alive:
        await call.answer("Целей нет.", show_alert=True)
        return
    rows = []
    row = []
    for idx, enemy in alive:
        row.append(InlineKeyboardButton(text=f"{enemy['emoji']} 🔫", callback_data=f"battle_skill_target|{skill_id}|{idx}"))
    rows.append(row)
    rows.append([InlineKeyboardButton(text="Назад", callback_data="battle_skills", icon_custom_emoji_id="5215361191051798408")])
    await edit_battle_markup(call, InlineKeyboardMarkup(inline_keyboard=rows))
    await call.answer("Выбери цель.")

async def apply_battle_skill(call: CallbackQuery, skill_id: str, target_idx: Optional[int] = None, auto_from_attack: bool = False):
    uid = call.from_user.id
    battle = active_battles.get(uid)
    if not battle or battle.get("mode") != "bosses":
        await call.answer("Боя нет.", show_alert=True)
        return
    user = await db.get_user(uid)
    if skill_id not in get_unlocked_path_skills(user):
        await call.answer("Скилл не открыт.", show_alert=True)
        return
    if path_weapon_mismatch(user):
        await call.answer("Оружие не того типа.", show_alert=True)
        return
    cooldowns = battle.setdefault("skill_cooldowns", {})
    if cooldowns.get(skill_id, 0) > 0:
        await call.answer(f"КД {cooldowns[skill_id]} ход.", show_alert=True)
        return
    resource, cost = get_skill_resource_cost(user, skill_id)
    alive = [enemy for enemy in battle.get("enemies", []) if enemy.get("hp", 0) > 0]
    if resource == "hp_percent":
        hp_cost = max(1, math.ceil(battle.get("player_hp", 1) * cost / 100))
        if battle.get("player_hp", 0) <= hp_cost:
            await call.answer("Не хватает HP.", show_alert=True)
            return
    elif resource in ("mana", "stamina") and battle.get(resource, 0) < cost:
        resource_name = "маны" if resource == "mana" else "выносливости"
        await call.answer(f"Не хватает {resource_name}.", show_alert=True)
        return
    if skill_id in TOGGLE_BATTLE_SKILLS and not auto_from_attack:
        current_skill = battle.get(ACTIVE_BATTLE_SKILL_KEY)
        if current_skill == skill_id:
            battle.pop(ACTIVE_BATTLE_SKILL_KEY, None)
            user.pop("auto_battle_skill", None)
            answer_text = f"✅ {PATH_SKILL_INFO[skill_id]['name']} выключен."
        else:
            battle[ACTIVE_BATTLE_SKILL_KEY] = skill_id
            user["auto_battle_skill"] = skill_id
            answer_text = f"✅ {PATH_SKILL_INFO[skill_id]['name']} включен."
        await save_battle_state_throttled(uid, user, force=True)
        await show_battle_skills(call, answer_text=answer_text)
        return
    if is_single_target_path_skill(skill_id) and target_idx is None and len(alive) > 1:
        await show_battle_skill_targets(call, skill_id, battle)
        return
    if resource == "hp_percent":
        hp_cost = max(1, math.ceil(battle.get("player_hp", 1) * cost / 100))
        if battle.get("player_hp", 0) <= hp_cost:
            await call.answer("Не хватает HP.", show_alert=True)
            return
        battle["player_hp"] -= hp_cost
    elif resource in ("mana", "stamina"):
        if battle.get(resource, 0) < cost:
            resource_name = "маны" if resource == "mana" else "выносливости"
            await call.answer(f"Не хватает {resource_name}.", show_alert=True)
            return
        battle[resource] -= cost
    if not auto_from_attack:
        await call.answer()
        await set_battle_waiting(call)

    alive = [enemy for enemy in battle.get("enemies", []) if enemy.get("hp", 0) > 0]

    base_damage, weapon_name = get_equipped_attack(battle_user_context(user, battle))
    player_log = f"<tg-emoji emoji-id=\"5373268949339227455\">🔫</tg-emoji> <b>{PATH_SKILL_INFO[skill_id]['name']}</b>"

    # Баффовые скиллы — не тратят ход, враги не атакуют
    if skill_id in ("war_cry", "aim", "magic_shield", "blood_rage", "fortify", "berserk", "eagle_eye", "arcane_shield"):
        effects = battle.setdefault("effects", {})
        if skill_id == "war_cry":
            effects["war_cry_turns"] = 3
            player_log += ": урон +30% на 3 хода."
        elif skill_id == "aim":
            effects["aim_turns"] = 2
            player_log += ": крит усилен на 2 хода."
        elif skill_id == "magic_shield":
            effects["shield_turns"] = 2
            player_log += ": щит −50% урона на 2 хода."
        elif skill_id == "blood_rage":
            effects["blood_rage_turns"] = 3
            player_log += ": урон +40% на 3 хода."
        elif skill_id == "fortify":
            effects["fortify_turns"] = 3
            player_log += ": входящий урон −35% на 3 хода."
        elif skill_id == "berserk":
            effects["berserk_turns"] = 2
            player_log += ": урон +60% на 2 хода."
        elif skill_id == "eagle_eye":
            effects["eagle_eye_turns"] = 4
            player_log += ": крит +25% на 4 хода."
        elif skill_id == "arcane_shield":
            shield_hp = max(1, math.ceil(int(battle.get("player_max_hp") or battle.get("player_hp") or 1) * 0.30))
            effects["arcane_shield_turns"] = 2
            effects["arcane_shield_hp"] = shield_hp
            player_log += f": щит на {shield_hp} HP (2 хода)."
        cd = PATH_SKILL_INFO[skill_id]["cooldown"]
        if cd:
            cooldowns[skill_id] = cd
        await save_battle_state_throttled(uid, user)
        await edit_battle_message(call, get_battle_text(battle, player_log), reply_markup=battle_keyboard(battle))
        return

    if battle.get("effects", {}).get("stun_turns", 0) > 0:
        enemy_damage = 0
        enemy_log = f"{ENEMY_HIT_EMOJI} <b>Противники оглушены и пропускают ход</b>"
    else:
        enemy_damage = roll_boss_wave_damage(battle, alive)
        enemy_damage = apply_incoming_damage_reduction(battle_user_context(user, battle), enemy_damage)
        enemy_damage = _cap_boss_incoming_damage(battle, enemy_damage)
        enemy_log = f"{ENEMY_HIT_EMOJI} <b>Урон по тебе: −{enemy_damage} HP</b>"
    battle["player_hp"] -= enemy_damage
    if battle["player_hp"] <= 0:
        active_battles.pop(uid, None)
        await save_battle_state_throttled(uid, user, force=True)
        await edit_battle_message(call, get_battle_text(battle, enemy_log) + "\n\n<tg-emoji emoji-id=\"6327816922544997828\">💀</tg-emoji> <b>Поражение.</b> Рейд провален.")
        return

    if skill_id in ("juggernaut", "arrow_rain", "splash"):
        if skill_id == "juggernaut":
            percent = int(get_path_bonus(user, "juggernaut_power") or 40)
        elif skill_id == "arrow_rain":
            percent = int(get_path_bonus(user, "arrow_rain_power") or 40)
        else:
            percent = int(get_path_bonus(user, "splash_power") or 40)
        damage = max(1, math.ceil(base_damage * percent / 100))
        for enemy in alive:
            enemy["hp"] -= damage
        player_log = f"{DAMAGE_EMOJI} <b>Твой урон: −{damage} HP по всем врагам</b>"
    elif skill_id == "blast_wave":
        damage = max(1, math.ceil(base_damage * 2))
        for enemy in alive:
            enemy["hp"] -= damage
        battle.setdefault("effects", {})["stun_turns"] = 2
        player_log = f"{DAMAGE_EMOJI} <b>Твой урон: −{damage} HP по всем · стан 2 хода</b>"
    elif skill_id == "nova":
        damage = max(1, math.ceil(base_damage * 3))
        for enemy in alive:
            enemy["hp"] -= damage
            enemy["slow_turns"] = max(int(enemy.get("slow_turns", 0) or 0), 2)
        player_log = f"{DAMAGE_EMOJI} <b>Твой урон: −{damage} HP по всем · замедление 2 хода</b>"
    else:
        if target_idx is not None and 0 <= target_idx < len(battle.get("enemies", [])) and battle["enemies"][target_idx].get("hp", 0) > 0:
            target = battle["enemies"][target_idx]
        else:
            target = alive[0]
        if skill_id == "multi_shot":
            hit = max(1, math.ceil(base_damage * 0.70))
            total = 0
            for _ in range(3):
                target["hp"] -= hit
                total += hit
            damage = total
            player_log = f"{DAMAGE_EMOJI} <b>Залп: 3×{hit} = −{total} HP</b>"
        elif skill_id == "rune_barrage":
            hit = max(1, math.ceil(base_damage * 0.50))
            total = 0
            for _ in range(4):
                target["hp"] -= hit
                total += hit
            damage = total
            player_log = f"{DAMAGE_EMOJI} <b>Шквал рун: 4×{hit} = −{total} HP</b>"
        elif skill_id == "pierce_shot":
            damage = max(1, math.ceil(base_damage * 2.5))
            target["hp"] -= damage
            player_log = f"{DAMAGE_EMOJI} <b>Пробитие: −{damage} HP</b> (игнор 20% брони)"
        elif skill_id == "great_power":
            damage = max(1, math.ceil(base_damage * 5))
            target["hp"] -= damage
            player_log = f"{DAMAGE_EMOJI} <b>Твой урон: −{damage} HP</b>"
        elif skill_id == "sniper_shot":
            damage = max(1, math.ceil(base_damage * 2))
            target["hp"] -= damage
            player_log = f"{DAMAGE_EMOJI} <b>Твой урон: −{damage} HP</b>"
            wound_dmg = max(1, math.ceil(target.get("max_hp", damage) * 0.05))
            target.setdefault("dot", {})["wound"] = {"damage": wound_dmg, "turns": 2}
            player_log += f"\n{VAMPIRISM_EMOJI} <b>Ранение: −{wound_dmg} HP/ход на 2 хода</b>"
        else:
            damage = max(1, math.ceil(base_damage * 2))
            target["hp"] -= damage
            player_log = f"{DAMAGE_EMOJI} <b>Твой урон: −{damage} HP</b>"
    user["total_damage"] = user.get("total_damage", 0) + max(0, locals().get("damage", 0))
    add_path_attack_xp(user)
    cd = PATH_SKILL_INFO[skill_id]["cooldown"]
    if cd:
        cooldowns[skill_id] = cd
    tick_battle_effects(battle)
    if await finish_boss_reward(call, battle, user, enemy_log, player_log):
        return
    await save_battle_state_throttled(uid, user)
    await edit_battle_message(call, get_battle_text(battle, f"{enemy_log}\n{player_log}"), reply_markup=battle_keyboard(battle))

async def handle_boss_attack(
    call: CallbackQuery,
    battle: dict,
    user: dict,
    player_damage: int,
    weapon_name: str,
    attack_notes: Optional[List[str]] = None,
    target_idx: Optional[int] = None,
):
    uid = call.from_user.id
    alive_enemies = [enemy for enemy in battle["enemies"] if enemy["hp"] > 0]
    if battle.get("effects", {}).get("stun_turns", 0) > 0:
        enemy_damage = 0
        enemy_log = f"{ENEMY_HIT_EMOJI} <b>Противники оглушены и пропускают ход</b>"
    else:
        enemy_damage = roll_boss_wave_damage(battle, alive_enemies)
        enemy_damage = apply_incoming_damage_reduction(battle_user_context(user, battle), enemy_damage)
        enemy_damage = _cap_boss_incoming_damage(battle, enemy_damage)
        enemy_log = f"{ENEMY_HIT_EMOJI} <b>Урон по тебе: −{enemy_damage} HP</b>"
    battle["player_hp"] -= enemy_damage
    _boss_for_log = battle.get("boss") or {}

    if battle["player_hp"] <= 0:
        await write_activity_log(
            f"BOSS {_log_user_name(uid, user)} | {_boss_for_log.get('name', '?')} волна {battle.get('wave', '?')} | "
            f"получил {enemy_damage}, ПОРАЖЕНИЕ"
        )
        active_battles.pop(uid, None)
        await save_battle_state_throttled(uid, user, force=True)
        await edit_battle_message(
            call,
            get_battle_text(battle, enemy_log)
            + "\n\n<tg-emoji emoji-id=\"6327816922544997828\">💀</tg-emoji> <b>Поражение.</b> Рейд провален.",
        )
        return

    if target_idx is not None and 0 <= target_idx < len(battle["enemies"]) and battle["enemies"][target_idx].get("hp", 0) > 0:
        target = battle["enemies"][target_idx]
    else:
        target = alive_enemies[0]
    add_path_attack_xp(user)
    target["hp"] -= player_damage
    user["total_damage"] = user.get("total_damage", 0) + player_damage
    attack_notes = attack_notes or []
    if "промах" in attack_notes:
        player_log = f"{DAMAGE_EMOJI} <b>Твой урон: промах</b>"
    else:
        crit_text = f" | Крит{CRIT_EMOJI}" if any("крит" in note.lower() for note in attack_notes) else ""
        player_log = f"{DAMAGE_EMOJI} <b>Твой урон: −{player_damage} HP{crit_text}</b>"
        heal = apply_vampirism_heal(user, battle, player_damage)
        if heal:
            player_log += f'\n{VAMPIRISM_EMOJI} <b>Вампиризм: +{heal} HP</b>'
    if target["hp"] <= 0:
        player_log += f"\n{TARGET_DOWN_EMOJI} <b>Цель повержена.</b>"
    _notes = ",".join(attack_notes) if attack_notes else ""
    await write_activity_log(
        f"BOSS {_log_user_name(uid, user)} | {_boss_for_log.get('name', '?')}"
        f"{' (хард)' if battle.get('hard_mode') else ''} волна {battle.get('wave', '?')} | "
        f"удар {weapon_name}: {player_damage}{(' ' + _notes) if _notes else ''} по «{target.get('name', '?')}» "
        f"(осталось {max(0, target['hp'])}) | получил {enemy_damage}, HP {battle['player_hp']}/{battle.get('player_max_hp', '?')}"
    )

    if all(enemy["hp"] <= 0 for enemy in battle["enemies"]):
        if battle["wave"] >= 4:
            boss = battle.get("boss", next(iter(BOSSES.values())))
            coins_reward = boss["coins"]
            coins = coins_reward if isinstance(coins_reward, int) else random.randint(*coins_reward)
            coins = apply_coin_buff(user, coins)
            hard_mode = bool(battle.get("hard_mode"))
            xp = get_boss_xp_reward(user, boss, hard_mode)
            user["coins"] = user.get("coins", 0) + coins
            user["monsters_killed"] = user.get("monsters_killed", 0) + 10
            user["boss_kills"] = user.get("boss_kills", 0) + 1
            ensure_daily_stats(user)["boss_kills"] += 1
            add_weekly_stat(user, "bosses")
            location_kills = user.setdefault("boss_location_kills", {})
            location_id = boss.get("location")
            if location_id:
                location_kills[location_id] = location_kills.get(location_id, 0) + 1
            boss_defeats = user.setdefault("boss_defeats", {})
            boss_id = boss.get("id")
            if boss_id:
                boss_defeats[boss_id] = boss_defeats.get(boss_id, 0) + 1
            drops = roll_boss_loot(user, boss)
            levels_gained = add_xp(user, xp)
            await log_boss_victory(call.from_user.id, user, boss, hard_mode, coins, xp, drops)
            user.setdefault("boss_cooldowns", {})[boss.get("id", "")] = time.time() + get_boss_cooldown(boss, user, hard_mode)
            if is_final_location_boss(boss):
                user.setdefault("boss_cd_notified", {})[boss.get("id", "")] = False
            active_battles.pop(uid, None)
            await save_battle_state_throttled(uid, user, force=True)
            await db.save_user(uid, user)
            level_text = f"\n<tg-emoji emoji-id=\"6084922627736996647\">🆙</tg-emoji> Новый уровень: <b>{user['level']}</b>" if levels_gained else ""
            loot_emoji = '<tg-emoji emoji-id="5463046637842608206">🪙</tg-emoji>'
            drop_text = "\n" + "\n".join(f"{loot_emoji} {drop}" for drop in drops) if drops else f"\n{loot_emoji} Лут не выпал."
            coin_emoji = '<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji>'
            xp_emoji = '<tg-emoji emoji-id="5431816358675366190">🆙</tg-emoji>'
            win_emoji = '<tg-emoji emoji-id="5226431245918942763">🏆</tg-emoji>'
            await edit_battle_message(
                call,
                get_battle_text(battle, f"{enemy_log}\n{player_log}")
                + f"\n\n{win_emoji} <b>Босс побеждён!</b>"
                + f"\n{coin_emoji} +{coins} монет · {xp_emoji} +{format_num(xp)} опыта"
                + drop_text
                + level_text,
                reply_markup=boss_victory_keyboard(),
            )
            await notify_completed_quests(
                uid,
                user,
                lambda t, kb: answer_from_callback(call, t, kb),
                lambda: send_quest_done_sticker(call.message),
            )
            return

        battle["wave"] += 1
        battle["enemies"] = create_boss_wave(
            battle["wave"],
            get_current_boss_template(battle),
            bool(battle.get("hard_mode")),
        )
        await save_battle_state_throttled(uid, user, force=True)
        await edit_battle_message(
            call,
            get_battle_text(
                battle,
                f"{enemy_log}\n{player_log}\n\n🌊 Волна {battle['wave']}/4. Противники ходят первыми.",
            ),
            reply_markup=battle_keyboard(battle),
        )
        return

    dot_log = tick_battle_effects(battle)

    # Проверяем победу после тика DoT (ранение могло добить врага)
    if all(enemy["hp"] <= 0 for enemy in battle["enemies"]):
        if battle["wave"] >= 4:
            boss = battle.get("boss", next(iter(BOSSES.values())))
            coins_reward = boss["coins"]
            coins = coins_reward if isinstance(coins_reward, int) else random.randint(*coins_reward)
            coins = apply_coin_buff(user, coins)
            hard_mode = bool(battle.get("hard_mode"))
            xp = get_boss_xp_reward(user, boss, hard_mode)
            user["coins"] = user.get("coins", 0) + coins
            user["monsters_killed"] = user.get("monsters_killed", 0) + 10
            user["boss_kills"] = user.get("boss_kills", 0) + 1
            ensure_daily_stats(user)["boss_kills"] += 1
            add_weekly_stat(user, "bosses")
            location_kills = user.setdefault("boss_location_kills", {})
            location_id = boss.get("location")
            if location_id:
                location_kills[location_id] = location_kills.get(location_id, 0) + 1
            boss_defeats = user.setdefault("boss_defeats", {})
            boss_id = boss.get("id")
            if boss_id:
                boss_defeats[boss_id] = boss_defeats.get(boss_id, 0) + 1
            drops = roll_boss_loot(user, boss)
            levels_gained = add_xp(user, xp)
            await log_boss_victory(call.from_user.id, user, boss, hard_mode, coins, xp, drops)
            user.setdefault("boss_cooldowns", {})[boss.get("id", "")] = time.time() + get_boss_cooldown(boss, user, hard_mode)
            if is_final_location_boss(boss):
                user.setdefault("boss_cd_notified", {})[boss.get("id", "")] = False
            active_battles.pop(uid, None)
            await save_battle_state_throttled(uid, user, force=True)
            await db.save_user(uid, user)
            level_text = f"\n<tg-emoji emoji-id=\"6084922627736996647\">🆙</tg-emoji> Новый уровень: <b>{user['level']}</b>" if levels_gained else ""
            loot_emoji = '<tg-emoji emoji-id="5463046637842608206">🪙</tg-emoji>'
            drop_text = "\n" + "\n".join(f"{loot_emoji} {drop}" for drop in drops) if drops else f"\n{loot_emoji} Лут не выпал."
            coin_emoji = '<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji>'
            xp_emoji = '<tg-emoji emoji-id="5431816358675366190">🆙</tg-emoji>'
            win_emoji = '<tg-emoji emoji-id="5226431245918942763">🏆</tg-emoji>'
            await edit_battle_message(
                call,
                get_battle_text(battle, f"{enemy_log}\n{player_log}{dot_log}")
                + f"\n\n{win_emoji} <b>Босс побеждён!</b>"
                + f"\n{coin_emoji} +{coins} монет · {xp_emoji} +{format_num(xp)} опыта"
                + drop_text
                + level_text,
                reply_markup=boss_victory_keyboard(),
            )
            await notify_completed_quests(
                uid,
                user,
                lambda t, kb: answer_from_callback(call, t, kb),
                lambda: send_quest_done_sticker(call.message),
            )
            return
        battle["wave"] += 1
        battle["enemies"] = create_boss_wave(
            battle["wave"],
            get_current_boss_template(battle),
            bool(battle.get("hard_mode")),
        )
        await save_battle_state_throttled(uid, user, force=True)
        await edit_battle_message(
            call,
            get_battle_text(battle, f"{enemy_log}\n{player_log}{dot_log}\n\n🌊 Волна {battle['wave']}/4. Противники ходят первыми."),
            reply_markup=battle_keyboard(battle),
        )
        return

    await save_battle_state_throttled(uid, user)
    await edit_battle_message(
        call,
        get_battle_text(battle, f"{enemy_log}\n{player_log}{dot_log}"),
        reply_markup=battle_keyboard(battle),
    )

async def start_bosses(message: Message, user_id: Optional[int] = None, answer_func=None):
    uid = user_id or message.from_user.id
    as_reply = user_id is None

    async def _send(text, kb):
        if answer_func:
            await answer_func(text, kb)
        else:
            await send_owned_message(message, uid, text, reply_markup=kb, as_reply=as_reply)

    if uid in active_battles:
        battle = active_battles[uid]
        if await clear_expired_boss_battle(uid):
            await _send("<tg-emoji emoji-id=\"5287473790735890430\">⏳</tg-emoji> <b>Рейд завершён.</b> Ты не атаковал 5 минут.", None)
        else:
            await _send(get_battle_text(battle, "<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> Твой ход."), battle_keyboard(battle))
            return

    user = await db.get_user(uid)
    player_level = user.get("level", 1)
    equipped_power = calculate_user_power(user)

    loc_buttons = []
    loc_lines = []
    for loc in LOCATIONS.values():
        lock = "<tg-emoji emoji-id=\"5296369303661067030\">🔒</tg-emoji> " if player_level < loc["min_level"] else ""
        loc_emoji = loc.get("premium_emoji", loc["emoji"])
        loc_lines.append(
            f"{loc_emoji} <b>{loc['name']}</b> {lock}\n"
            f"{loc['description']} · с {loc['min_level']} ур."
        )
        loc_buttons.append([InlineKeyboardButton(
            text=f"{loc['emoji']} {loc['name']} {'🔒' if player_level < loc['min_level'] else ''}",
            callback_data=f"location|{loc['id']}",
        )])
    loc_buttons.append([InlineKeyboardButton(text="Настройки", callback_data="boss_settings", icon_custom_emoji_id="5366231924597604153")])


    text = (
        '<tg-emoji emoji-id="5217822164362739968">👑</tg-emoji> <b>Локации</b>\n\n'
        + "\n\n".join(loc_lines)
        + f'\n\n<tg-emoji emoji-id="5998843468716184159">❤️‍🔥</tg-emoji>Твой уровень: <b>{player_level}</b> · '
        f'<tg-emoji emoji-id="5332336747072208845">🔥</tg-emoji>Сила: <b>{equipped_power}</b>'
    )
    kb = InlineKeyboardMarkup(inline_keyboard=loc_buttons)
    await _send(text, kb)

async def show_quick_bosses(message: Message, user_id: Optional[int] = None, answer_func=None):
    uid = user_id or message.from_user.id
    as_reply = user_id is None

    async def _send(text, kb):
        if answer_func:
            await answer_func(text, kb)
        else:
            await send_owned_message(message, uid, text, reply_markup=kb, as_reply=as_reply)

    if uid in active_battles:
        battle = active_battles[uid]
        if await clear_expired_boss_battle(uid):
            await _send("<tg-emoji emoji-id=\"5287473790735890430\">⏳</tg-emoji> <b>Рейд завершён.</b> Ты не атаковал 5 минут.", None)
        else:
            await _send(get_battle_text(battle, "<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> Твой ход."), battle_keyboard(battle))
            return

    user = await db.get_user(uid)
    if user is None:
        await _send("Сначала напиши /start, чтобы начать игру.", None)
        return
    player_level = user.get("level", 1)
    available_bosses = [
        boss for boss in BOSSES.values()
        if player_level >= LOCATIONS.get(boss.get("location"), {}).get("min_level", 1)
    ]

    if not available_bosses:
        await _send("<tg-emoji emoji-id=\"5947121436723252849\">👑</tg-emoji> <b>Боссы</b>\n\nПока нет доступных боссов.", None)
        return

    rows = []
    row = []
    for boss in available_bosses:
        row.append(InlineKeyboardButton(text=boss["emoji"], callback_data=f"quick_boss|{boss['id']}"))
        if len(row) == 5:
            rows.append(row)
            row = []
    if row:
        rows.append(row)

    text = "<tg-emoji emoji-id=\"5947121436723252849\">👑</tg-emoji> <b>Быстрые боссы</b>"
    await _send(text, InlineKeyboardMarkup(inline_keyboard=rows))

async def start_location(message: Message, user_id: Optional[int] = None, loc_id: str = "swamp", answer_func=None):
    uid = user_id or message.from_user.id
    as_reply = user_id is None

    async def _send(text, kb):
        if answer_func:
            await answer_func(text, kb)
        else:
            await send_owned_message(message, uid, text, reply_markup=kb, as_reply=as_reply)

    if uid in active_battles:
        battle = active_battles[uid]
        if await clear_expired_boss_battle(uid):
            await _send("<tg-emoji emoji-id=\"5287473790735890430\">⏳</tg-emoji> <b>Рейд завершён.</b> Ты не атаковал 5 минут.", None)
        else:
            await _send(get_battle_text(battle, "<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> Твой ход."), battle_keyboard(battle))
            return

    loc = LOCATIONS.get(loc_id)
    if not loc:
        await _send("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Локация не найдена.", None)
        return

    user = await db.get_user(uid)
    player_level = user.get("level", 1)
    equipped_power = calculate_user_power(user)
    hard_mode = is_boss_hard_mode_enabled(user)

    loc_bosses = [b for b in BOSSES.values() if b["location"] == loc_id]
    boss_lines = []
    boss_buttons = []
    default_power_emoji = '<tg-emoji emoji-id="5321348429727700857">💪</tg-emoji>'
    low_power_emoji = '<tg-emoji emoji-id="5440660757194744323">‼️</tg-emoji>'
    for boss in loc_bosses:
        coins = boss["coins"]
        coins_text = str(coins) if isinstance(coins, int) else f"{coins[0]}–{coins[1]}"
        boss_emoji = boss.get("premium_emoji", boss["emoji"])
        boss_power = get_effective_boss_power(boss, hard_mode)
        power_mark = default_power_emoji if equipped_power >= boss_power else low_power_emoji
        boss_lines.append(
            f"{boss_emoji} {boss['name']}\n"
            f"{power_mark} Рек. сила: <b>{format_num(boss_power)}</b> · <tg-emoji emoji-id=\"5463046637842608206\">🪙</tg-emoji> {coins_text}"
        )
        boss_buttons.append([InlineKeyboardButton(
            text=f"{boss['emoji']} {boss['name']}",
            callback_data=f"boss|{boss['id']}",
        )])
    boss_buttons.append([InlineKeyboardButton(text="Локации", callback_data="bosses", icon_custom_emoji_id="5215361191051798408")])

    text = (
        f"{loc.get('premium_emoji', loc['emoji'])} {loc['name']}\n"
        f"{loc['description']}\n\n"
        + "\n\n".join(boss_lines)
        + f"\n\n4 волны: 3×3 врага и финальный босс\n"
        f'<tg-emoji emoji-id="5332336747072208845">🔥</tg-emoji>Твоя сила: <b>{equipped_power}</b>'
    )
    kb = InlineKeyboardMarkup(inline_keyboard=boss_buttons)
    await _send(text, kb)

async def start_boss_raid(message: Message, user_id: Optional[int] = None, boss_id: str = "bog_lurker", answer_func=None):
    uid = user_id or message.from_user.id
    as_reply = user_id is None
    print(f"[start_boss_raid] uid={uid} boss_id={boss_id} answer_func={answer_func is not None}")

    async def _send(text, kb):
        print(f"[start_boss_raid._send] sending, answer_func={answer_func is not None}")
        if answer_func:
            await answer_func(text, kb)
        else:
            await send_owned_message(message, uid, text, reply_markup=kb, as_reply=as_reply)

    if uid in active_battles:
        battle = active_battles[uid]
        if await clear_expired_boss_battle(uid):
            await _send("<tg-emoji emoji-id=\"5287473790735890430\">⏳</tg-emoji> <b>Рейд завершён.</b> Ты не атаковал 5 минут.", None)
        else:
            await _send(get_battle_text(battle, "<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> Твой ход."), battle_keyboard(battle))
            return

    boss = BOSSES.get(boss_id)
    if not boss:
        await _send("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Босс не найден.", None)
        return

    user = await db.get_user(uid)
    player_level = user.get("level", 1)
    equipped_power = calculate_user_power(user)
    equipped_armor = user.get("equipped_armor", {slot: None for slot in ARMOR_SLOTS})
    hard_mode = is_boss_hard_mode_enabled(user)

    cd_remaining = get_boss_cd_remaining(user, boss_id)
    if cd_remaining > 0:
        await _send(f"<tg-emoji emoji-id=\"5287473790735890430\">⏳</tg-emoji> Босс восстанавливается. Осталось: <b>{format_cd_time(cd_remaining)}</b>", None)
        return

    loc = LOCATIONS.get(boss["location"])
    if loc and player_level < loc["min_level"]:
        await _send(
            f"<tg-emoji emoji-id=\"5296369303661067030\">🔒</tg-emoji> Для входа в <b>{loc['name']}</b> нужен <b>{loc['min_level']}</b> уровень!\n"
            f"Сейчас: <b>{player_level}</b>.",
            None,
        )
        return

    battle = create_boss_battle(player_level, boss, equipped_armor, user, hard_mode)
    active_battles[uid] = battle
    await save_runtime_state(uid, user)
    await _send(
        get_battle_text(battle, "Рейд начался. В каждой волне сначала бьют враги, потом ты."),
        battle_keyboard(battle),
    )

async def start_farm(message: Message, user_id: Optional[int] = None):
    uid = user_id or message.from_user.id
    if uid in farming_users:
        await message.answer("🔎 Враг уже ищется. Немного подожди.")
        return
    if uid in active_battles:
        battle = active_battles[uid]
        await message.answer(get_battle_text(battle, "<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> Твой ход."), reply_markup=battle_keyboard(battle), parse_mode="HTML")
        return

    search_seconds = random.randint(10, 30)
    farming_users.add(uid)
    await message.answer("🔎 Ищем противника…")
    try:
        await asyncio.sleep(search_seconds)
        user = await db.get_user(uid)
        player_level = user.get("level", 1)
        equipped_armor = user.get("equipped_armor", {slot: None for slot in ARMOR_SLOTS})
        player_max_hp = calculate_max_hp_with_armor(player_level, equipped_armor, user)
        battle = {
            "enemy": create_enemy(player_level),
            "player_level": player_level,
            "player_hp": player_max_hp,
            "player_max_hp": player_max_hp,
            "busy": False,
        }
        active_battles[uid] = battle
        await save_runtime_state(uid, user)
        await message.answer(
            get_battle_text(battle, "<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> Противник найден. Твой ход."),
            reply_markup=battle_keyboard(battle),
            parse_mode="HTML",
        )
    finally:
        farming_users.discard(uid)


async def admin_broadcast_message(message: Message):
    """Запрос рассылки: ответь «рассылка» на сообщение → подтверждение → рассылка в ЛС."""
    if not is_admin_user(message.from_user.id):
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Команда только для админов.")
        return
    replied = message.reply_to_message
    if not replied:
        await reply_to_user(
            message,
            "📢 <b>Рассылка</b>\n\n"
            "Ответь командой <b>рассылка</b> (или /broadcast) на сообщение, "
            "которое нужно разослать всем игрокам в ЛС.\n"
            "Премиум-эмодзи и разметка сохраняются.\n"
            "Перед отправкой будет <b>подтверждение</b>.",
            parse_mode="HTML",
        )
        return

    await db.load()
    total = 0
    for uid_str in list(db.data.keys()):
        try:
            uid = int(uid_str)
        except (TypeError, ValueError):
            continue
        if uid in _banned_ids:
            continue
        total += 1

    if total == 0:
        await reply_to_user(message, "Нет игроков для рассылки.")
        return

    admin_id = message.from_user.id
    pending_broadcasts[admin_id] = {
        "from_chat_id": replied.chat.id,
        "message_id": replied.message_id,
        "total": total,
    }

    kb = InlineKeyboardMarkup(inline_keyboard=[
        [
            InlineKeyboardButton(text="Отправить", callback_data="broadcast_confirm", icon_custom_emoji_id="5325762861539016690"),
            InlineKeyboardButton(text="Отмена", callback_data="broadcast_cancel", icon_custom_emoji_id="5352669272575321097"),
        ]
    ])
    await reply_to_user(
        message,
        f"📢 <b>Подтверждение рассылки</b>\n\n"
        f"Сообщение (реплай выше) будет отправлено <b>{total}</b> игрокам в ЛС.\n"
        f"Премиум-эмодзи сохранятся.\n\n"
        f"Точно отправить?",
        reply_markup=kb,
        parse_mode="HTML",
    )


async def admin_broadcast_execute(call: CallbackQuery):
    """Выполнить рассылку после подтверждения."""
    admin_id = call.from_user.id
    if not is_admin_user(admin_id):
        await call.answer("Только для админов.", show_alert=True)
        return
    pending = pending_broadcasts.pop(admin_id, None)
    if not pending:
        await call.answer("Нет активной рассылки. Сначала: реплай → рассылка.", show_alert=True)
        return

    await call.answer()
    total = pending["total"]
    from_chat_id = pending["from_chat_id"]
    msg_id = pending["message_id"]

    try:
        await call.message.edit_text(
            f"📢 Рассылка начата… Игроков: <b>{total}</b>",
            parse_mode="HTML",
        )
    except Exception:
        pass

    await db.load()
    user_ids = []
    for uid_str in list(db.data.keys()):
        try:
            uid = int(uid_str)
        except (TypeError, ValueError):
            continue
        if uid in _banned_ids:
            continue
        user_ids.append(uid)

    bot = call.bot
    ok = 0
    fail = 0
    blocked = 0

    for i, uid in enumerate(user_ids, start=1):
        try:
            await bot.copy_message(
                chat_id=uid,
                from_chat_id=from_chat_id,
                message_id=msg_id,
            )
            ok += 1
        except Exception as e:
            err = str(e).lower()
            if "blocked" in err or "deactivated" in err or "chat not found" in err or "forbidden" in err:
                blocked += 1
            else:
                fail += 1
        if i % 25 == 0:
            await asyncio.sleep(1.0)
        else:
            await asyncio.sleep(0.05)

    result = (
        f"<tg-emoji emoji-id=\"5325762861539016690\">✅</tg-emoji> <b>Рассылка завершена</b>\n\n"
        f"• Доставлено: <b>{ok}</b>\n"
        f"• Заблокировали бота: <b>{blocked}</b>\n"
        f"• Ошибки: <b>{fail}</b>\n"
        f"• Всего в базе: <b>{len(user_ids)}</b>"
    )
    try:
        await call.message.edit_text(result, parse_mode="HTML")
    except Exception:
        await call.message.answer(result, parse_mode="HTML")


async def admin_broadcast_cancel(call: CallbackQuery):
    admin_id = call.from_user.id
    if not is_admin_user(admin_id):
        await call.answer("Только для админов.", show_alert=True)
        return
    pending_broadcasts.pop(admin_id, None)
    await call.answer("Отменено")
    try:
        await call.message.edit_text(premium_cross("❌ Рассылка отменена."), parse_mode="HTML")
    except Exception:
        pass



def is_admin_user(user_id: int) -> bool:
    return user_id in ADMIN_IDS

async def show_online_stats(message: Message):
    if not is_admin_user(message.from_user.id):
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Команда только для админов.")
        return

    await db.load()
    now = time.time()
    today = get_today_key()  # сутки по МСК
    users = [
        user for uid, user in db.data.items()
        if str(uid).isdigit() and isinstance(user, dict)
    ]
    total = len(users)
    online_5m = sum(
        1 for user in users
        if now - float(user.get("last_seen_at") or 0) <= 5 * 60
    )
    online_today = sum(1 for user in users if user.get("last_seen_date") == today)

    await reply_to_user(
        message,
        '<tg-emoji emoji-id="5429519916971599983">💻</tg-emoji> <b>Онлайн</b>\n\n'
        '<blockquote>'
        f'<tg-emoji emoji-id="5453957997418004470">👥</tg-emoji> Всего игроков: <b>{total}</b>\n'
        f'<tg-emoji emoji-id="5323289935334096761">🌐</tg-emoji> За 5 минут: <b>{online_5m}</b>\n'
        f'<tg-emoji emoji-id="5253456953966881468">🗓</tg-emoji> За сегодня: <b>{online_today}</b>'
        '</blockquote>',
        parse_mode="HTML",
    )

async def send_admin_log_chunks(message: Message, header: str, body: str):
    max_chunk = 3500
    chunks = [body[i:i + max_chunk] for i in range(0, len(body), max_chunk)] or [""]
    total = len(chunks)
    for index, chunk in enumerate(chunks, start=1):
        suffix = f" ({index}/{total})" if total > 1 else ""
        await reply_to_user(
            message,
            f"{header}{suffix}\n<pre>{html.escape(chunk)}</pre>",
            parse_mode="HTML",
        )

async def admin_show_logs(message: Message):
    """логи — весь лог файлом; логи 500 — последние 500 строк;
    логи id 123 / логи 123456789 / реплай «логи» — всё по игроку;
    логи клан ТЕГ — всё по клану; логи все — вместе с архивом."""
    if not is_admin_user(message.from_user.id):
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Команда только для админов.")
        return

    parts = (message.text or "").strip().split()
    limit: Optional[int] = None
    needle: Optional[str] = None
    include_old = False
    title = "all"

    args = [p.casefold() for p in parts[1:]]
    if "все" in args or "all" in args:
        include_old = True
        args = [x for x in args if x not in ("все", "all")]
    if args:
        if args[0] in ("id", "юзер", "user") and len(args) >= 2 and args[1].isdigit():
            needle = args[1]
        elif args[0] in ("клан", "clan") and len(args) >= 2:
            needle = f"[{args[1].upper()}]"
            title = f"clan_{args[1]}"
        elif args[0].isdigit():
            value = int(args[0])
            if value <= 100000:
                limit = value
            else:
                needle = args[0]
    replied = message.reply_to_message
    if needle is None and replied and replied.from_user and not replied.from_user.is_bot:
        needle = str(replied.from_user.id)
    if needle and needle.isdigit():
        title = f"user_{needle}"

    await flush_activity_log()  # дописываем буфер, чтобы в выгрузке были самые свежие строки
    files = []
    old_path = ACTIVITY_LOG_FILE.replace(".txt", ".old.txt")
    if include_old or needle:
        files.append(old_path)
    files.append(ACTIVITY_LOG_FILE)
    lines: List[str] = []
    for path in files:
        if not os.path.exists(path):
            continue
        async with aiofiles.open(path, "r", encoding="utf-8", errors="replace") as f:
            lines.extend(await f.readlines())
    if not lines:
        await reply_to_user(message, "📭 Лог-файл пуст или не найден.")
        return
    if needle:
        if needle.isdigit():
            id_re = re.compile(rf"(?<!\d){needle}(?!\d)")
            # время в начале строки не учитываем, чтобы id не совпал с датой
            lines = [line for line in lines if id_re.search(line[22:])]
        else:
            lines = [line for line in lines if needle in line]
    if limit:
        lines = lines[-limit:]
    if not lines:
        await reply_to_user(message, "📭 Нет записей по этому фильтру.")
        return

    content = "".join(line if line.endswith("\n") else line + "\n" for line in lines).encode("utf-8")
    max_bytes = 45 * 1024 * 1024  # лимит Telegram на файл от бота — 50 МБ
    cut_note = ""
    if len(content) > max_bytes:
        content = content[-max_bytes:]
        content = content[content.find(b"\n") + 1:]
        cut_note = "\nФайл большой — отправлен конец лога."
    stamp = datetime.now().strftime("%Y-%m-%d_%H-%M")
    filename = f"lootify_logs_{title}_{stamp}.txt"
    caption = f"📜 <b>Логи бота</b>\nСтрок: <b>{len(lines)}</b>"
    if needle:
        caption += f" · фильтр: <code>{html.escape(needle)}</code>"
    if limit:
        caption += f" · последние {limit}"
    caption += cut_note
    await message.reply_document(
        BufferedInputFile(content, filename=filename),
        caption=caption,
        parse_mode="HTML",
    )


async def admin_set_old_badge(message: Message, enable: bool):
    """олд+ / олд- — реплай на сообщение игрока."""
    if not is_admin_user(message.from_user.id):
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Команда только для админов.")
        return
    replied = message.reply_to_message
    if not replied or not replied.from_user:
        await reply_to_user(
            message,
            "Ответь командой <b>олд+</b> или <b>олд-</b> на сообщение игрока.",
            parse_mode="HTML",
        )
        return
    tid = replied.from_user.id
    if replied.from_user.is_bot:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Это бот.")
        return
    user = await db.get_user(tid)
    if not user:
        await reply_to_user(message, "У игрока нет профиля.")
        return
    if enable:
        user["old_badge"] = True
        await db.save_user(tid, user)
        await reply_to_user(
            message,
            f"<tg-emoji emoji-id=\"5325762861539016690\">✅</tg-emoji> В профиле <b>{render_user_nickname(user, str(tid))}</b> дата регистрации → <b>олд</b>.",
            parse_mode="HTML",
        )
    else:
        user.pop("old_badge", None)
        await db.save_user(tid, user)
        await reply_to_user(
            message,
            f"<tg-emoji emoji-id=\"5325762861539016690\">✅</tg-emoji> Снят статус олд у <b>{render_user_nickname(user, str(tid))}</b>. Дата снова обычная.",
            parse_mode="HTML",
        )

async def admin_ban_user(message: Message):
    if not is_admin_user(message.from_user.id):
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Команда только для админов.")
        return

    parts = (message.text or "").strip().split()
    if len(parts) != 2 or not parts[1].isdigit():
        await reply_to_user(message, "Напиши так: <b>бан 123456789</b>.", parse_mode="HTML")
        return

    target_id = int(parts[1])
    if target_id in ADMIN_IDS:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Нельзя забанить админа.")
        return
    if target_id == message.from_user.id:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Нельзя забанить самого себя.")
        return
    if await is_user_banned(target_id):
        await reply_to_user(message, f"ℹ️ Пользователь <code>{target_id}</code> уже заблокирован.", parse_mode="HTML")
        return

    await ban_user_by_id(target_id)
    user = await db.get_user(target_id)
    player_name = render_user_nickname(user, "неизвестно") if user else "без профиля"
    await write_activity_log(f"BAN {get_log_user_label(message.from_user)} -> {target_id} ({player_name})")
    await reply_to_user(
        message,
        f"⛔ Пользователь <code>{target_id}</code> заблокирован.\n"
        f"Профиль: <b>{player_name}</b>",
        parse_mode="HTML",
    )

