def build_admin_pet_take_keyboard(target_id: int, user: dict, page: int = 0) -> InlineKeyboardMarkup:
    normalize_pet_storage(user)
    pets = sorted(
        user.get("pets", []),
        key=lambda pet: (
            RARITY_ORDER.index(pet.get("rarity")) if pet.get("rarity") in RARITY_ORDER else 999,
            PET_DEFS.get(pet.get("pet_id"), {}).get("name", pet.get("name", "")),
            int(pet.get("iid", 0)),
        ),
    )
    page_size = 8
    max_page = max(0, math.ceil(len(pets) / page_size) - 1)
    page = max(0, min(page, max_page))
    start = page * page_size
    rows = []
    for pet in pets[start:start + page_size]:
        pet_id = pet.get("pet_id")
        name = PET_DEFS.get(pet_id, {}).get("name", pet.get("name", "Пет"))
        rows.append([InlineKeyboardButton(
            text=f"{name} · ур. {get_pet_level(pet)}",
            callback_data=f"admin_pet_take|{target_id}|{pet.get('iid')}|{page}",
            icon_custom_emoji_id=get_pet_icon_custom_emoji_id(pet),
        )])
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"admin_pet_take_page|{target_id}|{page - 1}"))
    if page < max_page:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"admin_pet_take_page|{target_id}|{page + 1}"))
    if nav:
        rows.append(nav)
    if not rows:
        rows.append([InlineKeyboardButton(text="Петов нет", callback_data="noop")])
    return InlineKeyboardMarkup(inline_keyboard=rows)

def admin_pet_take_text(target_id: int, user: dict, target_name: str = "Игрок") -> str:
    normalize_pet_storage(user)
    count = len(user.get("pets", []))
