def find_boss_resource_id(query: str) -> Optional[str]:
    """Ищет ресурс с боссов (лут/фрагмент/осколок) по id или по части названия."""
    q = (query or "").strip().lower()
    if not q:
        return None
    if q in BOSS_RESOURCE_DEFS:
        return q
    for res_id, info in BOSS_RESOURCE_DEFS.items():
        if q == info.get("name", "").lower():
            return res_id
    matches = [res_id for res_id, info in BOSS_RESOURCE_DEFS.items() if q in info.get("name", "").lower()]
    if len(matches) == 1:
        return matches[0]
    return None

def list_boss_resources_text() -> str:
    lines = ["<b>Доступный лут с боссов (id — название):</b>"]
    for loc_id, loc_loot in BOSS_LOCATION_LOOT.items():
        lines.append(f"\n<b>{loc_id}</b>:")
        for item in loc_loot.values():
            lines.append(f"  <code>{item['id']}</code> — {html.escape(item['name'])}")
    shard_items = [
        item for item in BOSS_RESOURCE_DEFS.values()
        if item.get("kind") == "engraving_shard"
    ]
    if shard_items:
        lines.append("\n<b>Осколки гравировки:</b>")
        for item in sorted(shard_items, key=lambda entry: entry.get("level", 0)):
            lines.append(f"  <code>{item['id']}</code> — {html.escape(item['name'])}")
    lines.append("\n<b>Эссенция</b> (выдать: <code>эс+ epic 5</code>, забрать: <code>эс- epic 5</code>):")
    for rarity in RARITIES:
        rid = get_essence_id_for_rarity(rarity)
        info = BOSS_RESOURCE_DEFS.get(rid)
        if info:
            lines.append(f"  <code>{rarity}</code> — {html.escape(info['name'])}")
    return "\n".join(lines)

