async def admin_give_armor(message: Message):
    admin_id = message.from_user.id
    if admin_id not in ADMIN_IDS:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Команда только для админов.")
        return

    parts = (message.text or "").split()
    if len(parts) < 2:
        await reply_to_user(message,
            "Напиши так: <b>броня+ iron_helmet 1</b> (или часть названия, например <b>броня+ корона вечности</b>) реплаем на игрока.\n"
            "Наручи: <b>броня+ iron_bracers 1 пара</b> — левый и правый; <b>лев</b> / <b>прав</b> — только один.\n"
            "Список брони: команда <b>бронлист</b>.",
            parse_mode="HTML",
        )
        return

    amount = 1
    args = parts[1:]
    # Сторона для наручей: лев / прав / пара (можно указать в любом месте)
    side_aliases = {
        "лев": "left", "левый": "left", "left": "left", "l": "left",
        "прав": "right", "правый": "right", "right": "right", "r": "right",
        "пара": "both", "оба": "both", "both": "both", "pair": "both",
    }
    side = None
    rest_args = []
    for a in args:
        if a.lower() in side_aliases:
            side = side_aliases[a.lower()]
        else:
            rest_args.append(a)
    args = rest_args
    if len(args) >= 2 and args[-1].lstrip("-").isdigit():
        amount = int(args[-1])
        args = args[:-1]
    query = " ".join(args)

    if amount <= 0:
        await reply_to_user(message, "Количество должно быть больше нуля.")
        return

    found = find_armor_def(query)
    if not found:
        await reply_to_user(message,
            f"Не нашёл броню по запросу «{html.escape(query)}». Посмотри список: команда <b>бронлист</b>.",
            parse_mode="HTML",
        )
        return
    armor_piece, slot_group, rarity_key = found
    # Наручи: по умолчанию выдаём ПАРУ (левый + правый) за каждую единицу количества
    if slot_group in ("bracers", "bracers_left", "bracers_right"):
        if side is None:
            side = {"bracers_left": "left", "bracers_right": "right"}.get(slot_group, "both")
        give_slots = {
            "left": ["bracers_left"],
            "right": ["bracers_right"],
            "both": ["bracers_left", "bracers_right"],
        }[side]
    else:
        give_slots = [slot_group]
    actual_slot = give_slots[0]

    replied = message.reply_to_message
    if not replied or not replied.from_user:
        await reply_to_user(message, "Ответь этой командой на сообщение игрока.")
        return

    target = replied.from_user
    if target.is_bot:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Ботам броня не нужна.")
        return

    user = await db.get_user(target.id)
    if not user:
        await reply_to_user(message, "У игрока нет профиля. Он должен сначала написать /start.")
        return

    given = 0
    trashed = 0
    for _ in range(amount):
        for give_slot in give_slots:
            item = create_armor_item(armor_piece, give_slot, rarity_key, user.get("level", 1))
            if add_item_to_inventory_or_trash(user, item):
                given += 1
            else:
                trashed += 1

    await save_runtime_state(target.id, user)

    rarity_info = RARITIES[rarity_key]
    slot_name = " + ".join(ARMOR_SLOT_NAMES.get(sl, sl) for sl in give_slots)
    trash_note = f"\n⚠️ Экипировка заполнена, {trashed} шт. отправлено в корзину." if trashed else ""
    await reply_to_user(message,
        f"<tg-emoji emoji-id=\"5325762861539016690\">✅</tg-emoji> Выдано в экипировку: {armor_piece['emoji']} <b>{html.escape(armor_piece['name'])}</b> "
        f"({rarity_info['emoji']} {rarity_info['name']}, {slot_name}) "
        f"{'пар: ' + str(given // 2) if len(give_slots) == 2 else 'x' + str(given)} "
        f"игроку <b>{html.escape(target.first_name or 'Игрок')}</b>.{trash_note}",
        parse_mode="HTML",
    )

