async def admin_adjust_boss_loot(message: Message, give: bool):
    admin_id = message.from_user.id
    if admin_id not in ADMIN_IDS:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Команда только для админов.")
        return

    parts = (message.text or "").split()
    if len(parts) < 2:
        await reply_to_user(message,
            "Напиши так: <b>лут+ swamp_fragment 3</b> (или часть названия, например <b>лут+ фрагмент болота 1</b>) реплаем на игрока.\n"
            "Список лута: команда <b>лутлист</b>.",
            parse_mode="HTML",
        )
        return

    amount = 1
    args = parts[1:]
    if len(args) >= 2 and args[-1].lstrip("-").isdigit():
        amount = int(args[-1])
        args = args[:-1]
    query = " ".join(args)

    if amount <= 0:
        await reply_to_user(message, "Количество должно быть больше нуля.")
        return

    resource_id = find_boss_resource_id(query)
    if not resource_id:
        await reply_to_user(message,
            f"Не нашёл лут по запросу «{html.escape(query)}». Посмотри список: команда <b>лутлист</b>.",
            parse_mode="HTML",
        )
        return

    replied = message.reply_to_message
    if not replied or not replied.from_user:
        await reply_to_user(message, "Ответь этой командой на сообщение игрока.")
        return

    target = replied.from_user
    if target.is_bot:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Ботам лут не нужен.")
        return

    user = await db.get_user(target.id)
    if not user:
        await reply_to_user(message, "У игрока нет профиля. Он должен сначала написать /start.")
        return

    info = BOSS_RESOURCE_DEFS[resource_id]
    resources = user.setdefault("boss_loot", {})
    before = resources.get(resource_id, 0)

    if give:
        resources[resource_id] = before + amount
        verb = "Выдано"
    else:
        resources[resource_id] = max(0, before - amount)
        verb = "Забрано"
        amount = before - resources[resource_id]

    await save_runtime_state(target.id, user)

    after = resources[resource_id]
    await reply_to_user(message,
        f"<tg-emoji emoji-id=\"5325762861539016690\">✅</tg-emoji> {verb}: {info['emoji']} <b>{html.escape(info['name'])}</b> x{amount} "
        f"игроку <b>{html.escape(target.first_name or 'Игрок')}</b>.\n"
        f"Теперь у него: <b>{after}</b>.",
        parse_mode="HTML",
    )

