    for pid, info in POTION_DEFS.items():
        if q == info.get("name", "").lower():
            return pid
    matches = [pid for pid, info in POTION_DEFS.items() if q in info.get("name", "").lower()]
    if len(matches) == 1:
        return matches[0]
