async def admin_adjust_potion(message: Message, give: bool):
    admin_id = message.from_user.id
    if admin_id not in ADMIN_IDS:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Команда только для админов.")
        return

    parts = (message.text or "").split()
    if len(parts) < 2:
        await reply_to_user(message,
            "Напиши так: <b>зелье+ damage_potion 2</b> (или часть названия, например <b>зелье+ зелье удачи 1</b>) реплаем на игрока.\n"
            "Список зелий: команда <b>зельелист</b>.",
            parse_mode="HTML",
        )
        return

    amount = 1
    args = parts[1:]
    if len(args) >= 2 and args[-1].lstrip("-").isdigit():
        amount = int(args[-1])
        args = args[:-1]
    query = " ".join(args)

    if amount <= 0:
        await reply_to_user(message, "Количество должно быть больше нуля.")
        return

    potion_id = find_potion_id(query)
    if not potion_id:
        await reply_to_user(message,
            f"Не нашёл зелье по запросу «{html.escape(query)}». Посмотри список: команда <b>зельелист</b>.",
            parse_mode="HTML",
        )
        return

    replied = message.reply_to_message
    if not replied or not replied.from_user:
        await reply_to_user(message, "Ответь этой командой на сообщение игрока.")
        return

    target = replied.from_user
    if target.is_bot:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Ботам зелья не нужны.")
        return

    user = await db.get_user(target.id)
    if not user:
        await reply_to_user(message, "У игрока нет профиля. Он должен сначала написать /start.")
        return

    pdef = POTION_DEFS[potion_id]

    if give:
        for _ in range(amount):
            add_potion_to_user(user, potion_id)
        verb = "Выдано"
    else:
        removed = 0
        for _ in range(amount):
            if remove_potion_from_user(user, potion_id):
                removed += 1
            else:
                break
        verb = "Забрано"
        amount = removed

    await save_runtime_state(target.id, user)

    after = sum(1 for p in get_potions_in_inventory(user) if p.get("potion_id") == potion_id)
    await reply_to_user(message,
        f"<tg-emoji emoji-id=\"5325762861539016690\">✅</tg-emoji> {verb}: {pdef['emoji']} <b>{html.escape(pdef['name'])}</b> x{amount} "
        f"игроку <b>{html.escape(target.first_name or 'Игрок')}</b>.\n"
        f"Теперь у него: <b>{after}</b>.",
        parse_mode="HTML",
    )

async def admin_give_potion(message: Message):
    await admin_adjust_potion(message, give=True)

async def admin_take_potion(message: Message):
    await admin_adjust_potion(message, give=False)

async def admin_bulk_roll(message: Message):
    if message.from_user.id not in ADMIN_IDS:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Команда только для админов.")
        return

    parts = (message.text or "").split()
    if len(parts) != 2:
        await reply_to_user(message, "Напиши так: <b>ролл 100</b>", parse_mode="HTML")
        return

    try:
        amount = int(parts[1])
    except ValueError:
        await reply_to_user(message, "Количество роллов должно быть числом.")
        return

    if amount <= 0:
        await reply_to_user(message, "Количество роллов должно быть больше нуля.")
        return
    if amount > 1000:
        await reply_to_user(message, "За раз можно сделать максимум <b>1000</b> роллов.", parse_mode="HTML")
        return

    user = await db.get_user(message.from_user.id)
    if not user:
        await reply_to_user(message, "Сначала создай профиль через /start.")
        return

    rarity_counts = {rarity: 0 for rarity in RARITIES}
    added_to_inventory = 0
    sent_to_trash = 0
    total_levels_gained = 0

    rarity_stats = user.setdefault("rarity_stats", {rarity: 0 for rarity in RARITIES})
    for _ in range(amount):
        if random.random() < 0.5:
            item = roll_weapon(user.get("level", 1), get_rebirth_count(user), user)
        else:
            item = roll_armor(user.get("level", 1), get_rebirth_count(user), user)
        rarity = item["rarity"]
        rarity_counts[rarity] = rarity_counts.get(rarity, 0) + 1
        rarity_stats[rarity] = rarity_stats.get(rarity, 0) + 1
        if add_item_to_inventory_or_trash(user, item):
            added_to_inventory += 1
        else:
            sent_to_trash += 1
        user["chests_opened"] = user.get("chests_opened", 0) + 1
        ensure_daily_stats(user)["rolls"] += 1
        add_weekly_stat(user, "rolls")
        total_levels_gained += add_xp(user, apply_xp_buff(user, get_chest_xp_reward(user)))

    await db.save_user(message.from_user.id, user)
    await notify_completed_quests(
        message.from_user.id,
        user,
        lambda t, kb: reply_to_user(message, t, kb),
        lambda: send_quest_done_sticker(message),
    )

    rarity_lines = [
        f"{RARITIES[rarity]['emoji']} {RARITIES[rarity]['name']}: <b>{rarity_counts.get(rarity, 0)}</b>"
        for rarity in reversed(RARITY_ORDER)
        if rarity_counts.get(rarity, 0)
    ]
    level_text = (
        f"\n⬆️ Получено уровней: <b>{total_levels_gained}</b> · текущий: <b>{user['level']}</b>"
        if total_levels_gained else ""
    )
    await reply_to_user(message, 
        f"🎲 <b>Массовый ролл: {amount}</b>\n\n"
        + ("\n".join(rarity_lines) if rarity_lines else "Без предметов")
        + f"\n\n<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> В экипировку: <b>{added_to_inventory}</b>"
        + f"\n🗑️ В корзину: <b>{sent_to_trash}</b>"
        + f"\n<tg-emoji emoji-id=\"5370831521039017384\">✨</tg-emoji> Опыт: <b>+{amount * get_chest_xp_reward(user)}</b>"
        + level_text,
        parse_mode="HTML",
    )

async def handle_roll_command(message: Message):
    user = await db.get_user(message.from_user.id)
    if user.get("auto_roll_unlocked"):
        await show_auto_roll_menu(message.from_user.id, lambda t, kb: reply_to_user(message, t, kb))
        return
    await do_roll(
        message.from_user.id,
        lambda t, kb: reply_to_user(message, t, kb),
        sticker_func=lambda: send_quest_done_sticker(message),
    )

def get_auto_roll_session(user_id: int) -> dict:
    return auto_roll_sessions.setdefault(user_id, get_empty_auto_roll_session())

async def notify_auto_roll_finished(user_id: int, user: Optional[dict] = None, save_state: bool = True):
    user = user or await db.get_user(user_id)
    if not user or user.get("auto_roll_end_notified"):
        return
    session = get_auto_roll_session(user_id)
    user["auto_roll_end_notified"] = True
    restart_text = await try_auto_restart(user_id, user)
    if restart_text and session.get("running"):
        left = int((user.get("autorestart") or {}).get("durability", 0))
        await send_user_notification(user_id, restart_text, reply_markup=nav_kb(NAV_AUTOROLL, NAV_ARP if left > 0 else NAV_SHOP))
        return
    if save_state:
        await save_runtime_state(user_id, user)
    if restart_text:  # не сработал (сумка полна) — сообщаем причину
        await send_user_notification(user_id, restart_text, reply_markup=nav_kb(NAV_AUTOROLL))
        return
    await send_user_notification(
        user_id,
        '<blockquote><b>Авторолл</b> закончил работу<tg-emoji emoji-id="5440660757194744323">‼️</tg-emoji></blockquote>\n\n'
        '<blockquote>Напиши <b>Ролл</b> и запусти его снова<tg-emoji emoji-id="5310119641459206495">🙂</tg-emoji></blockquote>',
        reply_markup=nav_kb(NAV_AUTOROLL),
    )

async def perform_auto_roll_once(user_id: int) -> bool:
    session = get_auto_roll_session(user_id)
    if time.time() >= session.get("until", 0):
        session["running"] = False
        session["until"] = 0
        await notify_auto_roll_finished(user_id)
        await save_runtime_state(user_id)
        return False
    if len(session["items"]) >= get_auto_roll_bag_capacity(db.data.get(str(user_id))):
        session["running"] = False
        await save_runtime_state(user_id)
        return False

    user = await db.get_user(user_id)
    if not user or not user.get("auto_roll_unlocked"):
        session["running"] = False
        await save_runtime_state(user_id, user) if user else None
        return False

    if random.random() < 0.5:
        item = roll_weapon(user.get("level", 1), get_rebirth_count(user), user)
    else:
        item = roll_armor(user.get("level", 1), get_rebirth_count(user), user)
    rarity = item["rarity"]
    announce_item_drop(user_id, user, item, "авторолл")
    rarity_stats = user.setdefault("rarity_stats", {rarity_key: 0 for rarity_key in RARITIES})
    rarity_stats[rarity] = rarity_stats.get(rarity, 0) + 1
    user["chests_opened"] = user.get("chests_opened", 0) + 1
    add_xp(user, apply_xp_buff(user, get_chest_xp_reward(user)))

    essence_filters = set(user.get("auto_roll_essence", []))
    filters = set(user.get("auto_roll_filters", []))
    if rarity in essence_filters and rarity in AUTO_ROLL_ESSENCE_RARITIES:
        # Автоутиль в эссенцию (эпик+): предмет сразу превращается в эссенцию редкости
        add_boss_resource(user, get_essence_id_for_rarity(rarity), 1)
    elif rarity in filters:
        user["coins"] = user.get("coins", 0) + apply_coin_buff(user, RECYCLE_VALUES.get(rarity, 0))
    else:
        session["items"].append(item)
    ensure_daily_stats(user)["rolls"] += 1
    add_weekly_stat(user, "rolls")

    # Не пишем в базу на каждый ролл: состояние в памяти, в базу — не чаще раза в AUTO_ROLL_SAVE_INTERVAL
    await save_runtime_state_lazy(user_id, user)
    return True

async def auto_roll_loop(user_id: int):
    set_log_context("авторолл (фон)")
    try:
        while get_auto_roll_session(user_id).get("running"):
            user = await db.get_user(user_id)
            await asyncio.sleep(get_auto_roll_interval(user))
            if not await perform_auto_roll_once(user_id):
                break
    finally:
        if auto_roll_tasks.get(user_id) is asyncio.current_task():
            auto_roll_tasks.pop(user_id, None)
        # Механизм автоперезапуска мог снова включить авторолл изнутри этого цикла — продолжаем новым циклом
        session = get_auto_roll_session(user_id)
        if session.get("running") and time.time() < session.get("until", 0) and user_id not in auto_roll_tasks:
            try:
                auto_roll_tasks[user_id] = asyncio.create_task(auto_roll_loop(user_id))
            except RuntimeError:
                pass

async def start_auto_roll(user_id: int):
    session = get_auto_roll_session(user_id)
    user = await db.get_user(user_id)
    if len(session["items"]) >= get_auto_roll_bag_capacity(user):
        return
    duration = get_auto_roll_duration(user)
    session["running"] = True
    session["until"] = time.time() + duration
    user["auto_roll_end_notified"] = False
    await save_runtime_state(user_id, user)
    task = auto_roll_tasks.get(user_id)
    if not task or task.done():
        auto_roll_tasks[user_id] = asyncio.create_task(auto_roll_loop(user_id))

async def stop_auto_roll(user_id: int):
    session = get_auto_roll_session(user_id)
    session["running"] = False
    session["until"] = 0
    await save_runtime_state(user_id)
    task = auto_roll_tasks.pop(user_id, None)
    if task and not task.done():
        task.cancel()

async def claim_auto_roll_items(user_id: int) -> tuple:
    session = get_auto_roll_session(user_id)
    items = session["items"]
    user = await db.get_user(user_id)
    added = 0
    trashed = 0
    for item in items:
        if add_item_to_inventory_or_trash(user, item):
            added += 1
        else:
            trashed += 1
    session["items"] = []
    await save_runtime_state(user_id, user)
    return added, trashed

async def show_auto_roll_menu(user_id: int, answer_func):
    user = await db.get_user(user_id)
    if not user.get("auto_roll_unlocked"):
        await do_roll(user_id, answer_func)
        return

    session = get_auto_roll_session(user_id)
    items = session["items"]
    running = bool(session.get("running"))
    if running and time.time() >= session.get("until", 0):
        session["running"] = False
        session["until"] = 0
        running = False
        await notify_auto_roll_finished(user_id)
        await save_runtime_state(user_id, user)

    rarity_counts = {rarity: 0 for rarity in RARITIES}
    for item in items:
        rarity_counts[item["rarity"]] = rarity_counts.get(item["rarity"], 0) + 1
    rarity_text = "\n".join(
        f"{PREMIUM_RARITY_EMOJIS[rarity]} {RARITIES[rarity]['name']}: <b>{rarity_counts[rarity]}</b>"
        for rarity in RARITY_ORDER
        if rarity_counts.get(rarity)
    ) or "Пока пусто."

    status = "работает" if running else "остановлен"
    bag_cap = get_auto_roll_bag_capacity(user)
    if len(items) >= bag_cap:
        status = f"сумка полна {bag_cap}/{bag_cap}"
    max_duration = get_auto_roll_duration(user)
    remaining = max(0, int(session.get("until", 0) - time.time())) if running else max_duration
    minutes = remaining // 60
    seconds = remaining % 60
    time_text = f"{minutes}:{seconds:02d}"
    auto_emojis = {
        "title": '<tg-emoji emoji-id="5226702984204797593">🔄</tg-emoji>',
        "status": '<tg-emoji emoji-id="5832572966721818453">🟢</tg-emoji>',
        "time": '<tg-emoji emoji-id="5787432469598835099">⏳</tg-emoji>',
        "interval": '<tg-emoji emoji-id="5287473790735890430">⏳</tg-emoji>',
        "box": '<tg-emoji emoji-id="5854908544712707500">📦</tg-emoji>',
    }
    interval = get_auto_roll_interval(user)
    text = (
        f"{auto_emojis['title']} <b>Авторолл</b>\n\n"
        "<blockquote>"
        f"{auto_emojis['status']}: <b>{status}</b>\n"
        f"{auto_emojis['time']}: <b>{time_text}</b>\n"
        f"{auto_emojis['interval']} Интервал: <b>{interval} сек.</b>\n"
        f"{auto_emojis['box']}: <b>{len(items)}/{bag_cap}</b></blockquote>\n\n"
        f"<blockquote>{rarity_text}</blockquote>"
    )

    buttons = []
    if running:
        buttons.append([InlineKeyboardButton(text="Стоп", callback_data="auto_stop", icon_custom_emoji_id="5352669272575321097")])
    else:
        buttons.append([InlineKeyboardButton(text="Старт", callback_data="auto_start", icon_custom_emoji_id="5213214459023076318")])
    buttons.append([InlineKeyboardButton(text="Забрать", callback_data="auto_claim", icon_custom_emoji_id="5303214794336125778")])
    buttons.append([InlineKeyboardButton(text="Фильтр", callback_data="auto_filter_menu", icon_custom_emoji_id="5215327492738392838")])
    essence_on = [r for r in AUTO_ROLL_ESSENCE_RARITIES if r in set(user.get("auto_roll_essence", []))]
    essence_label = (
        "Эссенция: " + ", ".join(RARITIES[r]["emoji"] for r in essence_on)
        if essence_on else "Эссенция: выкл"
    )
    buttons.append([InlineKeyboardButton(text=essence_label, callback_data="auto_essence_menu", icon_custom_emoji_id="5370831521039017384")])
    ar = user.get("autorestart") or {}
    ar_dur = int(ar.get("durability", 0) or 0)
    ar_label = (
        f"Автоперезапуск: {ar_dur}/{AUTORESTART_MAX_DURABILITY}" + ("" if ar.get("enabled", True) else " · выкл")
        if ar_dur > 0 else "Автоперезапуск — в магазине"
    )
    buttons.append([InlineKeyboardButton(text=ar_label, callback_data="arp" if ar_dur > 0 else "shop", icon_custom_emoji_id="5346321684574003384")])

    await answer_func(text, InlineKeyboardMarkup(inline_keyboard=buttons))

