async def show_quests(user_id: int, answer_func):
    user = await db.get_user(user_id)
    visible_quests = get_current_quest_ids(user)
    active_count = sum(1 for quest_id in visible_quests if not get_quest_state(user, quest_id).get("claimed"))
    buttons = []
    for quest_id in visible_quests:
        quest = QUESTS[quest_id]
        state = get_quest_state(user, quest_id)
        progress = get_quest_progress(user, quest_id)
        target = quest["target"]
        if state.get("claimed"):
            prefix = "✅"
        elif progress >= target:
            prefix = "🎁"
        else:
            prefix = f"{progress}/{target}"
        buttons.append([
            InlineKeyboardButton(
                text=f"{prefix} {quest['name']}",
                callback_data=f"quest|{quest_id}",
            )
        ])

    if not buttons:
        buttons.append([InlineKeyboardButton(text="Все задания выполнены", callback_data="noop", icon_custom_emoji_id="5325762861539016690")])
    buttons.append([InlineKeyboardButton(text="Все ветки и будущие задания", callback_data="qchains", icon_custom_emoji_id="5197269100878907942")])

    await answer_func(
        f'<tg-emoji emoji-id="5197269100878907942">✍️</tg-emoji> <b>Задания ({active_count})</b>',
        InlineKeyboardMarkup(inline_keyboard=buttons),
    )

