QUEST_CHAIN_PAGE_SIZE = 8


def get_chain_quest_ids(chain: str) -> List[str]:
    """Задания ветки по порядку (по цепочке requires)."""
    return [qid for qid, q in QUESTS.items() if q.get("chain", qid) == chain]


def get_quest_chain_order() -> List[str]:
    order = []
    for q_id, q in QUESTS.items():
        chain = q.get("chain", q_id)
        if chain not in order:
            order.append(chain)
    return order


def quest_status_prefix(user: dict, quest_id: str) -> str:
    quest = QUESTS[quest_id]
    if get_quest_state(user, quest_id).get("claimed"):
        return "✅"
    if not is_quest_unlocked(user, quest_id):
        return "🔒"
    progress = get_quest_progress(user, quest_id)
    if progress >= quest["target"]:
        return "🎁"
    return f"{format_num(progress)}/{format_num(quest['target'])}"


async def show_quest_detail(user_id: int, quest_id: str, answer_func):
    user = await db.get_user(user_id)
    quest = QUESTS.get(quest_id)
    if not quest:
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Задание не найдено.", InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="Назад", callback_data="quests", icon_custom_emoji_id="5215361191051798408")]
        ]))
        return

    unlocked = is_quest_unlocked(user, quest_id)
    state = get_quest_state(user, quest_id)
    progress = get_quest_progress(user, quest_id)
    target = quest["target"]
    completed = progress >= target
    claimed = state.get("claimed", False)
    reward_lines = []
    if quest.get("coins", 0):
        reward_lines.append(f"<tg-emoji emoji-id=\"5463046637842608206\">🪙</tg-emoji> {format_num(quest['coins'])} монет")
    reward_xp_preview = get_quest_reward_xp(user, quest)
    if reward_xp_preview:
        share_note = f" ({int(quest['xp_share'] * 100)}% уровня)" if quest.get("xp_share") else ""
        reward_lines.append(f"<tg-emoji emoji-id=\"5370831521039017384\">✨</tg-emoji> {format_num(reward_xp_preview)} опыта{share_note}")
    if quest.get("weapon_id"):
        reward_weapon = create_weapon_by_id(quest["weapon_id"], quest["weapon_rarity"], user.get("level", 1))
        if reward_weapon:
            reward_lines.append(f"{reward_weapon['emoji']} {html.escape(reward_weapon['name'])}")
    if quest.get("unlock_auto_roll"):
        reward_lines.append("🔁 Авторолл")

    chain = quest.get("chain", quest_id)
    chain_ids = get_chain_quest_ids(chain)
    pos = chain_ids.index(quest_id) if quest_id in chain_ids else 0
    chain_name, chain_icon = QUEST_CHAIN_NAMES.get(chain, (chain, "5197269100878907942"))

    if claimed:
        status = f"{PE_OK} Награда забрана."
    elif not unlocked:
        prev = QUESTS.get(quest.get("requires") or "", {})
        status = f"🔒 Откроется после задания «{html.escape(prev.get('name', '…'))}»."
    elif completed:
        status = "🎁 Можно забрать награду!"
    else:
        status = f"{PE_HOURGLASS} В процессе: <b>{format_num(progress)}/{format_num(target)}</b>"
    text = (
        f"📌 <b>{quest['name']}</b>\n"
        f"<i>Ветка «{chain_name}» · задание {pos + 1} из {len(chain_ids)}</i>\n\n"
        f"<blockquote>{quest['description']}</blockquote>\n\n"
        "<blockquote><b>Награда:</b>\n" + "\n".join(reward_lines or ["—"]) + "</blockquote>\n\n"
        f"{status}"
    )

    buttons = []
    if unlocked and completed and not claimed:
        buttons.append([InlineKeyboardButton(text="Забрать награду", callback_data=f"claim_quest|{quest_id}", icon_custom_emoji_id="5293998404404272267")])
    nav = []
    if pos > 0:
        nav.append(InlineKeyboardButton(text="◀️", callback_data=f"quest|{chain_ids[pos - 1]}"))
    nav.append(InlineKeyboardButton(text=f"{pos + 1}/{len(chain_ids)}", callback_data=f"qchain|{chain}|{pos // QUEST_CHAIN_PAGE_SIZE}"))
    if pos < len(chain_ids) - 1:
        nav.append(InlineKeyboardButton(text="▶️", callback_data=f"quest|{chain_ids[pos + 1]}"))
    buttons.append(nav)
    buttons.append([InlineKeyboardButton(text=f"Вся ветка «{chain_name}»", callback_data=f"qchain|{chain}|{pos // QUEST_CHAIN_PAGE_SIZE}", icon_custom_emoji_id=chain_icon)])
    buttons.append([InlineKeyboardButton(text="К заданиям", callback_data="quests", icon_custom_emoji_id="5215361191051798408")])
    await answer_func(text, InlineKeyboardMarkup(inline_keyboard=buttons))


async def show_quest_chain(user_id: int, chain: str, page: int, answer_func):
    user = await db.get_user(user_id)
    ids = get_chain_quest_ids(chain)
    if not ids:
        await show_quests(user_id, answer_func)
        return
    chain_name, chain_icon = QUEST_CHAIN_NAMES.get(chain, (chain, "5197269100878907942"))
    done = sum(1 for q in ids if get_quest_state(user, q).get("claimed"))
    pages = max(1, math.ceil(len(ids) / QUEST_CHAIN_PAGE_SIZE))
    page = max(0, min(page, pages - 1))
    rows = []
    for qid in ids[page * QUEST_CHAIN_PAGE_SIZE:(page + 1) * QUEST_CHAIN_PAGE_SIZE]:
        rows.append([InlineKeyboardButton(text=f"{quest_status_prefix(user, qid)} {QUESTS[qid]['name']}"[:60], callback_data=f"quest|{qid}")])
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="◀️", callback_data=f"qchain|{chain}|{page - 1}"))
    if pages > 1:
        nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page < pages - 1:
        nav.append(InlineKeyboardButton(text="▶️", callback_data=f"qchain|{chain}|{page + 1}"))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton(text="Все ветки", callback_data="qchains", icon_custom_emoji_id="5197269100878907942")])
    rows.append([InlineKeyboardButton(text="К заданиям", callback_data="quests", icon_custom_emoji_id="5215361191051798408")])
    await answer_func(
        f'<tg-emoji emoji-id="{chain_icon}">📌</tg-emoji> <b>Ветка «{chain_name}»</b>\n\n'
        f"<blockquote>Выполнено: <b>{done}/{len(ids)}</b>\n{durability_bar(done, len(ids))}\n"
        "✅ забрано · 🎁 можно забрать · 🔒 откроется позже</blockquote>",
        InlineKeyboardMarkup(inline_keyboard=rows),
    )


async def show_quest_chains(user_id: int, answer_func):
    user = await db.get_user(user_id)
    rows = []
    for chain in get_quest_chain_order():
        ids = get_chain_quest_ids(chain)
        done = sum(1 for q in ids if get_quest_state(user, q).get("claimed"))
        name, icon = QUEST_CHAIN_NAMES.get(chain, (chain, None))
        rows.append([InlineKeyboardButton(text=f"{name} · {done}/{len(ids)}", callback_data=f"qchain|{chain}|0", icon_custom_emoji_id=icon)])
    rows.append([InlineKeyboardButton(text="К заданиям", callback_data="quests", icon_custom_emoji_id="5215361191051798408")])
    total = len(QUESTS)
    done_all = sum(1 for q in QUESTS if get_quest_state(user, q).get("claimed"))
    await answer_func(
        f'<tg-emoji emoji-id="5197269100878907942">✍️</tg-emoji> <b>Все ветки заданий</b>\n\n'
        f"<blockquote>Выполнено всего: <b>{done_all}/{total}</b>\n{durability_bar(done_all, total)}</blockquote>\n\n"
        "<i>Открой ветку, чтобы посмотреть и будущие задания.</i>",
        InlineKeyboardMarkup(inline_keyboard=rows),
    )


@dp.callback_query(F.data.startswith("qchain|"))
async def cb_quest_chain(call: CallbackQuery):
    await call.answer()
    _, chain, page = (call.data.split("|") + ["0"])[:3]
    await show_quest_chain(call.from_user.id, chain, int(page) if page.isdigit() else 0, lambda t, kb: edit_for_user(call, t, kb))


@dp.callback_query(F.data == "qchains")
async def cb_quest_chains(call: CallbackQuery):
    await call.answer()
    await show_quest_chains(call.from_user.id, lambda t, kb: edit_for_user(call, t, kb))


async def claim_quest_reward(user_id: int, quest_id: str, answer_func):
    user = await db.get_user(user_id)
    quest = QUESTS.get(quest_id)
    if not quest or not is_quest_unlocked(user, quest_id):
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Задание не найдено.", InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="Назад", callback_data="quests", icon_custom_emoji_id="5215361191051798408")]
        ]))
        return

    state = get_quest_state(user, quest_id)
    if state.get("claimed"):
        await show_quest_detail(user_id, quest_id, answer_func)
        return
    if not is_quest_completed(user, quest_id):
        await show_quest_detail(user_id, quest_id, answer_func)
        return

    reward_weapon = None
    if quest.get("weapon_id"):
        reward_weapon = create_weapon_by_id(quest["weapon_id"], quest["weapon_rarity"], user.get("level", 1))
    quest_coins = apply_coin_buff(user, quest["coins"])
    user["coins"] = user.get("coins", 0) + quest_coins
    reward_xp = apply_xp_buff(user, get_quest_reward_xp(user, quest))
    levels_gained = add_xp(user, reward_xp)
    weapon_in_inventory = True
    if reward_weapon:
        weapon_in_inventory = add_item_to_inventory_or_trash(user, reward_weapon)
    if quest.get("unlock_auto_roll"):
        user["auto_roll_unlocked"] = True
    state["claimed"] = True
    state["notified"] = True
    await db.save_user(user_id, user)

    weapon_text = ""
    if reward_weapon:
        place = "в экипировку" if weapon_in_inventory else "в корзину"
        weapon_text = f"\n{reward_weapon['emoji']} {html.escape(reward_weapon['name'])} добавлена {place}."
    level_text = f"\n<tg-emoji emoji-id=\"6084922627736996647\">🆙</tg-emoji> Новый уровень: <b>{user['level']}</b>" if levels_gained else ""
    unlock_text = "\n🔁 Открыт авторолл. Напиши <b>ролл</b>." if quest.get("unlock_auto_roll") else ""
    await answer_func(
        "<tg-emoji emoji-id=\"5293998404404272267\">🎁</tg-emoji> <b>Награда получена!</b>\n"
        f"<tg-emoji emoji-id=\"5463046637842608206\">🪙</tg-emoji> +{format_num(quest_coins)} монет\n"
        f"<tg-emoji emoji-id=\"5370831521039017384\">✨</tg-emoji> +{format_num(reward_xp)} опыта"
        f"{weapon_text}"
        f"{level_text}"
        f"{unlock_text}",
        InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="К заданиям", callback_data="quests", icon_custom_emoji_id="5215361191051798408")]
        ]),
    )

def get_xp_bar(current_xp: int, level: int) -> str:
    needed = get_level_xp_required(level)
    filled = max(0, min(10, round(current_xp / needed * 10))) if needed else 0
    bar = "█" * filled + "░" * (10 - filled)
    return f"{bar} {format_num(current_xp)}/{format_num(needed)}"

