async def show_belt_items(user_id: int, filter_type: str, answer_func):
    """Показывает предметы из инвентаря, отфильтрованные по типу (weapon или слот брони)"""
    u = await db.get_user(user_id)
    inv = u.get("inventory", [])
    
    if filter_type == "weapon":
        title = "<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> <b>Оружие в инвентаре</b>"
    else:
        slot_name = ARMOR_SLOT_NAMES.get(filter_type, filter_type)
        slot_emoji = ARMOR_SLOT_EMOJI.get(filter_type, "<tg-emoji emoji-id=\"5854908544712707500\">📦</tg-emoji>")
        title = f"{slot_emoji} <b>{slot_name} в инвентаре</b>"

    copy_counts = {}
    item_entries = []
    for item in inv:
        item_id = item["id"]
        copy_idx = copy_counts.get(item_id, 0)
        copy_counts[item_id] = copy_idx + 1
        if filter_type == "weapon" and item.get("item_type") != "armor":
            item_entries.append((item, copy_idx))
        elif item.get("item_type") == "armor":
            if armor_slot_matches(item.get("slot"), filter_type):
                item_entries.append((item, copy_idx))
    
    if not item_entries:
        await answer_func(f"{title}\n\nНет предметов этого типа.", InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="Назад", callback_data="belt_back", icon_custom_emoji_id="5215361191051798408")]
        ]))
        return

    def belt_item_sort_key(entry):
        item = entry[0]
        rarity_idx = RARITY_ORDER.index(item["rarity"]) if item.get("rarity") in RARITY_ORDER else 999
        if filter_type == "weapon":
            return (rarity_idx, -item.get("power", 0), -item.get("weapon_level", 1))
        return (rarity_idx, -item.get("hp", 0), -item.get("level", 1))

    sorted_entries = sorted(item_entries, key=belt_item_sort_key)

    weapon_buttons = []
    row = []
    item_lines = []
    for item, copy_idx in sorted_entries:
        item_id = item["id"]
        item_lines.append(format_belt_weapon_line(item) if filter_type == "weapon" else format_belt_armor_line(item))
        btn_text = f"{item['emoji']} [{item['rarity_emoji']}]"
        item_ref = f"iid:{item.get('iid')}" if item.get("iid") else f"{item_id}|{copy_idx}"
        cb_data = f"belt_equip|{filter_type}|{item_ref}"
        row.append(InlineKeyboardButton(text=btn_text, callback_data=cb_data))
        if len(row) == 5:
            weapon_buttons.append(row)
            row = []
    if row:
        weapon_buttons.append(row)
    weapon_buttons.append([InlineKeyboardButton(text="Назад", callback_data="belt_back", icon_custom_emoji_id="5215361191051798408")])
    
    await answer_func(
        title + "\n\n" + "\n".join(item_lines),
        InlineKeyboardMarkup(inline_keyboard=weapon_buttons),
    )

