async def recycle_selected_weapons(user_id: int) -> tuple:
    selected = recycle_sessions.pop(user_id, set())
    recycle_modes.pop(user_id, None)
    if not selected:
        return 0, 0

    user = await db.get_user(user_id)
    locked = lock_sessions.get(user_id, set())
    inventory = user.get("inventory", [])
    kept = []
    copy_counts = {}
    coins = 0
    removed_count = 0

    for item in inventory:
        item_id = item["id"]
        copy_idx = copy_counts.get(item_id, 0)
        copy_counts[item_id] = copy_idx + 1
        selected_key = f"{item_id}|{copy_idx}"
        if selected_key in selected and selected_key not in locked:
            coins += RECYCLE_VALUES.get(item.get("rarity"), 0)
            removed_count += 1
            continue
        kept.append(item)

    user["inventory"] = kept
    coins = apply_coin_buff(user, coins)
    user["coins"] = user.get("coins", 0) + coins
    sync_equipment_with_inventory(user)
    # замки хранятся по iid: после удаления предметов индексы копий сдвигаются,
    # поэтому ключи пересобираем из iid, а не сохраняем старые
    restore_lock_session_from_user(user_id, user)

    await db.save_user(user_id, user)
    return coins, removed_count

def get_trash_recycle_key(item_data: dict) -> str:
    level = item_data.get("weapon_level") or item_data.get("level", 1)
    return f'{item_data.get("id", "")}|{item_data.get("rarity", "")}|{level}'

async def recycle_selected_trash(user_id: int) -> tuple:
    selected = trash_recycle_sessions.pop(user_id, set())
    if not selected:
        return 0, 0

    user = await db.get_user(user_id)
    trash = user.get("trash") or []
    kept = []
    coins = 0
    removed_count = 0

    for trash_item in trash:
        item_data = trash_item.get("item", {})
        if get_trash_recycle_key(item_data) in selected:
            coins += RECYCLE_VALUES.get(item_data.get("rarity"), 0)
            removed_count += 1
            continue
        kept.append(trash_item)

    user["trash"] = kept
    coins = apply_coin_buff(user, coins)
    user["coins"] = user.get("coins", 0) + coins
    await db.save_user(user_id, user)
    return coins, removed_count

async def show_inv(user_id, answer_func, page=0):
    u = await db.get_user(user_id)
    inv = u.get("inventory", [])
    trash = u.get("trash") or []
    recycle_selected = recycle_sessions.get(user_id)
    restore_lock_session_from_user(user_id, u)
    locked_items = lock_sessions.setdefault(user_id, set())
    lock_mode = user_id in lock_modes

    if not inv:
        text = "<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> <b>Экипировка пуста</b>"
        kb_buttons = []
        if trash:
            kb_buttons.append([InlineKeyboardButton(text=f"🗑️ Корзина ({len(trash)})", callback_data="trash")])
        await answer_func(text, InlineKeyboardMarkup(inline_keyboard=kb_buttons))
        return

    copy_counts = {}
    inventory_items = []
    for item in inv:
        item_id = item["id"]
        copy_idx = copy_counts.get(item_id, 0)
        copy_counts[item_id] = copy_idx + 1
        inventory_items.append((item_id, item, copy_idx))
    if recycle_selected is not None:
        valid_keys = {f"{item_id}|{copy_idx}" for item_id, _, copy_idx in inventory_items}
        recycle_selected.intersection_update(valid_keys)
    valid_keys = {f"{item_id}|{copy_idx}" for item_id, _, copy_idx in inventory_items}
    locked_items.intersection_update(valid_keys)

    def sort_key(item_data):
        item = item_data[1]
        rarity_idx = RARITY_ORDER.index(item["rarity"]) if item.get("rarity") in RARITY_ORDER else 999
        if item.get("item_type") == "armor":
            slot = item.get("slot", "helmet")
            if slot == "bracers":
                slot = "bracers_left"
            slot_idx = ARMOR_SLOTS.index(slot) if slot in ARMOR_SLOTS else len(ARMOR_SLOTS)
            return (1, rarity_idx, -item.get("hp", 0), -item.get("level", 1), slot_idx)
        else:
            return (0, rarity_idx, -item.get("power", 0), -item.get("weapon_level", 1))

    sorted_items = sorted(inventory_items, key=sort_key)

    items_per_page = 10
    total_pages = max(1, (len(sorted_items) + items_per_page - 1) // items_per_page)
    page = min(page, total_pages - 1)
    start = page * items_per_page
    end = min(start + items_per_page, len(sorted_items))
    page_items = sorted_items[start:end]

    equipped_weapon = u.get("equipped")
    equipped_armor = u.get("equipped_armor", {})
    equipped_iids = set()
    if equipped_weapon and equipped_weapon.get("iid"):
        equipped_iids.add(equipped_weapon["iid"])
    for slot in ARMOR_SLOTS:
        piece = equipped_armor.get(slot)
        if piece and piece.get("iid"):
            equipped_iids.add(piece["iid"])

    weapon_buttons = []
    row = []
    for key, item, copy_idx in page_items:
        selected_key = f"{key}|{copy_idx}"
        selected_mark = "✅" if recycle_selected is not None and selected_key in recycle_selected else ""
        lock_mark = "🔒" if selected_key in locked_items else ""  # замок виден всегда: и при выборе замков, и при утиле
        equip_mark = "✨" if item.get("iid") and item["iid"] in equipped_iids else ""
        prefix = "".join(filter(None, [selected_mark, lock_mark, equip_mark]))
        btn_text = f"{prefix}{item['emoji']}{item['rarity_emoji']}"
        cb_data = f"w|iid:{item.get('iid')}|{page}" if item.get("iid") else f"w|{key}|{copy_idx}|{page}"
        row.append(InlineKeyboardButton(text=btn_text, callback_data=cb_data))
        if len(row) == 4:
            weapon_buttons.append(row)
            row = []
    if row:
        weapon_buttons.append(row)

    lock_button_text = "Замки" if not lock_mode else "Готово"
    essence_mode = recycle_modes.get(user_id) == "essence"
    recycle_row = [
        InlineKeyboardButton(text=lock_button_text, callback_data="lock_toggle", icon_custom_emoji_id="5296369303661067030" if not lock_mode else "5325762861539016690"),
        InlineKeyboardButton(text="Утиль", callback_data="recycle_toggle", icon_custom_emoji_id="5445267414562389170"),
        InlineKeyboardButton(text="Эссенция", callback_data="essence_select", icon_custom_emoji_id="5370831521039017384"),
    ]
    if recycle_selected is not None:
        recycle_row = [
            InlineKeyboardButton(text="Отмена", callback_data="recycle_cancel", icon_custom_emoji_id="5352669272575321097"),
            InlineKeyboardButton(text="Все", callback_data="recycle_all", icon_custom_emoji_id="5332336747072208845"),
            (
                InlineKeyboardButton(text=f"Далее ({len(recycle_selected)})", callback_data="essence_ask", icon_custom_emoji_id="5370831521039017384")
                if essence_mode else
                InlineKeyboardButton(text="Утиль", callback_data="recycle_toggle", icon_custom_emoji_id="5445267414562389170")
            ),
        ]
    nav_rows = [recycle_row]
    if total_pages > 1:
        arrow_buttons = []
        if page > 0:
            arrow_buttons.append(InlineKeyboardButton(text="◀️", callback_data=f"inv_page_{page-1}"))
        if page < total_pages - 1:
            arrow_buttons.append(InlineKeyboardButton(text="▶️", callback_data=f"inv_page_{page+1}"))
        if arrow_buttons:
            nav_rows.append(arrow_buttons)

    bottom_buttons = []
    if trash:
        bottom_buttons.append([InlineKeyboardButton(text=f"🗑️ Корзина ({len(trash)})", callback_data="trash")])

    kb = InlineKeyboardMarkup(inline_keyboard=weapon_buttons + nav_rows + bottom_buttons)
    total = len(inv)
    text = f"<tg-emoji emoji-id=\"5373173798633752502\">⚔️</tg-emoji> <b>Экипировка</b> ({total}/{MAX_INVENTORY}, страница {page+1}/{total_pages})"
    if recycle_selected is not None:
        selected_count = len(recycle_selected)
        if essence_mode:
            text += (
                f"\n\n<tg-emoji emoji-id=\"5370831521039017384\">✨</tg-emoji> В эссенцию: выбрано <b>{selected_count}</b>. "
                "Отметь предметы и нажми «Далее» — перед превращением будет подтверждение. Надетые и под замком не трогаются."
            )
        else:
            text += f"\n\n<tg-emoji emoji-id=\"5445267414562389170\">🗑</tg-emoji> Переработка: выбрано <b>{selected_count}</b>."
    if lock_mode:
        text += f"\n<tg-emoji emoji-id=\"5296369303661067030\">🔒</tg-emoji> Замки: выбрано <b>{len(locked_items)}</b>."
    await answer_func(text, kb)

async def show_trash(user_id, answer_func, page=0):
    u = await db.get_user(user_id)
    trash = u.get("trash") or []
    recycle_selected = trash_recycle_sessions.get(user_id)
    now = time.time()
    grouped = {}
    for item in trash:
        item_data = item["item"]
        key = get_trash_recycle_key(item_data)
        if key not in grouped:
            grouped[key] = {
                "item": item_data,
                "count": 0,
                "expires_at": item["expires_at"],
                "key": key,
            }
        grouped[key]["count"] += 1
        grouped[key]["expires_at"] = min(grouped[key]["expires_at"], item["expires_at"])
    if recycle_selected is not None:
        recycle_selected.intersection_update(grouped.keys())

    lines = []
    sorted_groups = sorted(
        grouped.values(),
        key=lambda group: (
            RARITY_ORDER.index(group["item"].get("rarity")) if group["item"].get("rarity") in RARITY_ORDER else 999,
            - (group["item"].get("weapon_level") or group["item"].get("level", 1)),
            group["expires_at"],
        ),
    )
    groups_per_page = 10
    total_pages = max(1, (len(sorted_groups) + groups_per_page - 1) // groups_per_page)
    page = max(0, min(page, total_pages - 1))
    page_groups = sorted_groups[page * groups_per_page:(page + 1) * groups_per_page]

    group_buttons = []
    button_row = []
    for group in page_groups:
        item_data = group["item"]
        left = max(0, int(group["expires_at"] - now))
        h = left // 3600
        m = (left % 3600) // 60
        time_str = f"{h}ч {m}м"
        lines.append(
            f"{item_data['emoji']} {item_data['rarity_emoji']} "
            f"{html.escape(item_data['name'])} · {item_data.get('weapon_level') or item_data.get('level', 1)} ур. "
            f"×{group['count']} · {time_str}"
        )
        if recycle_selected is not None:
            selected_mark = "✅ " if group["key"] in recycle_selected else ""
            button_text = f"{selected_mark}{item_data['emoji']} [{item_data['rarity_emoji']}] ×{group['count']}"
            button_row.append(InlineKeyboardButton(text=button_text, callback_data=f"trash_pick|{page}|{group['key']}"))
            if len(button_row) == 2:
                group_buttons.append(button_row)
                button_row = []
    if button_row:
        group_buttons.append(button_row)

    if lines:
        text = (
            f"🗑️ <b>Корзина</b> ({len(trash)} предметов, страница {page+1}/{total_pages})\n\n"
            + "\n".join(lines)
        )
    else:
        text = "🗑️ <b>Корзина пуста</b>"

    if recycle_selected is not None:
        text += f"\n\n<tg-emoji emoji-id=\"5445267414562389170\">🗑</tg-emoji> Переработка: выбрано <b>{len(recycle_selected)}</b>."

    kb_buttons = group_buttons
    if lines and total_pages > 1:
        nav_buttons = []
        if page > 0:
            nav_buttons.append(InlineKeyboardButton(text="◀️", callback_data=f"trash_page_{page-1}"))
        if page < total_pages - 1:
            nav_buttons.append(InlineKeyboardButton(text="▶️", callback_data=f"trash_page_{page+1}"))
        if nav_buttons:
            kb_buttons.append(nav_buttons)
    if trash:
        if recycle_selected is None:
            kb_buttons.append([
                InlineKeyboardButton(text="Забрать всё", callback_data="claim_trash", icon_custom_emoji_id="5854908544712707500"),
                InlineKeyboardButton(text="Утиль", callback_data="trash_recycle_toggle", icon_custom_emoji_id="5445267414562389170"),
            ])
        else:
            kb_buttons.append([
                InlineKeyboardButton(text="Отмена", callback_data="trash_recycle_cancel", icon_custom_emoji_id="5352669272575321097"),
                InlineKeyboardButton(text="Все", callback_data="trash_recycle_all", icon_custom_emoji_id="5332336747072208845"),
                InlineKeyboardButton(text="Утиль", callback_data="trash_recycle_toggle", icon_custom_emoji_id="5445267414562389170"),
            ])
    kb_buttons.append([InlineKeyboardButton(text="Назад", callback_data="equipment", icon_custom_emoji_id="5215361191051798408")])

    await answer_func(text, InlineKeyboardMarkup(inline_keyboard=kb_buttons))

def get_roll_result_text(
    item: dict,
    chests_opened: int,
    inventory_full: bool = False,
    xp_reward: int = 0,
    level_gained: bool = False,
) -> str:
    item_name = html.escape(item["name"])
    rarity_name = html.escape(item["rarity_name"])
    rarity_emoji = PREMIUM_RARITY_EMOJIS.get(item.get("rarity"), item.get("rarity_emoji", ""))
    success_emoji = '<tg-emoji emoji-id="5325762861539016690">✅</tg-emoji>'
    xp_emoji = '<tg-emoji emoji-id="5431816358675366190">🆙</tg-emoji>'
    level_emoji = '<tg-emoji emoji-id="6251319294395680297">🍉</tg-emoji>'
    damage_emoji = '<tg-emoji emoji-id="5373173798633752502">🛡</tg-emoji>'
    power_emoji = '<tg-emoji emoji-id="5332336747072208845">🔥</tg-emoji>'
    slot_emoji = '<tg-emoji emoji-id="5197269100878907942">✍️</tg-emoji>'
    hp_emoji = '<tg-emoji emoji-id="5404843113652970870">💊</tg-emoji>'
    level_up_emoji = '<tg-emoji emoji-id="5370632904571380120">⏏️</tg-emoji>'
    status = (
        "⚠️ Экипировка заполнена. Предмет отправлен в корзину на 24 часа."
        if inventory_full else
        f"{success_emoji} Добавлено в экипировку."
    )
    xp_text = f"\n{xp_emoji} +{xp_reward} опыта" if xp_reward else ""
    level_text = f"\n{level_up_emoji} Новый уровень!" if level_gained else ""
    
    if item.get("item_type") == "armor":
        slot_name = ARMOR_SLOT_NAMES.get(item["slot"], item["slot"])
        resource_lines = get_armor_resource_lines(item)
        return (
            f"{item['emoji']} <b>{item_name}</b>\n"
            f"{rarity_emoji} {rarity_name}\n"
            f"{slot_emoji} {slot_name}\n"
            f"{level_emoji}<b>{item.get('level', 1)}</b> Уровень\n"
            f"{hp_emoji} <b>+{item['hp']}</b> HP"
            + (("\n" + "\n".join(resource_lines)) if resource_lines else "")
            + "\n\n"
            f"{status}{xp_text}{level_text}"
        )
    else:
        return (
            f"{item['emoji']} <b>{item_name}</b>\n"
            f"{rarity_emoji} {rarity_name}\n"
            f"{get_weapon_type_text(item)}\n"
            f"{level_emoji}<b>{item.get('weapon_level', 1)}</b> Уровень\n"
            f"{damage_emoji} Урон: <b>{item['dmg'][0]}–{item['dmg'][1]}</b>\n"
            f"{power_emoji} Сила: <b>{item.get('power', 0)}</b>\n\n"
            f"{status}{xp_text}{level_text}"
        )

async def do_roll(user_id, answer_func, notify_func=None, cooldown_func=None, sticker_func=None):
    notify_func = notify_func or answer_func
    now = time.time()
    if user_id in last_roll:
        if now - last_roll[user_id] < 5:
            осталось = math.ceil(5 - (now - last_roll[user_id]))
            if cooldown_func:
                await cooldown_func(осталось)
                return
            await answer_func(f"<tg-emoji emoji-id=\"5287473790735890430\">⏳</tg-emoji> Следующий ролл можно сделать через <b>{осталось} сек.</b>", None)
            return
    last_roll[user_id] = now
    u = await db.get_user(user_id)
    xp_reward = get_chest_xp_reward(u)
    xp_reward = apply_xp_buff(u, xp_reward)
    
    if random.random() < 0.5:
        item = roll_weapon(u.get("level", 1), get_rebirth_count(u), u)
    else:
        item = roll_armor(u.get("level", 1), get_rebirth_count(u), u)
    
    rarity_stats = u.setdefault("rarity_stats", {rarity: 0 for rarity in RARITIES})
    rarity_stats[item["rarity"]] = rarity_stats.get(item["rarity"], 0) + 1
    announce_item_drop(user_id, u, item, "ролл")
    levels_gained = add_xp(u, xp_reward)

    if len(u["inventory"]) >= MAX_INVENTORY:
        if "trash" not in u:
            u["trash"] = []
        u["trash"].append({
            "item": item,
            "expires_at": now + TRASH_TTL_SECONDS
        })
        u["chests_opened"] += 1
        ensure_daily_stats(u)["rolls"] += 1
        add_weekly_stat(u, "rolls")
        await db.save_user(user_id, u)
        await answer_func(
            get_roll_result_text(item, u["chests_opened"], inventory_full=True, xp_reward=xp_reward, level_gained=bool(levels_gained)),
            InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="🗑️ Открыть корзину", callback_data="trash")],
                [InlineKeyboardButton(text="🎲 Роллить снова", callback_data="roll")],
            ])
        )
        await notify_completed_quests(user_id, u, notify_func, sticker_func)
    else:
        u["inventory"].append(item)
        u["chests_opened"] += 1
        ensure_daily_stats(u)["rolls"] += 1
        add_weekly_stat(u, "rolls")
        await db.save_user(user_id, u)
        await answer_func(
            get_roll_result_text(item, u["chests_opened"], xp_reward=xp_reward, level_gained=bool(levels_gained)),
            InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="🎲 Роллить снова", callback_data="roll")],
            ])
        )
        await notify_completed_quests(user_id, u, notify_func, sticker_func)

# ====== ФОНОВАЯ ЗАДАЧА ======
async def cleanup_trash():
    while True:
        await asyncio.sleep(60)
        await db.load()
        changed_ids = []
        now = time.time()
        for uid, u in list(db.data.items()):
            trash = u.get("trash") or []
            if not trash:
                continue
            new_trash = [t for t in trash if t["expires_at"] > now]
            if len(new_trash) != len(trash):
                u["trash"] = new_trash
                changed_ids.append(uid)
        if changed_ids:
            await db.save_users(changed_ids)

async def check_boss_cooldown_notifications():
    await db.load()
    changed = False
    changed_ids = set()
    final_bosses = get_final_location_bosses()
    for uid_raw, user in list(db.data.items()):
        try:
            uid = int(uid_raw)
        except (TypeError, ValueError):
            continue
        if not isinstance(user, dict):
            continue
        cooldowns = user.get("boss_cooldowns") or {}
        if not cooldowns:
            continue
        notified = user.setdefault("boss_cd_notified", {})
        for boss in final_bosses:
            boss_id = boss.get("id")
            if not boss_id or boss_id not in cooldowns or notified.get(boss_id):
                continue
            if get_boss_cd_remaining(user, boss_id) <= 0:
                await send_user_notification(
                    uid, get_boss_ready_notification_text(boss),
                    reply_markup=nav_kb(("В бой", f"quick_boss|{boss_id}", premium_emoji_id(boss.get("premium_emoji", "")) or "5373173798633752502"), NAV_BOSSES),
                )
                notified[boss_id] = True
                changed = True
                changed_ids.add(uid)

    if changed:
        await db.save_users(changed_ids)

