async def check_farm_notifications():
    """Урожай созрел — одно уведомление на игрока, со списком созревшего и кнопкой «Огород»."""
    now = time.time()
    changed = set()
    for uid_str, user in list(db.data.items()):
        if not isinstance(user, dict) or not user.get("farm"):
            continue
        ripe = collections.Counter()
        for bed in user["farm"]:
            if not isinstance(bed, dict) or not bed.get("crop") or bed.get("notified"):
                continue
            if float(bed.get("ready_at", 0)) <= now:
                bed["notified"] = True
                ripe[bed["crop"]] += 1
        if not ripe:
            continue
        changed.add(uid_str)
        lines = [f"{CROPS[c][1]} <b>{CROPS[c][0]}</b> ×{n}" for c, n in ripe.items() if c in CROPS]
        await send_user_notification(
            int(uid_str),
            f'<blockquote><tg-emoji emoji-id="5197555094161234652">🌿</tg-emoji> <b>Урожай созрел</b>{PE_ALARM}</blockquote>\n\n'
            "<blockquote>" + "\n".join(lines) + "</blockquote>\n\n"
            f"<blockquote>{PE_GIFT} Собери его в огороде и посади новое — грядки не должны пустовать</blockquote>",
            reply_markup=nav_kb(("Огород", "farm|ref", "5197555094161234652")),
        )
    if changed:
        await db.save_users(changed)


async def check_pet_hunger_notifications():
    await db.load()
    changed = False
    changed_ids = set()
    now = time.time()
    for uid_raw, user in list(db.data.items()):
        try:
            uid = int(uid_raw)
        except (TypeError, ValueError):
            continue
        if not isinstance(user, dict):
            continue
        for pet in user.get("pets") or []:
            until = float(pet.get("feeding_until") or 0)
            if until <= 0 or until > now or float(pet.get("hunger_notified", 0) or 0) == until:
                continue
            pet["hunger_notified"] = until
            changed = True
            changed_ids.add(uid)

            await send_user_notification(uid, get_pet_hunger_notification_text(pet), reply_markup=nav_kb(nav_pet(pet), ("Покормить всех", "pets_feed_all", "5395625559784968299")))
    if changed:
        await db.save_users(changed_ids)


