class _CallbackReplyProxy:
    """Позволяет вызвать обработчик команды (проф и т.п.) из кнопки на уведомлении."""
    def __init__(self, call: CallbackQuery):
        self.from_user = call.from_user
        self.chat = call.message.chat if call.message else None
        self.reply_to_message = None
        self.text = ""
        self.entities = []
        self._call = call

    async def reply(self, *args, **kwargs):
        return await self._call.message.answer(*args, **kwargs)

    async def answer(self, *args, **kwargs):
        return await self._call.message.answer(*args, **kwargs)


@dp.callback_query(F.data == "open_profile")
async def cb_open_profile(call: CallbackQuery):
    await call.answer()
    if not await db.has_user(call.from_user.id):
        return
    await show_profile(_CallbackReplyProxy(call))


async def boss_cooldown_notification_loop():
    while True:
        try:
            await check_boss_cooldown_notifications()
            await check_witch_brew_notifications()
            await check_pet_hunger_notifications()
            await check_farm_notifications()
        except Exception as e:
            print(f"[boss_cooldown_notification_loop] failed: {e}")
        await asyncio.sleep(60)

async def restore_runtime_state():
    await db.load()
    now = time.time()
    changed = cleanup_test_profiles()
    restored_auto_rolls = 0
    restored_battles = 0

    for uid_raw, user in list(db.data.items()):
        try:
            uid = int(uid_raw)
        except (TypeError, ValueError):
            continue

        restore_lock_session_from_user(uid, user)

        session = user.get("auto_roll_session") or get_empty_auto_roll_session()
        session_items = session.get("items") or []
        session_until = float(session.get("until") or 0)
        session_running = bool(session.get("running")) and session_until > now and len(session_items) < get_auto_roll_bag_capacity(user)
        restored_session = {
            "items": session_items,
            "running": session_running,
            "until": session_until if session_running else 0,
        }

        if session.get("items") or session.get("running") or session.get("until"):
            auto_roll_sessions[uid] = restored_session
            user["auto_roll_session"] = restored_session
            restored_auto_rolls += 1
            if session.get("running") != session_running or session.get("until") != restored_session["until"]:
                changed = True
            if (
                session.get("running")
                and not session_running
                and session_until <= now
                and len(session_items) < get_auto_roll_bag_capacity(user)
                and not user.get("auto_roll_end_notified")
            ):
                await notify_auto_roll_finished(uid, user, save_state=False)
                changed = True
            if session_running:
                auto_roll_tasks[uid] = asyncio.create_task(auto_roll_loop(uid))

        battle = user.get("active_battle")
        if battle:
            restored_battle = copy.deepcopy(battle)
            restored_battle["busy"] = False
            restored_battle["last_saved_at"] = 0
            if (restored_battle.get("boss") or {}).get("id") in BOSSES:
                restored_battle["boss"] = BOSSES[restored_battle["boss"]["id"]]
            ensure_boss_battle_damage_scaled(restored_battle)
            if is_boss_battle_expired(restored_battle):
                user["active_battle"] = None
                changed = True
            else:
                active_battles[uid] = restored_battle
                user["active_battle"] = restored_battle
                restored_battles += 1
            if battle.get("busy"):
                changed = True

    if changed:
        await db.save()
    print(f"Restored runtime: auto_rolls={restored_auto_rolls}, battles={restored_battles}")


