async def show_clan_members(user_id: int, clan_id: str, answer_func, call: Optional[CallbackQuery] = None):
    await load_clans()
    await db.load()
    clan = get_clan(clan_id)
    clan_emoji = '<tg-emoji emoji-id="5359778044745622115">🏛</tg-emoji>'
    if not clan:
        msg = "❌ Клан не найден."
        if call:
            await call.answer(msg, show_alert=True)
        else:
            await answer_func(premium_cross(msg), None)
        return

    members = clan.get("members") or {}
    # Sort: leader first, then by level desc
    rows = []
    for uid_str, minfo in members.items():
        try:
            mid = int(uid_str)
        except (TypeError, ValueError):
            continue
        muser = db.data.get(str(mid)) or {}
        name = str(muser.get("name") or f"id{mid}")
        level = int(muser.get("level", 1) or 1)
        prest = get_rebirth_count(muser)
        role = (minfo or {}).get("role", "member")
        rows.append((clan_rank_order(role), level, prest, name, mid, role))

    rows.sort(key=lambda x: (-x[0], -x[1], -x[2], x[3].casefold()))

    text_msg = (
        f"{clan_emoji} <b>Участники [{html.escape(str(clan.get('tag','')))}]</b>\n\n"
        f"<blockquote>{len(rows)} / {CLAN_MAX_MEMBERS}</blockquote>\n"
        "Нажми на игрока, чтобы увидеть вклад и детали."
    )

    buttons = []
    for _ord, level, prest, name, mid, role in rows:
        re = clan_rank_info(role).get("emoji", "")
        label = f"{re} {name} · {level} ур. · {prest} пр."
        if len(label) > 64:
            label = label[:61] + "..."
        buttons.append([InlineKeyboardButton(
            text=label,
            callback_data=f"clan_member|{clan_id}|{mid}",
        )])
    buttons.append([InlineKeyboardButton(text="Назад к клану", callback_data=f"clan_back|{clan_id}", icon_custom_emoji_id=BTN_BACK)])

    await answer_func(text_msg, InlineKeyboardMarkup(inline_keyboard=buttons))


async def show_clan_member_info(viewer_id: int, clan_id: str, member_id: int, answer_func, call: Optional[CallbackQuery] = None):
    await load_clans()
    await db.load()
    clan = get_clan(clan_id)
    clan_emoji = '<tg-emoji emoji-id="5359778044745622115">🏛</tg-emoji>'
    if not clan:
        if call:
            await call.answer("Клан не найден", show_alert=True)
        return
    members = clan.get("members") or {}
    minfo = members.get(str(member_id))
    if not minfo:
        if call:
            await call.answer("Игрок не в клане", show_alert=True)
        return
    minfo = _ensure_member_data(dict(minfo))
    muser = db.data.get(str(member_id)) or {}
    name = render_user_nickname(muser, f"id{member_id}")
    level = int(muser.get("level", 1) or 1)
    prest = get_rebirth_count(muser)
    power = calculate_user_power(muser) if muser else 0
    role = minfo.get("role", "member")
    joined = format_clan_date(minfo.get("joined_at", 0))
    rank_text = format_clan_rank(role)

    contrib_lines = []
    total_contrib = 0
    for rid in CLAN_RESOURCE_IDS:
        cnt = int((minfo.get("contributions") or {}).get(rid, 0))
        total_contrib += cnt
        info = BOSS_RESOURCE_DEFS.get(rid, {})
        contrib_lines.append(f"{info.get('emoji','•')} {info.get('name', rid)}: <b>{cnt}</b>")

    tg_username = get_user_tg_username(muser)
    username_text = f"@{html.escape(tg_username)}" if tg_username else "<i>не указан</i>"
    text_msg = (
        f"{clan_emoji} <b>{name}</b>\n\n"
        f"<blockquote>"
        f"{PE_ID} Юзернейм: {username_text}\n"
        f"Ранг: <b>{rank_text}</b>\n"
        f"Уровень: <b>{level}</b>\n"
        f"Престиж: <b>{prest}</b>\n"
        f"Сила: <b>{power}</b>\n"
        f"В клане с: <b>{joined}</b>"
        f"</blockquote>\n\n"
        f"<blockquote><b>Вклад в склад</b>\n"
        + "\n".join(contrib_lines)
        + f"\n———\nВсего единиц: <b>{total_contrib}</b>"
        + "</blockquote>"
    )

    buttons = []
    viewer_mem = members.get(str(viewer_id)) or {}
    # Кнопки повышения/понижения
    if viewer_id != member_id and role != "leader" and clan_has_perm(viewer_mem, "promote"):
        can_manage = True
        v_role = viewer_mem.get("role", "member")
        if v_role != "leader" and role not in CLAN_OFFICER_MANAGEABLE:
            can_manage = False
        if can_manage:
            # next higher / lower in CLAN_RANK_ORDER (excluding leader for promote target)
            order = [r for r in CLAN_RANK_ORDER if r != "leader"]
            try:
                ri = order.index(role) if role in order else order.index("member")
            except ValueError:
                ri = order.index("member")
            # promote = lower index in order list (officer is before veteran)
            if ri > 0:
                higher = order[ri - 1]
                buttons.append([InlineKeyboardButton(
                    text=f"Повысить → {clan_rank_info(higher)['name']}",
                    callback_data=f"clan_rank|{clan_id}|{member_id}|{higher}",
                    icon_custom_emoji_id=BTN_UP,
                )])
            if ri < len(order) - 1:
                lower = order[ri + 1]
                buttons.append([InlineKeyboardButton(
                    text=f"⬇️ Понизить → {clan_rank_info(lower)['name']}",
                    callback_data=f"clan_rank|{clan_id}|{member_id}|{lower}",
                )])

    if viewer_mem.get("role") == "leader" and viewer_id != member_id:
        buttons.append([InlineKeyboardButton(
            text="Передать лидерство", callback_data=f"clan_lead_ask|{clan_id}|{member_id}",
            icon_custom_emoji_id="5947121436723252849",
        )])
        buttons.append([InlineKeyboardButton(
            text="В чёрный список", callback_data=f"clan_bl_ask|{clan_id}|{member_id}",
            icon_custom_emoji_id="5352669272575321097",
        )])
    buttons.append([InlineKeyboardButton(text="К участникам", callback_data=f"clan_members|{clan_id}", icon_custom_emoji_id=BTN_MEMBERS)])
    buttons.append([InlineKeyboardButton(text="К клану", callback_data=f"clan_back|{clan_id}", icon_custom_emoji_id=BTN_CLAN)])
    await answer_func(text_msg, InlineKeyboardMarkup(inline_keyboard=buttons))



async def clan_create(user_id: int, name: str, tag: str, answer_func):
    await load_clans()
    user = await db.get_user(user_id)
    if user.get("clan_id"):
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Ты уже в клане.", None)
        return
    name = (name or "").strip()[:24]
    tag = re.sub(r"[^A-Za-zА-Яа-я0-9]", "", (tag or "").strip())[:5]
    if len(name) < 2 or len(tag) < 2:
        await answer_func("Формат: <code>клан создать Название Тег</code>", None)
        return
    for c in clans_data.values():
        if str(c.get("tag", "")).upper() == tag.upper():
            await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Такой тег уже занят.", None)
            return
    if not take_resources(user, CLAN_CREATE_COST):
        await answer_func(f"<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Нужно: {format_cost(CLAN_CREATE_COST)}", None)
        return
    clan = create_default_clan(name, tag, user_id)
    for other in remove_user_applications(user_id):
        await save_clan(other)
    clan_audit(clan, user_id, f"{clan_user_name(user_id)} создал клан [{clan['tag']}] {clan['name']}")
    user["clan_id"] = clan["id"]
    await db.save_user(user_id, user)
    await save_clan(clan)
    await answer_func(f"{PE_OK} Клан <b>[{html.escape(clan['tag'])}] {html.escape(clan['name'])}</b> создан!", None)


async def clan_deposit(user_id: int, resource_id: str, amount: int, answer_func):
    await load_clans()
    user = await db.get_user(user_id)
    clan = get_user_clan(user)
    if not clan:
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Ты не в клане.", None)
        return
    me = (clan.get("members") or {}).get(str(user_id)) or {}
    if not clan_has_perm(me, "deposit"):
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Новобранцы не могут вкладывать. Попроси повысить ранг.", None)
        return
    if resource_id not in CLAN_RESOURCE_IDS:
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Неизвестный ресурс.", None)
        return
    amount = max(1, int(amount))
    if get_resource_count(user, resource_id) < amount:
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Недостаточно ресурса.", None)
        return
    take_resources(user, {resource_id: amount})
    bank = clan.setdefault("bank", {})
    bank[resource_id] = int(bank.get(resource_id, 0) + amount)
    members = clan.setdefault("members", {})
    mem = _ensure_member_data(members.setdefault(str(user_id), {"role": "member", "joined_at": time.time()}))
    mem["contributions"][resource_id] = int(mem["contributions"].get(resource_id, 0) + amount)
    clan_audit(clan, user_id, f"{clan_user_name(user_id)} вложил в склад: {BOSS_RESOURCE_DEFS.get(resource_id, {}).get('name', resource_id)} ×{amount}")
    await db.save_user(user_id, user)
    await save_clan(clan)
    info = BOSS_RESOURCE_DEFS.get(resource_id, {})
    await answer_func(f"{PE_OK} В склад: {info.get('emoji','')} {info.get('name', resource_id)} ×{amount}", None)


def get_clan_level_up_view(clan: dict) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    """Экран прокачки: что нужно на следующий уровень и сколько есть на складе."""
    lvl = int(clan.get("level", 1))
    tag = html.escape(str(clan.get("tag", "")))
    back_row = [InlineKeyboardButton(text="К клану", callback_data=f"clan_back|{clan['id']}", icon_custom_emoji_id=BTN_CLAN)]
    header = f"{PE_LEVELUP} <b>Прокачка клана [{tag}]</b>\n\n"
    if lvl >= CLAN_MAX_LEVEL:
        return (
            header + f"<blockquote>Уровень: <b>{lvl}</b> / {CLAN_MAX_LEVEL}\n"
            f"Клан прокачан до максимума {PE_TROPHY}\n"
            f"Бонус: <b>+{get_clan_level_bonus(clan, 'damage'):.1f}%</b> урона и HP всем участникам</blockquote>",
            InlineKeyboardMarkup(inline_keyboard=[back_row]),
        )
    costs = CLAN_LEVEL_UP_COST.get(lvl + 1, {})
    bank = clan.get("bank") or {}
    lines = []
    ready = True
    for rid, need in costs.items():
        have = int(bank.get(rid, 0))
        info = BOSS_RESOURCE_DEFS.get(rid, {})
        ok = have >= need
        ready = ready and ok
        mark = PE_OK if ok else "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji>"
        lines.append(
            f"{mark} {info.get('emoji', '•')} {html.escape(str(info.get('name', rid)))}: "
            f"<b>{min(have, need)}/{need}</b>" + ("" if ok else f" · не хватает {need - have}")
        )
    next_bonus = max(0, lvl) * 0.5
    text = (
        header
        + f"<blockquote>Уровень: <b>{lvl}</b> → <b>{lvl + 1}</b> / {CLAN_MAX_LEVEL}\n"
        f"Бонус: <b>+{get_clan_level_bonus(clan, 'damage'):.1f}%</b> → <b>+{next_bonus:.1f}%</b> урона и HP</blockquote>\n\n"
        + f"<blockquote>{PE_BOX} <b>Нужно со склада</b>\n" + "\n".join(lines) + "</blockquote>\n\n"
        + ("<i>Всё собрано — лидер может вкачать уровень.</i>" if ready
           else "<i>Закидывайте ресурсы: <code>клан склад</code> — список названий.</i>")
    )
    rows = [
        [InlineKeyboardButton(text="Вкачать уровень", callback_data=f"clan_up_do|{clan['id']}", icon_custom_emoji_id=BTN_UP)],
        [InlineKeyboardButton(text="Обновить", callback_data=f"clan_up_view|{clan['id']}", icon_custom_emoji_id=BTN_REFRESH)],
        back_row,
    ]
    return text, InlineKeyboardMarkup(inline_keyboard=rows)


def _release_message_owner(msg):
    """Кнопки прокачки может жать любой участник (права проверяются в обработчике)."""
    try:
        if msg is not None:
            interactive_message_owners.pop((msg.chat.id, msg.message_id), None)
    except Exception:
        pass


