async def clan_level_up(user_id: int, answer_func):
    await load_clans()
    user = await db.get_user(user_id)
    clan = get_user_clan(user)
    if not clan:
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Ты не в клане.", None)
        return
    me = (clan.get("members") or {}).get(str(user_id)) or {}
    if me.get("role") != "leader":
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Вкачивать уровень клана может только лидер.", None)
        return
    lvl = int(clan.get("level", 1))
    if lvl >= CLAN_MAX_LEVEL:
        await answer_func("Максимальный уровень клана.", None)
        return
    costs = CLAN_LEVEL_UP_COST.get(lvl + 1, {})
    bank = clan.setdefault("bank", {})
    for rid, need in costs.items():
        if int(bank.get(rid, 0)) < need:
            await answer_func(f"<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> На складе нужно: {format_cost(costs)}", None)
            return
    for rid, need in costs.items():
        bank[rid] = int(bank.get(rid, 0) - need)
    clan["level"] = lvl + 1
    clan_audit(clan, user_id, f"{clan_user_name(user_id)} повысил уровень клана до {lvl + 1} (списано: {clan_plain_cost(costs)})")
    await save_clan(clan)
    await answer_func(
        f"{PE_LEVELUP} Клан: <b>{clan['level']}</b> ур. (+{get_clan_level_bonus(clan,'damage'):.1f}% урона/HP)",
        None,
    )


CLAN_BUFF_ICON_IDS = {
    "war_cry": "5373173798633752502",
    "iron_wall": "5287786962571241490",
    "nightmare_aura": "5287734091523829559",
    "swamp_blessing": "5197555094161234652",
}


def get_clan_active_buff_left(clan: dict, buff_id: str) -> int:
    return max(0, int(float((clan.get("active_buffs") or {}).get(buff_id, 0)) - time.time()))


def build_clan_buffs_view(clan: dict, me: dict) -> tuple[str, InlineKeyboardMarkup]:
    bank = clan.get("bank") or {}
    can_manage = clan_has_perm(me, "buff")
    active_lines, blocks, rows = [], [], []
    for bid, bdef in CLAN_BUFF_DEFS.items():
        left = get_clan_active_buff_left(clan, bid)
        icon = f'<tg-emoji emoji-id="{CLAN_BUFF_ICON_IDS[bid]}">{bdef.get("emoji", "✨")}</tg-emoji>' if bid in CLAN_BUFF_ICON_IDS else bdef.get("emoji", "✨")
        if left:
            active_lines.append(f"{icon} <b>{bdef['name']}</b> — ещё {format_clan_boss_time(left)}")
        cost_lines = []
        for rid, need in bdef["cost"].items():
            have = int(bank.get(rid, 0))
            info = BOSS_RESOURCE_DEFS.get(rid, {})
            mark = PE_OK if have >= need else PE_CROSS
            cost_lines.append(f"{mark} {info.get('emoji', '•')} {html.escape(str(info.get('name', rid)))}: <b>{min(have, need)}/{need}</b>")
        status = f"\nАктивен ещё <b>{format_clan_boss_time(left)}</b>" if left else ""
        blocks.append(
            f"<blockquote>{icon} <b>{bdef['name']}</b>\n{html.escape(bdef['description'])}\n"
            + "\n".join(cost_lines) + status + "</blockquote>"
        )
        rows.append([InlineKeyboardButton(
            text=(f"{bdef['name']} · активен" if left else f"Включить «{bdef['name']}»"),
            callback_data=f"clan_buff_on|{bid}",
            icon_custom_emoji_id=CLAN_BUFF_ICON_IDS.get(bid),
        )])
    active = "<blockquote><b>Сейчас действует</b>\n" + "\n".join(active_lines) + "</blockquote>" if active_lines \
        else "<blockquote>Сейчас баффов нет.</blockquote>"
    who = "Баффы оплачиваются со склада клана и действуют 6 часов на всех участников."
    if not can_manage:
        who += " Включать их могут офицеры и лидер."
    text = (
        f"{PE_SPARK} <b>Баффы клана [{html.escape(str(clan.get('tag', '')))}]</b>\n\n"
        f"{active}\n\n<i>{who}</i>\n\n" + "\n\n".join(blocks)
    )
    rows.append([InlineKeyboardButton(text="К клану", callback_data=f"clan_back|{clan['id']}", icon_custom_emoji_id=BTN_CLAN)])
    return text, InlineKeyboardMarkup(inline_keyboard=rows)


async def show_clan_buffs(user_id: int, answer_func):
    await load_clans()
    user = await db.get_user(user_id)
    clan = get_user_clan(user) if user else None
    if not clan:
        await answer_func(premium_cross("❌ Ты не в клане."), None)
