@dp.callback_query(F.data.startswith("clan_buff_on|"))
async def cb_clan_buff_on(call: CallbackQuery):
    buff_id = call.data.split("|", 1)[1]
    uid = call.from_user.id
    await load_clans()
    user = await db.get_user(uid)
    clan = get_user_clan(user) if user else None
    if not clan:
        await call.answer("Ты не в клане.", show_alert=True)
        return
    me = (clan.get("members") or {}).get(str(uid)) or {}
    bdef = CLAN_BUFF_DEFS.get(buff_id)
    if not bdef:
        await call.answer("Бафф не найден.", show_alert=True)
        return
    if not clan_has_perm(me, "buff"):
        await call.answer("Включать баффы могут только офицеры и лидер.", show_alert=True)
        return
    left = get_clan_active_buff_left(clan, buff_id)
    if left:
        await call.answer(f"«{bdef['name']}» уже действует, осталось {format_clan_boss_time(left)}.", show_alert=True)
        return
    bank = clan.setdefault("bank", {})
    missing = [
        f"{BOSS_RESOURCE_DEFS.get(rid, {}).get('name', rid)} ×{need - int(bank.get(rid, 0))}"
        for rid, need in bdef["cost"].items() if int(bank.get(rid, 0)) < need
    ]
    if missing:
        await call.answer("Не хватает на складе: " + ", ".join(missing), show_alert=True)
        return
    for rid, need in bdef["cost"].items():
        bank[rid] = int(bank.get(rid, 0)) - need
    clan.setdefault("active_buffs", {})[buff_id] = time.time() + bdef["duration"]
    clan_audit(clan, uid, f"{clan_user_name(uid)} активировал бафф «{bdef['name']}»")
    await save_clan(clan)
    await call.answer(f"«{bdef['name']}» включён на 6 часов!", show_alert=True)
    text, kb = build_clan_buffs_view(clan, me)
    sent = await edit_for_user(call, text, kb)
    _release_message_owner(sent)


CLAN_ANNOUNCE_COOLDOWN = 5 * 60
CLAN_ANNOUNCE_MAX_LEN = 1000


async def clan_announce(message: Message, raw: str):
    """«клан сообщение текст» — разослать сообщение всем участникам клана в ЛС."""
    uid = message.from_user.id
    await load_clans()
    await db.load()
    user = await db.get_user(uid)
    clan = get_user_clan(user) if user else None
    if not clan:
        await reply_to_user(message, "Ты не в клане.")
        return
    me = (clan.get("members") or {}).get(str(uid)) or {}
    if not clan_has_perm(me, "announce"):
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Писать сообщение клану могут только офицеры и лидер.")
        return
    body = re.sub(r"^\s*\S+\s+\S+", "", raw, count=1).strip()
    if not body:
        await reply_to_user(
            message,
            f"{CLAN_PREMIUM_EMOJI} <b>Сообщение клану</b>\n\n"
            f"<blockquote>Напиши <code>клан сообщение текст</code> — его получат в ЛС все участники.\n"
            f"До {CLAN_ANNOUNCE_MAX_LEN} символов, не чаще раза в {CLAN_ANNOUNCE_COOLDOWN // 60} мин.</blockquote>",
        )
        return
    if len(body) > CLAN_ANNOUNCE_MAX_LEN:
        await reply_to_user(message, f"<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Слишком длинно: {len(body)}/{CLAN_ANNOUNCE_MAX_LEN} символов.")
        return
    left = int(float(clan.get("last_announce_at", 0)) + CLAN_ANNOUNCE_COOLDOWN - time.time())
    if left > 0 and not is_admin_user(uid):
        await reply_to_user(message, f"{PE_SCROLL} Следующее сообщение клану можно отправить через {format_clan_boss_time(left)}.")
        return

    # Сначала — предпросмотр и подтверждение, чтобы не отправить случайно
    token = f"{uid}_{int(time.time() * 1000) % 10**9}"
    pending_clan_announces[token] = {"uid": uid, "clan_id": clan["id"], "body": body, "created": time.time()}
    for key, pend in list(pending_clan_announces.items()):
        if time.time() - pend.get("created", 0) > CLAN_ANNOUNCE_CONFIRM_TTL:
            pending_clan_announces.pop(key, None)
    recipients = max(0, get_clan_member_count(clan) - 1)
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text=f"Отправить ({recipients})", callback_data=f"clan_ann_ok|{token}", icon_custom_emoji_id=BTN_OK)],
        [InlineKeyboardButton(text="Отмена", callback_data=f"clan_ann_no|{token}", icon_custom_emoji_id="5352669272575321097")],
    ])
    await reply_to_user(
        message,
        f"{PE_SCROLL} <b>Проверь сообщение перед отправкой</b>\n"
        f"Его получат <b>{recipients}</b> участников клана в ЛС:\n\n"
        + build_clan_announce_text(clan, user, me, body),
        kb,
    )


pending_clan_announces: Dict[str, dict] = {}
CLAN_ANNOUNCE_CONFIRM_TTL = 10 * 60


def build_clan_announce_text(clan: dict, user: dict, me: dict, body: str) -> str:
    sender = render_user_nickname(user, "?")
    tag = html.escape(str(clan.get("tag", "")))
    return (
        f"<blockquote>{CLAN_PREMIUM_EMOJI} <b>Сообщение клана [{tag}]</b>\n"
        f"от {format_clan_rank(me.get('role', 'member'))} <b>{sender}</b></blockquote>\n\n"
        f"<blockquote>{html.escape(body)}</blockquote>"
    )


@dp.callback_query(F.data.startswith("clan_ann_no|"))
async def cb_clan_announce_cancel(call: CallbackQuery):
    token = call.data.split("|", 1)[1]
    pend = pending_clan_announces.get(token)
    if pend and pend["uid"] != call.from_user.id:
        await call.answer("Это не твоё сообщение.", show_alert=True)
        return
    pending_clan_announces.pop(token, None)
    await call.answer("Отменено")
    await edit_for_user(call, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Сообщение клану отменено.", None)


@dp.callback_query(F.data.startswith("clan_ann_ok|"))
async def cb_clan_announce_send(call: CallbackQuery):
    token = call.data.split("|", 1)[1]
    pend = pending_clan_announces.get(token)
    if not pend or time.time() - pend.get("created", 0) > CLAN_ANNOUNCE_CONFIRM_TTL:
        pending_clan_announces.pop(token, None)
        await call.answer("Подтверждение устарело. Напиши команду заново.", show_alert=True)
        return
    if pend["uid"] != call.from_user.id:
        await call.answer("Это не твоё сообщение.", show_alert=True)
        return
    uid = call.from_user.id
    await load_clans()
    user = await db.get_user(uid)
    clan = get_user_clan(user) if user else None
    if not clan or clan["id"] != pend["clan_id"]:
        pending_clan_announces.pop(token, None)
        await call.answer("Ты больше не в этом клане.", show_alert=True)
        return
    me = (clan.get("members") or {}).get(str(uid)) or {}
    if not clan_has_perm(me, "announce"):
        pending_clan_announces.pop(token, None)
        await call.answer("Писать клану могут только офицеры и лидер.", show_alert=True)
        return
    left = int(float(clan.get("last_announce_at", 0)) + CLAN_ANNOUNCE_COOLDOWN - time.time())
    if left > 0 and not is_admin_user(uid):
        await call.answer(f"Следующее сообщение можно через {format_clan_boss_time(left)}.", show_alert=True)
        return
    pending_clan_announces.pop(token, None)
    clan["last_announce_at"] = time.time()
    await call.answer("Отправляю…")
    body = pend["body"]
    text = build_clan_announce_text(clan, user, me, body)
    kb = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="К клану", callback_data=f"clan_back|{clan['id']}", icon_custom_emoji_id=BTN_CLAN),
    ]])
    delivered = failed = 0
    for member_id in list((clan.get("members") or {}).keys()):
        if member_id == str(uid):
            continue
        ok = await send_user_notification(int(member_id), text, reply_markup=kb)
        if ok:
            delivered += 1
        else:
            failed += 1
        await asyncio.sleep(0.05)
    clan_audit(clan, uid, f"{clan_user_name(uid)} отправил сообщение клану: {body[:120]}")
    await save_clan(clan)
    fail_text = f"\nНе доставлено: <b>{failed}</b> (закрыли ЛС с ботом)" if failed else ""
    await edit_for_user(call, f"{PE_OK} Сообщение отправлено: <b>{delivered}</b> участникам.{fail_text}\n\n" + text, None)


async def show_clan_top(user_id: int, answer_func, by: str = "level"):
    await load_clans()
    await db.load()
    rows = []
    for clan in clans_data.values():
        if by == "power":
            val = calculate_clan_power(clan)
            label = f"{val} силы"
        else:
            val = int(clan.get("level", 1))
            label = f"{val} ур."
        rows.append((val, clan, label))
    rows.sort(key=lambda x: x[0], reverse=True)
    lines = []
    for i, (val, clan, label) in enumerate(rows[:15], 1):
        num = int(clan.get("number") or 0)
        num_s = f"#{num}" if num else ""
        lines.append(
            f"{i}. {num_s} <b>[{html.escape(str(clan.get('tag','')))}] {html.escape(str(clan.get('name','')))}</b> — {label}"
            f" · {get_clan_member_count(clan)} чел."
        )
    title = ('<tg-emoji emoji-id="5359778044745622115">🏛</tg-emoji> <b>Топ кланов по силе</b>' if by == "power" else '<tg-emoji emoji-id="5359778044745622115">🏛</tg-emoji> <b>Топ кланов по уровню</b>')
    if not lines:
        await answer_func(f"{title}\n\nПока нет кланов.", None)
        return
    await answer_func(title + "\n\n<blockquote>" + "\n".join(lines) + "</blockquote>", None)


@dp.message(Command("clan", "клан"))
async def cmd_clan(message: Message):
    await show_clan(message.from_user.id, lambda t, kb: reply_to_user(message, t, kb))


@dp.message(lambda msg: msg.text and message_command(msg) in ("клан", "clan"))
async def text_clan_root(message: Message):
    raw = (message.text or "").strip()
    parts = raw.split()
    if len(parts) == 1:
        await show_clan(message.from_user.id, lambda t, kb: reply_to_user(message, t, kb))
        return
    cmd = parts[1].lower()
    uid = message.from_user.id
    reply = lambda t, kb: reply_to_user(message, t, kb)

    if cmd in ("создать", "create") and len(parts) >= 4:
        await clan_create(uid, " ".join(parts[2:-1]), parts[-1], reply)
        return
    if cmd in ("склад", "deposit", "вложить"):
        user_for_help = await db.get_user(uid)
        help_text = (
            f"{PE_BOX} <b>Ресурсы для склада клана</b>\n\n"
            "<blockquote>" + "\n".join(clan_resources_help_lines(user_for_help)) + "</blockquote>\n\n"
            "Можно писать и полное название: <code>клан склад морозный кристалл 10</code>\n"
            "Вложить всё, что есть: <code>клан склад морозный все</code>"
        )
        if len(parts) < 4:
            await reply_to_user(message, help_text)
            return
        amount_token = parts[-1].lower()
        rid = resolve_clan_resource(" ".join(parts[2:-1]))
        if amount_token in ("все", "всё", "all"):
            amount = get_resource_count(user_for_help, rid) if rid else 0
            if rid and amount <= 0:
                await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> У тебя нет этого ресурса.")
                return
        else:
            try:
                amount = int(amount_token)
            except ValueError:
                amount = 0
        if not rid or amount <= 0:
            await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Не понял ресурс или количество.\n\n" + help_text)
            return
        await clan_deposit(uid, rid, amount, reply)
        return
    if cmd in ("ап", "up", "прокачка", "level", "уровень"):
        await show_clan_level_up(uid, reply)
        return
    if cmd in ("бафф", "баффы", "buff", "buffs", "баф"):
        await show_clan_buffs(uid, reply)
        return
    if cmd in ("выйти", "leave"):
        await load_clans()
        user = await db.get_user(uid)
        clan = get_user_clan(user)
        if not clan:
            await reply_to_user(message, "Ты не в клане.")
            return
        members = clan.setdefault("members", {})
        if str(uid) == str(clan.get("leader_id")) and len(members) > 1:
            await reply_to_user(message, "Лидер не может выйти, пока есть участники. Сначала передай лидерство: карточка участника → «Передать лидерство».")
            return
        members.pop(str(uid), None)
        user["clan_id"] = None
        clan_audit(clan, uid, f"{clan_user_name(uid)} покинул клан")
        await db.save_user(uid, user)
        if not members:
            clans_data.pop(clan["id"], None)
            try:
                await delete_clan(clan["id"])
            except Exception:
                pass
        else:
            await save_clan(clan)
        await reply_to_user(message, "Ты покинул клан.")
        return
    if cmd in ("описание", "desc", "description", "био"):
        await load_clans()
        user = await db.get_user(uid)
        clan = get_user_clan(user)
        if not clan:
            await reply_to_user(message, "Ты не в клане.")
            return
        me = (clan.get("members") or {}).get(str(uid)) or {}
        # Текст после «клан описание», с сохранением переносов строк
        body = re.sub(r"^\s*\S+\s+\S+", "", raw, count=1).strip()
        if not body:
            current = str(clan.get("description") or "").strip()
            cur_text = f"<blockquote>{html.escape(current)}</blockquote>" if current else "<i>Описание не задано.</i>"
            await reply_to_user(
                message,
                f"{CLAN_PREMIUM_EMOJI} <b>Описание клана</b>\n\n{cur_text}\n\n"
                f"Изменить: <code>клан описание текст</code> (до {CLAN_DESCRIPTION_MAX_LEN} символов)\n"
                "Удалить: <code>клан описание удалить</code>\n"
                "Доступно офицерам и лидеру.",
            )
            return
        if not clan_has_perm(me, "edit_desc"):
            await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Менять описание могут только офицеры и лидер.")
            return
        if body.lower() in ("удалить", "очистить", "-", "delete", "clear"):
            clan["description"] = ""
            clan_audit(clan, uid, f"{clan_user_name(uid)} удалил описание клана")
            await save_clan(clan)
            await reply_to_user(message, f"{PE_OK} Описание клана удалено.")
            return
        # Убираем лишние пустые строки и ограничиваем длину
        body = re.sub(r"\n{3,}", "\n\n", body)
        if len(body) > CLAN_DESCRIPTION_MAX_LEN:
            await reply_to_user(message, f"<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Слишком длинно: {len(body)}/{CLAN_DESCRIPTION_MAX_LEN} символов.")
            return
        clan["description"] = body
        clan_audit(clan, uid, f"{clan_user_name(uid)} изменил описание клана")
        await save_clan(clan)
        await reply_to_user(
            message,
            f"{PE_OK} Описание обновлено:\n<blockquote>{html.escape(body)}</blockquote>",
        )
        return
    if cmd in ("сообщение", "сообщ", "объявление", "рассылка", "msg", "announce"):
        await clan_announce(message, raw)
        return
    if cmd in ("босс", "boss", "рб"):
        await show_clan_boss(uid, reply)
        return
    if cmd in ("журнал", "аудит", "audit", "log", "логи"):
        await show_clan_audit(uid, 0, reply)
        return
    if cmd in ("пригласить", "invite"):
        await load_clans()
        user = await db.get_user(uid)
        clan = get_user_clan(user)
        if not clan:
            await reply_to_user(message, "Ты не в клане.")
            return
        me = (clan.get("members") or {}).get(str(uid)) or {}
        if not clan_has_perm(me, "invite"):
            await reply_to_user(message, "Недостаточно прав для приглашений.")
            return
        if get_clan_member_count(clan) >= CLAN_MAX_MEMBERS:
            await reply_to_user(message, "Клан полон.")
            return
        replied = message.reply_to_message
        if not replied or not replied.from_user:
            await reply_to_user(message, "Реплай на сообщение игрока.")
            return
        tid = replied.from_user.id
        if tid == uid:
            await reply_to_user(message, "Нельзя пригласить себя.")
            return
        target = await db.get_user(tid)
        if not target:
            await reply_to_user(message, "Игрок ещё не в боте.")
            return
        if target.get("clan_id"):
            await reply_to_user(message, "Игрок уже в клане.")
            return
        if is_clan_blacklisted(clan, tid):
            await reply_to_user(message, premium_cross("❌ Этот игрок в чёрном списке клана. Лидер может убрать его через «Чёрный список»."))
            return
        # Уже есть исходящий инвайт?
        for inv in list(pending_clan_invites.values()):
            if inv.get("to_id") == tid and inv.get("clan_id") == clan["id"]:
                await reply_to_user(message, "Этому игроку уже отправлено приглашение в ваш клан.")
                return
        invite_id = f"inv_{uid}_{tid}_{int(time.time())}"
        pending_clan_invites[invite_id] = {
            "clan_id": clan["id"],
            "from_id": uid,
            "to_id": tid,
            "created_at": time.time(),
        }
        clan_emoji = CLAN_PREMIUM_EMOJI
        inviter_name = render_user_nickname(user, str(uid))
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [
                InlineKeyboardButton(text="Принять", callback_data=f"clan_inv_ok|{invite_id}", icon_custom_emoji_id=BTN_OK),
                InlineKeyboardButton(text="Отказаться", callback_data=f"clan_inv_no|{invite_id}", icon_custom_emoji_id="5352669272575321097"),
            ]
        ])
        inv_desc = str(clan.get("description") or "").strip()
        inv_desc_block = f"\n\n<blockquote expandable>{html.escape(inv_desc)}</blockquote>" if inv_desc else ""
        sent = await send_user_notification(
            tid,
            f"{clan_emoji} <b>Приглашение в клан</b>\n\n"
            f"{inviter_name} приглашает тебя в\n"
            f"<b>[{html.escape(str(clan.get('tag','')))}] {html.escape(str(clan.get('name','')))}</b>\n"
            f"Номер: <b>#{int(clan.get('number') or 0)}</b>\n\n"
            f"Уровень клана: <b>{clan.get('level', 1)}</b> · Участников: <b>{get_clan_member_count(clan)}</b>"
            f"{inv_desc_block}",
            reply_markup=kb,
        )
        if sent:
            clan_audit(clan, uid, f"{clan_user_name(uid)} пригласил {clan_user_name(tid)}")
            await save_clan(clan)
            await reply_to_user(message, f"{PE_OK} Приглашение отправлено игроку в ЛС.")
        else:
            pending_clan_invites.pop(invite_id, None)
            await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Не удалось написать игроку в ЛС (закрыл бота?).")
        return
    if cmd in ("кик", "kick"):
        await load_clans()
        user = await db.get_user(uid)
        clan = get_user_clan(user)
        if not clan:
            await reply_to_user(message, "Ты не в клане.")
            return
        me = (clan.get("members") or {}).get(str(uid)) or {}
        if not clan_has_perm(me, "kick"):
            await reply_to_user(message, "Недостаточно прав для кика.")
            return
        replied = message.reply_to_message
        if not replied or not replied.from_user:
            await reply_to_user(message, "Реплай на игрока.")
            return
        tid = replied.from_user.id
        if tid == clan.get("leader_id") or tid == uid:
            await reply_to_user(message, "Нельзя кикнуть лидера / себя.")
            return
        target_mem = (clan.get("members") or {}).get(str(tid)) or {}
        # Офицер не может кикать тех, кто не ниже него / не в зоне управления
        my_role = me.get("role", "member")
        t_role = target_mem.get("role", "member")
        if my_role != "leader":
            if t_role not in CLAN_OFFICER_MANAGEABLE:
                await reply_to_user(message, "Офицер может кикать только ветеранов, участников и новобранцев.")
                return
            if clan_rank_order(t_role) >= clan_rank_order(my_role):
                await reply_to_user(message, "Нельзя кикнуть игрока с равным или высшим рангом.")
                return
        clan.setdefault("members", {}).pop(str(tid), None)
        clan_audit(clan, uid, f"{clan_user_name(uid)} исключил {clan_user_name(tid)} ({clan_rank_info(t_role)['name']})")
        target = await db.get_user(tid)
        if target:
            target["clan_id"] = None
            await db.save_user(tid, target)
        await save_clan(clan)
        await reply_to_user(message, "Игрок исключён.")
        return
    await show_clan(uid, reply)


