@dp.callback_query(F.data.startswith("clan_inv_ok|"))
async def cb_clan_inv_accept(call: CallbackQuery):
    # call.answer() вызывается ровно один раз в каждой ветке — повторный ответ
    # на тот же callback падает с ошибкой и обрывал обработчик.
    invite_id = call.data.split("|", 1)[1]
    inv = pending_clan_invites.pop(invite_id, None)
    if not inv:
        await call.answer("Приглашение устарело или уже использовано.", show_alert=True)
        try:
            await call.message.edit_text("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Приглашение больше недействительно.", parse_mode="HTML")
        except Exception:
            pass
        return
    if call.from_user.id != inv.get("to_id"):
        await call.answer("Это приглашение не для тебя.", show_alert=True)
        pending_clan_invites[invite_id] = inv
        return
    await call.answer()
    await load_clans()
    await db.load()
    clan = get_clan(inv.get("clan_id"))
    user = await db.get_user(call.from_user.id)
    if not clan:
        try:
            await call.message.edit_text("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Клан больше не существует.", parse_mode="HTML")
        except Exception:
            pass
        return
    if user.get("clan_id"):
        try:
            await call.message.edit_text("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Ты уже состоишь в клане.", parse_mode="HTML")
        except Exception:
            pass
        return
    if get_clan_member_count(clan) >= CLAN_MAX_MEMBERS:
        try:
            await call.message.edit_text("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Клан уже полон.", parse_mode="HTML")
        except Exception:
            pass
        return
    if is_clan_blacklisted(clan, call.from_user.id):
        try:
            await call.message.edit_text("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Ты в чёрном списке этого клана.", parse_mode="HTML")
        except Exception:
            pass
        return
    for other in remove_user_applications(call.from_user.id, except_clan_id=clan["id"]):
        await save_clan(other)
    (clan.get("applications") or {}).pop(str(call.from_user.id), None)
    clan.setdefault("members", {})[str(call.from_user.id)] = {
        "role": "recruit",
        "joined_at": time.time(),
        "contributions": {rid: 0 for rid in CLAN_RESOURCE_IDS},
    }
    user["clan_id"] = clan["id"]
    clan_audit(
        clan, call.from_user.id,
        f"{clan_user_name(call.from_user.id)} вступил в клан (пригласил {clan_user_name(inv.get('from_id'))})",
    )
    await db.save_user(call.from_user.id, user)
    await save_clan(clan)
    clan_emoji = CLAN_PREMIUM_EMOJI
    try:
        # parse_mode обязателен: без него Telegram показывает сырые <tg-emoji> теги
        await call.message.edit_text(
            f"{clan_emoji} {PE_OK} Ты вступил в <b>[{html.escape(str(clan.get('tag','')))}] "
            f"{html.escape(str(clan.get('name','')))}</b>\n"
            f"Ранг: {format_clan_rank('recruit')}",
            parse_mode="HTML",
        )
    except Exception as e:
        print(f"[clan_inv_ok] edit failed: {e}")
    # уведомить пригласившего
    try:
        await send_user_notification(
            inv["from_id"],
            f"{clan_emoji} <b>{render_user_nickname(user, str(call.from_user.id))}</b> "
            f"принял приглашение в клан [{html.escape(str(clan.get('tag','')))}].",
            reply_markup=nav_kb(NAV_CLAN),
        )
    except Exception:
        pass


@dp.callback_query(F.data.startswith("clan_inv_no|"))
async def cb_clan_inv_decline(call: CallbackQuery):
    invite_id = call.data.split("|", 1)[1]
    inv = pending_clan_invites.pop(invite_id, None)
    if not inv:
        await call.answer()
        try:
            await call.message.edit_text("Приглашение уже закрыто.", parse_mode="HTML")
        except Exception:
            pass
        return
    if call.from_user.id != inv.get("to_id"):
        pending_clan_invites[invite_id] = inv
        await call.answer("Это не твоё приглашение.", show_alert=True)
        return
    await call.answer()
    try:
        await call.message.edit_text("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Ты отклонил приглашение в клан.", parse_mode="HTML")
    except Exception:
        pass
    await load_clans()
    declined_clan = get_clan(inv.get("clan_id"))
    if declined_clan:
        clan_audit(declined_clan, call.from_user.id, f"{clan_user_name(call.from_user.id)} отклонил приглашение")
        await save_clan(declined_clan)
    try:
        await send_user_notification(inv["from_id"], f"<blockquote>{PE_CROSS} Игрок отклонил приглашение в клан.</blockquote>", reply_markup=nav_kb(NAV_CLAN))
    except Exception:
        pass


@dp.callback_query(F.data.startswith("clan_rank|"))
async def cb_clan_rank(call: CallbackQuery):
    await call.answer()
    parts = call.data.split("|")
    if len(parts) < 4:
        return
    _, clan_id, mid_s, new_role = parts[0], parts[1], parts[2], parts[3]
    try:
        member_id = int(mid_s)
    except ValueError:
        return
    if new_role not in CLAN_RANKS or new_role == "leader":
        await call.answer("Нельзя назначить этот ранг.", show_alert=True)
        return
    await load_clans()
    await db.load()
    clan = get_clan(clan_id)
    if not clan:
        await call.answer("Клан не найден", show_alert=True)
        return
    members = clan.get("members") or {}
    viewer = members.get(str(call.from_user.id)) or {}
    target = members.get(str(member_id))
    if not target:
        await call.answer("Игрок не в клане", show_alert=True)
        return
    if not clan_has_perm(viewer, "promote") and not clan_has_perm(viewer, "demote"):
        await call.answer("Недостаточно прав", show_alert=True)
        return
    old_role = target.get("role", "member")
    if old_role == "leader":
        await call.answer("Нельзя менять ранг лидера", show_alert=True)
        return
    v_role = viewer.get("role", "member")
    if v_role != "leader":
        if old_role not in CLAN_OFFICER_MANAGEABLE or new_role not in CLAN_OFFICER_MANAGEABLE:
            await call.answer("Офицер может менять только ветеранов/участников/новобранцев", show_alert=True)
            return
    target["role"] = new_role
    members[str(member_id)] = target
    if old_role != new_role:
        verb = "повысил" if clan_rank_order(new_role) > clan_rank_order(old_role) else "понизил"
        clan_audit(
            clan, call.from_user.id,
            f"{clan_user_name(call.from_user.id)} {verb} {clan_user_name(member_id)}: "
            f"{clan_rank_info(old_role)['name']} → {clan_rank_info(new_role)['name']}",
        )
    await save_clan(clan)
    await show_clan_member_info(
        call.from_user.id,
        clan_id,
        member_id,
        lambda t, kb: edit_for_user(call, t, kb),
        call=call,
    )

