@dp.callback_query(F.data.startswith("clan_up_do|"))
async def cb_clan_up_do(call: CallbackQuery):
    clan_id = call.data.split("|", 1)[1]
    await load_clans()
    clan = get_clan(clan_id)
    if not clan:
        await call.answer("Клан не найден.", show_alert=True)
        return
    me = (clan.get("members") or {}).get(str(call.from_user.id)) or {}
    if me.get("role") != "leader":
        await call.answer("Вкачать уровень может только лидер клана.", show_alert=True)
        return
    lvl = int(clan.get("level", 1))
    if lvl >= CLAN_MAX_LEVEL:
        await call.answer("Клан уже максимального уровня.", show_alert=True)
        return
    costs = CLAN_LEVEL_UP_COST.get(lvl + 1, {})
    bank = clan.get("bank") or {}
    missing = [
        f"{BOSS_RESOURCE_DEFS.get(rid, {}).get('name', rid)} ×{need - int(bank.get(rid, 0))}"
        for rid, need in costs.items() if int(bank.get(rid, 0)) < need
    ]
    if missing:
        await call.answer("Не хватает на складе: " + ", ".join(missing), show_alert=True)
        return
    results = []
    await clan_level_up(call.from_user.id, lambda t, kb: results.append(t) or asyncio.sleep(0))
    await call.answer(f"Клан прокачан до {clan.get('level')} уровня!", show_alert=True)
    text, kb = get_clan_level_up_view(clan)
    sent = await edit_for_user(call, text, kb)
    _release_message_owner(sent)


