# ============================================================
# === Журнал аудита клана (UI) ===
# ============================================================

async def show_clan_audit(user_id: int, page: int, answer_func, call: Optional[CallbackQuery] = None):
    await load_clans()
    await db.load()
    user = await db.get_user(user_id)
    clan = get_user_clan(user) if user else None
    if not clan:
        if call:
            await call.answer("Ты не в клане.", show_alert=True)
        else:
            await answer_func("Ты не в клане.", None)
        return
    me = (clan.get("members") or {}).get(str(user_id)) or {}
    if not clan_has_perm(me, "audit"):
        msg = f"{PE_SCROLL} Журнал аудита доступен с ранга Офицер."
        if call:
            await call.answer(msg, show_alert=True)
        else:
            await answer_func(msg, None)
        return

    entries = list(reversed(clan.get("audit_log") or []))
    total_pages = max(1, math.ceil(len(entries) / CLAN_AUDIT_PAGE_SIZE))
    page = max(0, min(int(page), total_pages - 1))
    chunk = entries[page * CLAN_AUDIT_PAGE_SIZE:(page + 1) * CLAN_AUDIT_PAGE_SIZE]

    header = (
        f"{PE_SCROLL} <b>Журнал аудита [{html.escape(str(clan.get('tag', '')))}]</b>\n\n"
    )
    if not chunk:
        body = "<blockquote>Записей пока нет.</blockquote>"
    else:
        lines = []
        for entry in chunk:
            ts = format_clan_date(entry.get("ts", 0))
            lines.append(f"<code>{ts}</code>\n{html.escape(str(entry.get('text', '')))}")
        body = "<blockquote>" + "\n\n".join(lines) + "</blockquote>"
    footer = f"\n\nСтраница <b>{page + 1}</b> / {total_pages} · всего записей: <b>{len(entries)}</b>"

    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="◀️", callback_data=f"clan_audit|{page - 1}"))
    nav.append(InlineKeyboardButton(text="Обновить", callback_data=f"clan_audit|{page}", icon_custom_emoji_id=BTN_REFRESH))
    if page < total_pages - 1:
        nav.append(InlineKeyboardButton(text="▶️", callback_data=f"clan_audit|{page + 1}"))
    buttons = [nav, [InlineKeyboardButton(text="К клану", callback_data=f"clan_back|{clan.get('id')}", icon_custom_emoji_id=BTN_CLAN)]]
    await answer_func(header + body + footer, InlineKeyboardMarkup(inline_keyboard=buttons))


@dp.callback_query(F.data.startswith("clan_audit|"))
async def cb_clan_audit(call: CallbackQuery):
    try:
        page = int(call.data.split("|", 1)[1])
    except (ValueError, IndexError):
        page = 0
    await load_clans()
    user = await db.get_user(call.from_user.id)
    clan = get_user_clan(user) if user else None
    me = ((clan or {}).get("members") or {}).get(str(call.from_user.id)) or {}
    if not clan or not clan_has_perm(me, "audit"):
        await call.answer("📃 Журнал аудита доступен с ранга Офицер.", show_alert=True)
        return
    await call.answer()
    await show_clan_audit(call.from_user.id, page, lambda t, kb: edit_for_user(call, t, kb))


# ============================================================
# === Клановый босс: Лутиафан ===
# Мультиплеерный босс: один общий запас HP на весь клан, бьют все
# участники одновременно. Появляется раз в сутки (сброс в 12:00 МСК).
# ============================================================

CLAN_BOSS_NAME = "Лутиафан"
CLAN_BOSS_TITLE = "Лутиафан, Пожиратель Сокровищ"
CLAN_BOSS_EMOJI = '<tg-emoji emoji-id="5258112758645282249">🐲</tg-emoji>'  # только для текста, в кнопках — icon_custom_emoji_id

CLAN_BOSS_HITS_PER_MEMBER = 200     # столько «средних» ударов на участника закладывается в HP (было 25)
CLAN_BOSS_MIN_HP = 80_000           # минимальное HP даже для слабого/маленького клана (было 10 000)
CLAN_BOSS_MIN_MEMBERS_FOR_HP = 3    # HP считается минимум как для 3 участников
CLAN_BOSS_TIER_HP_STEP = 0.20       # +20% HP за каждый тир
CLAN_BOSS_MAX_TIER = 50
# Лимита ударов нет. Опыт мастерства пути даётся только за первые N ударов в сутки,
# чтобы босс с огромным HP не превращался в бесконечную ферму XP пути.
CLAN_BOSS_PATH_XP_HITS = 100
CLAN_BOSS_HIT_COOLDOWN = 1.0        # анти-спам между ударами, сек (лишние нажатия молча пропускаются)
CLAN_BOSS_XP_LEVEL_SHARE = 0.20  # доля опыта текущего уровня за победу (до множителей вклада и тира)
CLAN_BOSS_KO_SECONDS = 3 * 60       # восстановление после нокаута
CLAN_BOSS_RECENT_LOG = 6
CLAN_BOSS_SAVE_INTERVAL = 3.0

# Урон босса считается в % от макс. HP игрока — одинаково честно для всех уровней.
CLAN_BOSS_HIT_PCT = (0.03, 0.05)        # обычный удар (было 6–10%)
CLAN_BOSS_SPECIAL_PCT = (0.07, 0.10)    # каждый 5-й ход — «Жадный укус» (было 15–20%)
CLAN_BOSS_SPECIAL_EVERY = 5
CLAN_BOSS_MAX_HIT_PCT = 0.12            # один удар никогда не снимает больше 12% HP (было 25%)
CLAN_BOSS_TIER_DMG_STEP = 0.04          # +4% урона босса за тир
CLAN_BOSS_TIER_DMG_MAX = 1.6

CLAN_BOSS_PLAYER_RESOURCES = ("swamp_crystal", "ember_stone", "frost_crystal")
CLAN_BOSS_PLAYER_RES_CHANCE = 0.5   # шанс, что участнику вообще выпадет ресурс
CLAN_BOSS_TOP_EYE_CHANCE = 0.3      # шанс «Высохшего глаза» для топа урона

_clan_boss_locks: Dict[str, asyncio.Lock] = {}
_clan_boss_last_save: Dict[str, float] = {}
_clan_boss_user_last_save: Dict[int, float] = {}


def _clan_boss_lock(clan_id: str) -> asyncio.Lock:
    lock = _clan_boss_locks.get(clan_id)
    if lock is None:
        lock = asyncio.Lock()
        _clan_boss_locks[clan_id] = lock
    return lock


CLAN_BOSS_SPAWN_HOUR_MSK = 12  # Лутиафан появляется в 12:00 МСК (раньше было 00:00)


def get_clan_boss_day_key() -> str:
    """«Сутки» Лутиафана начинаются в 12:00 МСК."""
    return (get_msk_now() - timedelta(hours=CLAN_BOSS_SPAWN_HOUR_MSK)).strftime("%Y-%m-%d")


def get_clan_boss_reset_left() -> int:
    now = get_msk_now()
    nxt = now.replace(hour=CLAN_BOSS_SPAWN_HOUR_MSK, minute=0, second=0, microsecond=0)
    if nxt <= now:
        nxt += timedelta(days=1)
    return max(0, int((nxt - now).total_seconds()))


def format_clan_boss_time(seconds: int) -> str:
    seconds = max(0, int(seconds))
    h, rem = divmod(seconds, 3600)
    m, s = divmod(rem, 60)
    if h:
        return f"{h}ч {m}м"
    if m:
        return f"{m}м {s}с"
    return f"{s}с"


def estimate_clan_boss_member_damage(user: Optional[dict]) -> float:
    """Средний урон одного удара игрока (с учётом промахов и критов)."""
    if not user:
        return 0.0
    ctx = dict(user)
    ctx["battle_effects"] = {}
    level = int(user.get("level", 1) or 1)
    equipped = user.get("equipped")
    if equipped:
        lo, hi = scale_weapon_damage(equipped.get("dmg", (1, 2)), level)
    else:
        lo, hi = 1 + level // 3, 3 + level // 2
    avg = (int(lo) + int(hi)) / 2 * get_damage_multiplier(ctx)
    hit_rate = 1 - get_miss_chance(ctx) / 100
    crit_mult = 1 + get_crit_chance(ctx) / 100 * get_crit_damage_percent(ctx) / 100
    return max(1.0, avg * hit_rate * crit_mult)


def create_clan_boss(clan: dict) -> dict:
    tier = max(1, min(CLAN_BOSS_MAX_TIER, int(clan.get("boss_tier", 1) or 1)))
    estimates = []
    for uid_str in (clan.get("members") or {}):
        estimates.append(estimate_clan_boss_member_damage(db.data.get(str(uid_str))))
    estimates.sort(reverse=True)
    # Добиваем до минимального числа «виртуальных» участников средним уроном,
    # чтобы клан из 1–2 человек не получал смешное HP.
    if estimates and len(estimates) < CLAN_BOSS_MIN_MEMBERS_FOR_HP:
        avg = sum(estimates) / len(estimates)
        estimates += [avg] * (CLAN_BOSS_MIN_MEMBERS_FOR_HP - len(estimates))
    tier_mult = 1 + CLAN_BOSS_TIER_HP_STEP * (tier - 1)
    raw_hp = sum(estimates) * CLAN_BOSS_HITS_PER_MEMBER * tier_mult
    max_hp = int(max(CLAN_BOSS_MIN_HP * tier_mult, raw_hp))
    # Красивое круглое число
    magnitude = 10 ** max(0, len(str(max_hp)) - 3)
    max_hp = int(math.ceil(max_hp / magnitude) * magnitude)
    return {
        "day": get_clan_boss_day_key(),
        "tier": tier,
        "max_hp": max_hp,
        "hp": max_hp,
        "spawned_at": time.time(),
        "defeated": False,
        "defeated_at": 0,
        "killer": None,
        "players": {},
        "recent": [],
        "rewards": {},
    }


def ensure_clan_boss(clan: dict, notify: bool = True) -> tuple[dict, bool]:
    """Возвращает актуального босса клана, при смене суток создаёт нового."""
    boss = clan.get("boss")
    today = get_clan_boss_day_key()
    if boss and boss.get("day") == today:
        return boss, False
    if boss and not boss.get("defeated"):
        old_tier = int(clan.get("boss_tier", 1) or 1)
        clan["boss_tier"] = max(1, old_tier - 1)
        left_pct = 100 * int(boss.get("hp", 0)) / max(1, int(boss.get("max_hp", 1)))
        clan_audit(clan, 0, f"{CLAN_BOSS_NAME} (тир {boss.get('tier', old_tier)}) ушёл непобеждённым, осталось {left_pct:.1f}% HP")
    boss = create_clan_boss(clan)
    clan["boss"] = boss
    clan_audit(clan, 0, f"Появился {CLAN_BOSS_NAME} тир {boss['tier']} · {format_num(boss['max_hp'])} HP")
    # Уведомление участникам в ЛС (один раз на каждого босса)
    boss["notified"] = True
    if not notify:
        return boss, True
    try:
        task = asyncio.get_running_loop().create_task(notify_clan_boss_spawn(clan, boss))
        _clan_boss_notify_tasks.add(task)
        task.add_done_callback(_clan_boss_notify_tasks.discard)
    except RuntimeError:
        boss["notified"] = False  # нет event loop (тесты) — уведомим позже
    return boss, True


_clan_boss_notify_tasks: set = set()


def get_clan_boss_spawn_notification_text(clan: dict, boss: dict) -> str:
    alarm = '<tg-emoji emoji-id="5440660757194744323">‼️</tg-emoji>'
    crown = '<tg-emoji emoji-id="5217822164362739968">👑</tg-emoji>'
    hourglass = '<tg-emoji emoji-id="5287473790735890430">⏳</tg-emoji>'
    tag = html.escape(str(clan.get("tag", "")))
    return (
        f"<blockquote>{CLAN_BOSS_EMOJI} <b>{CLAN_BOSS_TITLE}</b>\n"
        f"Пробудился и ждёт клан <b>[{tag}]</b>{alarm}</blockquote>\n\n"
        f"<blockquote>{PE_TROPHY} Тир: <b>{int(boss.get('tier', 1))}</b>\n"
        f"{HP_EMOJI} Здоровье: <b>{format_num(int(boss.get('max_hp', 0)))}</b>\n"
        f"{hourglass} Уйдёт через: <b>{format_clan_boss_time(get_clan_boss_reset_left())}</b></blockquote>\n\n"
        f"<blockquote>Пиши <b>клан босс</b> и покажи ему вместе с кланом, кто тут главный{crown}</blockquote>"
    )


async def notify_clan_boss_spawn(clan: dict, boss: dict):
    text = get_clan_boss_spawn_notification_text(clan, boss)
    kb = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="К боссу", callback_data="cboss|open", icon_custom_emoji_id=BTN_DRAGON),
    ]])
    for uid_str in list((clan.get("members") or {}).keys()):
        try:
            await send_user_notification(int(uid_str), text, reply_markup=kb)
        except Exception as e:
            print(f"[clan_boss_notify] {uid_str}: {e}")
        await asyncio.sleep(0.05)  # не упираемся в лимиты Telegram


async def clan_boss_spawn_loop():
    """Раз в минуту проверяет кланы: в 12:00 МСК появляется новый Лутиафан и всем приходит уведомление."""
    while True:
        try:
            await load_clans()
            await db.load()
            for clan in list(clans_data.values()):
                if not clan.get("members"):
                    continue
                async with _clan_boss_lock(clan["id"]):
                    boss, created = ensure_clan_boss(clan)
                    if not created and boss.get("notified") is False and not boss.get("defeated"):
                        boss["notified"] = True
                        asyncio.get_running_loop().create_task(notify_clan_boss_spawn(clan, boss))
                        created = True
                    if created:
                        await _save_clan_boss_throttled(clan, force=True)
        except Exception as e:
            print(f"[clan_boss_spawn_loop] {e}")
        await asyncio.sleep(60)


def get_clan_boss_player(boss: dict, user_id: int, user: dict) -> dict:
    players = boss.setdefault("players", {})
    p = players.get(str(user_id))
    max_hp = calculate_max_hp_with_armor(
        int(user.get("level", 1) or 1),
        user.get("equipped_armor", {slot: None for slot in ARMOR_SLOTS}),
        user,
    )
    if not p:
        p = {
            "hp": max_hp, "max_hp": max_hp, "hits": 0, "damage": 0,
            "ko_until": 0, "last_hit": 0, "turn": 0, "deaths": 0,
            "name": str(user.get("name") or f"id{user_id}"),
        }
        players[str(user_id)] = p
    p["name"] = str(user.get("name") or p.get("name") or f"id{user_id}")
    # Если игрок вырос (новая броня/уровень) — поднимаем максимум, сохраняя долю HP
    if max_hp != p.get("max_hp") and p.get("hp", 0) > 0:
        ratio = p["hp"] / max(1, p.get("max_hp", max_hp))
        p["max_hp"] = max_hp
        p["hp"] = max(1, min(max_hp, math.ceil(max_hp * ratio)))
    # Нокаут прошёл — встаём с полным HP
    if p.get("hp", 0) <= 0 and time.time() >= float(p.get("ko_until", 0)):
        p["max_hp"] = max_hp
        p["hp"] = max_hp
        p["turn"] = 0
    return p


def get_clan_boss_damage_ranking(boss: dict) -> List[tuple]:
    rows = []
    for uid_str, p in (boss.get("players") or {}).items():
        dmg = int(p.get("damage", 0))
        if dmg > 0:
            rows.append((dmg, uid_str, p))
    rows.sort(key=lambda x: x[0], reverse=True)
    return rows


def roll_clan_boss_counter(user_ctx: dict, p: dict, boss: dict) -> tuple[int, str]:
    p["turn"] = int(p.get("turn", 0)) + 1
    tier = int(boss.get("tier", 1))
    tier_mult = min(CLAN_BOSS_TIER_DMG_MAX, 1 + CLAN_BOSS_TIER_DMG_STEP * (tier - 1))
    special = p["turn"] % CLAN_BOSS_SPECIAL_EVERY == 0
    lo, hi = CLAN_BOSS_SPECIAL_PCT if special else CLAN_BOSS_HIT_PCT
    raw = math.ceil(p["max_hp"] * random.uniform(lo, hi) * tier_mult)
    dmg = apply_incoming_damage_reduction(user_ctx, raw)
    dmg = min(dmg, math.ceil(p["max_hp"] * CLAN_BOSS_MAX_HIT_PCT))
    if dmg <= 0:
        name = "Жадный укус" if special else "Удар хвостом"
        return 0, f"{PE_DODGE} {name} — ты увернулся!"
    if special:
        return dmg, f"{PE_BLOOD} <b>Жадный укус!</b> −{format_num(dmg)} HP"
    return dmg, f"{ENEMY_HIT_EMOJI} Удар хвостом: −{format_num(dmg)} HP"


def get_clan_boss_text(clan: dict, boss: dict, user_id: int, log: str = "") -> str:
    tier = int(boss.get("tier", 1))
    hp = max(0, int(boss.get("hp", 0)))
    max_hp = max(1, int(boss.get("max_hp", 1)))
    pct = 100 * hp / max_hp
    ranking = get_clan_boss_damage_ranking(boss)
    lines = [
        f"{CLAN_BOSS_EMOJI} <b>{CLAN_BOSS_TITLE}</b>",
        f"<i>Клан [{html.escape(str(clan.get('tag', '')))}] · тир {tier}</i>",
        "",
    ]
    boss_block = [
        f"{HP_EMOJI} {health_bar(hp, max_hp)} <b>{pct:.1f}%</b>",
        f"<b>{format_num(hp)}</b> / {format_num(max_hp)} HP",
        f"Участвуют: <b>{len(ranking)}</b> · до сброса: <b>{format_clan_boss_time(get_clan_boss_reset_left())}</b>",
    ]
    lines.append("<blockquote>" + "\n".join(boss_block) + "</blockquote>")

    p = (boss.get("players") or {}).get(str(user_id))
    if boss.get("defeated"):
        killer_name = clan_user_name_html(boss.get("killer")) if boss.get("killer") else "—"
        lines.append(f"\n{PE_TROPHY} <b>Повержен!</b> Добивающий удар: <b>{killer_name}</b>")
        reward = (boss.get("rewards") or {}).get(str(user_id))
        if reward:
            reward_lines = [
                f"{PE_COIN} Монеты: <b>+{format_num(reward.get('coins', 0))}</b>",
                f"{PE_XP} Опыт: <b>+{format_num(reward.get('xp', 0))}</b>",
            ]
            drops = reward.get("drops")
            if drops is None and reward.get("resource"):
                drops = [[reward["resource"], reward.get("resource_amount", 1)]]
            for rid, amount in (drops or []):
                info = BOSS_RESOURCE_DEFS.get(rid, {})
                reward_lines.append(f"{info.get('emoji', '•')} {html.escape(str(info.get('name', rid)))} ×{amount}")
            if reward.get("bonus"):
                reward_lines.append(f"{PE_SPARK} {html.escape(str(reward['bonus']))}")
            lines.append("<blockquote><b>Твоя награда</b>\n" + "\n".join(reward_lines) + "</blockquote>")
        else:
            lines.append("<i>Ты не участвовал в этой битве — награды нет.</i>")
        lines.append(f"Новый {CLAN_BOSS_NAME} появится через <b>{format_clan_boss_time(get_clan_boss_reset_left())}</b>.")
    else:
        if p:
            if p.get("hp", 0) <= 0:
                state = f"{PE_SKULL} Нокаут · восстановление {format_clan_boss_time(float(p.get('ko_until', 0)) - time.time())}"
            else:
                state = f"{HP_EMOJI} {health_bar(p['hp'], p['max_hp'])} {format_num(p['hp'])}/{format_num(p['max_hp'])}"
            lines.append(
                "<blockquote><b>Ты</b>\n"
                f"{state}\n"
                f"Удары: <b>{int(p.get('hits', 0))}</b> · "
                f"урон: <b>{format_num(int(p.get('damage', 0)))}</b></blockquote>"
            )
        else:
            lines.append(
                f"<blockquote>Бей сколько угодно — лимита ударов нет. "
                f"Каждый {CLAN_BOSS_SPECIAL_EVERY}-й ход босс делает «Жадный укус».</blockquote>"
            )

    if log:
        lines.append("\n" + log)

    recent = boss.get("recent") or []
    if recent:
        rec_lines = []
        for r in reversed(recent[-CLAN_BOSS_RECENT_LOG:]):
            nm = clan_user_name_html(r["uid"]) if r.get("uid") else html.escape(str(r.get("name", "?")))
            if r.get("miss"):
                rec_lines.append(f"• {nm}: промах")
            else:
                crit = f" {CRIT_EMOJI}" if r.get("crit") else ""
                rec_lines.append(f"• {nm}: −{format_num(int(r.get('dmg', 0)))}{crit}")
        lines.append("\n<b>Последние удары клана</b>\n<blockquote>" + "\n".join(rec_lines) + "</blockquote>")

    if ranking:
        medals = ["🥇", "🥈", "🥉"]
        top_lines = []
        for i, (dmg, uid_str, pp) in enumerate(ranking[:3]):
            top_lines.append(f"{medals[i]} {clan_user_name_html(uid_str)} — {format_num(dmg)}")
        lines.append("<b>Топ урона</b>\n<blockquote>" + "\n".join(top_lines) + "</blockquote>")
    return "\n".join(lines)


def clan_boss_keyboard(boss: dict) -> InlineKeyboardMarkup:
    rows = []
    if not boss.get("defeated"):
        rows.append([InlineKeyboardButton(text="Атаковать", callback_data="cboss|atk", icon_custom_emoji_id=BTN_SWORD)])
    rows.append([
        InlineKeyboardButton(text="Обновить", callback_data="cboss|ref", icon_custom_emoji_id=BTN_REFRESH),
        InlineKeyboardButton(text="Рейтинг", callback_data="cboss|top", icon_custom_emoji_id=BTN_TROPHY),
    ])
    rows.append([InlineKeyboardButton(text="К клану", callback_data="cboss|clan", icon_custom_emoji_id=BTN_CLAN)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _save_clan_boss_throttled(clan: dict, force: bool = False):
    cid = clan["id"]
    now = time.time()
    if force or now - _clan_boss_last_save.get(cid, 0) >= CLAN_BOSS_SAVE_INTERVAL:
        _clan_boss_last_save[cid] = now
        await save_clan(clan)


async def _save_user_throttled(uid: int, user: dict, force: bool = False):
    now = time.time()
    if force or now - _clan_boss_user_last_save.get(uid, 0) >= 5.0:
        _clan_boss_user_last_save[uid] = now
        await db.save_user(uid, user)


async def show_clan_boss(user_id: int, answer_func, log: str = ""):
    await load_clans()
    await db.load()
    user = await db.get_user(user_id)
    clan = get_user_clan(user) if user else None
    if not clan:
        await answer_func("<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Ты не в клане. Клановый босс доступен только участникам клана.", None)
        return
    async with _clan_boss_lock(clan["id"]):
        boss, created = ensure_clan_boss(clan)
        if created:
            await _save_clan_boss_throttled(clan, force=True)
    await answer_func(get_clan_boss_text(clan, boss, user_id, log), clan_boss_keyboard(boss))


async def finish_clan_boss(clan: dict, boss: dict, killer_id: int) -> None:
    """Раздаёт награды всем участникам. Вызывается под локом клана."""
    boss["defeated"] = True
    boss["defeated_at"] = time.time()
    boss["killer"] = str(killer_id)
    tier = int(boss.get("tier", 1))
    # Награда растёт с тиром, но не бесконечно: максимум ×2.5 (≈ 13-й тир)
    tier_mult = min(2.5, 1 + 0.12 * (tier - 1))
    ranking = get_clan_boss_damage_ranking(boss)
    total_dmg = max(1, sum(r[0] for r in ranking))
    n = max(1, len(ranking))
    top_uid = ranking[0][1] if ranking else None
    rewards = boss.setdefault("rewards", {})

    for dmg, uid_str, p in ranking:
        try:
            uid = int(uid_str)
        except (TypeError, ValueError):
            continue
        user = await db.get_user(uid)
        if not user:
            continue
        level = int(user.get("level", 1) or 1)
        # Равная доля урона = 1.0; малый вклад — от 0.4; большой — до 1.3
        share = 0.4 + 0.6 * min(1.5, dmg / total_dmg * n)
        mult = share * tier_mult
        bonus_notes = []
        if uid_str == top_uid:
            mult *= 1.25
            bonus_notes.append("Топ урона: +25%")
        if uid_str == str(killer_id):
            mult *= 1.10
            bonus_notes.append("Добивание: +10%")
        coins = apply_coin_buff(user, math.ceil((800 + 45 * level) * mult))
        # Базовый опыт не больше одного уровня игрока — чтобы низкоуровневые не прыгали на 5 уровней сразу
        # Опыт ≈ 20% текущего уровня (у среднего участника), но не меньше старой формулы
        base_xp = max(2000 + 180 * level, math.ceil(get_level_xp_required(level) * CLAN_BOSS_XP_LEVEL_SHARE))
        xp = apply_xp_buff(user, math.ceil(base_xp * mult))
        # Ресурсы — теперь не гарантированы
        drops: List[tuple] = []
        if random.random() < CLAN_BOSS_PLAYER_RES_CHANCE:
            drops.append((random.choice(CLAN_BOSS_PLAYER_RESOURCES), 1 + tier // 10))
        if uid_str == top_uid and random.random() < CLAN_BOSS_TOP_EYE_CHANCE:
            drops.append(("dried_eye", 1))
        user["coins"] = int(user.get("coins", 0)) + coins
        levels = add_xp(user, xp)
        for rid, amount in drops:
            add_boss_resource(user, rid, amount)
        res_id, res_amount = drops[0] if drops else (None, 0)
        user["clan_boss_kills"] = int(user.get("clan_boss_kills", 0)) + 1
        await db.save_user(uid, user)
        _clan_boss_user_last_save[uid] = time.time()
        log_event_nowait(
            f"CBOSS {_log_user_name(uid, user)} | клан [{clan.get('tag')}] тир {tier} | награда: +{coins} монет, +{xp} опыта, "
            f"ресурсы: {', '.join(f'{r} x{a}' for r, a in drops) or 'нет'}, урон {dmg}"
        )
        rewards[uid_str] = {
            "coins": coins, "xp": xp, "resource": res_id, "resource_amount": res_amount,
            "drops": [[rid, amount] for rid, amount in drops],
            "bonus": ", ".join(bonus_notes),
        }
        drop_lines = "".join(
            f"\n{BOSS_RESOURCE_DEFS.get(rid, {}).get('emoji', '•')} "
            f"{html.escape(str(BOSS_RESOURCE_DEFS.get(rid, {}).get('name', rid)))} ×{amount}"
            for rid, amount in drops
        )
        lvl_text = f"\n{PE_LEVELUP} Новый уровень: <b>{user['level']}</b>" if levels else ""
        try:
            await send_user_notification(
                uid,
                f"{CLAN_BOSS_EMOJI} <b>{CLAN_BOSS_NAME} повержен!</b>\n"
                f"Клан [{html.escape(str(clan.get('tag', '')))}] · тир {tier}\n\n"
                f"<blockquote>Твой урон: <b>{format_num(dmg)}</b> ({100 * dmg / total_dmg:.1f}%)\n"
                f"{PE_COIN} +{format_num(coins)} монет\n"
                f"{PE_XP} +{format_num(xp)} опыта"
                f"{drop_lines}"
                + (f"\n{PE_SPARK} {html.escape(', '.join(bonus_notes))}" if bonus_notes else "")
                + f"</blockquote>{lvl_text}",
                reply_markup=nav_kb(NAV_CLAN_BOSS, NAV_CLAN),
            )
        except Exception:
            pass

    # Награда в склад клана
    bank = clan.setdefault("bank", {})
    # Урезанный дроп в склад (раньше на 1 тире: 12/7/5/1)
    bank_reward = {
        "swamp_crystal": 4 + tier,
        "ember_stone": 2 + tier // 2,
        "frost_crystal": 1 + tier // 2,
    }
    if tier >= 4:
        bank_reward["dried_eye"] = tier // 4
    if tier >= 10:
        bank_reward["nightmare_shard"] = tier // 10
    for rid, amount in bank_reward.items():
        bank[rid] = int(bank.get(rid, 0)) + amount
    boss["bank_reward"] = bank_reward
    clan["boss_tier"] = min(CLAN_BOSS_MAX_TIER, tier + 1)
    clan["boss_kills"] = int(clan.get("boss_kills", 0)) + 1
    clan_audit(
        clan, killer_id,
        f"{CLAN_BOSS_NAME} тир {tier} повержен! Добил: {clan_user_name(killer_id)}, "
        f"участников: {len(ranking)}. В склад: {clan_plain_cost(bank_reward)}",
    )


async def clan_boss_attack(call: CallbackQuery):
    uid = call.from_user.id
    await load_clans()
    await db.load()
    user = await db.get_user(uid)
    clan = get_user_clan(user) if user else None
    if not clan:
        await call.answer("Ты не в клане.", show_alert=True)
        return

    alert = None
    silent_skip = False
    log = ""
    async with _clan_boss_lock(clan["id"]):
        boss, created = ensure_clan_boss(clan)
        now = time.time()
        p = get_clan_boss_player(boss, uid, user)
        if boss.get("defeated"):
            alert = f"{CLAN_BOSS_NAME} уже повержен. Новый появится в {CLAN_BOSS_SPAWN_HOUR_MSK}:00 МСК."
        elif p.get("hp", 0) <= 0:
            alert = f"💀 Ты в нокауте. Восстановление: {format_clan_boss_time(float(p.get('ko_until', 0)) - now)}"
        elif now - float(p.get("last_hit", 0)) < CLAN_BOSS_HIT_COOLDOWN:
            silent_skip = True  # слишком частое нажатие — молча пропускаем, без всплывающего окна
        else:
            p["last_hit"] = now
            ctx = dict(user)
            ctx["battle_effects"] = {}
            damage, _weapon_name = get_equipped_attack(ctx)
            damage, notes = roll_player_attack_effects(ctx, damage)
            damage = max(0, min(int(damage), int(boss["hp"])))
            missed = "промах" in notes
            crit = "крит" in notes
            boss["hp"] = int(boss["hp"]) - damage
            p["hits"] = int(p.get("hits", 0)) + 1
            add_weekly_stat(user, "cboss_hits")
            p["damage"] = int(p.get("damage", 0)) + damage
            user["total_damage"] = int(user.get("total_damage", 0)) + damage
            if p["hits"] <= CLAN_BOSS_PATH_XP_HITS:
                add_path_attack_xp(user)

            if missed:
                player_log = f"{DAMAGE_EMOJI} <b>Твой удар: промах</b>"
            else:
                crit_text = f" | Крит{CRIT_EMOJI}" if crit else ""
                player_log = f"{DAMAGE_EMOJI} <b>Твой урон: −{format_num(damage)}{crit_text}</b>"
                heal = calc_vampirism_heal(ctx, damage, p["max_hp"])
                if heal > 0:
                    old_hp = p["hp"]
                    p["hp"] = min(p["max_hp"], old_hp + heal)
                    if p["hp"] > old_hp:
                        player_log += f"\n{VAMPIRISM_EMOJI} Вампиризм: +{format_num(p['hp'] - old_hp)} HP"

            recent = boss.setdefault("recent", [])
            recent.append({"name": p["name"], "uid": uid, "dmg": damage, "crit": crit, "miss": missed, "ts": now})
            _cb_log = (
                f"CBOSS {_log_user_name(uid, user)} | клан [{clan.get('tag')}] тир {boss.get('tier')} | "
                f"удар {'промах' if missed else damage}{' крит' if crit else ''} | HP босса {max(0, boss['hp'])}/{boss['max_hp']}"
            )
            del recent[:-CLAN_BOSS_RECENT_LOG * 2]

            if boss["hp"] <= 0:
                boss["hp"] = 0
                _cb_log += " | ДОБИВАНИЕ"
                await finish_clan_boss(clan, boss, uid)
                log = player_log + f"\n\n{PE_TROPHY} <b>Ты нанёс добивающий удар!</b>"
                await save_clan(clan)
                _clan_boss_last_save[clan["id"]] = time.time()
            else:
                enemy_dmg, enemy_log = roll_clan_boss_counter(ctx, p, boss)
                p["hp"] = int(p["hp"]) - enemy_dmg
                _cb_log += f" | получил {enemy_dmg}, HP {max(0, p['hp'])}/{p['max_hp']}" + (" НОКАУТ" if p["hp"] <= 0 else "")
                log = player_log + "\n" + enemy_log
                if p["hp"] <= 0:
                    p["hp"] = 0
                    p["ko_until"] = now + CLAN_BOSS_KO_SECONDS
                    p["deaths"] = int(p.get("deaths", 0)) + 1
                    log += f"\n{PE_SKULL} <b>Нокаут!</b> Вернёшься в бой через {format_clan_boss_time(CLAN_BOSS_KO_SECONDS)}."
                await _save_clan_boss_throttled(clan, force=created or p["hp"] <= 0)
            await write_activity_log(_cb_log)
            await _save_user_throttled(uid, user, force=boss.get("defeated", False))

    if silent_skip:
        await call.answer()
        return
    if alert:
        await call.answer(alert, show_alert=True)
        return
    await call.answer()
    await edit_for_user(call, get_clan_boss_text(clan, boss, uid, log), clan_boss_keyboard(boss))


async def show_clan_boss_ranking(user_id: int, answer_func):
    await load_clans()
    user = await db.get_user(user_id)
    clan = get_user_clan(user) if user else None
    if not clan:
        await answer_func("Ты не в клане.", None)
        return
    async with _clan_boss_lock(clan["id"]):
        boss, created = ensure_clan_boss(clan)
        if created:
            await _save_clan_boss_throttled(clan, force=True)
    ranking = get_clan_boss_damage_ranking(boss)
    total = max(1, sum(r[0] for r in ranking))
    lines = []
    for i, (dmg, uid_str, p) in enumerate(ranking, 1):
        me = " ← ты" if uid_str == str(user_id) else ""
        lines.append(
            f"{i}. {clan_user_name_html(uid_str)} — <b>{format_num(dmg)}</b> "
            f"({100 * dmg / total:.1f}%) · {int(p.get('hits', 0))} уд.{me}"
        )
    body = "\n".join(lines) if lines else "Пока никто не атаковал."
    text_msg = (
        f"{PE_TROPHY} <b>Рейтинг урона · {CLAN_BOSS_NAME} тир {boss.get('tier', 1)}</b>\n\n"
        f"<blockquote expandable>{body}</blockquote>\n"
        f"Всего побед клана над боссом: <b>{int(clan.get('boss_kills', 0))}</b>"
    )
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="К боссу", callback_data="cboss|ref", icon_custom_emoji_id=BTN_DRAGON)],
        [InlineKeyboardButton(text="К клану", callback_data="cboss|clan", icon_custom_emoji_id=BTN_CLAN)],
    ])
    await answer_func(text_msg, kb)


@dp.callback_query(F.data.startswith("cboss|"))
async def cb_clan_boss(call: CallbackQuery):
    action = call.data.split("|", 1)[1] if "|" in call.data else "open"
    if action == "atk":
        await clan_boss_attack(call)
        return
    await call.answer()
    edit = lambda t, kb: edit_for_user(call, t, kb)
    if action == "top":
        await show_clan_boss_ranking(call.from_user.id, edit)
    elif action == "clan":
        await show_clan(call.from_user.id, edit)
    else:
        await show_clan_boss(call.from_user.id, edit)


