def find_clan_admin(query: str) -> Optional[dict]:
    q = (query or "").strip().lstrip("#")
    if not q:
        return None
    if q in clans_data:
        return clans_data[q]
    if q.isdigit():
        for c in clans_data.values():
            if int(c.get("number") or 0) == int(q):
                return c
    for c in clans_data.values():
        if str(c.get("tag", "")).upper() == q.upper():
            return c
    return None


def admin_clan_card(clan: dict) -> str:
    members = clan.get("members") or {}
    leader = clan_user_name(clan.get("leader_id"))
    bank = clan.get("bank") or {}
    bank_line = ", ".join(
        f"{BOSS_RESOURCE_DEFS.get(r, {}).get('name', r)}: {int(bank.get(r, 0))}" for r in CLAN_RESOURCE_IDS
    )
    member_lines = []
    rows = sorted(members.items(), key=lambda kv: -clan_rank_order((kv[1] or {}).get("role", "member")))
    for uid_str, m in rows:
        member_lines.append(
            f"{clan_rank_info((m or {}).get('role', 'member'))['name']}: "
            f"{clan_user_name_html(uid_str)} <code>{uid_str}</code>"
        )
    boss = clan.get("boss") or {}
    if boss:
        state = "повержен" if boss.get("defeated") else f"{format_num(int(boss.get('hp', 0)))}/{format_num(int(boss.get('max_hp', 0)))}"
        boss_line = f"тир {boss.get('tier')} · {state} · день {boss.get('day')}"
    else:
        boss_line = "ещё не появлялся"
    buffs = [b for b, exp in (clan.get("active_buffs") or {}).items() if exp > time.time()]
    return (
        f"{CLAN_PREMIUM_EMOJI} <b>[{html.escape(str(clan.get('tag')))}] {html.escape(str(clan.get('name')))}</b> "
        f"#{clan.get('number')}\n"
        f"<code>{clan.get('id')}</code>\n\n"
        f"<blockquote>Лидер: {html.escape(leader)} <code>{clan.get('leader_id')}</code>\n"
        f"Уровень: <b>{clan.get('level', 1)}</b> · участников: <b>{len(members)}</b>/{CLAN_MAX_MEMBERS}\n"
        f"Сила: <b>{calculate_clan_power(clan)}</b>\n"
        f"Создан: {format_clan_date(clan.get('created_at', 0))}\n"
        f"Баффы: {', '.join(buffs) or 'нет'}\n"
        f"Лутиафан: {boss_line} · след. тир {clan.get('boss_tier', 1)} · побед {clan.get('boss_kills', 0)}</blockquote>\n\n"
        f"<blockquote>Склад: {html.escape(bank_line)}</blockquote>\n\n"
        f"<blockquote expandable>" + "\n".join(member_lines) + "</blockquote>"
    )


def _admin_target_id(message: Message, args: List[str]) -> Optional[int]:
    for a in args:
        if a.isdigit() and len(a) >= 5:
            return int(a)
    replied = message.reply_to_message
    if replied and replied.from_user and not replied.from_user.is_bot:
        return replied.from_user.id
    return None


@dp.message(lambda msg: msg.text and message_command(msg) in ("акланы", "aclans"))
async def text_admin_clans_list(message: Message):
    if not is_admin_user(message.from_user.id):
        return
    await load_clans()
    await db.load()
    rows = sorted(clans_data.values(), key=lambda c: int(c.get("number") or 0))
    if not rows:
        await reply_to_user(message, "Кланов нет.")
        return
    lines = [
        f"#{c.get('number')} [{c.get('tag')}] {c.get('name')} — ур.{c.get('level', 1)}, "
        f"{get_clan_member_count(c)} чел., тир босса {c.get('boss_tier', 1)}, лидер {clan_user_name(c.get('leader_id'))} ({c.get('leader_id')})"
        for c in rows
    ]
    if len(lines) <= 40:
        await reply_to_user(message, f"<b>Кланы ({len(lines)})</b>\n<blockquote expandable>" + html.escape("\n".join(lines)) + "</blockquote>")
    else:
        await message.reply_document(
            BufferedInputFile("\n".join(lines).encode("utf-8"), filename="clans.txt"),
            caption=f"Кланов: {len(lines)}",
        )


@dp.message(lambda msg: msg.text and message_command(msg) in ("аклан", "aclan"))
async def text_admin_clan(message: Message):
    admin_id = message.from_user.id
    if not is_admin_user(admin_id):
        return
    await load_clans()
    await db.load()
    raw = (message.text or "").strip()
    parts = raw.split()
    if len(parts) < 2:
        await reply_to_user(message, ADMIN_CLAN_HELP)
        return
    clan = find_clan_admin(parts[1])
    if not clan:
        await reply_to_user(message, f"<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Клан «{html.escape(parts[1])}» не найден. Укажи тег или номер.")
        return
    if len(parts) == 2:
        await reply_to_user(message, admin_clan_card(clan))
        return

    sub = parts[2].lower()
    args = parts[3:]
    admin_label = f"Админ {clan_user_name(admin_id)}"
    tail_text = re.sub(r"^\s*\S+\s+\S+\s+\S+\s*", "", raw, count=1)  # всё после «аклан ТЕГ команда»

    async def done(text_msg: str, audit: str):
        clan_audit(clan, admin_id, f"{admin_label}: {audit}")
        await save_clan(clan)
        await reply_to_user(message, f"✅ [{html.escape(str(clan.get('tag')))}] {text_msg}")

    if sub in ("уровень", "level", "лвл"):
        if not args or not args[0].isdigit():
            await reply_to_user(message, "Формат: <code>аклан ТЕГ уровень 10</code>")
            return
        lvl = max(1, min(CLAN_MAX_LEVEL, int(args[0])))
        old = clan.get("level", 1)
        clan["level"] = lvl
        await done(f"уровень {old} → <b>{lvl}</b>", f"уровень {old} → {lvl}")
        return

    if sub in ("склад", "bank"):
        if len(args) < 2 or not args[1].lstrip("-").isdigit():
            await reply_to_user(message, "Формат: <code>аклан ТЕГ склад болотный 50</code> (или <code>все</code>, минус — забрать)")
            return
        amount = int(args[1])
        rids = list(CLAN_RESOURCE_IDS) if args[0].lower() in ("все", "all") else [resolve_clan_resource(args[0])]
        if not rids[0]:
            await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Ресурсы: " + ", ".join(CLAN_RESOURCE_SHORT.values()) + ", все")
            return
        bank = clan.setdefault("bank", {})
        for rid in rids:
            bank[rid] = max(0, int(bank.get(rid, 0)) + amount)
        names = ", ".join(BOSS_RESOURCE_DEFS.get(r, {}).get("name", r) for r in rids)
        await done(f"склад: {html.escape(names)} {amount:+d}", f"склад {names} {amount:+d}")
        return

    if sub in ("бафф", "buff"):
        bid = args[0].lower() if args else ""
        bdef = CLAN_BUFF_DEFS.get(bid)
        if not bdef:
            await reply_to_user(message, "Баффы: " + ", ".join(f"<code>{k}</code>" for k in CLAN_BUFF_DEFS))
            return
        clan.setdefault("active_buffs", {})[bid] = time.time() + bdef["duration"]
        await done(f"бесплатно включён бафф «{bdef['name']}»", f"включил бафф «{bdef['name']}» бесплатно")
        return

    if sub in ("баффы", "buffs") and args and args[0].lower() in ("сброс", "reset"):
        clan["active_buffs"] = {}
        await done("все баффы сняты", "снял все баффы")
        return

    if sub in ("имя", "name"):
        name = tail_text.strip()[:24]
        if len(name) < 2:
            await reply_to_user(message, "Формат: <code>аклан ТЕГ имя Новое имя</code>")
            return
        old = clan.get("name")
        clan["name"] = name
        await done(f"имя: {html.escape(str(old))} → <b>{html.escape(name)}</b>", f"имя «{old}» → «{name}»")
        return

    if sub in ("тег", "tag"):
        new_tag = re.sub(r"[^A-Za-zА-Яа-я0-9]", "", args[0] if args else "")[:5].upper()
        if len(new_tag) < 2:
            await reply_to_user(message, "Тег — 2–5 букв/цифр.")
            return
        if any(str(c.get("tag", "")).upper() == new_tag and c is not clan for c in clans_data.values()):
            await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Такой тег уже занят.")
            return
        old = clan.get("tag")
        clan["tag"] = new_tag
        await done(f"тег {html.escape(str(old))} → <b>{html.escape(new_tag)}</b>", f"тег {old} → {new_tag}")
        return

    if sub in ("описание", "desc"):
        body = tail_text.strip()
        if body.lower() in ("удалить", "очистить", "-"):
            clan["description"] = ""
            await done("описание удалено", "удалил описание")
            return
        if not body:
            await reply_to_user(message, "Формат: <code>аклан ТЕГ описание текст</code>")
            return
        clan["description"] = body[:CLAN_DESCRIPTION_MAX_LEN]
        await done("описание обновлено", "изменил описание")
        return

    if sub in ("лидер", "leader"):
        tid = _admin_target_id(message, args)
        members = clan.setdefault("members", {})
        if not tid or str(tid) not in members:
            await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Укажи ID участника клана или ответь на его сообщение.")
            return
        old_leader = clan.get("leader_id")
        if old_leader and str(old_leader) in members and str(old_leader) != str(tid):
            members[str(old_leader)]["role"] = "officer"
        members[str(tid)]["role"] = "leader"
        clan["leader_id"] = tid
        await done(
            f"новый лидер: <b>{clan_user_name_html(tid)}</b>",
            f"назначил лидером {clan_user_name(tid)} (прошлый: {clan_user_name(old_leader)} → офицер)",
        )
        return

    if sub in ("ранг", "rank", "роль"):
        tid = _admin_target_id(message, args)
        role = next((CLAN_ROLE_ALIASES[a.lower()] for a in args if a.lower() in CLAN_ROLE_ALIASES), None)
        members = clan.get("members") or {}
        if not tid or str(tid) not in members or not role:
            await reply_to_user(message, "Формат: <code>аклан ТЕГ ранг ID офицер</code> (офицер/ветеран/участник/новобранец)")
            return
        if str(tid) == str(clan.get("leader_id")):
            await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Это лидер. Сначала назначь другого лидера.")
            return
        old = members[str(tid)].get("role", "member")
        members[str(tid)]["role"] = role
        await done(
            f"{clan_user_name_html(tid)}: {clan_rank_info(old)['name']} → <b>{clan_rank_info(role)['name']}</b>",
            f"ранг {clan_user_name(tid)}: {clan_rank_info(old)['name']} → {clan_rank_info(role)['name']}",
        )
        return

    if sub in ("кик", "kick"):
        tid = _admin_target_id(message, args)
        members = clan.setdefault("members", {})
        if not tid or str(tid) not in members:
            await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Укажи ID участника или ответь на его сообщение.")
            return
        if str(tid) == str(clan.get("leader_id")) and len(members) > 1:
            await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Это лидер. Сначала назначь другого лидера.")
            return
        members.pop(str(tid), None)
        target = await db.get_user(tid)
        if target and target.get("clan_id") == clan["id"]:
            target["clan_id"] = None
            await db.save_user(tid, target)
        await done(f"исключён {clan_user_name_html(tid)}", f"исключил {clan_user_name(tid)}")
        return

    if sub in ("добавить", "add"):
        tid = _admin_target_id(message, args)
        target = await db.get_user(tid) if tid else None
        if not target:
            await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Игрок не найден (нужен ID или реплай, и профиль в боте).")
            return
        if target.get("clan_id"):
            await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Игрок уже в клане. Сначала кикни его оттуда.")
            return
        if get_clan_member_count(clan) >= CLAN_MAX_MEMBERS:
            await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Клан полон.")
            return
        clan.setdefault("members", {})[str(tid)] = {
            "role": "recruit", "joined_at": time.time(),
            "contributions": {rid: 0 for rid in CLAN_RESOURCE_IDS},
        }
        target["clan_id"] = clan["id"]
        await db.save_user(tid, target)
        await done(f"добавлен {clan_user_name_html(tid)}", f"добавил в клан {clan_user_name(tid)}")
        return

    if sub in ("тир", "tier"):
        if not args or not args[0].isdigit():
            await reply_to_user(message, "Формат: <code>аклан ТЕГ тир 5</code>")
            return
        tier = max(1, min(CLAN_BOSS_MAX_TIER, int(args[0])))
        clan["boss_tier"] = tier
        await done(
            f"тир Лутиафана: <b>{tier}</b> (с следующего появления; сейчас — <code>аклан ТЕГ босс новый</code>)",
            f"тир босса → {tier}",
        )
        return

    if sub in ("босс", "boss"):
        action = args[0].lower() if args else ""
        async with _clan_boss_lock(clan["id"]):
            if action in ("новый", "new", "респ", "спавн"):
                clan.pop("boss", None)
                boss, _ = ensure_clan_boss(clan)
                await done(
                    f"призван новый {CLAN_BOSS_NAME}: тир {boss['tier']}, {format_num(boss['max_hp'])} HP (участники уведомлены)",
                    f"призвал нового {CLAN_BOSS_NAME} тир {boss['tier']}",
                )
                return
            boss, _ = ensure_clan_boss(clan)
            if action in ("хп", "hp") and len(args) >= 2 and args[1].isdigit():
                if boss.get("defeated"):
                    await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Босс уже повержен сегодня. Используй <code>босс новый</code>.")
                    return
                hp = max(1, int(args[1]))
                boss["hp"] = hp
                boss["max_hp"] = max(int(boss.get("max_hp", hp)), hp)
                await done(f"HP босса: <b>{format_num(hp)}</b>", f"HP босса → {hp}")
                return
            if action in ("убить", "kill"):
                if boss.get("defeated"):
                    await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Уже повержен.")
                    return
                ranking = get_clan_boss_damage_ranking(boss)
                killer = int(ranking[0][1]) if ranking else int(clan.get("leader_id") or admin_id)
                boss["hp"] = 0
                await finish_clan_boss(clan, boss, killer)
                await done(
                    f"{CLAN_BOSS_NAME} убит, награды выданы {len(ranking)} участникам",
                    f"убил {CLAN_BOSS_NAME} вручную (награды {len(ranking)} участникам)",
                )
                return
        await reply_to_user(message, "Формат: <code>аклан ТЕГ босс новый|хп N|убить</code>")
        return

    if sub in ("журнал", "аудит", "audit"):
        entries = clan.get("audit_log") or []
        if not entries:
            await reply_to_user(message, "Журнал пуст.")
            return
        body = "\n".join(f"{format_clan_date(e.get('ts', 0))}  {e.get('text', '')}" for e in entries)
        await message.reply_document(
            BufferedInputFile(body.encode("utf-8"), filename=f"clan_{clan.get('tag')}_audit.txt"),
            caption=f"Журнал [{html.escape(str(clan.get('tag')))}]: {len(entries)} записей",
        )
        return

    if sub in ("удалить", "delete"):
        if not args or args[0].lower() not in ("подтвердить", "confirm"):
            await reply_to_user(message, f"⚠️ Точно удалить клан? Напиши <code>аклан {html.escape(str(clan.get('tag')))} удалить подтвердить</code>")
            return
        for uid_str in list((clan.get("members") or {}).keys()):
            u = db.data.get(uid_str)
            if u and u.get("clan_id") == clan["id"]:
                u["clan_id"] = None
                await db.save_user(int(uid_str), u)
        log_event_nowait(f"CLAN [{clan.get('tag')}] #{clan.get('number')} | {admin_label}: УДАЛИЛ КЛАН")
        clans_data.pop(clan["id"], None)
        try:
            await delete_clan(clan["id"])
        except Exception as e:
            print(f"[aclan delete] {e}")
        await reply_to_user(message, f"✅ Клан [{html.escape(str(clan.get('tag')))}] удалён, участники освобождены.")
        return

    await reply_to_user(message, ADMIN_CLAN_HELP)


# ============================================================
# === Админ: воскресить боссов (сброс кулдауна) ===
# ============================================================

REVIVE_HELP = (
    "<b>Воскрешение боссов</b>\n\n"
    "<blockquote>"
    "<code>воскресить все</code> — все боссы для всех игроков\n"
    "<code>воскресить Колосс пустыни</code> — один босс (название или id)\n"
    "<code>воскресить лутиафан</code> — новый Лутиафан во всех кланах\n\n"
    "Реплаем на игрока — только для него.\n"
    "Добавь <code>тихо</code>, чтобы игрокам не приходили уведомления."
    "</blockquote>"
)


def find_boss_for_admin(query: str) -> Optional[dict]:
    q = (query or "").strip().casefold()
    if not q:
        return None
    for boss in BOSSES.values():
        if q == str(boss.get("id", "")).casefold() or q == str(boss.get("name", "")).casefold():
            return boss
    matches = [b for b in BOSSES.values() if q in str(b.get("name", "")).casefold() or q in str(b.get("id", "")).casefold()]
    return matches[0] if len(matches) == 1 else None


def get_bosses_revived_notification_text(bosses: List[dict], reviver: Optional[dict] = None, by_admin: bool = False) -> str:
    if reviver and by_admin:
        who = (f'<blockquote><tg-emoji emoji-id="5217822164362739968">👑</tg-emoji> <b>Админ воскресил</b>{PE_ALARM}\n'
               f"{PE_REVIVE} <b>{render_user_nickname(reviver)}</b></blockquote>\n\n")
    elif reviver:
        who = f"<blockquote>{PE_REVIVE} Воскресил: <b>{render_user_nickname(reviver)}</b></blockquote>\n\n"
    else:
        who = ""
    if len(bosses) == 1:
        return who + get_boss_ready_notification_text(bosses[0])
    lines = []
    for boss in bosses[:15]:
        emoji = boss.get("premium_emoji", boss.get("emoji", ""))
        lines.append(f"{emoji} <b>{html.escape(boss.get('name', 'Босс'))}</b>")
    more = f"\n…и ещё {len(bosses) - 15}" if len(bosses) > 15 else ""
    return who + (
        '<blockquote><tg-emoji emoji-id="5217822164362739968">👑</tg-emoji> <b>Боссы воскрешены</b>'
        '<tg-emoji emoji-id="5440660757194744323">‼️</tg-emoji>\n\n'
        + "\n".join(lines) + more
        + "\n\nГотовы к сражению</blockquote>"
        + '\n\n<blockquote>Пиши <b>Бсс</b> или <b>Бс</b> и покажи им кто тут главный'
        + '<tg-emoji emoji-id="5217822164362739968">👑</tg-emoji></blockquote>'
    )


@dp.message(lambda msg: msg.text and message_command(msg) in ("воскресить", "воскрес", "revive"))
async def text_admin_revive_bosses(message: Message):
    admin_id = message.from_user.id
    if not is_admin_user(admin_id):
        return
    await db.load()
    parts = (message.text or "").split()
    silent = any(p.casefold() in ("тихо", "silent") for p in parts[1:])
    query_parts = [p for p in parts[1:] if p.casefold() not in ("тихо", "silent")]
    query = " ".join(query_parts).strip()
    if not query:
        await reply_to_user(message, REVIVE_HELP)
        return

    # --- Лутиафан во всех кланах ---
    if query.casefold() in ("лутиафан", "клан", "кланбосс", "clan"):
        await load_clans()
        count = 0
        for clan in list(clans_data.values()):
            if not clan.get("members"):
                continue
            async with _clan_boss_lock(clan["id"]):
                clan.pop("boss", None)
                boss, _ = ensure_clan_boss(clan, notify=not silent)  # сам разошлёт уведомления участникам
                clan_audit(clan, admin_id, f"Админ {clan_user_name(admin_id)}: воскресил {CLAN_BOSS_NAME} (тир {boss['tier']})")
                await save_clan(clan)
                count += 1
        await write_activity_log(f"ADMIN {_log_user_name(admin_id)} | воскресил {CLAN_BOSS_NAME} в {count} кланах")
        await reply_to_user(message, f"✅ {CLAN_BOSS_NAME} воскрешён в <b>{count}</b> кланах.")
        return

    # --- обычные боссы ---
    if query.casefold() in ("все", "всех", "all"):
        bosses = list(BOSSES.values())
    else:
        boss = find_boss_for_admin(query)
        if not boss:
            await reply_to_user(message, f"<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Не нашёл босса «{html.escape(query)}». Напиши точнее название или id.")
            return
        bosses = [boss]
    boss_ids = {b.get("id") for b in bosses if b.get("id")}

    replied = message.reply_to_message
    if replied and replied.from_user and not replied.from_user.is_bot:
        targets = [str(replied.from_user.id)]
    else:
        targets = list(db.data.keys())

    now = time.time()
    affected: Dict[int, List[dict]] = {}
    for uid_str in targets:
        user = db.data.get(uid_str)
        if not isinstance(user, dict):
            continue
        cooldowns = user.get("boss_cooldowns") or {}
        revived = [b for b in bosses if b.get("id") in cooldowns and float(cooldowns.get(b["id"], 0)) > now]
        if not revived:
            continue
        for b in revived:
            cooldowns.pop(b["id"], None)
            # чтобы стандартное уведомление «готов» не пришло вторым сообщением
            user.setdefault("boss_cd_notified", {})[b["id"]] = True
        try:
            affected[int(uid_str)] = revived
        except ValueError:
            pass

    if affected:
        await db.save()
    names = ", ".join(b.get("name", "?") for b in bosses) if len(bosses) <= 5 else f"все боссы ({len(bosses)})"
    await write_activity_log(
        f"ADMIN {_log_user_name(admin_id)} | воскресил: {names} | игроков с откатом: {len(affected)}"
        + (" (тихо)" if silent else "")
    )

    if not silent:
        for uid, revived in affected.items():
            try:
                await send_user_notification(uid, get_bosses_revived_notification_text(revived, db.data.get(str(admin_id)), by_admin=True), reply_markup=nav_kb(NAV_BOSSES))
            except Exception as e:
                print(f"[revive notify] {uid}: {e}")
            await asyncio.sleep(0.05)

    who = "игроку" if len(targets) == 1 else "игрокам"
    await reply_to_user(
        message,
        f"✅ Воскрешено: <b>{html.escape(names)}</b>\n"
        f"Откат сброшен {who}: <b>{len(affected)}</b>"
        + ("" if silent or not affected else " · уведомления отправлены")
        + ("\n<i>Ни у кого не было отката на этих боссов.</i>" if not affected else ""),
    )


# ============================================================
# === «лф» — информация об игроке (реплаем) ===
# ============================================================

def _format_last_seen(ts: Any) -> str:
    try:
        delta = int(time.time() - float(ts))
    except (TypeError, ValueError):
        return "неизвестно"
    if delta < 120:
        return "онлайн"
    if delta < 3600:
        return f"{delta // 60} мин. назад"
    if delta < 86400:
        return f"{delta // 3600} ч. назад"
    return f"{delta // 86400} дн. назад"


async def build_player_info_text(target_id: int, user: dict, viewer_is_admin: bool, tg_user=None) -> str:
    e = {
        "title": '<tg-emoji emoji-id="5442879640379076105">👤</tg-emoji>',
        "power": '<tg-emoji emoji-id="5332336747072208845">🔥</tg-emoji>',
        "armor": '<tg-emoji emoji-id="5998843468716184159">❤️‍🔥</tg-emoji>',
        "name": '<tg-emoji emoji-id="5837012579926412863">🪪</tg-emoji>',
        "level": '<tg-emoji emoji-id="5431816358675366190">🆙</tg-emoji>',
        "prestige": '<tg-emoji emoji-id="6278098265162387317">🤩</tg-emoji>',
        "coins": '<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji>',
        "date": '<tg-emoji emoji-id="5028418466000930064">📆</tg-emoji>',
        "sword": '<tg-emoji emoji-id="5373173798633752502">⚔️</tg-emoji>',
        "boss": '<tg-emoji emoji-id="5947121436723252849">👑</tg-emoji>',
        "roll": '<tg-emoji emoji-id="5293998404404272267">🎁</tg-emoji>',
        "paw": '<tg-emoji emoji-id="5258111319831227095">🐾</tg-emoji>',
        "pc": '<tg-emoji emoji-id="5429519916971599983">💻</tg-emoji>',
    }
    name = render_user_nickname(user)
    level = int(user.get("level", 1) or 1)
    xp = int(user.get("xp", 0) or 0)
    rebirths = get_rebirth_count(user)
    armor_hp = calculate_total_armor_hp(user.get("equipped_armor", {slot: None for slot in ARMOR_SLOTS}))
    if user.get("old_badge"):
        joined_text = "олд"
    else:
        try:
            joined_text = datetime.fromisoformat(user.get("joined_at", "")).strftime("%d.%m.%Y")
        except (TypeError, ValueError):
            joined_text = "неизвестно"

    main_block = (
        f"{e['power']} Сила: <b>{format_num(calculate_user_power(user))}</b>\n"
        f"{e['armor']} Броня: <b>+{armor_hp} HP</b>\n"
        f"{e['name']}: <b>{name}</b>\n"
        f"{e['level']}: <b>{level}</b> (<b>{format_num(xp)}/{format_num(get_level_xp_required(level))}</b>)\n"
        f"{e['prestige']}: <b>{format_prestige_name(rebirths)}</b>\n"
        f"{e['coins']}: <b>{format_num(int(user.get('coins', 0) or 0))}</b>\n"
        f"{e['date']}: <b>{joined_text}</b>"
    )

    # Путь и клан
    extra = []
    path = get_user_path(user)
    if path:
        info = PATHS[path]
        extra.append(f"{info.get('premium_emoji', info['emoji'])} Путь: <b>{info['name']}</b> · мастерство <b>{get_path_level(user)}/{PATH_MAX_LEVEL}</b>")
    else:
        extra.append("Путь: <b>не выбран</b>")
    clan = get_user_clan(user)
    if clan:
        role = ((clan.get("members") or {}).get(str(target_id)) or {}).get("role", "member")
        extra.append(
            f"{CLAN_PREMIUM_EMOJI} Клан: <b>[{html.escape(str(clan.get('tag', '')))}] {html.escape(str(clan.get('name', '')))}</b> · "
            f"{format_clan_rank(role)}"
        )
    else:
        extra.append(f"{CLAN_PREMIUM_EMOJI} Клан: <b>нет</b>")

    # Экипировка и питомцы
    gear = []
    weapon = user.get("equipped")
    if isinstance(weapon, dict):
        rarity = RARITIES.get(weapon.get("rarity"), {})
        stars = get_fusion_stars(weapon) if weapon.get("fusion_level") else ""
        gear.append(
            f"{e['sword']} {weapon.get('emoji', '')} <b>{html.escape(str(weapon.get('name', 'Оружие')))}</b> "
            f"{rarity.get('emoji', '')} ур.{weapon.get('weapon_level', 1)}{(' ' + stars) if stars else ''}"
        )
    else:
        gear.append(f"{e['sword']} Оружие: <b>нет</b>")
    armor_count = sum(1 for piece in (user.get("equipped_armor") or {}).values() if piece)
    gear.append(f"Надето брони: <b>{armor_count}/{len(ARMOR_SLOTS)}</b>")
    pet_parts = []
    for slot in range(get_pet_slots(user)):
        pet = get_equipped_pet(user, slot)
        if pet:
            pet_parts.append(f"{get_pet_emoji(pet)} {html.escape(str(pet.get('name', 'Пет')))} ур.{get_pet_level(pet)}")
    gear.append(f"{e['paw']} Питомцы: " + (", ".join(pet_parts) if pet_parts else "<b>нет</b>"))

    stats = [
        f"{e['boss']} Боссов убито: <b>{format_num(int(user.get('boss_kills', 0) or 0))}</b>",
        f"{e['roll']} Роллов: <b>{format_num(int(user.get('chests_opened', 0) or 0))}</b>",
        f"{e['sword']} Урона всего: <b>{format_num(int(user.get('total_damage', 0) or 0))}</b>",
    ]
    if int(user.get("clan_boss_kills", 0) or 0):
        stats.append(f"{CLAN_BOSS_EMOJI} Побед над {CLAN_BOSS_NAME}: <b>{int(user['clan_boss_kills'])}</b>")

    banner = get_user_profile_banner(int(target_id), db.data.get(str(target_id)))
    banner_text = f"{banner}\n\n" if banner else ""
    lf_title = get_active_title(db.data.get(str(target_id)))
    if lf_title:
        banner_text += f"{lf_title}\n\n"  # титул за достижение
    text = (
        f"{e['title']} <b>Игрок</b>\n\n"
        f"{banner_text}"
        f"<blockquote>{main_block}</blockquote>\n\n"
        f"<blockquote>" + "\n".join(extra) + "</blockquote>\n\n"
        f"<blockquote>" + "\n".join(gear) + "</blockquote>\n\n"
        f"<blockquote>" + "\n".join(stats) + "</blockquote>"
    )

    if viewer_is_admin:
        username = get_user_tg_username(user) or (getattr(tg_user, "username", None) or "")
        banned = await is_user_banned(target_id)
        admin_lines = [
            f"ID: <code>{target_id}</code>",
            f"Юзернейм: {('@' + html.escape(username)) if username else '<i>нет</i>'}",
            f"Был в боте: <b>{_format_last_seen(user.get('last_seen_at'))}</b>",
            f"Очки талантов: <b>{get_skill_points(user)}</b> · вложено: <b>{get_spent_skill_points(user)}</b>",
            f"Предметов: <b>{len(user.get('inventory') or [])}</b>/{MAX_INVENTORY} · питомцев: <b>{len(user.get('pets') or [])}</b>",
            f"Бан: <b>{'да' if banned else 'нет'}</b>",
        ]
        text += f"\n\n{e['pc']} <b>Для админа</b>\n<blockquote>" + "\n".join(admin_lines) + "</blockquote>"
    return text


@dp.message(lambda msg: msg.text and message_command(msg) in ("лф", "lf"))
async def text_player_info(message: Message):
    viewer_id = message.from_user.id
    viewer_is_admin = is_admin_user(viewer_id)
    parts = (message.text or "").split()
    replied = message.reply_to_message
    tg_user = None
    target_id: Optional[int] = None

    if replied and replied.from_user:
        if replied.from_user.is_bot:
            await reply_to_user(message, "Это бот, у него нет профиля.")
            return
        tg_user = replied.from_user
        target_id = replied.from_user.id
    elif viewer_is_admin and len(parts) >= 2 and parts[1].isdigit():
        target_id = int(parts[1])  # админ может смотреть по ID
    else:
        await reply_to_user(
            message,
            "Ответь командой <b>лф</b> на сообщение игрока, чтобы посмотреть его профиль."
            + ("\nАдмину можно и так: <code>лф 123456789</code>" if viewer_is_admin else ""),
        )
        return

    if not await db.has_user(target_id):
        await reply_to_user(message, "У этого игрока ещё нет профиля в боте.")
        return
    user = await db.get_user(target_id)
    if user.get("lf_hidden") and user.get("lf_hide_owned") and not viewer_is_admin and viewer_id != target_id:
        await reply_to_user(
            message,
            f"<blockquote>{PE_STAR} <b>{render_user_nickname(user)}</b> скрыл свой профиль от других игроков.</blockquote>",
        )
        return
    await reply_to_user(message, await build_player_info_text(target_id, user, viewer_is_admin, tg_user))


# ============================================================
# === Передача монет между игроками ===
# «передать 1000» реплаем на игрока → подтверждение → перевод
# ============================================================

COIN_TRANSFER_MIN_AMOUNT = 1
COIN_TRANSFER_MIN_LEVEL = 5          # с какого уровня можно отправлять (защита от твинков)
COIN_TRANSFER_FEE_PERCENT = 0        # комиссия, % (0 — без комиссии)
COIN_TRANSFER_CONFIRM_TTL = 5 * 60
COIN_TRANSFER_DAILY_RECEIVE_LIMIT = 50_000  # сколько монет игрок может получить от других за сутки
pending_coin_transfers: Dict[str, dict] = {}
_coin_transfer_lock = asyncio.Lock()


def parse_coin_amount(text: str) -> Optional[int]:
    """1000, 1 000, 10к, 1.5к, 2м."""
    t = (text or "").strip().lower().replace(" ", "").replace(",", ".")
    m = re.fullmatch(r"(\d+(?:\.\d+)?)(к|k|кк|м|m)?", t)
    if not m:
        return None
    value = float(m.group(1))
    mult = {"к": 1_000, "k": 1_000, "кк": 1_000_000, "м": 1_000_000, "m": 1_000_000}.get(m.group(2) or "", 1)
    amount = int(value * mult)
    return amount if amount > 0 else None


def get_coins_received_today(user: Optional[dict]) -> int:
    if not user:
        return 0
    return int(ensure_daily_stats(user).get("coins_received", 0) or 0)


def get_coin_receive_left(user: Optional[dict]) -> int:
    return max(0, COIN_TRANSFER_DAILY_RECEIVE_LIMIT - get_coins_received_today(user))


def format_time_until_daily_reset() -> str:
    now = get_msk_now()
    tomorrow = (now + timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
    return format_clan_boss_time(int((tomorrow - now).total_seconds()))


def get_coin_transfer_fee(amount: int) -> int:
    return math.ceil(amount * COIN_TRANSFER_FEE_PERCENT / 100) if COIN_TRANSFER_FEE_PERCENT > 0 else 0


COIN_E = '<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji>'


@dp.message(lambda msg: msg.text and message_command(msg) in ("передать", "перевод", "перевести", "pay"))
async def text_coin_transfer(message: Message):
    uid = message.from_user.id
    parts = (message.text or "").split()
    usage = (
        f"{COIN_E} <b>Передача монет</b>\n\n"
        "<blockquote>Ответь на сообщение игрока: <code>передать 1000</code>\n"
        "Можно сокращённо: <code>передать 10к</code>, <code>передать 1.5к</code>, <code>передать все</code>\n"
        f"Один игрок может получить не больше <b>{format_num(COIN_TRANSFER_DAILY_RECEIVE_LIMIT)}</b> монет в день.</blockquote>"
    )
    replied = message.reply_to_message
    if len(parts) < 2 or not replied or not replied.from_user:
        await reply_to_user(message, usage)
        return
    target = replied.from_user
    if target.is_bot:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Боту монеты не нужны.")
        return
    if target.id == uid:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Нельзя передать монеты самому себе.")
        return
    sender = await db.get_user(uid)
    if not sender:
        return
    if not await db.has_user(target.id):
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> У этого игрока нет профиля в боте.")
        return
    if await is_user_banned(target.id):
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Этот игрок заблокирован.")
        return
    if int(sender.get("level", 1)) < COIN_TRANSFER_MIN_LEVEL and not is_admin_user(uid):
        await reply_to_user(message, f"<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Передавать монеты можно с <b>{COIN_TRANSFER_MIN_LEVEL}</b> уровня.")
        return

    balance = int(sender.get("coins", 0) or 0)
    if parts[1].lower() in ("все", "всё", "all"):
        # «все» — с учётом комиссии, чтобы хватило
        amount = int(balance * 100 / (100 + COIN_TRANSFER_FEE_PERCENT)) if COIN_TRANSFER_FEE_PERCENT else balance
    else:
        amount = parse_coin_amount("".join(parts[1:3]) if len(parts) > 2 and parts[2].lower() in ("к", "k", "м", "m") else parts[1])
    if not amount or amount < COIN_TRANSFER_MIN_AMOUNT:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Не понял сумму.\n\n" + usage)
        return
    fee = get_coin_transfer_fee(amount)
    if balance < amount + fee:
        await reply_to_user(
            message,
            f"<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Не хватает монет: нужно <b>{format_num(amount + fee)}</b> {COIN_E}, у тебя <b>{format_num(balance)}</b>.",
        )
        return

    receiver = await db.get_user(target.id)
    sender_is_admin = is_admin_user(uid)
    receive_left = get_coin_receive_left(receiver)
    if parts[1].lower() in ("все", "всё", "all") and not sender_is_admin:
        amount = min(amount, receive_left)
        fee = get_coin_transfer_fee(amount)
    if not sender_is_admin and amount > receive_left:
        if receive_left <= 0:
            await reply_to_user(
                message,
                f"<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> <b>{render_user_nickname(receiver, str('Игрок'))}</b> уже получил сегодня максимум "
                f"<b>{format_num(COIN_TRANSFER_DAILY_RECEIVE_LIMIT)}</b> {COIN_E}.\n"
                f"Лимит обновится через {format_time_until_daily_reset()}.",
            )
        else:
            await reply_to_user(
                message,
                f"<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Сегодня этому игроку можно передать ещё только <b>{format_num(receive_left)}</b> {COIN_E} "
                f"(лимит {format_num(COIN_TRANSFER_DAILY_RECEIVE_LIMIT)} в день).",
            )
        return
    if not amount:
        await reply_to_user(message, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Нечего передавать.")
        return
    token = f"{uid}_{target.id}_{int(time.time() * 1000) % 10**9}"
    pending_coin_transfers[token] = {
        "from": uid, "to": target.id, "amount": amount, "fee": fee, "created": time.time(),
    }
    for key, pend in list(pending_coin_transfers.items()):
        if time.time() - pend.get("created", 0) > COIN_TRANSFER_CONFIRM_TTL:
            pending_coin_transfers.pop(key, None)

    fee_line = f"\nКомиссия: <b>{format_num(fee)}</b> {COIN_E} ({COIN_TRANSFER_FEE_PERCENT}%)" if fee else ""
    text = (
        f"{COIN_E} <b>Передача монет</b>\n\n"
        f"<blockquote>Кому: <b>{render_user_nickname(receiver, str(target.first_name or 'Игрок'))}</b>\n"
        f"Сумма: <b>{format_num(amount)}</b> {COIN_E}{fee_line}\n"
        f"Спишется: <b>{format_num(amount + fee)}</b> · останется <b>{format_num(balance - amount - fee)}</b>"
        + ("" if sender_is_admin else
           f"\nЛимит получателя сегодня: <b>{format_num(receive_left - amount)}</b> из {format_num(COIN_TRANSFER_DAILY_RECEIVE_LIMIT)} останется")
        + "</blockquote>\n\n"
        "Подтверди перевод — отменить его потом будет нельзя."
    )
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="Передать", callback_data=f"pay_ok|{token}", icon_custom_emoji_id="5325762861539016690")],
        [InlineKeyboardButton(text="Отмена", callback_data=f"pay_no|{token}", icon_custom_emoji_id="5352669272575321097")],
    ])
    await reply_to_user(message, text, kb)


@dp.callback_query(F.data.startswith("pay_no|"))
async def cb_coin_transfer_cancel(call: CallbackQuery):
    token = call.data.split("|", 1)[1]
    pend = pending_coin_transfers.get(token)
    if pend and pend["from"] != call.from_user.id:
        await call.answer("Это не твой перевод.", show_alert=True)
        return
    pending_coin_transfers.pop(token, None)
    await call.answer("Отменено")
    await edit_for_user(call, "<tg-emoji emoji-id=\"5352669272575321097\">❌</tg-emoji> Передача монет отменена.", None)


@dp.callback_query(F.data.startswith("pay_ok|"))
async def cb_coin_transfer_confirm(call: CallbackQuery):
    token = call.data.split("|", 1)[1]
    pend = pending_coin_transfers.get(token)
    if not pend or time.time() - pend.get("created", 0) > COIN_TRANSFER_CONFIRM_TTL:
        pending_coin_transfers.pop(token, None)
        await call.answer("Подтверждение устарело. Напиши команду заново.", show_alert=True)
        return
    if pend["from"] != call.from_user.id:
        await call.answer("Это не твой перевод.", show_alert=True)
        return
    async with _coin_transfer_lock:
        # второй раз по той же кнопке не сработает
        if pending_coin_transfers.pop(token, None) is None:
            await call.answer("Перевод уже выполнен.", show_alert=True)
            return
        sender = await db.get_user(pend["from"])
        receiver = await db.get_user(pend["to"]) if await db.has_user(pend["to"]) else None
        amount, fee = int(pend["amount"]), int(pend["fee"])
        if not sender or not receiver:
            await call.answer("Игрок не найден.", show_alert=True)
            return
        if int(sender.get("coins", 0) or 0) < amount + fee:
            await call.answer("Не хватает монет.", show_alert=True)
            return
        sender_is_admin = is_admin_user(pend["from"])
        if not sender_is_admin and amount > get_coin_receive_left(receiver):
            left = get_coin_receive_left(receiver)
            await call.answer(
                f"Игрок уже получил сегодня почти весь лимит. Можно передать ещё {format_num(left)}." if left
                else "Игрок уже получил сегодня максимум монет. Попробуй завтра.",
                show_alert=True,
            )
            return
        sender["coins"] = int(sender.get("coins", 0)) - amount - fee
        receiver["coins"] = int(receiver.get("coins", 0) or 0) + amount
        if not sender_is_admin:
            stats = ensure_daily_stats(receiver)
            stats["coins_received"] = int(stats.get("coins_received", 0) or 0) + amount
        set_log_context(f"передача монет {pend['from']} → {pend['to']}")
        await db.save_user(pend["from"], sender)
        await db.save_user(pend["to"], receiver)
    await write_activity_log(
        f"PAY {_log_user_name(pend['from'], sender)} → {_log_user_name(pend['to'], receiver)} | "
        f"{amount} монет" + (f", комиссия {fee}" if fee else "")
    )
    sender_name = render_user_nickname(sender)
    receiver_name = render_user_nickname(receiver)
    await call.answer("Монеты переданы!")
    await edit_for_user(
        call,
        f"{PE_OK} <b>{sender_name}</b> передал <b>{receiver_name}</b> "
        f"<b>{format_num(amount)}</b> {COIN_E}",
        None,
    )
    await send_user_notification(
        pend["to"],
        f"<blockquote>{COIN_E} <b>Тебе перевели монеты!</b>\n"
        f"От: <b>{sender_name}</b>\n"
        f"Сумма: <b>+{format_num(amount)}</b> {COIN_E}\n"
        f"Баланс: <b>{format_num(int(receiver.get('coins', 0)))}</b>\n"
        f"Можно получить сегодня ещё: <b>{format_num(get_coin_receive_left(receiver))}</b></blockquote>",
        reply_markup=nav_kb(NAV_PROFILE),
    )


