ESSENCE_RARITY_ALIASES = {
    "common": "common", "обычная": "common", "обычное": "common", "обыч": "common",
    "uncommon": "uncommon", "необычная": "uncommon", "необычное": "uncommon", "необыч": "uncommon",
    "rare": "rare", "редкая": "rare", "редкое": "rare", "редк": "rare",
    "epic": "epic", "эпическая": "epic", "эпическое": "epic", "эпик": "epic",
    "legendary": "legendary", "легендарная": "legendary", "легендарное": "legendary", "лега": "legendary",
    "mythic": "mythic", "мифическая": "mythic", "мифическое": "mythic", "миф": "mythic",
    "nightmare": "nightmare", "кошмарная": "nightmare", "кошмарное": "nightmare", "кошмар": "nightmare",
}


def resolve_essence_rarity(text: str) -> Optional[str]:
    q = (text or "").strip().lower().replace("ё", "е")
    if q.startswith("essence_"):
        q = q[len("essence_"):]
    return ESSENCE_RARITY_ALIASES.get(q)


def is_weapon_item(item: Any) -> bool:
    return isinstance(item, dict) and not item.get("slot") and (item.get("item_type") == "weapon" or "dmg" in item)


async def admin_adjust_prestige(message: Message, give: bool):
    usage = "пр+ 1" if give else "пр- 1"
    amount, error = parse_admin_amount_command(message, usage)
    if error:
        await reply_to_user(message, error, parse_mode="HTML")
        return
    target, user = await get_admin_reply_target_user(message, usage)
    if not target:
        return
    max_prestige = len(REBIRTH_REQUIREMENTS)
    old = get_rebirth_count(user)
    new = min(max_prestige, old + amount) if give else max(0, old - amount)
    user["rebirths"] = new
    normalize_pet_storage(user)  # слоты питомцев зависят от престижа
    await save_runtime_state(target.id, user)
    await write_activity_log(f"ADMIN {_log_user_name(message.from_user.id)} | престиж {_log_user_name(target.id, user)}: {old} → {new}")
    limit_note = f"\nМаксимум — {max_prestige} престиж." if give and old + amount > max_prestige else ""
    await reply_to_user(
        message,
        f"{PE_OK} <b>{html.escape(target.first_name or 'Игрок')}</b>: престиж {old} → <b>{new}</b>.{limit_note}",
    )


async def admin_adjust_essence(message: Message, give: bool):
    usage = "эс+ эпическая 5" if give else "эс- эпическая 5"
    if message.from_user.id not in ADMIN_IDS:
        await reply_to_user(message, premium_cross("❌ Команда только для админов."))
        return
    parts = (message.text or "").split()
    rarities_help = ", ".join(f"<code>{r}</code>" for r in RARITY_ORDER[::-1])
    if len(parts) != 3:
        await reply_to_user(
            message,
            f"Напиши так: <b>{usage}</b> реплаем на игрока.\n"
            f"Редкость: {rarities_help} или по-русски (обычная, эпическая, кошмарная…), либо <code>все</code>.",
        )
        return
    try:
        amount = int(parts[2])
    except ValueError:
        await reply_to_user(message, "Количество должно быть числом.")
        return
    if amount <= 0:
        await reply_to_user(message, "Количество должно быть больше нуля.")
        return
    if parts[1].lower() in ("все", "всё", "all"):
        rarities = list(RARITIES.keys())
    else:
        rarity = resolve_essence_rarity(parts[1])
        if not rarity:
            await reply_to_user(message, f"{premium_cross('❌')} Не понял редкость. Варианты: {rarities_help}.")
            return
        rarities = [rarity]
    target, user = await get_admin_reply_target_user(message, usage)
    if not target:
        return
    loot = user.setdefault("boss_loot", {})
    lines = []
    for rarity in rarities:
        rid = get_essence_id_for_rarity(rarity)
        old = int(loot.get(rid, 0) or 0)
        new = old + amount if give else max(0, old - amount)
        if new > 0:
            loot[rid] = new
        else:
            loot.pop(rid, None)
        info = BOSS_RESOURCE_DEFS.get(rid, {})
        lines.append(f"{info.get('emoji', '')} {html.escape(str(info.get('name', rid)))}: {old} → <b>{new}</b>")
    await save_runtime_state(target.id, user)
    await write_activity_log(
        f"ADMIN {_log_user_name(message.from_user.id)} | эссенция {'+' if give else '-'}{amount} "
        f"({', '.join(rarities)}) → {_log_user_name(target.id, user)}"
    )
    await reply_to_user(
        message,
        f"{PE_OK} <b>{html.escape(target.first_name or 'Игрок')}</b>, эссенция:\n<blockquote>" + "\n".join(lines) + "</blockquote>",
    )


def _admin_weapon_label(item: dict, equipped_iid: Any) -> str:
    rarity = RARITIES.get(item.get("rarity"), {})
    stars = get_fusion_stars(item) if item.get("fusion_level") else ""
    mark = " (надето)" if item.get("iid") and item.get("iid") == equipped_iid else ""
    return f"{rarity.get('emoji', '')} {item.get('name', 'Оружие')} ур.{item.get('weapon_level', 1)}{(' ' + stars) if stars else ''}{mark}"


def _admin_remove_weapon(user: dict, iid: Any) -> Optional[dict]:
    inv = user.get("inventory") or []
    for idx, item in enumerate(inv):
        if is_weapon_item(item) and str(item.get("iid")) == str(iid):
            inv.pop(idx)
            equipped = user.get("equipped")
            if isinstance(equipped, dict) and str(equipped.get("iid")) == str(iid):
                user["equipped"] = None
            return item
    equipped = user.get("equipped")
    if isinstance(equipped, dict) and str(equipped.get("iid")) == str(iid):
        user["equipped"] = None
        return equipped
    return None


def build_admin_weapon_take_view(target_id: int, target_name: str, user: dict) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    equipped = user.get("equipped") if isinstance(user.get("equipped"), dict) else None
    equipped_iid = equipped.get("iid") if equipped else None
    weapons = [it for it in (user.get("inventory") or []) if is_weapon_item(it)]
    if equipped and not any(str(w.get("iid")) == str(equipped_iid) for w in weapons):
        weapons.insert(0, equipped)
    order = {r: i for i, r in enumerate(RARITY_ORDER)}
    weapons.sort(key=lambda w: (str(w.get("iid")) != str(equipped_iid), order.get(w.get("rarity"), 99), -int(w.get("weapon_level", 1) or 1)))
    name = render_user_nickname(user, target_name)
    if not weapons:
        return f"У <b>{name}</b> нет оружия.", None
    shown = weapons[:40]
    rows = [[InlineKeyboardButton(
        text=_admin_weapon_label(w, equipped_iid)[:60],
        callback_data=f"adm_wtake|{target_id}|{w.get('iid')}",
    )] for w in shown if w.get("iid")]
    rows.append([InlineKeyboardButton(text="Закрыть", callback_data=f"adm_wtake_close|{target_id}", icon_custom_emoji_id="5352669272575321097")])
    more = f"\nПоказаны первые 40 из {len(weapons)}. Остальные: <code>оруж- название</code>." if len(weapons) > 40 else ""
    text = (
        f"{premium_cross('❌')} <b>Забрать оружие</b> у <b>{name}</b>\n\n"
        f"<blockquote>Нажми на оружие — оно сразу пропадёт у игрока. Надетое тоже снимется.</blockquote>{more}"
    )
    return text, InlineKeyboardMarkup(inline_keyboard=rows)


async def admin_take_weapon(message: Message):
    if message.from_user.id not in ADMIN_IDS:
        await reply_to_user(message, premium_cross("❌ Команда только для админов."))
        return
    target, user = await get_admin_reply_target_user(message, "оруж-")
    if not target:
        return
    parts = (message.text or "").split()
    args = parts[1:]
    if not args:
        text, kb = build_admin_weapon_take_view(target.id, target.first_name or "Игрок", user)
        await reply_to_user(message, text, kb)
        return
    # «оруж- название [кол-во]» или «оруж- все»
    amount = None
    if len(args) >= 2 and args[-1].isdigit():
        amount = int(args[-1])
        args = args[:-1]
    query = " ".join(args).strip().lower()
    weapons = [it for it in (user.get("inventory") or []) if is_weapon_item(it)]
    if query in ("все", "всё", "all"):
        matched = weapons
    else:
        matched = [
            w for w in weapons
            if query == str(w.get("id", "")).lower() or query in str(w.get("name", "")).lower()
        ]
    if not matched:
        await reply_to_user(message, f"{premium_cross('❌')} У игрока нет оружия по запросу «{html.escape(query)}».")
        return
    if amount:
        matched = matched[:amount]
    removed = []
    for w in list(matched):
        item = _admin_remove_weapon(user, w.get("iid"))
        if item:
            removed.append(item.get("name", "Оружие"))
    await save_runtime_state(target.id, user)
    await write_activity_log(
        f"ADMIN {_log_user_name(message.from_user.id)} | забрал оружие у {_log_user_name(target.id, user)}: {', '.join(removed)}"
    )
    shown = ", ".join(html.escape(n) for n in removed[:10]) + (" …" if len(removed) > 10 else "")
    await reply_to_user(message, f"{PE_OK} Забрано у <b>{html.escape(target.first_name or 'Игрок')}</b>: {len(removed)} шт.\n{shown}")


@dp.callback_query(F.data.startswith("adm_wtake|"))
async def cb_admin_take_weapon(call: CallbackQuery):
    if call.from_user.id not in ADMIN_IDS:
        await call.answer("Только для админов.", show_alert=True)
        return
    try:
        _, target_id, iid = call.data.split("|", 2)
        target_id = int(target_id)
    except ValueError:
        await call.answer("Некорректные данные.", show_alert=True)
        return
    user = await db.get_user(target_id) if await db.has_user(target_id) else None
    if not user:
        await call.answer("Игрок не найден.", show_alert=True)
        return
    item = _admin_remove_weapon(user, iid)
    if not item:
        await call.answer("Этого оружия уже нет.", show_alert=True)
    else:
        await save_runtime_state(target_id, user)
        await write_activity_log(
            f"ADMIN {_log_user_name(call.from_user.id)} | забрал оружие у {_log_user_name(target_id, user)}: {item.get('name')}"
        )
        await call.answer(f"Забрано: {item.get('name', 'оружие')}")
    text, kb = build_admin_weapon_take_view(target_id, str(user.get("name") or "Игрок"), user)
    await edit_for_user(call, text, kb)


