@dp.message(lambda msg: msg.text and re.match(r"^скрещ[+-](\s+\d+)?$", msg.text.lower().strip()) is not None)
async def text_admin_fusion_guarantee(message: Message):
    if message.from_user.id not in ADMIN_IDS:
        return
    text = message.text.lower().strip()
    enable = text.startswith("скрещ+")
    target, user = await get_admin_reply_target_user(message, "скрещ+ (или скрещ+ 3)")
    if not target:
        return
    name = render_user_nickname(user, target.first_name or "Игрок")
    if enable:
        parts = text.split()
        left = int(parts[1]) if len(parts) > 1 else None
        user["fusion_guarantee"] = {"left": left, "by": message.from_user.id, "ts": time.time()}
        how = f"на <b>{left}</b> попыт." if left else "до отключения"
        how = how.replace("попыт.", "попытку" if left == 1 else ("попытки" if left and 2 <= left % 10 <= 4 and not 12 <= left % 100 <= 14 else "попыток"))
        await save_runtime_state(target.id, user)
        await write_activity_log(f"ADMIN {_log_user_name(message.from_user.id)} | гарантия скрещивания 100% для {_log_user_name(target.id, user)} ({how})")
        await reply_to_user(message, f"{PE_OK} <b>{name}</b>: скрещивание <b>100%</b> {how}.\nВыключить: <code>скрещ-</code> реплаем.")
    else:
        had = bool(user.pop("fusion_guarantee", None))
        await save_runtime_state(target.id, user)
        await write_activity_log(f"ADMIN {_log_user_name(message.from_user.id)} | гарантия скрещивания снята с {_log_user_name(target.id, user)}")
        await reply_to_user(message, f"{PE_OK} <b>{name}</b>: гарантия скрещивания снята." if had else f"У <b>{name}</b> гарантии не было.")


