# Варятся у алхимика отдельно от обычных зелий, между собой не меняются.
# ============================================================

ENEMY_POTION_DEFS = {
    "poison_flask": {
        "name": "Флакон яда",
        "emoji": '<tg-emoji emoji-id="5474265685125271190">🩸</tg-emoji>',
        "icon_id": "5474265685125271190",
        "description": "Все враги 3 хода теряют по 60% твоего среднего удара",
        "weight": 30,
    },
    "weakness_brew": {
        "name": "Отвар слабости",
        "emoji": '<tg-emoji emoji-id="5354961788678978979">🤕</tg-emoji>',
        "icon_id": "5354961788678978979",
        "description": "Враги 3 хода бьют на 25% слабее",
        "weight": 30,
    },
    "curse_vial": {
        "name": "Склянка уязвимости",
        "emoji": '<tg-emoji emoji-id="5368451104134685900">💥</tg-emoji>',
        "icon_id": "5368451104134685900",
        "description": "Твои следующие 3 удара наносят на 25% больше урона",
        "weight": 25,
    },
    "stun_bomb": {
        "name": "Оглушающая бомба",
        "emoji": '<tg-emoji emoji-id="5463274047771000031">😵</tg-emoji>',
        "icon_id": "5463274047771000031",
        "description": "Враги пропускают свой следующий ход",
        "weight": 15,
    },
}
ENEMY_POTION_COST = {"swamp_crystal": 3}
ENEMY_POTIONS_PER_RAID = 3          # не больше 3 бросков за рейд
ENEMY_POTION_DEBUFF_TURNS = 3
ENEMY_POTION_POISON_RATIO = 0.6


def get_enemy_potions(user: Optional[dict]) -> Dict[str, int]:
    pots = (user or {}).setdefault("enemy_potions", {}) if user is not None else {}
    for key in list(pots):
        if key not in ENEMY_POTION_DEFS or int(pots.get(key, 0) or 0) <= 0:
            pots.pop(key, None)
    return pots


def estimate_player_avg_hit(user: dict, battle: dict) -> int:
    ctx = battle_user_context(user, battle)
    level = int(user.get("level", 1) or 1)
    equipped = user.get("equipped")
    if equipped:
        lo, hi = scale_weapon_damage(equipped.get("dmg", (1, 2)), level)
    else:
        lo, hi = 1 + level // 3, 3 + level // 2
    return max(1, math.ceil((int(lo) + int(hi)) / 2 * get_damage_multiplier(ctx)))


# ---------- Алхимик: вкладка ----------

async def show_alchemist_enemy_potions(user_id: int, answer_func):
    user = await db.get_user(user_id)
    pots = get_enemy_potions(user)
    crystals = get_resource_count(user, "swamp_crystal")
    crystal_info = BOSS_RESOURCE_DEFS.get("swamp_crystal", {})
    need = ENEMY_POTION_COST["swamp_crystal"]
    total_w = sum(d["weight"] for d in ENEMY_POTION_DEFS.values())
    lines = []
    for pid, d in ENEMY_POTION_DEFS.items():
        lines.append(
            f"{d['emoji']} <b>{d['name']}</b>: {int(pots.get(pid, 0))} шт. · шанс {100 * d['weight'] / total_w:.0f}%\n"
            f"<i>{d['description']}</i>"
        )
    text = (
        '<tg-emoji emoji-id="5276124975311370560">👀</tg-emoji> <b>Алхимик Петросян · зелья против врагов</b>\n\n'
        "<blockquote>Сварю тебе случайное зелье, которое можно бросить во врагов прямо в рейде "
        f"(кнопка 🎒 в бою). Не больше {ENEMY_POTIONS_PER_RAID} бросков за рейд.\n"
        "С обычными зельями они не меняются.</blockquote>\n\n"
        f"<blockquote>Цена: <b>{need}</b> {crystal_info.get('emoji', '')} {html.escape(str(crystal_info.get('name', 'болотных кристалла')))}\n"
        f"У тебя: <b>{crystals}</b></blockquote>\n\n"
        "<blockquote>" + "\n\n".join(lines) + "</blockquote>"
    )
    rows = []
    if crystals >= need:
        rows.append([InlineKeyboardButton(text=f"Сварить · {need} кристалла", callback_data="alch_enemy_brew|1", icon_custom_emoji_id="5474265685125271190")])
        if crystals >= need * 5:
            rows.append([InlineKeyboardButton(text=f"Сварить 5 · {need * 5} кристаллов", callback_data="alch_enemy_brew|5", icon_custom_emoji_id="5474265685125271190")])
    else:
        rows.append([InlineKeyboardButton(text=f"Нужно {need} болотных кристалла", callback_data="noop", icon_custom_emoji_id="5352669272575321097")])
    rows.append([InlineKeyboardButton(text="Обмен зелий", callback_data="alch_menu", icon_custom_emoji_id="5215361191051798408")])
    await answer_func(text, InlineKeyboardMarkup(inline_keyboard=rows))


