@dp.callback_query(F.data.startswith("alch_enemy_brew|"))
async def cb_alchemist_enemy_brew(call: CallbackQuery):
    uid = call.from_user.id
    try:
        count = max(1, min(5, int(call.data.split("|", 1)[1])))
    except ValueError:
        count = 1
    user = await db.get_user(uid)
    need = ENEMY_POTION_COST["swamp_crystal"] * count
    if get_resource_count(user, "swamp_crystal") < need:
        await call.answer(f"Нужно {need} болотных кристаллов.", show_alert=True)
        return
    loot = user.setdefault("boss_loot", {})
    loot["swamp_crystal"] = int(loot.get("swamp_crystal", 0)) - need
    if loot["swamp_crystal"] <= 0:
        loot.pop("swamp_crystal", None)
    pots = get_enemy_potions(user)
    got = []
    ids = list(ENEMY_POTION_DEFS)
    weights = [ENEMY_POTION_DEFS[i]["weight"] for i in ids]
    for _ in range(count):
        pid = random.choices(ids, weights=weights, k=1)[0]
        pots[pid] = int(pots.get(pid, 0)) + 1
        got.append(ENEMY_POTION_DEFS[pid]["name"])
    await db.save_user(uid, user)
    summary = ", ".join(f"{n} ×{got.count(n)}" for n in dict.fromkeys(got))
    await call.answer(f"Сварено: {summary}", show_alert=True)
    await show_alchemist_enemy_potions(uid, lambda t, kb: edit_for_user(call, t, kb))


# ---------- Рюкзак в бою ----------

def build_battle_backpack_keyboard(user: dict, battle: dict) -> InlineKeyboardMarkup:
    pots = get_enemy_potions(user)
    used = int(battle.get("enemy_potions_used", 0))
    rows = []
    for pid, d in ENEMY_POTION_DEFS.items():
        cnt = int(pots.get(pid, 0))
        if cnt <= 0:
            continue
        rows.append([InlineKeyboardButton(
            text=f"{d['name']} ×{cnt}",
            callback_data=f"battle_throw|{pid}",
            icon_custom_emoji_id=d["icon_id"],
        )])
    if not rows:
        rows.append([InlineKeyboardButton(text="Нет зелий — свари у алхимика", callback_data="noop", icon_custom_emoji_id="5352669272575321097")])
    rows.append([InlineKeyboardButton(
        text=f"Назад · бросков {used}/{ENEMY_POTIONS_PER_RAID}",
        callback_data="battle_skill_back",
        icon_custom_emoji_id="5215361191051798408",
    )])
    return InlineKeyboardMarkup(inline_keyboard=rows)


@dp.callback_query(F.data == "battle_backpack")
async def cb_battle_backpack(call: CallbackQuery):
    uid = call.from_user.id
    battle = active_battles.get(uid)
    if not battle:
        await call.answer("Боя нет.", show_alert=True)
        return
    if battle.get("mode") != "bosses":
        await call.answer("Зелья против врагов работают только в рейдах на боссов.", show_alert=True)
        return
    user = await db.get_user(uid)
    await call.answer()
    kb = build_battle_backpack_keyboard(user, battle)
    await edit_battle_markup(call, kb)


@dp.callback_query(F.data.startswith("battle_throw|"))
async def cb_battle_throw(call: CallbackQuery):
    uid = call.from_user.id
    pid = call.data.split("|", 1)[1]
    lock = battle_locks.setdefault(uid, asyncio.Lock())
    async with lock:
        battle = active_battles.get(uid)
        if not battle or battle.get("mode") != "bosses":
            await call.answer("Боя нет.", show_alert=True)
            return
        if battle.get("busy"):
            await call.answer("Ход уже выполняется.")
            return
        d = ENEMY_POTION_DEFS.get(pid)
        user = await db.get_user(uid)
        pots = get_enemy_potions(user)
        if not d or int(pots.get(pid, 0)) <= 0:
            await call.answer("Такого зелья нет.", show_alert=True)
            return
        if int(battle.get("enemy_potions_used", 0)) >= ENEMY_POTIONS_PER_RAID:
            await call.answer(f"За рейд можно бросить не больше {ENEMY_POTIONS_PER_RAID} зелий.", show_alert=True)
            return
        effects = battle.setdefault("effects", {})
        alive = [e for e in battle.get("enemies", []) if e.get("hp", 0) > 0]
        if not alive:
            await call.answer("Врагов нет.", show_alert=True)
            return
        if pid == "poison_flask":
            if any((e.get("dot") or {}).get("poison") for e in alive):
                await call.answer("Враги уже отравлены.", show_alert=True)
                return
            per_tick = max(1, math.ceil(estimate_player_avg_hit(user, battle) * ENEMY_POTION_POISON_RATIO))
            for e in alive:
                e.setdefault("dot", {})["poison"] = {"damage": per_tick, "turns": ENEMY_POTION_DEBUFF_TURNS}
            log = f"{d['emoji']} <b>{d['name']}</b>: враги отравлены, −{format_num(per_tick)} HP каждому за ход ({ENEMY_POTION_DEBUFF_TURNS} хода)."
        elif pid == "weakness_brew":
            if effects.get("enemy_weak_turns", 0) > 0:
                await call.answer("Слабость уже действует.", show_alert=True)
                return
            effects["enemy_weak_turns"] = ENEMY_POTION_DEBUFF_TURNS
            log = f"{d['emoji']} <b>{d['name']}</b>: враги ослаблены, урон −25% на {ENEMY_POTION_DEBUFF_TURNS} хода."
        elif pid == "curse_vial":
            if effects.get("enemy_vuln_turns", 0) > 0:
                await call.answer("Уязвимость уже действует.", show_alert=True)
                return
            effects["enemy_vuln_turns"] = ENEMY_POTION_DEBUFF_TURNS
            log = f"{d['emoji']} <b>{d['name']}</b>: твой урон +25% на {ENEMY_POTION_DEBUFF_TURNS} удара."
        else:  # stun_bomb
            if effects.get("stun_turns", 0) > 0:
                await call.answer("Враги уже оглушены.", show_alert=True)
                return
            effects["stun_turns"] = 1
            log = f"{d['emoji']} <b>{d['name']}</b>: враги пропустят свой следующий ход."
        pots[pid] = int(pots.get(pid, 0)) - 1
        if pots[pid] <= 0:
            pots.pop(pid, None)
        battle["enemy_potions_used"] = int(battle.get("enemy_potions_used", 0)) + 1
        battle["last_action_at"] = time.time()
        await write_activity_log(f"BOSS {_log_user_name(uid, user)} | бросил «{d['name']}» ({battle['enemy_potions_used']}/{ENEMY_POTIONS_PER_RAID})")
        await save_battle_state_throttled(uid, user, force=True)
        await call.answer(f"Брошено: {d['name']}")
        await edit_battle_message(call, get_battle_text(battle, log), reply_markup=battle_keyboard(battle))


# ============================================================
# === Список кланов, заявки на вступление, чёрный список ===
# ============================================================

CLAN_LIST_PAGE_SIZE = 8
CLAN_APPLICATION_TTL = 3 * 24 * 3600
MAX_PENDING_CLAN_APPLICATIONS = 3
CLAN_APPLY_COOLDOWN = 2 * 60
PE_BLOCK = '<tg-emoji emoji-id="5352669272575321097">❌</tg-emoji>'


def is_clan_blacklisted(clan: dict, user_id: Any) -> bool:
    return str(user_id) in (clan.get("blacklist") or {})


def clean_clan_applications(clan: dict) -> bool:
    """Убирает устаревшие заявки и заявки тех, кто уже в клане. True — если что-то удалено."""
    apps = clan.get("applications") or {}
    changed = False
    for uid_str, app in list(apps.items()):
        u = db.data.get(uid_str)
        if (time.time() - float(app.get("ts", 0)) > CLAN_APPLICATION_TTL) or not u or u.get("clan_id"):
            apps.pop(uid_str, None)
            changed = True
    return changed


def count_user_applications(user_id: int) -> int:
    return sum(1 for c in clans_data.values() if str(user_id) in (c.get("applications") or {}))


def remove_user_applications(user_id: int, except_clan_id: Optional[str] = None) -> List[dict]:
    touched = []
    for c in clans_data.values():
        if c.get("id") == except_clan_id:
            continue
        if (c.get("applications") or {}).pop(str(user_id), None) is not None:
            touched.append(c)
    return touched


def clan_short_line(clan: dict) -> str:
    return f"[{clan.get('tag')}] {clan.get('name')} · ур.{clan.get('level', 1)} · {get_clan_member_count(clan)}/{CLAN_MAX_MEMBERS}"


def player_short_info(user: Optional[dict]) -> str:
    if not user:
        return "профиль не найден"
    return (
        f"ур. <b>{user.get('level', 1)}</b> · престиж <b>{get_rebirth_count(user)}</b> · "
        f"сила <b>{format_num(calculate_user_power(user))}</b>"
    )


# ---------- Список кланов ----------

async def show_clan_list(user_id: int, page: int, answer_func):
    await load_clans()
    await db.load()
    clans = sorted(
        clans_data.values(),
        key=lambda c: (-int(c.get("level", 1)), -calculate_clan_power(c), int(c.get("number") or 0)),
    )
    if not clans:
        await answer_func(f"{CLAN_PREMIUM_EMOJI} <b>Кланы</b>\n\nПока нет ни одного клана — создай первый!", None)
        return
    pages = max(1, math.ceil(len(clans) / CLAN_LIST_PAGE_SIZE))
    page = max(0, min(page, pages - 1))
    chunk = clans[page * CLAN_LIST_PAGE_SIZE:(page + 1) * CLAN_LIST_PAGE_SIZE]
    user = await db.get_user(user_id)
    my_clan_id = (user or {}).get("clan_id")
    rows = []
    for c in chunk:
        mark = " · твой" if c.get("id") == my_clan_id else (" · полон" if get_clan_member_count(c) >= CLAN_MAX_MEMBERS else "")
        rows.append([InlineKeyboardButton(
            text=(clan_short_line(c) + mark)[:60],
            callback_data=f"clan_view|{c['id']}|{page}",
            icon_custom_emoji_id=BTN_CLAN,
        )])
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="◀️", callback_data=f"clan_list|{page - 1}"))
    if pages > 1:
        nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page < pages - 1:
        nav.append(InlineKeyboardButton(text="▶️", callback_data=f"clan_list|{page + 1}"))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton(text="Мой клан" if my_clan_id else "Назад", callback_data="clan_home", icon_custom_emoji_id="5215361191051798408")])
    text = (
        f"{CLAN_PREMIUM_EMOJI} <b>Кланы</b> · всего {len(clans)}\n\n"
        "<blockquote>Нажми на клан, чтобы посмотреть информацию и подать заявку на вступление.</blockquote>"
    )
    await answer_func(text, InlineKeyboardMarkup(inline_keyboard=rows))


async def show_clan_public(user_id: int, clan_id: str, page: int, answer_func):
    await load_clans()
    await db.load()
    clan = get_clan(clan_id)
    if not clan:
        await answer_func(premium_cross("❌ Клан не найден — возможно, его распустили."), InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="К списку", callback_data=f"clan_list|{page}", icon_custom_emoji_id="5215361191051798408")]]))
        return
    if clean_clan_applications(clan):
        await save_clan(clan)
    user = await db.get_user(user_id)
    members = clan.get("members") or {}
    desc = str(clan.get("description") or "").strip()
    desc_block = f"<blockquote expandable>{html.escape(desc)}</blockquote>\n\n" if desc else ""
    roles = collections.Counter((m or {}).get("role", "member") for m in members.values())
    officers = roles.get("officer", 0)
    text = (
        f"{CLAN_PREMIUM_EMOJI} <b>[{html.escape(str(clan.get('tag')))}] {html.escape(str(clan.get('name')))}</b>\n\n"
        f"{desc_block}"
        f"<blockquote>Номер: <b>#{int(clan.get('number') or 0)}</b>\n"
        f"Лидер: <b>{clan_user_name_html(clan.get('leader_id'))}</b>\n"
        f"{PE_LEVELUP} Уровень: <b>{clan.get('level', 1)}</b> / {CLAN_MAX_LEVEL} · бонус +{get_clan_level_bonus(clan, 'damage'):.1f}%\n"
        f"{PE_MEMBERS} Участников: <b>{len(members)}</b> / {CLAN_MAX_MEMBERS} · офицеров {officers}\n"
        f"Сила: <b>{format_num(calculate_clan_power(clan))}</b>\n"
        f"{CLAN_BOSS_EMOJI} Побед над {CLAN_BOSS_NAME}: <b>{int(clan.get('boss_kills', 0))}</b> · тир {int(clan.get('boss_tier', 1))}\n"
        f"Создан: {format_clan_date(clan.get('created_at', 0))}</blockquote>"
    )
    rows = []
    in_this = (user or {}).get("clan_id") == clan["id"]
    applied = str(user_id) in (clan.get("applications") or {})
    if in_this:
        text += f"\n\n<i>Это твой клан.</i>"
    elif (user or {}).get("clan_id"):
        text += "\n\n<i>Ты уже состоишь в клане — подать заявку можно, только выйдя из него.</i>"
    elif is_clan_blacklisted(clan, user_id):
        text += f"\n\n{PE_BLOCK} <i>Ты в чёрном списке этого клана.</i>"
    elif applied:
        text += f"\n\n{PE_OK} <i>Заявка отправлена, ждём ответа офицеров.</i>"
        rows.append([InlineKeyboardButton(text="Отозвать заявку", callback_data=f"clan_app_cancel|{clan['id']}|{page}", icon_custom_emoji_id="5352669272575321097")])
    elif len(members) >= CLAN_MAX_MEMBERS:
        text += "\n\n<i>Клан полон.</i>"
    else:
        rows.append([InlineKeyboardButton(text="Подать заявку", callback_data=f"clan_apply|{clan['id']}|{page}", icon_custom_emoji_id="5325762861539016690")])
    rows.append([InlineKeyboardButton(text="К списку кланов", callback_data=f"clan_list|{page}", icon_custom_emoji_id="5215361191051798408")])
    await answer_func(text, InlineKeyboardMarkup(inline_keyboard=rows))


