# ---------- Заявки ----------

async def notify_clan_officers(clan: dict, text: str, kb: Optional[InlineKeyboardMarkup] = None, perm: str = "invite"):
    for uid_str, m in list((clan.get("members") or {}).items()):
        if clan_has_perm(m or {}, perm):
            try:
                await send_user_notification(int(uid_str), text, reply_markup=kb)
            except Exception as e:
                print(f"[clan notify] {uid_str}: {e}")
            await asyncio.sleep(0.05)


def application_keyboard(clan_id: str, applicant_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="Принять", callback_data=f"clan_app_ok|{clan_id}|{applicant_id}", icon_custom_emoji_id="5325762861539016690"),
        InlineKeyboardButton(text="Отклонить", callback_data=f"clan_app_no|{clan_id}|{applicant_id}", icon_custom_emoji_id="5352669272575321097"),
    ]])


@dp.callback_query(F.data.startswith("clan_apply|"))
async def cb_clan_apply(call: CallbackQuery):
    uid = call.from_user.id
    _, clan_id, page = (call.data.split("|") + ["0"])[:3]
    await load_clans()
    clan = get_clan(clan_id)
    user = await db.get_user(uid)
    if not clan or not user:
        await call.answer("Клан не найден.", show_alert=True)
        return
    clean_clan_applications(clan)
    if user.get("clan_id"):
        await call.answer("Ты уже в клане.", show_alert=True)
        return
    if is_clan_blacklisted(clan, uid):
        await call.answer("Ты в чёрном списке этого клана.", show_alert=True)
        return
    if get_clan_member_count(clan) >= CLAN_MAX_MEMBERS:
        await call.answer("Клан полон.", show_alert=True)
        return
    apps = clan.setdefault("applications", {})
    if str(uid) in apps:
        await call.answer("Заявка уже отправлена.", show_alert=True)
        return
    last_apply = float(user.get("last_clan_apply_at", 0) or 0)
    if time.time() - last_apply < CLAN_APPLY_COOLDOWN:
        await call.answer(f"Подать новую заявку можно через {format_clan_boss_time(int(CLAN_APPLY_COOLDOWN - (time.time() - last_apply)))}.", show_alert=True)
        return
    if count_user_applications(uid) >= MAX_PENDING_CLAN_APPLICATIONS:
        await call.answer(f"Можно держать не больше {MAX_PENDING_CLAN_APPLICATIONS} заявок одновременно. Отзови одну из старых.", show_alert=True)
        return
    apps[str(uid)] = {"ts": time.time(), "name": str(user.get("name") or uid)}
    user["last_clan_apply_at"] = time.time()  # защита от спама уведомлениями офицерам
    await db.save_user(uid, user)
    clan_audit(clan, uid, f"{clan_user_name(uid)} подал заявку на вступление")
    await save_clan(clan)
    await call.answer("Заявка отправлена! Офицеры клана получат уведомление.", show_alert=True)
    await notify_clan_officers(
        clan,
        f"<blockquote>{CLAN_PREMIUM_EMOJI} <b>Заявка в клан [{html.escape(str(clan.get('tag')))}]</b>\n"
        f"От: <b>{render_user_nickname(user, str(uid))}</b>\n{player_short_info(user)}</blockquote>",
        application_keyboard(clan["id"], uid),
    )
    await show_clan_public(uid, clan_id, int(page) if page.isdigit() else 0, lambda t, kb: edit_for_user(call, t, kb))


@dp.callback_query(F.data.startswith("clan_app_cancel|"))
async def cb_clan_app_cancel(call: CallbackQuery):
    uid = call.from_user.id
    _, clan_id, page = (call.data.split("|") + ["0"])[:3]
