@dp.callback_query(F.data.startswith("clan_lead_do|"))
async def cb_clan_leader_do(call: CallbackQuery):
    _, clan_id, member_id = call.data.split("|", 2)
    old_leader = call.from_user.id
    await load_clans()
    clan = get_clan(clan_id)
    if not clan or str(clan.get("leader_id")) != str(old_leader):
        await call.answer("Передать лидерство может только лидер.", show_alert=True)
        return
    members = clan.setdefault("members", {})
    if str(member_id) not in members:
        await call.answer("Игрок уже не в клане.", show_alert=True)
        return
    members[str(member_id)]["role"] = "leader"
    if str(old_leader) in members:
        members[str(old_leader)]["role"] = "officer"
    clan["leader_id"] = int(member_id)
    clan_audit(clan, old_leader, f"{clan_user_name(old_leader)} передал лидерство {clan_user_name(member_id)}")
    await save_clan(clan)
    await call.answer("Лидерство передано!", show_alert=True)
    await send_user_notification(int(member_id), f"<blockquote>{CLAN_PREMIUM_EMOJI} Ты теперь <b>лидер</b> клана <b>[{html.escape(str(clan.get('tag')))}]</b>{PE_ALARM}</blockquote>", reply_markup=nav_kb(NAV_CLAN))
    await show_clan(old_leader, lambda t, kb: edit_for_user(call, t, kb))


