@dp.callback_query(F.data.startswith("clan_bl_do|"))
async def cb_clan_blacklist_do(call: CallbackQuery):
    _, clan_id, member_id = call.data.split("|", 2)
    leader_id = call.from_user.id
    await load_clans()
    clan = get_clan(clan_id)
    if not clan or str(clan.get("leader_id")) != str(leader_id):
        await call.answer("Чёрный список доступен только лидеру.", show_alert=True)
        return
    if str(member_id) == str(leader_id):
        await call.answer("Себя в ЧС не добавить.", show_alert=True)
        return
    name = clan_user_name(member_id)
    clan.setdefault("blacklist", {})[str(member_id)] = {"ts": time.time(), "name": name, "by": leader_id}
    was_member = clan.setdefault("members", {}).pop(str(member_id), None) is not None
    (clan.get("applications") or {}).pop(str(member_id), None)
    target = await db.get_user(int(member_id)) if await db.has_user(int(member_id)) else None
    if was_member and target and target.get("clan_id") == clan["id"]:
        target["clan_id"] = None
        await db.save_user(int(member_id), target)
    clan_audit(clan, leader_id, f"{clan_user_name(leader_id)} добавил {name} в чёрный список" + (" и исключил" if was_member else ""))
    await save_clan(clan)
    await call.answer(f"{name} в чёрном списке.", show_alert=True)
    if was_member:
        await send_user_notification(int(member_id), f"<blockquote>{PE_BLOCK} Тебя исключили из клана <b>[{html.escape(str(clan.get('tag')))}]</b> и добавили в его чёрный список.</blockquote>", reply_markup=nav_kb(NAV_CLAN_LIST))
    await show_clan_blacklist(leader_id, lambda t, kb: edit_for_user(call, t, kb))


async def show_clan_blacklist(user_id: int, answer_func):
    await load_clans()
    user = await db.get_user(user_id)
    clan = get_user_clan(user) if user else None
    if not clan or str(clan.get("leader_id")) != str(user_id):
        await answer_func(premium_cross("❌ Чёрный список доступен только лидеру."), None)
        return
    bl = sorted((clan.get("blacklist") or {}).items(), key=lambda kv: -kv[1].get("ts", 0))
    rows = []
    lines = []
    for uid_str, entry in bl[:20]:
        name = str(entry.get("name") or clan_user_name(uid_str))
        lines.append(f"<b>{clan_user_name_html(uid_str) if str(uid_str) in db.data else html.escape(name)}</b> <code>{uid_str}</code> · с {format_clan_date(entry.get('ts', 0))}")
        rows.append([InlineKeyboardButton(text=f"Убрать из ЧС: {name}"[:45], callback_data=f"clan_bl_rm|{clan['id']}|{uid_str}", icon_custom_emoji_id="5445267414562389170")])
    body = "<blockquote>" + "\n".join(lines) + "</blockquote>" if lines else "<blockquote>Чёрный список пуст.</blockquote>"
    rows.append([InlineKeyboardButton(text="К клану", callback_data=f"clan_back|{clan['id']}", icon_custom_emoji_id=BTN_CLAN)])
    await answer_func(
        f"{PE_BLOCK} <b>Чёрный список [{html.escape(str(clan.get('tag')))}]</b> · {len(bl)}\n\n{body}\n\n"
        "<i>Добавить участника — кнопка «В чёрный список» в его карточке.</i>",
        InlineKeyboardMarkup(inline_keyboard=rows),
    )


