# ============================================================
# === Магазин: механизм автоперезапуска авторолла ===
# После окончания авторолла сам запускает его снова, теряя 1 прочность.
# ============================================================

AUTORESTART_MAX_DURABILITY = 100
AUTORESTART_PACKS = {
    "s": {"charges": 10, "discount": 0.0},
    "l": {"charges": 30, "discount": 0.15},
}
AUTORESTART_ICON = "5346321684574003384"  # 🔄
PE_RESTART = '<tg-emoji emoji-id="5346321684574003384">🔄</tg-emoji>'
PE_GEAR = '<tg-emoji emoji-id="5366231924597604153">⚙️</tg-emoji>'
PE_TOOL = '<tg-emoji emoji-id="5213214428958306222">🛠</tg-emoji>'
PE_STATS = '<tg-emoji emoji-id="5404768823603650652">📊</tg-emoji>'
PE_HOURGLASS = '<tg-emoji emoji-id="5287473790735890430">⏳</tg-emoji>'
PE_ALARM = '<tg-emoji emoji-id="5440660757194744323">‼️</tg-emoji>'


def get_autorestart(user: dict) -> dict:
    data = user.setdefault("autorestart", {})
    data.setdefault("durability", 0)
    data.setdefault("enabled", True)
    data.setdefault("used", 0)
    return data


def get_autorestart_charge_price(user: dict) -> int:
    """Цена одного перезапуска растёт с уровнем: сессия авторолла тоже длиннее."""
    level = int(user.get("level", 1) or 1)
    return 300 + 15 * level


def get_autorestart_pack_price(user: dict, pack_id: str) -> int:
    pack = AUTORESTART_PACKS[pack_id]
    return int(math.ceil(get_autorestart_charge_price(user) * pack["charges"] * (1 - pack["discount"]) / 100) * 100)


def durability_bar(value: int, maximum: int, width: int = 10) -> str:
    filled = max(0, min(width, round(width * value / max(1, maximum))))
    if value > 0 and filled == 0:
        filled = 1
    return "▰" * filled + "▱" * (width - filled)


async def show_shop(user_id: int, answer_func):
    user = await db.get_user(user_id)
    ar = get_autorestart(user)
    coin = '<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji>'
    dur = int(ar["durability"])
    if dur > 0:
        state = (
            f"{PE_GEAR} Состояние: <b>{'включён' if ar['enabled'] else 'выключен'}</b>\n"
            f"{PE_TOOL} Прочность: <b>{dur}/{AUTORESTART_MAX_DURABILITY}</b>\n{durability_bar(dur, AUTORESTART_MAX_DURABILITY)}"
        )
    else:
        state = f"{PE_GEAR} Состояние: <b>нет механизма</b> — купи заряды ниже"
    unlock_note = "" if user.get("auto_roll_unlocked") else "\n\n<i>Авторолл ещё не открыт — сначала выполни задание на роллы.</i>"
    text = (
        '<tg-emoji emoji-id="5440841102871517055">🛒</tg-emoji> <b>Магазин</b>\n\n'
        f"<blockquote>{PE_RESTART} <b>Механизм автоперезапуска</b>\n"
        "Когда авторолл заканчивает работу, механизм сам запускает его снова. "
        "Каждый перезапуск стирает <b>1 прочность</b>; на нуле механизм ломается.\n"
        "Не срабатывает, если сумка авторолла полна — сначала забери лут.</blockquote>\n\n"
        f"<blockquote>{state}\n"
        f"{PE_STATS} Перезапусков сделано: <b>{int(ar.get('used', 0))}</b>\n"
        f"Монеты: <b>{format_num(int(user.get('coins', 0)))}</b> {coin}</blockquote>\n\n"
        "<i>Включить, выключить и посмотреть механизм — команда <b>арп</b>.</i>\n\n"
        + get_bag_shop_block(user)
        + unlock_note
    )
    rows = []
    for pack_id, pack in AUTORESTART_PACKS.items():
        price = get_autorestart_pack_price(user, pack_id)
        sale = f" · −{int(pack['discount'] * 100)}%" if pack["discount"] else ""
        rows.append([InlineKeyboardButton(
            text=f"+{pack['charges']} прочности · {format_num(price)}{sale}",
            callback_data=f"shop_ar_buy|{pack_id}",
            icon_custom_emoji_id="5433594926107481306",
        )])
    rows.append([InlineKeyboardButton(text="Управление механизмом", callback_data="arp", icon_custom_emoji_id=AUTORESTART_ICON)])
    rows.append([InlineKeyboardButton(text="Звёздный магазин", callback_data="star_shop", icon_custom_emoji_id="6269538837723090339")])
    bag_level = get_auto_roll_bag_level(user)
    if bag_level < len(AUTO_ROLL_BAG_PRICES):
        rows.append([InlineKeyboardButton(
            text=f"Сумка: {get_auto_roll_bag_capacity(user)} → {get_auto_roll_bag_capacity(user) + AUTO_ROLL_BAG_STEP} · {format_num(AUTO_ROLL_BAG_PRICES[bag_level])}",
            callback_data="shop_bag_ask",
            icon_custom_emoji_id="5854908544712707500",
        )])
    await answer_func(text, InlineKeyboardMarkup(inline_keyboard=rows))


PE_BAG = '<tg-emoji emoji-id="5854908544712707500">📦</tg-emoji>'


def get_bag_shop_block(user: dict) -> str:
    level = get_auto_roll_bag_level(user)
    cap = get_auto_roll_bag_capacity(user)
    max_cap = AUTO_ROLL_BAG_BASE + AUTO_ROLL_BAG_STEP * len(AUTO_ROLL_BAG_PRICES)
    if level >= len(AUTO_ROLL_BAG_PRICES):
        nxt = f"{PE_OK} Сумка улучшена до максимума"
    else:
        nxt = (f"{PE_LEVELUP} Следующее улучшение: <b>{cap} → {cap + AUTO_ROLL_BAG_STEP}</b> мест "
               f"за <b>{format_num(AUTO_ROLL_BAG_PRICES[level])}</b> монет")
    return (
        f"<blockquote>{PE_BAG} <b>Сумка авторолла</b>\n"
        "Сколько предметов авторолл копит, прежде чем остановиться. Улучшение навсегда.</blockquote>\n\n"
        f"<blockquote>{PE_BAG} Сейчас: <b>{cap}</b> мест (улучшений {level}/{len(AUTO_ROLL_BAG_PRICES)}, максимум {max_cap})\n{nxt}</blockquote>"
    )


@dp.callback_query(F.data == "shop_bag_ask")
async def cb_shop_bag_ask(call: CallbackQuery):
    user = await db.get_user(call.from_user.id)
    level = get_auto_roll_bag_level(user)
    if level >= len(AUTO_ROLL_BAG_PRICES):
        await call.answer("Сумка уже улучшена до максимума.", show_alert=True)
        return
    await call.answer()
    cap = get_auto_roll_bag_capacity(user)
    price = AUTO_ROLL_BAG_PRICES[level]
    coin = '<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji>'
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text=f"Улучшить за {format_num(price)}", callback_data="shop_bag_do", icon_custom_emoji_id="5325762861539016690")],
        [InlineKeyboardButton(text="Назад", callback_data="shop", icon_custom_emoji_id="5215361191051798408")],
    ])
    await edit_for_user(
        call,
        f"{PE_BAG} <b>Улучшение сумки авторолла</b>\n\n"
        f"<blockquote>Места: <b>{cap} → {cap + AUTO_ROLL_BAG_STEP}</b>\n"
        f"Цена: <b>{format_num(price)}</b> {coin}\n"
        f"У тебя: <b>{format_num(int(user.get('coins', 0)))}</b> {coin}</blockquote>",
        kb,
    )


@dp.callback_query(F.data == "shop_bag_do")
async def cb_shop_bag_do(call: CallbackQuery):
    uid = call.from_user.id
    user = await db.get_user(uid)
    level = get_auto_roll_bag_level(user)
    if level >= len(AUTO_ROLL_BAG_PRICES):
        await call.answer("Сумка уже улучшена до максимума.", show_alert=True)
        return
    price = AUTO_ROLL_BAG_PRICES[level]
    if int(user.get("coins", 0)) < price:
        await call.answer(f"Не хватает монет: нужно {format_num(price)}.", show_alert=True)
        return
    user["coins"] = int(user.get("coins", 0)) - price
    user["auto_roll_bag_level"] = level + 1
    await db.save_user(uid, user)
    await write_activity_log(f"SHOP {_log_user_name(uid, user)} | сумка авторолла → {get_auto_roll_bag_capacity(user)} мест за {price}")
    await call.answer(f"Сумка улучшена: {get_auto_roll_bag_capacity(user)} мест!", show_alert=True)
    await show_shop(uid, lambda t, kb: edit_for_user(call, t, kb))


async def show_autorestart_panel(user_id: int, answer_func):
    """«арп» — управление механизмом автоперезапуска."""
    user = await db.get_user(user_id)
    ar = get_autorestart(user)
    dur = int(ar["durability"])
    session = get_auto_roll_session(user_id)
    running = bool(session.get("running")) and time.time() < float(session.get("until", 0))
    if running:
        roll_state = f"{PE_HOURGLASS} Авторолл: <b>работает</b>, ещё {format_clan_boss_time(int(session['until'] - time.time()))}"
    else:
        roll_state = f"{PE_HOURGLASS} Авторолл: <b>не запущен</b>"
    if dur > 0:
        status = "включён" if ar["enabled"] else "выключен"
        hint = ("Сработает, когда авторолл закончит работу." if ar["enabled"]
                else "Выключен — прочность не тратится, авторолл не перезапускается.")
    else:
        status = "сломан" if int(ar.get("used", 0)) else "нет механизма"
        hint = "Купи прочность в магазине: команда <b>Магазин</b>."
    text = (
        f"{PE_RESTART} <b>Механизм автоперезапуска</b>\n\n"
        f"<blockquote>{PE_GEAR} Состояние: <b>{status}</b>\n"
        f"{PE_TOOL} Прочность: <b>{dur}/{AUTORESTART_MAX_DURABILITY}</b>\n{durability_bar(dur, AUTORESTART_MAX_DURABILITY)}\n"
        f"{PE_STATS} Перезапусков сделано: <b>{int(ar.get('used', 0))}</b>\n"
        f"{roll_state}</blockquote>\n\n"
        f"<blockquote>{hint}</blockquote>"
    )
    rows = []
    if dur > 0:
        rows.append([InlineKeyboardButton(
            text="Выключить" if ar["enabled"] else "Включить",
            callback_data="arp_toggle",
            icon_custom_emoji_id="5352669272575321097" if ar["enabled"] else "5325762861539016690",
        )])
    rows.append([InlineKeyboardButton(text="Купить прочность", callback_data="shop", icon_custom_emoji_id="5440841102871517055")])
    rows.append([InlineKeyboardButton(text="Обновить", callback_data="arp", icon_custom_emoji_id="5346321684574003384")])
    await answer_func(text, InlineKeyboardMarkup(inline_keyboard=rows))


