# ============================================================
# === Анонсы в канал: питомцы и экипировка мифической редкости и выше ===
# Бот должен быть администратором канала. ID канала задаётся здесь или командой
# «канал анонсов -100…» (сохраняется в файл настроек).
# ============================================================

ANNOUNCE_CHANNEL_FIXED_ID = -1003688582165         # жёсткая привязка: канал анонсов задан в коде и не слетает
ANNOUNCE_CHANNEL_ID: Optional[int] = ANNOUNCE_CHANNEL_FIXED_ID
ANNOUNCE_ITEM_MIN_RARITY = "mythic"                # экипировка: миф и выше
ANNOUNCE_PET_MIN_RARITY = "epic"                   # питомцы: эпик и выше
ANNOUNCE_SETTINGS_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "lootify_settings.json")
ANNOUNCE_SEND_INTERVAL = 1.5                       # пауза между постами (лимиты Telegram)
_announce_queue: Optional[asyncio.Queue] = None
_announce_last_error_at = 0.0

_RARITY_RANK = {r: i for i, r in enumerate(["common", "uncommon", "rare", "epic", "legendary", "mythic", "nightmare"])}


def _load_announce_settings() -> None:
    """Канал закреплён в коде — файл настроек его больше не меняет."""
    global ANNOUNCE_CHANNEL_ID
    if ANNOUNCE_CHANNEL_FIXED_ID:
        ANNOUNCE_CHANNEL_ID = ANNOUNCE_CHANNEL_FIXED_ID
        return
    try:
        with open(ANNOUNCE_SETTINGS_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if "announce_channel_id" in data:
            ANNOUNCE_CHANNEL_ID = data["announce_channel_id"]
    except FileNotFoundError:
        pass
    except Exception as e:
        print(f"[announce] settings read failed: {e}")


def _save_announce_settings() -> None:
    data = {}
    try:
        with open(ANNOUNCE_SETTINGS_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        pass
    data["announce_channel_id"] = ANNOUNCE_CHANNEL_ID
    with open(ANNOUNCE_SETTINGS_FILE, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)


def _announce_player_name(user_id: int, user: Optional[dict]) -> str:
    """В канал идёт не ник, а @username и ID игрока."""
    uname = (user or {}).get("tg_username")
    if uname:
        return f"@{html.escape(str(uname))} · ID <code>{user_id}</code>"
    return f"ID <code>{user_id}</code>"


def _announce_player_name_old(user_id: int, user: Optional[dict]) -> str:
    return render_user_nickname(user, f"Игрок {user_id}")


def queue_announcement(text: str) -> None:
    global _announce_queue
    log_event_nowait("ANNOUNCE | " + re.sub(r"<[^>]+>", "", text).replace("\n", " / ")[:200]
                     + ("" if ANNOUNCE_CHANNEL_ID else " | НЕ ОТПРАВЛЕНО: канал не задан"))
    if not ANNOUNCE_CHANNEL_ID:
        return
    if _announce_queue is None:  # очередь создаём сразу, чтобы не терять анонсы в первые секунды после запуска
        _announce_queue = asyncio.Queue(maxsize=500)
    try:
        _announce_queue.put_nowait(text)
    except Exception:
        pass


async def announce_worker():
    while True:
        text = await _announce_queue.get()
        try:
            if ANNOUNCE_CHANNEL_ID and NOTIFY_BOT:
                await NOTIFY_BOT.send_message(ANNOUNCE_CHANNEL_ID, text, parse_mode="HTML", disable_web_page_preview=True)
            else:
                log_event_nowait("ANNOUNCE | не отправлено: канал не задан или бот не запущен")
        except Exception as e:
            print(f"[announce] send failed: {e}")
            global _announce_last_error_at
            if time.time() - _announce_last_error_at > 3600:  # не чаще раза в час
                _announce_last_error_at = time.time()
                for admin_id in ADMIN_IDS:
                    await send_user_notification(
                        admin_id,
                        premium_cross(f"<blockquote>❌ Анонс в канал не отправился: <code>{html.escape(str(e))}</code></blockquote>\n\n"
                                      "Проверь командой <code>канал анонсов тест</code>."),
                    )
        await asyncio.sleep(ANNOUNCE_SEND_INTERVAL)


def announce_item_drop(user_id: int, user: dict, item: dict, source: str) -> None:
    rarity = item.get("rarity")
    if _RARITY_RANK.get(rarity, -1) < _RARITY_RANK[ANNOUNCE_ITEM_MIN_RARITY]:
        return
    r_icon = PREMIUM_RARITY_EMOJIS.get(rarity, RARITIES.get(rarity, {}).get("emoji", ""))
    r_name = RARITIES.get(rarity, {}).get("name", rarity)
    kind = "Оружие" if not item.get("slot") else "Броня"
    level = item.get("weapon_level") or item.get("armor_level") or item.get("level") or ""
    level_text = f" · ур. {level}" if level else ""
    queue_announcement(
        f"<blockquote>{r_icon} <b>{r_name}</b> выбито{PE_ALARM}</blockquote>\n\n"
        f"<blockquote>{item.get('emoji', '')} <b>{html.escape(str(item.get('name', 'Предмет')))}</b>{level_text}\n"
        f"{kind} · {source}\n"
        f'<tg-emoji emoji-id="5442879640379076105">👤</tg-emoji> {_announce_player_name(user_id, user)}</blockquote>'
    )


def announce_pet_drop(user_id: int, user: dict, pet: dict, egg_id: str) -> None:
    rarity = pet.get("rarity")
    if _RARITY_RANK.get(rarity, -1) < _RARITY_RANK.get(ANNOUNCE_PET_MIN_RARITY, 0):
        return
    egg = PET_EGGS.get(egg_id, {})
    r_icon = PET_RARITY_PREMIUM_EMOJIS.get(rarity, PET_RARITIES.get(rarity, {}).get("emoji", ""))
    r_name = PET_RARITIES.get(rarity, {}).get("name", rarity)
    queue_announcement(
        f'<blockquote><tg-emoji emoji-id="5332550902731535734">🥚</tg-emoji> <b>Новый питомец</b>{PE_ALARM}</blockquote>\n\n'
        f"<blockquote>{get_pet_emoji(pet)} <b>{html.escape(str(pet.get('name', 'Питомец')))}</b> · {r_icon} {r_name}\n"
        f"Из яйца: {egg.get('shop_emoji', egg.get('emoji', ''))} {html.escape(str(egg.get('name', '?')))}\n"
        f'<tg-emoji emoji-id="5442879640379076105">👤</tg-emoji> {_announce_player_name(user_id, user)}</blockquote>'
    )


@dp.message(lambda msg: msg.text and msg.text.lower().strip().startswith("канал анонсов"))
async def text_announce_channel(message: Message):
    global ANNOUNCE_CHANNEL_ID
    if message.from_user.id not in ADMIN_IDS:
        return
    arg = message.text.strip()[len("канал анонсов"):].strip().lower()
    if ANNOUNCE_CHANNEL_FIXED_ID:
        ANNOUNCE_CHANNEL_ID = ANNOUNCE_CHANNEL_FIXED_ID
        if arg in ("тест", "test", "проверка"):
            await reply_to_user(message, await diagnose_announce_channel(ANNOUNCE_CHANNEL_ID, send_test=True))
            return
        await reply_to_user(
            message,
            f"<blockquote><b>Канал анонсов закреплён в коде:</b> <code>{ANNOUNCE_CHANNEL_FIXED_ID}</code>\n"
            f"Экипировка: от «{RARITIES[ANNOUNCE_ITEM_MIN_RARITY]['name']}» · питомцы: от «{PET_RARITIES[ANNOUNCE_PET_MIN_RARITY]['name']}»</blockquote>\n\n"
            "Сменить или отключить командой нельзя — только в коде (<code>ANNOUNCE_CHANNEL_FIXED_ID</code>).\n"
            "<code>канал анонсов тест</code> — проверить канал и отправить пробный пост",
        )
        return
    if not arg:
        state = f"<code>{ANNOUNCE_CHANNEL_ID}</code>" if ANNOUNCE_CHANNEL_ID else "не задан"
        await reply_to_user(
            message,
            f"<blockquote><b>Канал анонсов:</b> {state}\n"
            f"Экипировка: от «{RARITIES[ANNOUNCE_ITEM_MIN_RARITY]['name']}» · питомцы: от «{PET_RARITIES[ANNOUNCE_PET_MIN_RARITY]['name']}»</blockquote>\n\n"
            "<code>канал анонсов -1001234567890</code> — задать по ID\n"
            "<code>канал анонсов @имя_канала</code> — задать публичный канал\n"
            "перешли пост из канала и ответь на него <code>канал анонсов этот</code>\n"
            "<code>канал анонсов тест</code> — проверочный пост\n"
            "<code>канал анонсов выкл</code> — отключить\n\n"
            "<i>Бот должен быть администратором канала с правом публикации.</i>",
        )
        return
    if arg in ("выкл", "off", "нет"):
        ANNOUNCE_CHANNEL_ID = None
        _save_announce_settings()
        await reply_to_user(message, f"{PE_OK} Анонсы отключены.")
        return
    if arg in ("тест", "test", "проверка"):
        if not ANNOUNCE_CHANNEL_ID:
            await reply_to_user(message, premium_cross("❌ Канал не задан."))
            return
        await reply_to_user(message, await diagnose_announce_channel(ANNOUNCE_CHANNEL_ID, send_test=True))
        return
    channel_id = None
    # 1) переслать пост из канала боту и ответить на него: «канал анонсов» + что угодно
    replied = message.reply_to_message
    origin_chat = None
    if replied is not None:
        origin = getattr(replied, "forward_origin", None)
        origin_chat = getattr(origin, "chat", None) or getattr(replied, "forward_from_chat", None) or getattr(replied, "sender_chat", None)
    if origin_chat is not None and arg in ("", "этот", "сюда", "задать"):
        channel_id = origin_chat.id
    elif arg.startswith("@") or "t.me/" in arg:
        # 2) публичный канал по юзернейму
        username = "@" + arg.split("t.me/")[-1].lstrip("@").split("/")[0]
        try:
            chat = await NOTIFY_BOT.get_chat(username)
            channel_id = chat.id
        except Exception as e:
            await reply_to_user(message, premium_cross(f"❌ Канал {html.escape(username)} не найден: {html.escape(str(e))}"))
            return
    else:
        try:
            channel_id = int(arg)
        except ValueError:
            await reply_to_user(
                message,
                "Укажи канал одним из способов:\n"
                "• <code>канал анонсов -1001234567890</code> (ID, начинается с -100)\n"
                "• <code>канал анонсов @имя_канала</code> (для публичного)\n"
                "• перешли боту любой пост из канала и ответь на него <code>канал анонсов этот</code>",
            )
            return
    ANNOUNCE_CHANNEL_ID = channel_id
    _save_announce_settings()
    report = await diagnose_announce_channel(channel_id, send_test=False)
    await reply_to_user(message, f"{PE_OK} Канал анонсов: <code>{channel_id}</code>\n\n{report}\n\nОтправить пробный пост: <code>канал анонсов тест</code>")


async def diagnose_announce_channel(channel_id: int, send_test: bool) -> str:
    """Проверяет, видит ли бот канал и может ли туда писать. Возвращает понятный отчёт."""
    lines = []
    try:
        chat = await NOTIFY_BOT.get_chat(channel_id)
        lines.append(f"{PE_OK} Канал найден: <b>{html.escape(getattr(chat, 'title', '') or str(channel_id))}</b> ({getattr(chat, 'type', '?')})")
    except Exception as e:
        err = str(e)
        hint = "ID неверный или бота нет в канале. ID канала начинается с <code>-100</code>."
        return premium_cross(f"❌ Бот не видит канал: <code>{html.escape(err)}</code>\n{hint}")
    try:
        me = await NOTIFY_BOT.get_me()
        member = await NOTIFY_BOT.get_chat_member(channel_id, me.id)
        status = str(getattr(member, "status", ""))
        status = status.split(".")[-1].lower()
        if status not in ("administrator", "creator"):
            lines.append(premium_cross(f"❌ Бот в канале не администратор (статус: {html.escape(status)}). Сделай его админом."))
        else:
            can_post = getattr(member, "can_post_messages", None)
            if getattr(chat, "type", "") == "channel" and can_post is False:
                lines.append(premium_cross("❌ У бота выключено право «Публикация сообщений» — включи его в настройках админа."))
            else:
                lines.append(f"{PE_OK} Бот — администратор, может публиковать.")
    except Exception as e:
        lines.append(f"<i>Права проверить не удалось: {html.escape(str(e))}</i>")
    if send_test:
        try:
            test_text = f"<blockquote>{PE_OK} Анонсы Lootify подключены{PE_ALARM}</blockquote>"
            sent = await NOTIFY_BOT.send_message(channel_id, test_text, parse_mode="HTML")
            lines.append(f"{PE_OK} Пробный пост отправлен.")
            # Проверяем, оставил ли Telegram премиум-эмодзи в посте
            expected = test_text.count("<tg-emoji")
            kept = sum(1 for e in (getattr(sent, "entities", None) or []) if str(getattr(e, "type", "")).endswith("custom_emoji"))
            if kept >= expected:
                lines.append(f"{PE_OK} Премиум-эмодзи в канале работают ({kept}/{expected}).")
            else:
                lines.append(premium_cross(
                    f"❌ Telegram убрал премиум-эмодзи из поста ({kept}/{expected}) — в канале они покажутся обычными. "
                    "Это ограничение Telegram, а не кода: бот отправляет их так же, как в ЛС."
                ))
        except Exception as e:
            lines.append(premium_cross(f"❌ Пост не отправился: <code>{html.escape(str(e))}</code>"))
    return "\n".join(lines)


# ============================================================
# === Смена ника за монеты: «сменить ник Новый Ник» ===
# ============================================================

NICK_CHANGE_COST = 25_000
_nick_change_pending: Dict[int, dict] = {}


def validate_nickname(nickname: str) -> Optional[str]:
    """None — ник подходит, иначе текст ошибки (те же правила, что при регистрации)."""
    if not nickname or nickname.startswith("/"):
        return "Напиши ник обычным текстом."
    if len(nickname) < 2 or len(nickname) > 20:
        return "Ник должен быть от 2 до 20 символов."
    if any(char in nickname for char in "<>\n\r\t"):
        return "В нике нельзя использовать переносы и символы < >."
    return None


@dp.message(lambda msg: msg.text and re.match(r"^(сменить|смена)\s+ник(а)?(\s|$)", msg.text.strip().lower()) is not None)
async def text_change_nickname(message: Message):
    uid = message.from_user.id
    if not await db.has_user(uid):
        return
    user = await db.get_user(uid)
    new_nick = re.sub(r"^\S+\s+\S+\s*", "", message.text.strip(), count=1).strip()
    coin = '<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji>'
    if not new_nick:
        await reply_to_user(
            message,
            f'<tg-emoji emoji-id="5837012579926412863">🪪</tg-emoji> <b>Смена ника</b>\n\n'
            f"<blockquote>Сейчас: <b>{render_user_nickname(user)}</b>\n"
            f"Цена: <b>{format_num(NICK_CHANGE_COST)}</b> {coin}</blockquote>\n\n"
            "Напиши: <code>сменить ник Новый Ник</code>\n"
            "<i>От 2 до 20 символов. Премиум-эмодзи в нике сохранятся и будут видны в профиле, топах и клане.</i>",
        )
        return
    error = validate_nickname(new_nick)
    if error:
        await reply_to_user(message, premium_cross(f"❌ {error}"))
        return
    if new_nick == user.get("name"):
        await reply_to_user(message, "Это и так твой ник.")
        return
    if await db.is_name_taken(new_nick, exclude_user_id=uid):
        await reply_to_user(message, premium_cross("❌ Такой ник уже занят. Выбери другой."))
        return
    if int(user.get("coins", 0)) < NICK_CHANGE_COST:
        await reply_to_user(message, premium_cross(f"❌ Нужно {format_num(NICK_CHANGE_COST)} монет, у тебя {format_num(int(user.get('coins', 0)))}."))
        return
    ids, texts = get_message_custom_emoji_data(message)
    _nick_change_pending[uid] = {"name": new_nick, "ids": ids, "texts": texts, "ts": time.time()}
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text=f"Сменить за {format_num(NICK_CHANGE_COST)}", callback_data="nick_change_ok", icon_custom_emoji_id="5325762861539016690")],
        [InlineKeyboardButton(text="Отмена", callback_data="nick_change_no", icon_custom_emoji_id="5352669272575321097")],
    ])
    await reply_to_user(
        message,
        f'<tg-emoji emoji-id="5837012579926412863">🪪</tg-emoji> <b>Сменить ник?</b>\n\n'
        f"<blockquote>{render_user_nickname(user)} → <b>{render_nickname_html(new_nick, ids, texts)}</b>\n"
        f"Цена: <b>{format_num(NICK_CHANGE_COST)}</b> {coin}</blockquote>",
        kb,
    )


@dp.callback_query(F.data == "nick_change_ok")
async def cb_nick_change_ok(call: CallbackQuery):
    uid = call.from_user.id
    pending = _nick_change_pending.pop(uid, None)
    if not pending or time.time() - pending["ts"] > 600:
        await call.answer("Подтверждение устарело. Напиши команду заново.", show_alert=True)
        return
    user = await db.get_user(uid)
    if await db.is_name_taken(pending["name"], exclude_user_id=uid):
        await call.answer("Этот ник только что заняли.", show_alert=True)
        return
    if int(user.get("coins", 0)) < NICK_CHANGE_COST:
        await call.answer("Не хватает монет.", show_alert=True)
        return
    old = user.get("name", "")
    old_html = render_user_nickname(user)
    user["coins"] = int(user.get("coins", 0)) - NICK_CHANGE_COST
    user["name"] = pending["name"]
    user["nickname_custom_emoji_ids"] = pending["ids"]
    user["nickname_custom_emoji_texts"] = pending["texts"]
    user["nick_changed_at"] = time.time()
    await db.save_user(uid, user)
    await write_activity_log(f"NICK {uid} | «{old}» → «{pending['name']}» за {NICK_CHANGE_COST}")
    await call.answer("Ник изменён!")
    await edit_for_user(
        call,
        f"{PE_OK} Ник изменён: {old_html} → <b>{render_user_nickname(user)}</b>\n"
        f"<i>Списано {format_num(NICK_CHANGE_COST)} монет.</i>",
        None,
    )


@dp.callback_query(F.data == "nick_change_no")
async def cb_nick_change_no(call: CallbackQuery):
    _nick_change_pending.pop(call.from_user.id, None)
    await call.answer("Отменено")
    await edit_for_user(call, "Смена ника отменена.", None)


# ============================================================
# === Воскрешение боссов за монеты ===
# Сбрасывает откат одного босса. Цена ≈ 80% средней монетной награды за него
# (окупается одним убийством), минимум 300. Лимит — BOSS_REVIVE_DAILY_LIMIT в сутки.
# ============================================================

BOSS_REVIVE_DAILY_LIMIT = 10
BOSS_REVIVE_PRICE_MULT = 0.8
BOSS_REVIVE_FINAL_MULT = 1.0
BOSS_REVIVE_MIN_PRICE = 300
BOSS_REVIVE_PAGE_SIZE = 8
PE_REVIVE = '<tg-emoji emoji-id="5346321684574003384">🔄</tg-emoji>'


def is_final_boss(boss: dict) -> bool:
    loc_bosses = [b for b in BOSSES.values() if b.get("location") == boss.get("location")]
    return bool(loc_bosses) and loc_bosses[-1]["id"] == boss["id"]


def get_boss_revive_price(boss: dict) -> int:
    coins = boss.get("coins", 0)
    avg = (coins[0] + coins[1]) / 2 if isinstance(coins, (tuple, list)) else float(coins or 0)
    price = avg * BOSS_REVIVE_PRICE_MULT * (BOSS_REVIVE_FINAL_MULT if is_final_boss(boss) else 1.0)
    price = max(BOSS_REVIVE_MIN_PRICE, price)
    step = 100 if price < 100_000 else 1000
    return int(math.ceil(price / step) * step)


def get_boss_revive_limit(user: Optional[dict]) -> int:
    return BOSS_REVIVE_DAILY_LIMIT + (STAR_PASS_EXTRA_REVIVES if has_star_pass(user) else 0)


def get_boss_revives_left(user: dict) -> int:
    used = int(ensure_daily_stats(user).get("boss_revives", 0) or 0)
    return max(0, get_boss_revive_limit(user) - used)


def get_revivable_bosses(user: dict) -> List[dict]:
    level = int(user.get("level", 1) or 1)
    result = []
    for boss in BOSSES.values():
        loc = LOCATIONS.get(boss.get("location"), {})
        if level < loc.get("min_level", 1):
            continue
        if get_boss_cd_remaining(user, boss["id"]) > 0:
            result.append(boss)
    return result


async def show_boss_revive_list(user_id: int, page: int, answer_func):
    user = await db.get_user(user_id)
    bosses = get_revivable_bosses(user)
    left = get_boss_revives_left(user)
    coin = '<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji>'
    back = [InlineKeyboardButton(text="К откатам", callback_data="bosscd_refresh", icon_custom_emoji_id="5215361191051798408")]
    header = (
        f"{PE_REVIVE} <b>Воскрешение боссов</b>\n\n"
        f"<blockquote>Сбрасывает откат босса — тебе и всем, у кого он открыт и на откате. Им придёт уведомление с твоим ником.\n"
        f"Воскрешений сегодня: <b>{left}/{get_boss_revive_limit(user)}</b>\n"
        f"Монеты: <b>{format_num(int(user.get('coins', 0)))}</b> {coin}</blockquote>"
    )
    if not bosses:
        await answer_func(header + "\n\n<i>Все боссы и так готовы к бою.</i>", InlineKeyboardMarkup(inline_keyboard=[back]))
        return
    # самые долгие откаты — сверху: их выгоднее всего воскрешать
    bosses.sort(key=lambda b: -get_boss_cd_remaining(user, b["id"]))
    pages = max(1, math.ceil(len(bosses) / BOSS_REVIVE_PAGE_SIZE))
    page = max(0, min(page, pages - 1))
    rows = []
    for boss in bosses[page * BOSS_REVIVE_PAGE_SIZE:(page + 1) * BOSS_REVIVE_PAGE_SIZE]:
        icon_id = premium_emoji_id(boss.get("premium_emoji", ""))
        label = f"{boss['name']} · {format_num(get_boss_revive_price(boss))}"
        rows.append([InlineKeyboardButton(
            text=label if icon_id else f"{boss['emoji']} {label}",
            callback_data=f"rv_ask|{boss['id']}|{page}",
            icon_custom_emoji_id=icon_id,
        )])
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="◀️", callback_data=f"rv_list|{page - 1}"))
    if pages > 1:
        nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page < pages - 1:
        nav.append(InlineKeyboardButton(text="▶️", callback_data=f"rv_list|{page + 1}"))
    if nav:
        rows.append(nav)
    rows.append(back)
    note = "" if left else f"\n\n{PE_CROSS} <i>Лимит за монеты на сегодня исчерпан — обновится в 00:00 МСК.</i>"
    if get_revive_scrolls(user):
        note += f"\n{PE_STAR} <i>Свитков: {get_revive_scrolls(user)} — ими можно воскрешать без лимита.</i>"
    await answer_func(header + "\n\n<i>Выбери босса. Цена на кнопке.</i>" + note, InlineKeyboardMarkup(inline_keyboard=rows))


@dp.callback_query(F.data.startswith("rv_list|"))
async def cb_boss_revive_list(call: CallbackQuery):
    await call.answer()
    page = call.data.split("|", 1)[1]
    await show_boss_revive_list(call.from_user.id, int(page) if page.isdigit() else 0, lambda t, kb: edit_for_user(call, t, kb))


@dp.callback_query(F.data.startswith("rv_ask|"))
async def cb_boss_revive_ask(call: CallbackQuery):
    _, boss_id, page = (call.data.split("|") + ["0"])[:3]
    boss = BOSSES.get(boss_id)
    user = await db.get_user(call.from_user.id)
    if not boss:
        await call.answer("Босс не найден.", show_alert=True)
        return
    cd = get_boss_cd_remaining(user, boss_id)
    if cd <= 0:
        await call.answer("Этот босс уже готов к бою.", show_alert=True)
        await show_boss_revive_list(call.from_user.id, int(page) if page.isdigit() else 0, lambda t, kb: edit_for_user(call, t, kb))
        return
    await call.answer()
    price = get_boss_revive_price(boss)
    coin = '<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji>'
    claim_pass_daily_scroll(user)
    scrolls = get_revive_scrolls(user)
    kb_rows = [[InlineKeyboardButton(text=f"Воскресить за {format_num(price)}", callback_data=f"rv_do|{boss_id}|{page}", icon_custom_emoji_id="5325762861539016690")]]
    if scrolls > 0:
        kb_rows.append([InlineKeyboardButton(text=f"Воскресить свитком ({scrolls})", callback_data=f"rv_do|{boss_id}|{page}|s", icon_custom_emoji_id="6269538837723090339")])
    kb_rows.append([InlineKeyboardButton(text="Назад", callback_data=f"rv_list|{page}", icon_custom_emoji_id="5215361191051798408")])
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)
    final_note = "\nОкупается одной победой над ним." if is_final_boss(boss) else ""
    await edit_for_user(
        call,
        f"{PE_REVIVE} <b>Воскресить босса?</b>\n\n"
        f"<blockquote>{boss.get('premium_emoji') or boss['emoji']} <b>{html.escape(boss['name'])}</b>\n"
        f"{PE_HOURGLASS} До возрождения: <b>{format_cd_time(cd)}</b>\n"
        f"Цена: <b>{format_num(price)}</b> {coin}{final_note}\n"
        f"Воскрешений сегодня: <b>{get_boss_revives_left(user)}/{get_boss_revive_limit(user)}</b></blockquote>",
        kb,
    )


_revive_locks: Dict[int, asyncio.Lock] = {}


@dp.callback_query(F.data.startswith("rv_do|"))
async def cb_boss_revive_do(call: CallbackQuery):
    lock = _revive_locks.setdefault(call.from_user.id, asyncio.Lock())
    if lock.locked():
        await call.answer("Подожди, воскрешение уже выполняется.")
        return
    async with lock:
        await _boss_revive_do(call)


async def _boss_revive_do(call: CallbackQuery):
    uid = call.from_user.id
    parts = call.data.split("|")
    boss_id = parts[1] if len(parts) > 1 else ""
    page = parts[2] if len(parts) > 2 else "0"
    use_scroll = len(parts) > 3 and parts[3] == "s"
    boss = BOSSES.get(boss_id)
    user = await db.get_user(uid)
    if not boss:
        await call.answer("Босс не найден.", show_alert=True)
        return
    if get_boss_cd_remaining(user, boss_id) <= 0:
        await call.answer("Этот босс уже готов к бою.", show_alert=True)
        return
    if not use_scroll and get_boss_revives_left(user) <= 0:  # свитки — без лимита
        await call.answer(f"Лимит {get_boss_revive_limit(user)} воскрешений в сутки исчерпан. Свитками можно и сверх лимита. Обновится в 00:00 МСК.", show_alert=True)
        return
    price = get_boss_revive_price(boss)
    if use_scroll:
        if get_revive_scrolls(user) <= 0:
            await call.answer("Свитков воскрешения нет. Их можно купить в «донат».", show_alert=True)
            return
        user["revive_scrolls"] = get_revive_scrolls(user) - 1
        price = 0
    elif int(user.get("coins", 0)) < price:
        await call.answer(f"Не хватает монет: нужно {format_num(price)}.", show_alert=True)
        return
    user["coins"] = int(user.get("coins", 0)) - price
    user.setdefault("boss_cooldowns", {})[boss_id] = 0
    user.setdefault("boss_cd_notified", {})[boss_id] = True  # не слать «босс готов» — игрок сам его воскресил
    stats = ensure_daily_stats(user)
    if not use_scroll:  # свитки в дневной лимит не засчитываются
        stats["boss_revives"] = int(stats.get("boss_revives", 0) or 0) + 1
    await save_runtime_state(uid, user)
    how = "свитком" if use_scroll else f"за {price}"
    await write_activity_log(f"BOSS {_log_user_name(uid, user)} | воскресил {boss['name']} {how} ({stats.get('boss_revives', 0)}/{get_boss_revive_limit(user)})")
    await call.answer(f"{boss['name']} воскрешён!")
    icon_id = premium_emoji_id(boss.get("premium_emoji", "")) or "5373173798633752502"
    # Босс воскресает и у всех остальных, кому он доступен и у кого он на откате, — им уведомление в ЛС
    revived_for = revive_boss_for_everyone(boss, exclude_uid=uid)
    if revived_for:
        await db.save_users(revived_for)
        asyncio.get_running_loop().create_task(notify_boss_revived_by_player(boss, uid, user, revived_for))
    await write_activity_log(f"BOSS {_log_user_name(uid, user)} | {boss['name']} воскрешён ещё для {len(revived_for)} игроков")
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="В бой", callback_data=f"quick_boss|{boss_id}", icon_custom_emoji_id=icon_id)],
        [InlineKeyboardButton(text="Воскресить ещё", callback_data=f"rv_list|{page}", icon_custom_emoji_id="5346321684574003384")],
    ])
    await edit_for_user(
        call,
        f"{PE_OK} <b>{html.escape(boss['name'])}</b> воскрешён и готов к бою{PE_ALARM}\n\n"
        + (f"<blockquote>Потрачен свиток воскрешения (осталось {get_revive_scrolls(user)})\n" if use_scroll
           else f"<blockquote>Списано: <b>{format_num(price)}</b> монет\n")
        + f"Воскрешён и для других игроков: <b>{len(revived_for)}</b> — им пришло уведомление с твоим ником\n"
        f"Осталось воскрешений сегодня: <b>{get_boss_revives_left(user)}/{get_boss_revive_limit(user)}</b></blockquote>",
        kb,
    )


def revive_boss_for_everyone(boss: dict, exclude_uid: int) -> List[str]:
    """Сбрасывает откат босса всем, кому он открыт по уровню и у кого он сейчас на откате."""
    min_level = LOCATIONS.get(boss.get("location"), {}).get("min_level", 1)
    now = time.time()
    revived = []
    for uid_str, u in list(db.data.items()):
        if uid_str == str(exclude_uid) or not isinstance(u, dict):
            continue
        if int(u.get("level", 1) or 1) < min_level:
            continue
        cds = u.get("boss_cooldowns") or {}
        if float(cds.get(boss["id"], 0) or 0) > now:
            cds[boss["id"]] = 0
            u.setdefault("boss_cd_notified", {})[boss["id"]] = True
            revived.append(uid_str)
    return revived


async def notify_boss_revived_by_player(boss: dict, reviver_id: int, reviver: dict, user_ids: List[str]):
    icon_id = premium_emoji_id(boss.get("premium_emoji", "")) or "5373173798633752502"
    text = (
        f"<blockquote>{PE_REVIVE} <b>{render_user_nickname(reviver)}</b> воскресил босса{PE_ALARM}</blockquote>\n\n"
        f"<blockquote>{boss.get('premium_emoji') or boss['emoji']} <b>{html.escape(boss['name'])}</b> снова готов к бою — "
        "и у тебя тоже, откат сброшен.</blockquote>"
    )
    kb = nav_kb(("В бой", f"quick_boss|{boss['id']}", icon_id), NAV_BOSSES)
    for uid_str in user_ids:
        try:
            await send_user_notification(int(uid_str), text, reply_markup=kb)
        except Exception as e:
            print(f"[revive notify] {uid_str}: {e}")


@dp.message(lambda msg: msg.text and message_command(msg) in ("воскрешение", "воскр", "рв"))
async def text_boss_revive(message: Message):
    if not await db.has_user(message.from_user.id):
        return
    await show_boss_revive_list(message.from_user.id, 0, lambda t, kb: reply_to_user(message, t, kb))


