def get_strongest_available_boss(user: dict) -> Optional[dict]:
    level = int(user.get("level", 1) or 1)
    best = None
    for boss in BOSSES.values():
        if level >= LOCATIONS.get(boss.get("location"), {}).get("min_level", 1):
            if best is None or boss.get("level", 0) >= best.get("level", 0):
                best = boss
    return best


def get_star_boss_res_id(user: dict) -> Optional[str]:
    """Редкий ресурс самого последнего (сильного) доступного босса."""
    boss = get_strongest_available_boss(user)
    return (boss or {}).get("loot_item")


def give_star_boss_res(user: dict, amount: int) -> str:
    rid = get_star_boss_res_id(user)
    if not rid:
        return ""
    add_boss_resource(user, rid, amount)
    info = BOSS_RESOURCE_DEFS.get(rid, {})
    return f"{info.get('emoji', '')} {html.escape(str(info.get('name', rid)))}: +{amount}"


