def get_star_coin_pack_amount(user: dict) -> int:
    level = int(user.get("level", 1) or 1)
    best = None
    for boss in BOSSES.values():
        if level >= LOCATIONS.get(boss.get("location"), {}).get("min_level", 1):
            if best is None or boss.get("level", 0) >= best.get("level", 0):
                best = boss
    coins = (best or {}).get("coins", 0)
    avg = (coins[0] + coins[1]) / 2 if isinstance(coins, (tuple, list)) else float(coins or 0)
    return max(50_000, int(avg * STAR_COIN_PACK_KILLS))


