@dp.callback_query(F.data.startswith("star_buy|"))
async def cb_star_buy(call: CallbackQuery):
    uid = call.from_user.id
    pid = call.data.split("|", 1)[1]
    product = STAR_PRODUCTS.get(pid)
    user = await db.get_user(uid)
    if not product or not user:
        await call.answer("Товар не найден.", show_alert=True)
        return
    if product.get("once") and pid in (user.get("star_once_bought") or []):
        await call.answer("Этот набор уже куплен — он доступен один раз.", show_alert=True)
        return
    if product["give"].get("banner") and product["give"]["banner"] in (user.get("banners") or []):
        await call.answer("Эта плашка уже у тебя есть.", show_alert=True)
        return
    if product["give"].get("bp_premium") and get_bp_state(user).get("premium"):
        await call.answer("Премиум пропуска на этот сезон уже куплен.", show_alert=True)
        return
    await call.answer()
    payload = f"{pid}|{uid}|{int(time.time())}"
    try:
        # счёт отправляем в личку: оплата звёздами работает в ЛС с ботом
        await call.bot.send_invoice(
            chat_id=uid,
            title=product["title"],
            # в счёте Telegram премиум-эмодзи не работают — убираем значок, чтобы не было «обычной» звезды
            description=product["desc"].replace("значок 🌟", "значок пропуска").replace("🌟", "")[:255],
            payload=payload,
            provider_token="",
            currency="XTR",
            prices=[LabeledPrice(label=product["title"], amount=int(product["stars"]))],
        )
    except Exception as e:
        await call.message.answer(premium_cross(f"❌ Не удалось выставить счёт: {html.escape(str(e))}\nНапиши боту в ЛС и попробуй снова."), parse_mode="HTML")


@dp.pre_checkout_query()
async def star_pre_checkout(query: PreCheckoutQuery):
    """Последняя проверка перед списанием звёзд."""
    try:
        pid, uid_str, _ = query.invoice_payload.split("|", 2)
        product = STAR_PRODUCTS.get(pid)
        ok = (
            product is not None
            and query.currency == "XTR"
            and int(query.total_amount) == int(product["stars"])
            and int(uid_str) == query.from_user.id
            and await db.has_user(query.from_user.id)
        )
        if ok and product.get("once"):
            user = await db.get_user(query.from_user.id)
            ok = pid not in (user.get("star_once_bought") or [])
        if ok and product["give"].get("bp_premium"):
            user = await db.get_user(query.from_user.id)
            ok = not get_bp_state(user).get("premium")
        if ok and product["give"].get("banner"):
            user = await db.get_user(query.from_user.id)
            ok = product["give"]["banner"] not in (user.get("banners") or [])
        if ok:
            await query.answer(ok=True)
        else:
            await query.answer(ok=False, error_message="Товар недоступен. Открой магазин заново: «донат».")
    except Exception as e:
        print(f"[pre_checkout] {e}")
        await query.answer(ok=False, error_message="Ошибка проверки заказа, попробуй ещё раз.")


@dp.message(F.successful_payment)
async def star_successful_payment(message: Message):
    payment = message.successful_payment
    uid = message.from_user.id
    pid = payment.invoice_payload.split("|", 1)[0]
    user = await db.get_user(uid)
    charge_id = payment.telegram_payment_charge_id
    history = user.setdefault("star_purchases", [])
    if any(h.get("charge_id") == charge_id for h in history):
        return  # повторное уведомление о том же платеже — не выдаём второй раз
    got = apply_star_product(user, pid) if pid in STAR_PRODUCTS else []
    history.append({"charge_id": charge_id, "product": pid, "stars": payment.total_amount, "ts": time.time()})
    await save_runtime_state(uid, user)
    await write_activity_log(
        f"PAY {_log_user_name(uid, user)} | {pid} за {payment.total_amount}⭐ | charge {charge_id}"
    )
    await message.answer(
        f"{PE_OK} <b>Спасибо за покупку!</b>{PE_ALARM}\n\n<blockquote>" + "\n".join(got or ["Товар выдан."]) + "</blockquote>",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="Звёздный магазин", callback_data="star_shop", icon_custom_emoji_id="6269538837723090339"),
        ]]),
    )
    for admin_id in ADMIN_IDS:
        await send_user_notification(
            admin_id,
            f"<blockquote>{PE_STAR} <b>Покупка</b>: {html.escape(STAR_PRODUCTS.get(pid, {}).get('title', pid))} — {payment.total_amount} ⭐\n"
            f"Игрок: {render_user_nickname(user)} · ID <code>{uid}</code>\n"
            f"Чек: <code>{charge_id}</code></blockquote>",
        )


