@dp.message(lambda msg: msg.text and re.match(r"^пропуск[+-](\s+\d+){0,2}$", msg.text.lower().strip()) is not None)
async def text_admin_star_pass(message: Message):
    """Админ: «пропуск+ [дни] [ID]» — выдать пропуск (по умолчанию 30 дней), «пропуск- [ID]» — снять.
    Без ID — реплаем на игрока."""
    if message.from_user.id not in ADMIN_IDS:
        return
    parts = message.text.lower().split()
    give = parts[0].endswith("+")
    nums = [int(x) for x in parts[1:]]
    days = STAR_PASS_DAYS
    target_id = None
    if give:
        if len(nums) >= 1:
            days = nums[0]
        if len(nums) >= 2:
            target_id = nums[1]
    elif nums:
        target_id = nums[0]
    if target_id is None:
        target, user = await get_admin_reply_target_user(message, "пропуск+ 30 (реплаем) или пропуск+ 30 ID")
        if not target:
            return
        target_id = target.id
    else:
        if not await db.has_user(target_id):
            await reply_to_user(message, premium_cross(f"❌ Игрока с ID <code>{target_id}</code> нет в базе."))
            return
        user = await db.get_user(target_id)
    name = render_user_nickname(user, f"ID {target_id}")
    if give:
        if days <= 0 or days > 3650:
            await reply_to_user(message, "Количество дней — от 1 до 3650.")
            return
        start = max(time.time(), float(user.get("star_pass_until", 0) or 0))
        user["star_pass_until"] = start + days * 86400
        until = datetime.utcfromtimestamp(user["star_pass_until"] + 3 * 3600).strftime("%d.%m.%Y")
        await save_runtime_state(target_id, user)
        await write_activity_log(f"ADMIN {_log_user_name(message.from_user.id)} | выдал пропуск {days} дн. {_log_user_name(target_id, user)} (до {until})")
        await reply_to_user(message, f"{PE_OK} <b>{name}</b>: пропуск на <b>{days}</b> дн. {PE_PASS} Активен до <b>{until}</b>.")
        await send_user_notification(
            target_id,
            f"<blockquote>{PE_PASS} <b>Тебе выдан пропуск</b> на {days} дн.{PE_ALARM}</blockquote>\n\n"
            f"<blockquote>Активен до <b>{until}</b>\n"
            f"+{int(STAR_PASS_COIN_BONUS * 100)}% монет, +{int(STAR_PASS_XP_BONUS * 100)}% опыта, "
            f"каждый день {STAR_PASS_DAILY_SCROLLS} свитка и {STAR_PASS_DAILY_RES} ресурса последнего босса, "
            f"+{STAR_PASS_EXTRA_REVIVES} к лимиту воскрешений</blockquote>",
            reply_markup=nav_kb(("Звёздный магазин", "star_shop", "6269538837723090339")),
        )
