@dp.message(lambda msg: msg.text and msg.text.lower().strip().startswith("рефанд"))
async def text_star_refund(message: Message):
    """Админ: «рефанд ID_игрока чек» — вернуть звёзды. Товар при этом не забирается автоматически."""
    if message.from_user.id not in ADMIN_IDS:
        return
    parts = message.text.split()
    if len(parts) != 3 or not parts[1].isdigit():
        await reply_to_user(message, "Формат: <code>рефанд ID_игрока чек</code> (чек — из уведомления о покупке).")
        return
    target_id, charge_id = int(parts[1]), parts[2]
    try:
        await message.bot.refund_star_payment(user_id=target_id, telegram_payment_charge_id=charge_id)
    except Exception as e:
        await reply_to_user(message, premium_cross(f"❌ Возврат не прошёл: {html.escape(str(e))}"))
        return
    if await db.has_user(target_id):
        tu = await db.get_user(target_id)
        for p in tu.get("star_purchases") or []:
            if p.get("charge_id") == charge_id:
                p["refunded"] = True  # возвращённое не считается в топе доната
        await save_runtime_state(target_id, tu)
    await write_activity_log(f"ADMIN {_log_user_name(message.from_user.id)} | возврат звёзд {target_id} чек {charge_id}")
    await reply_to_user(message, f"{PE_OK} Звёзды возвращены игроку <code>{target_id}</code>. Если нужно, забери товар вручную.")


