BOT_STARTED_AT = time.time()


@dp.message(lambda msg: msg.text and message_command(msg) in ("пинг", "лфинг", "ping"))
async def text_admin_ping(message: Message):
    """Админ: задержки бота — Telegram, база, цикл событий, нагрузка."""
    if message.from_user.id not in ADMIN_IDS:
        return
    t0 = time.perf_counter()
    sent = await message.answer("Меряю пинг…")
    tg_ms = (time.perf_counter() - t0) * 1000

    t1 = time.perf_counter()
    db_ms = None
    try:
        user = db.data.get(str(message.from_user.id))
        if user:
            await upsert_user(message.from_user.id, user)  # реальная запись в базу
            db_ms = (time.perf_counter() - t1) * 1000
    except Exception as e:
        print(f"[ping] db: {e}")

    t2 = time.perf_counter()
    await asyncio.sleep(0)
    loop_ms = (time.perf_counter() - t2) * 1000

    up = int(time.time() - BOT_STARTED_AT)
    now = time.time()
    online = sum(1 for u in db.data.values() if isinstance(u, dict) and now - float(u.get("last_seen_at", 0) or 0) < 600)
    autorolls = sum(1 for s_ in auto_roll_sessions.values() if s_.get("running"))
    battles = len(active_battles)

    def mark(ms: Optional[float], good: float, ok: float) -> str:
        if ms is None:
            return "—"
        icon = "🟢" if ms < good else ("🟡" if ms < ok else "🔴")
        return f"{icon} <b>{ms:.0f} мс</b>"

    text = (
        '<tg-emoji emoji-id="5429519916971599983">💻</tg-emoji> <b>Пинг бота</b>\n\n'
        "<blockquote>"
        f"Telegram (отправка сообщения): {mark(tg_ms, 300, 800)}\n"
        f"База данных (запись игрока): {mark(db_ms, 50, 200)}\n"
        f"Цикл событий: {mark(loop_ms, 5, 50)}"
        "</blockquote>\n\n"
        "<blockquote>"
        f"Работает: <b>{format_clan_boss_time(up)}</b>\n"
        f"Игроков в базе: <b>{len(db.data)}</b> · онлайн (10 мин): <b>{online}</b>\n"
        f"Автороллов: <b>{autorolls}</b> · боёв: <b>{battles}</b>\n"
        f"Очередь логов: <b>{len(_activity_log_buffer)}</b> строк"
        "</blockquote>"
    )
    try:
        await sent.edit_text(text, parse_mode="HTML")
    except Exception:
        await reply_to_user(message, text)


# ============================================================
# === Сеты экипировки ===
# Надетая броня одной редкости собирается в сет: 2 / 4 / 6 частей дают бонус.
# Чем выше редкость, тем сильнее бонус. Считается лучший сет из надетого.
# ============================================================

ARMOR_SET_INFO = {
    "common":    {"name": "Сет странника",        "mult": 1.0},
    "uncommon":  {"name": "Сет стража",           "mult": 1.2},
    "rare":      {"name": "Рыцарский сет",        "mult": 1.4},
    "epic":      {"name": "Сет бездны",           "mult": 1.6},
    "legendary": {"name": "Божественный сет",     "mult": 1.8},
    "mythic":    {"name": "Сет апокалипсиса",     "mult": 2.0},
    "nightmare": {"name": "Сет кошмаров",         "mult": 2.2},
}
# частей → (HP %, урон %) при множителе редкости 1.0
ARMOR_SET_TIERS = [(6, 7.0, 7.0), (4, 4.0, 3.0), (2, 2.0, 0.0)]
PE_SET = '<tg-emoji emoji-id="5373173798633752502">🛡</tg-emoji>'


def get_armor_set_bonus(user: Optional[dict]) -> Dict[str, Any]:
    """{'rarity', 'name', 'pieces', 'hp', 'dmg'} лучшего сета или {} если сета нет."""
    armor = (user or {}).get("equipped_armor") or {}
    counts = collections.Counter(
        p.get("rarity") for p in armor.values() if isinstance(p, dict) and p.get("rarity") in ARMOR_SET_INFO
    )
    best: Dict[str, Any] = {}
    for rarity, n in counts.items():
        info = ARMOR_SET_INFO[rarity]
        for need, hp, dmg in ARMOR_SET_TIERS:
            if n >= need:
                cand = {"rarity": rarity, "name": info["name"], "pieces": n, "tier": need,
                        "hp": round(hp * info["mult"], 1), "dmg": round(dmg * info["mult"], 1)}
                if not best or (cand["hp"] + cand["dmg"]) > (best["hp"] + best["dmg"]):
                    best = cand
                break
    return best


def format_armor_set_line(user: Optional[dict]) -> str:
    b = get_armor_set_bonus(user)
    if not b:
        return f"{PE_SET} Сет: <b>нет</b> — надень 2+ части брони одной редкости"
    parts = [f"+{b['hp']:g}% HP"]
    if b["dmg"]:
        parts.append(f"+{b['dmg']:g}% урона")
    nxt = next((need for need, _h, _d in reversed(ARMOR_SET_TIERS) if need > b["pieces"]), None)
    hint = f" · до следующего бонуса {nxt - b['pieces']} ч." if nxt else ""
    return f"{PE_SET} {b['name']} <b>{b['pieces']}/6</b>: {', '.join(parts)}{hint}"


async def show_armor_sets(user_id: int, answer_func):
    user = await db.get_user(user_id)
    lines = []
    for rarity, info in ARMOR_SET_INFO.items():
        icon = PREMIUM_RARITY_EMOJIS.get(rarity, RARITIES[rarity]["emoji"])
        tiers = " · ".join(
            f"{need} ч.: +{round(hp * info['mult'], 1):g}% HP" + (f", +{round(dmg * info['mult'], 1):g}% урона" if dmg else "")
            for need, hp, dmg in reversed(ARMOR_SET_TIERS)
        )
        lines.append(f"{icon} <b>{info['name']}</b> ({RARITIES[rarity]['name'].lower()})\n{tiers}")
    await answer_func(
        f"{PE_SET} <b>Сеты экипировки</b>\n\n"
        f"<blockquote>{format_armor_set_line(user)}</blockquote>\n\n"
        "<blockquote>Надень броню одной редкости: шлем, нагрудник, оба наруча, поножи и ботинки — "
        "всего 6 частей. Работает лучший сет из надетого.</blockquote>\n\n"
        "<blockquote expandable>" + "\n\n".join(lines) + "</blockquote>",
        None,
    )


