def resolve_banner_id(query: str) -> Optional[str]:
    q = (query or "").strip().lower().strip("«»\"'")
    if q in COSMETIC_BANNERS:
        return q
    for bid, b in COSMETIC_BANNERS.items():
        if q and (q == b["name"].lower() or q in b["name"].lower()):
            return bid
    return None


@dp.message(lambda msg: msg.text and re.match(r"^плашка[+-](\s|$)", msg.text.lower().strip()) is not None)
async def text_admin_banner(message: Message):
    """Админ: «плашка+ дракон [ID]» — выдать (и надеть), «плашка- дракон [ID]» — забрать.
    Без ID — реплаем. «плашка+» без названия — список плашек."""
    if message.from_user.id not in ADMIN_IDS:
        return
    parts = message.text.strip().split()
    give = parts[0].lower().endswith("+")
    args = parts[1:]
    target_id = int(args.pop()) if args and args[-1].isdigit() else None
    bid = resolve_banner_id(" ".join(args)) if args else None
    if not bid:
        listing = "\n".join(f"<code>{k}</code> — {b['html']}" for k, b in COSMETIC_BANNERS.items())
        await reply_to_user(
            message,
            f"{PE_STAR} <b>Плашки</b>\n\n<blockquote>{listing}</blockquote>\n\n"
            "<code>плашка+ dragon</code> (реплаем) или <code>плашка+ dragon 123456789</code> — выдать\n"
            "<code>плашка- dragon</code> — забрать. Можно писать и название: <code>плашка+ богач</code>",
        )
        return
    if target_id is None:
        target, user = await get_admin_reply_target_user(message, "плашка+ dragon (реплаем) или плашка+ dragon ID")
        if not target:
            return
        target_id = target.id
    else:
        if not await db.has_user(target_id):
            await reply_to_user(message, premium_cross(f"❌ Игрока с ID <code>{target_id}</code> нет в базе."))
            return
        user = await db.get_user(target_id)
    name = render_user_nickname(user, f"ID {target_id}")
    banner = COSMETIC_BANNERS[bid]
    owned = user.setdefault("banners", [])
    if give:
        if bid not in owned:
            owned.append(bid)
        user["active_banner"] = bid
        await save_runtime_state(target_id, user)
        await write_activity_log(f"ADMIN {_log_user_name(message.from_user.id)} | выдал плашку {bid} {_log_user_name(target_id, user)}")
        await reply_to_user(message, f"{PE_OK} <b>{name}</b> получил плашку и она надета:\n{banner['html']}")
        await send_user_notification(
            target_id,
            f"<blockquote>{PE_STAR} <b>Тебе выдана плашка</b>{PE_ALARM}</blockquote>\n\n"
            f"<blockquote>{banner['html']}\nОна уже надета. Сменить или снять — команда <b>плашки</b>.</blockquote>",
            reply_markup=nav_kb(("Плашки", "banners", "5217822164362739968")),
        )
    else:
        had = bid in owned
        if had:
            owned.remove(bid)
        if user.get("active_banner") == bid:
            user["active_banner"] = None
        await save_runtime_state(target_id, user)
        await write_activity_log(f"ADMIN {_log_user_name(message.from_user.id)} | забрал плашку {bid} у {_log_user_name(target_id, user)}")
        await reply_to_user(message, f"{PE_OK} У <b>{name}</b> забрана плашка «{banner['name']}»." if had else f"У <b>{name}</b> этой плашки не было.")


