# === Ежедневные награды за топы ===
# Каждый день в 00:00 МСК награждаются первые 3 места в топах роллов и боссов за день и в топе силы.
# Награда растёт с силой игрока (как мешок монет), плюс свитки, ресурс и значок на сутки.
# ============================================================

DAILY_TOP_CATEGORIES = {
    "rolls":      {"name": "Роллы дня",             "unit": "роллов",  "style": "rolls",    "top_cb": "top|rolls|day"},
    "bosses":     {"name": "Боссы дня",             "unit": "боссов",  "style": "bosses",   "top_cb": "top|bosses|day"},
    "level_all":  {"name": "Уровень",               "unit": "ур.",     "style": "level",    "top_cb": "top|level|all"},
    "rolls_all":  {"name": "Роллы (всё время)",     "unit": "роллов",  "style": "rolls",    "top_cb": "top|rolls|all"},
    "bosses_all": {"name": "Боссы (всё время)",     "unit": "боссов",  "style": "bosses",   "top_cb": "top|bosses|all"},
    "power":      {"name": "Сила",                  "unit": "силы",    "style": "power",    "top_cb": "top|power|all"},
    "prestige":   {"name": "Престиж",               "unit": "престиж", "style": "prestige", "top_cb": "top|prestige|all"},
}
# место → (зелья удачи, свитки, ресурсы последнего босса)
DAILY_TOP_REWARDS = {1: (3, 3, 1), 2: (2, 2, 0), 3: (1, 1, 0)}
DAILY_TITLE_HOURS = 24
DAILY_REWARDS_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "lootify_day_rewards.json")


def add_weekly_stat(user: dict, key: str, amount: int = 1) -> None:
    """Счётчик для дневных наград (имя оставлено для совместимости). Хранит и вчерашний день."""
    dt = user.setdefault("daily_top", {})
    day = get_today_key()
    if dt.get("day") != day:
        if dt.get("day"):
            user["daily_top_prev"] = dict(dt)
        dt.clear()
        dt["day"] = day
    dt[key] = int(dt.get(key, 0) or 0) + amount


def get_daily_top_value(user: dict, category: str, day: str) -> int:
    if category == "power":
        return calculate_user_power(user)
    if category == "level_all":
        return int(user.get("level", 1) or 1)
    if category == "rolls_all":
        return int(user.get("chests_opened", 0) or 0)
    if category == "bosses_all":
        return int(user.get("boss_kills", 0) or 0)
    if category == "prestige":
        return get_rebirth_count(user)
    for dt in (user.get("daily_top") or {}, user.get("daily_top_prev") or {}):
        if dt.get("day") == day:
            return int(dt.get(category, 0) or 0)
    return 0


def get_weekly_value(user: dict, category: str, week: str) -> int:
    """Недельные значения нужны только башне (у неё своя недельная награда)."""
    if category == "tower":
        t = user.get("tower") or {}
        return int(t.get("best_week", 0) or 0) if t.get("week") == week else 0
    return 0


def is_user_banned_sync(uid_str: str) -> bool:
    try:
        return int(uid_str) in _banned_ids
    except Exception:
        return False


def daily_ranking(category: str, day: str) -> List[tuple]:
    rows = []
    for uid_str, u in list(db.data.items()):
        if not isinstance(u, dict) or is_user_banned_sync(uid_str) or not is_real_top_user(uid_str, u):
            continue
        v = get_daily_top_value(u, category, day)
        if v > 0:
            rows.append((v, uid_str, u))
    rows.sort(key=lambda r: -r[0])
    return rows[:3]


def get_weekly_title(user: Optional[dict]) -> str:
    """Значок за топ дня (имя оставлено для совместимости)."""
    t = (user or {}).get("weekly_title") or {}
    if t and float(t.get("until", 0)) > time.time():
        return f"{TOP_PLACE_EMOJIS.get(int(t.get('place', 1)), '🏅')} {html.escape(str(t.get('text', '')))}"
    return ""


async def award_daily_tops(day: str) -> None:
    """Награды за первые 3 места во всех награждаемых топах. Каждому игроку — одно общее уведомление."""
    per_user: Dict[str, Dict[str, Any]] = {}
    summary = []
    for cat, info in DAILY_TOP_CATEGORIES.items():
        ranking = daily_ranking(cat, day)
        lines = []
        for place, (value, uid_str, user) in enumerate(ranking, start=1):
            entry = per_user.setdefault(uid_str, {"user": user, "places": [], "potions": 0, "scrolls": 0, "res": 0})
            potions, scrolls, res = DAILY_TOP_REWARDS[place]
            entry["potions"] += potions
            entry["scrolls"] += scrolls
            entry["res"] += res
            entry["places"].append((place, cat, value))
            medal = TOP_PLACE_EMOJIS.get(place, f"{place}.")
            lines.append(f"{medal} {_announce_player_name(int(uid_str), user)} — {format_num(value)} {info['unit']}")
        if lines:
            summary.append(f"<b>{info['name']}</b>\n" + "\n".join(lines))
        await write_activity_log(f"DAYTOP | {day} {cat}: награждено {len(ranking)}")

    for uid_str, e in per_user.items():
        user = e["user"]
        for _ in range(e["potions"]):
            add_potion_to_user(user, "luck_potion")
        user["revive_scrolls"] = int(user.get("revive_scrolls", 0) or 0) + e["scrolls"]
        got = [f'{POTION_PREMIUM_EMOJIS.get("luck_potion", "🍀")} +{e["potions"]} {"зелье" if e["potions"] == 1 else "зелья" if e["potions"] < 5 else "зелий"} удачи',
               f"{PE_REVIVE} +{e['scrolls']} {'свиток' if e['scrolls'] == 1 else 'свитка' if e['scrolls'] < 5 else 'свитков'} воскрешения"]
        if e["res"]:
            line = give_star_boss_res(user, e["res"])
            if line:
                got.append(line)
        best_place, best_cat, _v = min(e["places"], key=lambda x: x[0])
        user["weekly_title"] = {"text": f"{best_place}-е место · {DAILY_TOP_CATEGORIES[best_cat]['name']}",
                                "place": best_place, "until": time.time() + DAILY_TITLE_HOURS * 3600}
        await db.save_user(int(uid_str), user)
        place_lines = []
        for place, cat, value in sorted(e["places"]):
            info = DAILY_TOP_CATEGORIES[cat]
            icon = TOP_STYLES.get(info.get("style", cat), {}).get("icon", PE_TROPHY)
            place_lines.append(f"{TOP_PLACE_EMOJIS.get(place, str(place))} <b>{place}-е место</b> · {info['name']}\n"
                               f"{icon} {format_num(value)} {info['unit']}")
        first_cat = sorted(e["places"])[0][1]
        await send_user_notification(
            int(uid_str),
            f"<blockquote>{PE_TROPHY} <b>Награда за топы</b>{PE_ALARM}</blockquote>\n\n"
            "<blockquote>" + "\n\n".join(place_lines) + "</blockquote>\n\n"
            f"<blockquote><b>Ты получаешь:</b>\n" + "\n".join(got) + "</blockquote>\n\n"
            f"<blockquote>{PE_PASS} Значок в профиле на сутки:\n<b>{get_weekly_title(user)}</b></blockquote>",
            reply_markup=nav_kb(("Топы", DAILY_TOP_CATEGORIES[first_cat]["top_cb"], "5947236241199074198")),
        )
    if summary:
        queue_announcement(
            f"<blockquote>{PE_TROPHY} <b>Итоги дня</b>{PE_ALARM}</blockquote>\n\n"
            + "\n\n".join(f"<blockquote>{s_}</blockquote>" for s_ in summary)
        )


async def daily_rewards_loop():
    while True:
        try:
            await db.load()
            try:
                with open(DAILY_REWARDS_FILE, "r", encoding="utf-8") as f:
                    state = json.load(f)
            except FileNotFoundError:
                state = {}
            today = get_today_key()
            if not state.get("last_day"):
                state["last_day"] = today  # первый запуск: начинаем с сегодняшнего дня
            elif state["last_day"] != today:
                await award_daily_tops(state["last_day"])
                state["last_day"] = today
            with open(DAILY_REWARDS_FILE, "w", encoding="utf-8") as f:
                json.dump(state, f)
        except Exception as e:
            print(f"[daily_rewards_loop] {e}")
        await asyncio.sleep(60)


