FISHING_COOLDOWN = 15
FISH_TYPES = [
    # id, имя, эмодзи, вес шанса, базовая цена
    ("crucian", "Карась", '<tg-emoji emoji-id="5382210409824525356">🐟</tg-emoji>', 450, 20),
    ("perch", "Окунь", '<tg-emoji emoji-id="5382210409824525356">🐟</tg-emoji>', 250, 35),
    ("pike", "Щука", '<tg-emoji emoji-id="5397842858126353661">🐠</tg-emoji>', 150, 80),
    ("catfish", "Сом", "🐡", 90, 200),
    ("sturgeon", "Осётр", '<tg-emoji emoji-id="5204117997463030808">🦈</tg-emoji>', 40, 600),
    ("goldfish", "Золотая рыбка", '<tg-emoji emoji-id="5397842858126353661">🐠</tg-emoji>', 16, 2000),
    ("whale", "Кит", '<tg-emoji emoji-id="6264760978664065671">🐋</tg-emoji>', 4, 10000),
]
FISH_BY_ID = {f[0]: f for f in FISH_TYPES}
PE_FISH = '<tg-emoji emoji-id="5343609421316521960">🎣</tg-emoji>'


# === Навыки рыбалки и огорода: качаются практикой (уровни 0–25) ===
HOBBY_MAX_LEVEL = 25


def hobby_xp_needed(level: int) -> int:
    """Опыт до следующего уровня навыка."""
    return int(20 + 12 * level ** 1.5)


def hobby_level(user: dict, kind: str) -> int:
    return int(user.get(f"{kind}_lvl", 0) or 0)


def add_hobby_xp(user: dict, kind: str, amount: int) -> int:
    """Добавляет опыт навыка (kind = fish / farm). Возвращает число новых уровней."""
    lvl = hobby_level(user, kind)
    if lvl >= HOBBY_MAX_LEVEL:
        return 0
    xp = int(user.get(f"{kind}_xp", 0) or 0) + amount
    gained = 0
    while lvl < HOBBY_MAX_LEVEL and xp >= hobby_xp_needed(lvl):
        xp -= hobby_xp_needed(lvl)
        lvl += 1
        gained += 1
    user[f"{kind}_lvl"], user[f"{kind}_xp"] = lvl, (0 if lvl >= HOBBY_MAX_LEVEL else xp)
    return gained


def hobby_progress_line(user: dict, kind: str) -> str:
    lvl = hobby_level(user, kind)
    if lvl >= HOBBY_MAX_LEVEL:
        return f"уровень <b>{lvl}</b> — максимум!"
    xp, need = int(user.get(f"{kind}_xp", 0) or 0), hobby_xp_needed(lvl)
    return f"уровень <b>{lvl}</b> · {_progress_bar(xp, need)} {xp}/{need}"


def fishing_cooldown(user: dict) -> float:
    return max(5.0, FISHING_COOLDOWN - 0.4 * hobby_level(user, "fish"))


def fish_price(user: dict, fish_id: str) -> int:
    level = int(user.get("level", 1) or 1)
    skill = 1 + 0.04 * hobby_level(user, "fish")
    return int(FISH_BY_ID[fish_id][4] * (1 + level / 25) * skill)


def roll_fish(user: dict) -> str:
    luck = get_luck_skill_multiplier(user) * (1.15 if has_buff(user, "luck") else 1.0)
    luck *= 1 + 0.02 * hobby_level(user, "fish")  # навык рыбака тоже тянет к редкой рыбе
    ids = [f[0] for f in FISH_TYPES]
    weights = [f[3] * (luck ** i) for i, f in enumerate(FISH_TYPES)]  # удача сильнее тянет редкую рыбу
    return random.choices(ids, weights=weights, k=1)[0]


def farm_beds_count(user: dict) -> int:
    return FARM_BEDS + hobby_level(user, "farm") // 5  # +1 грядка каждые 5 уровней (до 8)


def farm_grow_time(user: dict, crop: tuple) -> int:
    return int(crop[2] * (1 - min(0.5, 0.02 * hobby_level(user, "farm"))))


def farm_value_mult(user: dict) -> float:
    return 1 + 0.04 * hobby_level(user, "farm")


F_BAG = '<tg-emoji emoji-id="5382210409824525356">🐟</tg-emoji>'


FISH_RARITY_LABEL = {"crucian": "обычная", "perch": "обычная", "pike": "необычная", "catfish": "редкая",
                     "sturgeon": "эпическая", "goldfish": "легендарная", "whale": "мифическая"}


def _progress_bar(done: float, total: float, width: int = 8) -> str:
    filled = max(0, min(width, round(width * done / max(1e-9, total))))
    return "▰" * filled + "▱" * (width - filled)


