async def show_farm(user_id: int, answer_func, note: str = ""):
    user = await db.get_user(user_id)
    beds = get_farm(user)
    m = crop_price_mult(user)
    now = time.time()
    blocks, rows = [], []
    ready = 0
    for i, bed in enumerate(beds):
        crop = CROPS.get(bed.get("crop"))
        if not crop:
            blocks.append(f'<b>Грядка {i + 1}</b> · <tg-emoji emoji-id="5289516580261091134">🌾</tg-emoji> пусто — можно сажать')
            continue
        total = max(1, int(float(bed.get("ready_at", 0)) - float(bed.get("planted_at", 0))) or crop[2])
        left = int(float(bed.get("ready_at", 0)) - now)
        if left <= 0:
            ready += 1
            blocks.append(f"<b>Грядка {i + 1}</b> · {crop[1]} {crop[0]}\n{_progress_bar(1, 1)} {PE_GIFT} <b>созрело!</b>")
        else:
            blocks.append(f"<b>Грядка {i + 1}</b> · {crop[1]} {crop[0]}\n{_progress_bar(total - left, total)} {PE_HOURGLASS} {format_clan_boss_time(left)}")
    if ready:
        rows.insert(0, [InlineKeyboardButton(text=f"Собрать урожай · {ready}", callback_data="farm|harvest", icon_custom_emoji_id="5303214794336125778")])
    empty_n = sum(1 for b in beds if not b.get("crop"))
    if empty_n:
        first_empty = next(i for i, b in enumerate(beds) if not b.get("crop"))
