@dp.callback_query(F.data.startswith("fish|"))
async def cb_fishing(call: CallbackQuery):
    uid = call.from_user.id
    action = call.data.split("|", 1)[1]
    user = await db.get_user(uid)
    note = ""
    if action == "cast":
        left = fishing_cooldown(user) - (time.time() - float(user.get("fish_last", 0) or 0))
        if left > 0:
            await call.answer(f"Рыба ещё не клюёт… {int(left) + 1} сек.")
            return
        user["fish_last"] = time.time()
        fid = roll_fish(user)
        bag = user.setdefault("fish", {})
        bag[fid] = int(bag.get(fid, 0)) + 1
        user["fish_caught"] = int(user.get("fish_caught", 0)) + 1
        add_weekly_stat(user, "fish")
        f = FISH_BY_ID[fid]
        note = f'{PE_FISH} Клюёт! {f[2]} <b>{f[1]}</b> · <tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji> {format_num(fish_price(user, fid))}'
        ups = add_hobby_xp(user, "fish", 1 + [x[0] for x in FISH_TYPES].index(fid))
        if ups:
            note += f"\n{PE_LEVELUP} Навык рыбака: <b>{hobby_level(user, 'fish')}</b> уровень!"
        if fid in ("goldfish", "whale") and random.random() < 0.5:
            add_potion_to_user(user, "luck_potion")
            note += f"\n{POTION_PREMIUM_EMOJIS.get('luck_potion', '🍀')} В брюхе нашлось зелье удачи!"
        await call.answer()
    elif action == "info":
        await call.answer()
        await show_fish_info(uid, lambda t, kb: edit_for_user(call, t, kb))
        return
    elif action == "sell":
        bag = user.get("fish") or {}
        total = sum(fish_price(user, fid) * int(n) for fid, n in bag.items() if fid in FISH_BY_ID)
        coins = apply_coin_buff(user, total)
        user["coins"] = int(user.get("coins", 0)) + coins
        user["fish"] = {}
        note = f'{PE_OK} Улов продан: <tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji> <b>+{format_num(coins)}</b> монет'
        await call.answer("Продано!")
    else:
        await call.answer()
    await save_runtime_state_lazy(uid, user) if action == "cast" else await save_runtime_state(uid, user)
    await show_fishing(uid, lambda t, kb: edit_for_user(call, t, kb), note)


