FARM_BEDS = 3
CROPS = {
    # id: (имя, эмодзи, время роста, цена семян, цена урожая, бонус)
    "wheat":      ("Пшеница",       '<tg-emoji emoji-id="5289516580261091134">🌾</tg-emoji>', 30 * 60,      200,   450,  None),
    "carrot":     ("Морковь",       '<tg-emoji emoji-id="5429630722832877722">🥕</tg-emoji>', 60 * 60,      400,   1000, None),
    "pumpkin":    ("Тыква",         '<tg-emoji emoji-id="6037368668231307433">🎃</tg-emoji>', 3 * 3600,     1000,  3000, None),
    "mandrake":   ("Мандрагора",    '<tg-emoji emoji-id="5197555094161234652">🌿</tg-emoji>', 6 * 3600, 2500, 7500, "potion"),
    "moonflower": ("Лунный цветок", '<tg-emoji emoji-id="5366300377786365557">🌕</tg-emoji>', 12 * 3600, 6000, 18000, "res"),
}


def crop_price_mult(user: dict) -> float:
    return 1 + int(user.get("level", 1) or 1) / 20


def get_farm(user: dict) -> List[dict]:
    beds = user.setdefault("farm", [])
    while len(beds) < farm_beds_count(user):
        beds.append({})
    return beds


@dp.callback_query(F.data.startswith("farm|"))
async def cb_farm(call: CallbackQuery):
    uid = call.from_user.id
    parts = call.data.split("|")
    action = parts[1]
    user = await db.get_user(uid)
    beds = get_farm(user)
    m = crop_price_mult(user)
    note = ""
    if action == "info":
        await call.answer()
        await show_farm_info(uid, lambda t, kb: edit_for_user(call, t, kb))
        return
    if action == "pickall":
        await call.answer()
        empty_n = sum(1 for b in beds if not b.get("crop"))
        rows = []
        for cid, c in CROPS.items():
            cost = int(c[3] * m)
            crop_icon = premium_emoji_id(c[1])
            label = f"{c[0]} ×{empty_n} · {format_num(cost * empty_n)} · {format_clan_boss_time(farm_grow_time(user, c))}"
            rows.append([InlineKeyboardButton(text=label if crop_icon else f"{c[1]} {label}",
                                              callback_data=f"farm|plantall|{cid}", icon_custom_emoji_id=crop_icon)])
        rows.append([InlineKeyboardButton(text="Назад", callback_data="farm|ref", icon_custom_emoji_id="5215361191051798408")])
        await edit_for_user(call, f'<tg-emoji emoji-id="5197555094161234652">🌿</tg-emoji> <b>Посадить на все пустые грядки ({empty_n})</b>\n\n'
                                  "<blockquote>Цена — за все грядки сразу · время роста</blockquote>",
                            InlineKeyboardMarkup(inline_keyboard=rows))
        return
    if action == "pick":
        idx = int(parts[2])
        await call.answer()
        rows = []
        for cid, c in CROPS.items():
            cost, value = int(c[3] * m), int(c[4] * m * farm_value_mult(user))
            crop_icon = premium_emoji_id(c[1])
            label = f"{c[0]} · {format_num(cost)} → {format_num(value)} · {format_clan_boss_time(farm_grow_time(user, c))}"
            rows.append([InlineKeyboardButton(text=label if crop_icon else f"{c[1]} {label}",
                                              callback_data=f"farm|plant|{idx}|{cid}", icon_custom_emoji_id=crop_icon)])
        rows.append([InlineKeyboardButton(text="Назад", callback_data="farm|ref", icon_custom_emoji_id="5215361191051798408")])
        extra = (f"\n{CROPS['mandrake'][1]} Мандрагора: 30% шанс на случайное зелье\n{CROPS['moonflower'][1]} Лунный цветок: 25% шанс на ресурс последнего босса")
        await edit_for_user(call, f'<tg-emoji emoji-id="5197555094161234652">🌿</tg-emoji> <b>Что посадить на грядку {idx + 1}?</b>\n\n'
                                  f"<blockquote>Цена семян → цена урожая · время роста{extra}</blockquote>",
                            InlineKeyboardMarkup(inline_keyboard=rows))
        return
    if action == "plant":
        idx, cid = int(parts[2]), parts[3]
        c = CROPS.get(cid)
        if not c or idx >= len(beds) or beds[idx].get("crop"):
            await call.answer("Грядка занята.", show_alert=True)
            return
        cost = int(c[3] * m)
        if int(user.get("coins", 0)) < cost:
            await call.answer(f"Не хватает монет: нужно {format_num(cost)}.", show_alert=True)
            return
        user["coins"] = int(user.get("coins", 0)) - cost
        beds[idx] = {"crop": cid, "planted_at": time.time(), "ready_at": time.time() + farm_grow_time(user, c)}
        note = f"{PE_OK} Посажено: {c[1]} <b>{c[0]}</b>\n{PE_HOURGLASS} Созреет через {format_clan_boss_time(farm_grow_time(user, c))}"
        await call.answer("Посажено!")
    elif action == "plantall":
        cid = parts[2]
        c = CROPS.get(cid)
        empty = [i for i, b in enumerate(beds) if not b.get("crop")]
        if not c or not empty:
            await call.answer("Свободных грядок нет.", show_alert=True)
            return
        cost = int(c[3] * m)
        can = min(len(empty), int(user.get("coins", 0)) // max(1, cost))
        if can <= 0:
            await call.answer(f"Не хватает монет: нужно {format_num(cost)} за грядку.", show_alert=True)
            return
        grow = farm_grow_time(user, c)
        for i in empty[:can]:
            beds[i] = {"crop": cid, "planted_at": time.time(), "ready_at": time.time() + grow}
        user["coins"] = int(user.get("coins", 0)) - cost * can
        note = (f"{PE_OK} Посажено на {can} гряд.: {c[1]} <b>{c[0]}</b>\n"
                f'<tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji> Потрачено: {format_num(cost * can)}\n'
                f"{PE_HOURGLASS} Созреет через {format_clan_boss_time(grow)}"
                + (f"\n{PE_CROSS} На остальные грядки не хватило монет." if can < len(empty) else ""))
        await call.answer("Посажено!")
    elif action == "harvest":
        now = time.time()
        coins, got = 0, []
        for i, bed in enumerate(beds):
            c = CROPS.get(bed.get("crop"))
            if not c or float(bed.get("ready_at", 0)) > now:
                continue
            coins += int(c[4] * m * farm_value_mult(user))
            farm_xp_gain = 2 + c[2] // 3600
            if c[5] == "potion" and random.random() < 0.30:
                pid = random.choice([p for p in POTION_DEFS if not str(p).startswith("_")])
                add_potion_to_user(user, pid)
                got.append(f"{POTION_PREMIUM_EMOJIS.get(pid, '🧪')} Зелье «{POTION_DEFS[pid].get('name', pid)}»")
            if c[5] == "res" and random.random() < 0.25:
                line = give_star_boss_res(user, 1)
                if line:
                    got.append(line)
            beds[i] = {}
            user["harvests"] = int(user.get("harvests", 0)) + 1
            add_weekly_stat(user, "harvests")
            if add_hobby_xp(user, "farm", farm_xp_gain):
                got.append(f"{PE_LEVELUP} Навык огородника: <b>{hobby_level(user, 'farm')}</b> уровень!")
        coins = apply_coin_buff(user, coins)
        user["coins"] = int(user.get("coins", 0)) + coins
        note = f'{PE_GIFT} Урожай собран: <tg-emoji emoji-id="5433594926107481306">⚪️</tg-emoji> <b>+{format_num(coins)}</b>' + ("\n" + "\n".join(got) if got else "")
        await call.answer("Собрано!")
    else:
        await call.answer()
    await save_runtime_state(uid, user)
    await show_farm(uid, lambda t, kb: edit_for_user(call, t, kb), note)


