ACH_ROMAN = ["I", "II", "III", "IV"]
ACH_MEDALS = ['<tg-emoji emoji-id="5870770249778859469">🥉</tg-emoji>', '<tg-emoji emoji-id="5283195573812340110">🥈</tg-emoji>',
              '<tg-emoji emoji-id="5870508673385630878">🥇</tg-emoji>', '<tg-emoji emoji-id="5217822164362739968">👑</tg-emoji>']
ACHIEVEMENTS = [
    ("bosses",    "Охотник на боссов", lambda u: int(u.get("boss_kills", 0) or 0),                       [100, 1000, 10000, 100000]),
    ("rolls",     "Лудоман",           lambda u: int(u.get("chests_opened", 0) or 0),                    [1000, 10000, 100000, 1000000]),
    ("level",     "Ветеран",           lambda u: int(u.get("level", 1) or 1),                            [25, 50, 100, 200]),
    ("prestige",  "Перерождённый",     lambda u: get_rebirth_count(u),                                   [1, 5, 10, 20]),
    ("pets",      "Зоопарк",           lambda u: len(u.get("pets") or []),                               [5, 15, 30, 60]),
    ("nightmare", "Кошмарная удача",   lambda u: int((u.get("rarity_stats") or {}).get("nightmare", 0)), [1, 5, 25, 100]),
    ("damage",    "Разрушитель",       lambda u: int(u.get("total_damage", 0) or 0),                     [10**6, 10**9, 10**12, 10**15]),
    ("cboss",     "Гроза Лутиафана",   lambda u: int(u.get("clan_boss_kills", 0) or 0),                  [1, 25, 100, 500]),
    ("wboss",     "Титаноборец",       lambda u: int(u.get("world_boss_kills", 0) or 0),                 [1, 5, 20, 50]),
    ("tower",     "Покоритель башни",  lambda u: int((u.get("tower") or {}).get("best_all", 0) or 0),    [10, 25, 50, 75]),
    ("fish",      "Рыболов",           lambda u: int(u.get("fish_caught", 0) or 0),                      [50, 500, 5000, 25000]),
    ("farm",      "Фермер",            lambda u: int(u.get("harvests", 0) or 0),                         [10, 100, 1000, 5000]),
    ("bestiary",  "Исследователь",     lambda u: bestiary_opened_count(u),                               [10, 25, 40, len(BOSSES)]),
    ("evolve",    "Селекционер",       lambda u: int(u.get("pet_evolutions", 0) or 0),                   [1, 5, 20, 50]),
]
ACH_BY_ID = {a[0]: a for a in ACHIEVEMENTS}


def ach_tier(user: dict, ach_id: str) -> int:
    """Сколько ступеней достижения пройдено (0–4)."""
    _id, _name, fn, steps = ACH_BY_ID[ach_id]
    try:
        v = fn(user)
    except Exception:
        return 0
    return sum(1 for s_ in steps if v >= s_)


def check_new_achievements(user: dict) -> List[tuple]:
    """Обновляет сохранённые ступени, возвращает [(ach_id, tier)] новых."""
    # При первом запуске системы ветераны получают награды за всё, что уже заработали
    saved = user.setdefault("ach", {})
    new = []
    for ach_id in ACH_BY_ID:
        t = ach_tier(user, ach_id)
        if t > int(saved.get(ach_id, 0)):
            for tier in range(int(saved.get(ach_id, 0)) + 1, t + 1):
                new.append((ach_id, tier))
            saved[ach_id] = t
    for ach_id, tier in new:  # награда: свитки по ступени и зелье удачи
        user["revive_scrolls"] = int(user.get("revive_scrolls", 0) or 0) + tier
        add_potion_to_user(user, "luck_potion")
    return new


def get_active_title(user: Optional[dict]) -> str:
    t = (user or {}).get("title")
    if not t or ":" not in t:
        return ""
    ach_id, tier = t.split(":", 1)
    if ach_id not in ACH_BY_ID or int((user.get("ach") or {}).get(ach_id, 0)) < int(tier):
        return ""
    return f"{ACH_MEDALS[int(tier) - 1]} {ACH_BY_ID[ach_id][1]} {ACH_ROMAN[int(tier) - 1]}"


async def notify_new_achievements(user_id: int, user: dict) -> None:
    new = check_new_achievements(user)
    if not new:
        return
    await save_runtime_state(user_id, user)
    if len(new) <= 8:
        lines = [f"{ACH_MEDALS[t - 1]} <b>{ACH_BY_ID[a][1]} {ACH_ROMAN[t - 1]}</b> · {PE_REVIVE} +{t} {'свиток' if t == 1 else 'свитка'}, "
                 f"{POTION_PREMIUM_EMOJIS.get('luck_potion', '🍀')} +1 зелье удачи" for a, t in new]
    else:
        # много сразу (ветеран при запуске системы) — сводка: лучшая ступень каждого достижения + общий итог
        best: Dict[str, int] = {}
        for a, t in new:
            best[a] = max(best.get(a, 0), t)
        lines = [f"{ACH_MEDALS[t - 1]} <b>{ACH_BY_ID[a][1]} {ACH_ROMAN[t - 1]}</b>" for a, t in best.items()]
        lines.append(f"\n<b>Итого за {len(new)} ступ.:</b> {PE_REVIVE} +{sum(t for _a, t in new)} свитков, "
                     f"{POTION_PREMIUM_EMOJIS.get('luck_potion', '🍀')} +{len(new)} зелий удачи")
    await send_user_notification(
        user_id,
        f"<blockquote>{PE_TROPHY} <b>Новое достижение</b>{PE_ALARM}</blockquote>\n\n<blockquote>" + "\n".join(lines) + "</blockquote>\n\n"
        "<blockquote>Титул можно поставить в профиль: <b>титулы</b></blockquote>",
        reply_markup=nav_kb(("Титулы", "ttl|0", "5217822164362739968")),
    )


async def show_achievements(user_id: int, answer_func):
    user = await db.get_user(user_id)
    await notify_new_achievements(user_id, user)  # выдаёт награды за новые ступени и присылает уведомление
    lines = []
    for ach_id, name, fn, steps in ACHIEVEMENTS:
        t = ach_tier(user, ach_id)
        try:
            v = fn(user)
        except Exception:
            v = 0
        medal = ACH_MEDALS[t - 1] if t else '<tg-emoji emoji-id="5296369303661067030">🔒</tg-emoji>'
        if t < 4:
            prog = f"{format_num(v)}/{format_num(steps[t])}"
            lines.append(f"{medal} <b>{name}</b> {ACH_ROMAN[t - 1] if t else ''}\n      до {ACH_ROMAN[t]}: {prog}")
        else:
            lines.append(f"{medal} <b>{name} IV</b> — максимум!")
    done = sum(ach_tier(user, a[0]) for a in ACHIEVEMENTS)
    await answer_func(
        f"{PE_TROPHY} <b>Достижения</b> · {done}/{len(ACHIEVEMENTS) * 4}\n\n"
        "<blockquote expandable>" + "\n".join(lines) + "</blockquote>\n\n"
        "<i>За каждую ступень — свитки воскрешения (по номеру ступени) и зелье удачи. Полученные ступени становятся титулами.</i>",
        InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="Титулы", callback_data="ttl|0", icon_custom_emoji_id="5217822164362739968")]]),
    )


