# ============================================================
# === Эволюция питомцев: 3 одинаковых → шанс на питомца редкостью выше ===
# Успех: 3 исчезают, появляется новый питомец следующей редкости (из того же яйца).
# Неудача: исчезают 2, один остаётся.
# ============================================================

PET_EVOLVE_CHANCES = {"common": 80, "uncommon": 65, "rare": 50, "epic": 35, "legendary": 20}
PET_RARITY_NEXT = {"common": "uncommon", "uncommon": "rare", "rare": "epic", "epic": "legendary", "legendary": "mythic"}


def evolvable_copies(user: dict, pet: dict) -> List[dict]:
    equipped = {x for x in (user.get("equipped_pets") or []) if x}
    return [p for p in (user.get("pets") or [])
            if p.get("pet_id") == pet.get("pet_id") and p.get("iid") not in equipped]


@dp.callback_query(F.data.startswith("pet_evo|"))
async def cb_pet_evolve(call: CallbackQuery):
    uid = call.from_user.id
    _, action, iid = call.data.split("|", 2)
    user = await db.get_user(uid)
    pet = get_pet_by_iid(user, int(iid))
    if not pet:
        await call.answer("Питомец не найден.", show_alert=True)
        return
    rarity = get_pet_rarity_key(pet)
    if rarity not in PET_EVOLVE_CHANCES:
        await call.answer("Мифических питомцев эволюционировать нельзя.", show_alert=True)
        return
    copies = evolvable_copies(user, pet)
    chance = PET_EVOLVE_CHANCES[rarity]
    if len(copies) < 3:
        await call.answer("Нужно 3 одинаковых питомца, не надетых в слоты.", show_alert=True)
        return
    if action == "ask":
        await call.answer()
        nxt = PET_RARITIES[PET_RARITY_NEXT[rarity]]["name"]
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text=f"Эволюция · шанс {chance}%", callback_data=f"pet_evo|do|{iid}", icon_custom_emoji_id="5370831521039017384")],
            [InlineKeyboardButton(text="Отмена", callback_data=f"pet_view|{iid}||", icon_custom_emoji_id="5215361191051798408")],
        ])
        await edit_for_user(
            call,
            f'<tg-emoji emoji-id="5370831521039017384">✨</tg-emoji> <b>Эволюция питомца</b>\n\n'
            f"<blockquote>{get_pet_emoji(pet)} <b>{html.escape(pet['name'])}</b> ×3 → случайный питомец «{nxt}»\n"
            f"Шанс успеха: <b>{chance}%</b></blockquote>\n\n"
            f"<blockquote>{PE_OK} Успех: три питомца превращаются в одного редкостью выше.\n"
            f"{PE_CROSS} Неудача: два питомца пропадают, один остаётся.</blockquote>",
            kb,
        )
        return
    # do
    copies.sort(key=lambda p: -get_pet_level(p))
    keep = copies[0]
    used = copies[:3]
    used_ids = {p["iid"] for p in used}
    success = random.random() * 100 < chance
    if success:
        user["pets"] = [p for p in user["pets"] if p["iid"] not in used_ids]
        egg_id = get_pet_source_egg(pet)
        pool = get_egg_pet_pool(egg_id).get(PET_RARITY_NEXT[rarity])
        if not pool:  # в яйце нет такой редкости — берём из любого старого яйца
            pool = [pid for pid, info in PET_DEFS.items() if info["rarity"] == PET_RARITY_NEXT[rarity]]
        new_pet = create_pet(random.choice(pool))
        new_pet["egg_id"] = PET_DEFS[new_pet["pet_id"]].get("egg") or egg_id
        user["pets"].append(new_pet)
        user["pet_evolutions"] = int(user.get("pet_evolutions", 0)) + 1
        msg = f"{PE_OK} <b>Успех!</b> Появился {get_pet_emoji(new_pet)} <b>{html.escape(new_pet['name'])}</b> ({PET_RARITIES[new_pet['rarity']]['name']})"
        await call.answer("Эволюция удалась!", show_alert=True)
    else:
        drop_ids = {p["iid"] for p in used if p["iid"] != keep["iid"]}
        user["pets"] = [p for p in user["pets"] if p["iid"] not in drop_ids]
        msg = f"{PE_CROSS} <b>Неудача.</b> Два питомца ушли, {get_pet_emoji(keep)} {html.escape(keep['name'])} остался."
        await call.answer("Не повезло…", show_alert=True)
    await save_runtime_state(uid, user)
    await write_activity_log(f"PET {_log_user_name(uid, user)} | эволюция {pet.get('name')} ({rarity}) — {'успех' if success else 'неудача'}")
    await edit_for_user(call, f'<tg-emoji emoji-id="5370831521039017384">✨</tg-emoji> <b>Эволюция</b>\n\n<blockquote>{msg}</blockquote>',
                        InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="К питомцам", callback_data="pets_all|0", icon_custom_emoji_id="5258111319831227095")]]))


async def main():
    global NOTIFY_BOT
    if not TOKEN:
        raise RuntimeError(
            "Укажите токен в переменной BOT_TOKEN или в файле bot_token.txt"
        )
    bot = Bot(token=TOKEN)
    NOTIFY_BOT = bot
    await bot.delete_webhook(drop_pending_updates=True)

    # Подключение к PostgreSQL
    await init_db()

    await load_banned_users()
    await load_clans()
    # Анонсы поднимаем ДО восстановления авторолла: восстановленные автороллы сразу начинают роллить
    global _announce_queue
    _load_announce_settings()
    if _announce_queue is None:
        _announce_queue = asyncio.Queue(maxsize=500)
    asyncio.create_task(announce_worker())
    await restore_runtime_state()
    print("Lootify RPG Bot started!")
    asyncio.create_task(cleanup_trash())
    asyncio.create_task(boss_cooldown_notification_loop())
    asyncio.create_task(clan_boss_spawn_loop())
    asyncio.create_task(lazy_save_loop())
    asyncio.create_task(quest_notification_loop())
    asyncio.create_task(world_boss_loop())
    asyncio.create_task(daily_rewards_loop())
    asyncio.create_task(mannequin_training_loop())
    try:
        await dp.start_polling(bot)
    finally:
        # дописываем в базу отложенные сохранения авторолла перед выключением
        try:
            await flush_lazy_saves(force=True)
            await flush_activity_log()
            _save_world_boss(force=True)
        except Exception as e:
            print(f"[shutdown flush] {e}")
        await close_db()

if __name__ == "__main__":
    if os.name == "nt":
        asyncio.set_event_loop_policy(asyncio.WindowsSelectorEventLoopPolicy())
    asyncio.run(main())

